INSERT INTO `quest_template_locale` VALUES (7810, 'ruRU', 'Повелитель арены', 'Поговорите с Коротышкой Джоном Мифрилом на арене Тернистой долины.', 'Должно быть, стать повелителем арены не так просто!\n\nБыть может, пират-распорядитель на Арене Гурубаши, знает, в чем тут штука!', '', '', '', '', '', 'Поговорите с Коротышкой Джоном Мифрилом на Арене Гурубаши, что в Тернистой долине.', 25549);
INSERT INTO `quest_template_locale` VALUES (7813, 'ruRU', 'Пожертвование – шерсть', '', '', '', '', '', '', '', '', 25549);
