INSERT INTO `quest_template_locale` VALUES (7815, 'ruRU', 'Хрустогрызы, чувак!', 'Убейте 10 морских хрустогрызов по поручению Катума Удильщика из деревни Сломанного Клыка во Внутренних землях.', 'Ты не смотри, что у них такие большие красивые глазки! Страшней морского хрустогрыза зверя нет! Только я удочку закину, как приплывают эти черепахи-переростки, жрут мне всю наживку и удилище пополам ломают!$B$BСделай мне и всей нашей деревеньке одолжение – поубивай их всех.$B$BВ смысле, хрустогрызов.', '', '', '', '', '', 'Вернитесь к Катуму Удильщику в Деревню Сломанного Клыка, что во Внутренних землях.', 19865);
INSERT INTO `quest_template_locale` VALUES (7816, 'ruRU', 'Гаммерита!', 'Убейте Гаммериту и верните Катуму Удильщику из деревни Сломанного Клыка его лучшую блесну.$B$BКатум сказал, что Гаммерита ползает по берегу среди остальных черепах.', 'Йоу! Тут живет всем черепахам черепаха – звать Гаммерита – предводительница всех морских хрустогрызов и просто наглая прожорливая рептилия, чтоб ей.$B$BОна сожрала мою лучшую блесну! Взяла и откусила прямо с удочки! С тех пор рыба совсем клевать перестала.$B$BНайди Гаммериту и вытащи у нее из брюха мою блесну!', '', '', '', '', '', 'Вернитесь к Катуму Удильщику в Деревню Сломанного Клыка, что во Внутренних землях.', 19865);
INSERT INTO `quest_template_locale` VALUES (7817, 'ruRU', 'Пожертвование – магическая ткань', '', '', '', '', '', '', '', '', 25549);
