INSERT INTO `quest_template_locale` VALUES (8655, 'ruRU', 'Наголенники Мстителя', 'Принесите киражские наручники господства, 2 идола Мудреца, 5 бронзовых и 5 глиняных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', 'Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.', '', '', '', '', '', '', 25549);
