INSERT INTO `quest_template_locale` VALUES (8856, 'ruRU', 'Неприкосновенный запас', 'Принесите 4 сферы воды, 4 мощных противоядия и 4 печеных лосося Каландрате в таверну в Крепости Кенария в Силитусе.', 'В Крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих наборов для выживания в пустыне и отнеси их Каландрате в Крепость Кенария.', '', '', '', '', '', 'Вернитесь к Каландрате в Улей Аши, что в Силитусе.', 19865);
INSERT INTO `quest_template_locale` VALUES (8860, 'ruRU', 'Отмечаем Новый Год!', 'Отнесите припасы Пастбищ Дымного Леса хозяйке таверны Аллисон в Штормград.', 'Сегодня в Штормграде празднуют Новый Год! Весь день – бесплатная выпивка, а вечером будет шоу фейерверков! Будет здорово... но в Пиратской Бухте сегодня тоже празднование; держу пари, там будет еще лучше!$B$BЛадно... Трактирщице Аллисон в Штормграде нужно пополнить запасы продуктов на пастбищах Дымного леса, чтобы накормить всех желающих. Не поможешь привезти их сюда?$B$BСпасибо, $n! Аллисон ты найдешь в \"Позолоченной розе\" в Торговом квартале Штормграда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (8861, 'ruRU', 'Отмечаем Новый Год!', 'Отнесите припасы Пастбищ Дымного Леса хозяйке таверны Пале в Громовой Утес.', 'Сегодня в Громовом утесе празднуют Новый Год! Весь день – бесплатная выпивка, а вечером будет шоу фейерверков!$B$BБудет здорово... но в Пиратской Бухте сегодня тоже празднование; держу пари, там будет еще лучше!$B$BЛадно... Трактирщице Пале в Громовом утесе нужно пополнить запасы продуктов на пастбищах Дымного леса, чтобы накормить всех желающих. Не поможешь привезти их сюда?$B$BСпасибо, $n! Палу можно найти в трактире около моста, ведущего к вершине Охотников.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (8863, 'ruRU', 'Праздничные клецки', '', '', '', '', '', '', '', '', 25549);
