INSERT INTO `quest_template_locale` VALUES (13476, 'ruRU', 'Великая честь', 'Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды или в Шаттрат.', 'Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс.$b$bСтупай же и вступи в схватку с Альянсом на всех фронтах. За честь! За Орду!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (13478, 'ruRU', 'В едином порыве', 'Принесите почетные знаки каждого поля боя бригадному генералу Альянса в любую столицу Альянса или в Шаттрат.', 'В войне против Орды решающей может оказаться любая битва, $gсынок:дочка;.$B$BПобеда на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой.$b$bАльянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закаленных в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (13479, 'ruRU', 'Большая охота за яйцами', 'Принесите весеннему сборщику 20 осколков раскрашенной яичной скорлупы.', 'Ах, Сад чудес, праздник весны и жизни! Надеюсь, тебе понравилось собирать яйца, $Gдруг:дорогая;, потому что мне как раз $Gнужен проворный помощник:нужна проворная помощница;.$B$BЯ не знаю, какую магию использовали при создании этих яиц, а друиды играют со мной в молчанку. Будешь разбивать яйца – сохрани для меня осколки скорлупы. Содержимое яиц можешь оставить себе, мне же понадобятся только скорлупки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (13480, 'ruRU', 'Большая охота за яйцами', 'Принесите весеннему собирателю 20 осколков раскрашенной яичной скорлупы.', 'Ах, Сад чудес, праздник весны и жизни! Надеюсь, тебе понравилось собирать яйца, $Gдруг:дорогая;, потому что мне как раз $Gнужен проворный помощник:нужна проворная помощница;.$B$BЯ не знаю, какую магию использовали при создании этих яиц, а друиды играют со мной в молчанку. Будешь разбивать яйца – сохрани для меня осколки скорлупы. Содержимое яиц можешь оставить себе, мне же понадобятся только скорлупки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (13481, 'ruRU', 'Валим отсюда!', 'Проводите отца Камароса в безопасное место и доложите об этом брату Кельтану на борту \"Молота Оргрима\".', 'Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих \"работ\".$B$BЯ не могу уйти сам, но с твоей помощью, |3-6($c), мне, может быть, и удастся спастись, и я еще повоюю с силами Плети.$B$BПоможешь мне выбраться, пока мясники Плети меня не нашли?', 'Проводить отца Камароса в безопасное место', '', '', '', '', 'Поговорите с братом Келтаном на \"Молоте Оргрима\", что в Ледяной Короне.', 25549);
INSERT INTO `quest_template_locale` VALUES (13482, 'ruRU', 'Валим отсюда!', 'Проводите отца Камароса в безопасное место, а затем сообщите об этом Абсалану Благочестивому на борту \"Усмирителя небес\".', 'Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих \"работ\".$B$BЯ не могу уйти сам, но с твоей помощью, |3-6($c), мне, может быть, и удастся спастись, и я еще повоюю с силами Плети.$B$BПоможешь мне выбраться, пока мясники Плети меня не нашли?', 'Проводить отца Камароса в безопасное место', '', '', '', '', 'Поговорите с Абсаланом Благочестивым на \"Усмирителе небес\", что в Ледяной Короне.', 25549);
INSERT INTO `quest_template_locale` VALUES (13483, 'ruRU', 'Весенние сборщики', 'Поговорите с весенним сборщиком в Колючем холме, Брилле, деревне Кровавого Копыта или на площади Соколиных Крыльев.', 'Если тебе не сидится на месте, то поищи магов в поселениях рядом со столицами – в Колючем холме, Брилле, деревне Кровавого Копыта и на площади Соколиных Крыльев. Им нужна помощь в каких-то исследованиях, и они нанимают большое количество охотников за яйцами. Больше сказать не могу, подробности узнаешь у магов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (13484, 'ruRU', 'Весенние собиратели', 'Поговорите с весенним собирателем в Златоземье, Караносе, Доланааре или на Лазурной заставе.', 'Если тебе не сидится на месте, то поищи магов в поселениях рядом со столицами – в Златоземье, Караносе, Доланааре и на Лазурной заставе. Им нужна помощь в каких-то исследованиях, и они нанимают большое количество охотников за яйцами. Больше сказать не могу, подробности узнаешь у магов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (13493, 'ruRU', 'Поклонение огню', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (13494, 'ruRU', 'Поклонение огню', '', '', '', '', '', '', '', '', 25549);
