INSERT INTO `quest_template_locale` VALUES (13721, 'ruRU', 'Путь искателя славы', 'Принесите 25 печатей искателя славы ловчему смерти Визери в Павильон Похитителей Солнца на Ристалище Серебряного Турнира.', 'Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.$B$BИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.$B$BПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (13722, 'ruRU', 'Путь искателя славы', 'Принесите 25 печатей искателя славы Эрессее Певице Рассвета в Павильон Похитителей Солнца на Ристалище Серебряного Турнира.', 'Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.$B$BИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.$B$BПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (13723, 'ruRU', 'Испытание искателя славы', 'Поговорите с оруженосцем Дэнни, чтобы вызвать на поединок вашего противника. Как только вы победите чемпиона Серебряного Авангарда, вернитесь к Амброзу Искрокруту в шатер Альянса на Ристалище Серебряного Турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Гномрегана. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (13724, 'ruRU', 'Испытание искателя славы', 'Поговорите с оруженосцем Дэнни, чтобы вызвать на поединок вашего противника. Как только вы победите чемпиона Серебряного Авангарда, вернитесь к Колосусу в шатер Альянса на Ристалище Серебряного Турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Экзодара. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.', '', '', '', '', '', '', 25549);
