INSERT INTO `quest_template_locale` VALUES (13726, 'ruRU', 'Испытание искателя славы', 'Поговорите с оруженосцем Дэнни, чтобы вызвать на поединок вашего противника. Как только вы победите чемпиона Серебряного Авангарда, вернитесь к Мокре Дробителю Черепов в шатер Орды на Ристалище Серебряного Турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.', 'Скоро ты будешь $gготов:готова; сразиться в великой битве. Если хочешь доказать, что $gдостоин:достойна; этой чести, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.', '', '', '', '', '', '', 25549);
