INSERT INTO `quest_template_locale` VALUES (25784, 'ruRU', 'Докопаться до истины', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (25785, 'ruRU', 'Докопаться до истины', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (25786, 'ruRU', 'Докопаться до истины', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (25787, 'ruRU', 'Докопаться до истины', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (25788, 'ruRU', 'Докопаться до истины', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (25789, 'ruRU', 'Докопаться до истины', 'Отнесите загадочное устройство в Оргриммар, Подгород, Луносвет или Громовой Утес и покажите его представителю Служителей Земли.', 'На месте разлома осталось это странное устройство – но что это такое?$B$BВозможно, в столице кто-нибудь сумеет разобраться.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (25790, 'ruRU', 'Назад к Краззлу', 'Поговорите с Краззлом Шустрецом на Утесе Треснувшего Копыта в Тысяче Игл.', 'Я не дурак!$B$BВернешься к тому, кто тебя послал, и скажешь, что сделки не будет! Если, конечно, сумеешь вернуться к нему живым...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25791, 'ruRU', 'Назад к Ризнеку', 'Поговорите с Ризнеком на Утесе Треснувшего Копыта в Тысяче Игл.', 'Я не дурак!$B$BВернешься к тому, кто тебя послал, и скажешь, что сделки не будет! Если, конечно, сумеешь вернуться к нему живым...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25792, 'ruRU', 'Наступление', 'Воспользуйтесь руной огня, чтобы разрушить 4 тотема удушения на передовой Мерзлогривов.', 'Большая часть горных пехотинцев и паровых танков Дун Морога заняты в бою на передовой Мерзлогривов, которая приближается к нам с юго-востока. У нас едва хватает сил сдерживать троллей, что уж говорить о входе в деревню или захвате их предводителя.$b$bОни перерезали нам все подходы, расставив загадочные тотемы, которые вызывают приступы удушья у всех приближающихся горных пехотинцев, делая их беззащитными перед врагами. На этом камне начертана руна огня. Он должен помочь разрушить эти тотемы и освободить наших горных пехотинцев.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25793, 'ruRU', 'Глубокие плёсы', 'Поговорите с Железной Лапой Макги в Глубоких плёсах в Когтистых горах.', 'Эта база нужна была для того, чтобы Терамор закрепился в Когтистых горах и мог поставлять припасы Ночным эльфам. Но, к сожалению, Орда задала нам хорошенькую трепку. Армии Адского Крика сильны и никогда не отступают. Такой яростной Орды я не помню со времен второй войны...$B$BТеперь вот, кажется, Орда использует шахту, выкопанную Лигой исследователей, для того, чтобы напасть на нас с тыла. Эту шахту нужно завалить!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25794, 'ruRU', 'Подводное убежище', 'Загляните в гадальный шар Эрунака, чтобы выяснить, где находится Дымчатый грот.', 'Я, кажется, выяснил, кто автор этой записки.$B$BПохоже, ему просто необходима чья-то помощь, если он хочет выжить.$B$BСейчас я настрою один из гадальных шаров и ты $gсам:сама; его увидишь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25795, 'ruRU', 'Возвращение в святилище', 'Вернитесь к Чолуне в святилище Авианы на горе Хиджал.', 'Яйцо Авианы было доставлено в святилище, и сейчас оно находится в безопасности. Чолуна должна знать, что делать дальше.$B$BЯ закончу кое-какие наши дела и присоединюсь к тебе позже.', '', '', '', '', '', 'Вернитесь к Чолуне в Святилище Авианы на горе Хиджал.', 25549);
INSERT INTO `quest_template_locale` VALUES (25796, 'ruRU', 'Богатые недра', 'Убейте 15 кентавров на Утесе Треснувшего Копыта.', 'Эта нефть нужна нам как воздух. Очень жаль, что кентавры ушли от наступающего моря именно сюда.$B$BЖаль для кентавров, разумеется.$B$BОни плюнули нам в лицо, $n. Мы сделали им щедрое предложение, и они поступили неразумно, отвергнув его. Теперь мы... то есть ты – покажешь им, что они были неправы.$B$BОчисти Утес Треснувшего Копыта от кентавров. Да прольется нефть!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25797, 'ruRU', 'Богатые недра', 'Убейте 15 кентавров на Утесе Треснувшего Копыта.', 'Эта нефть нужна нам как воздух. Очень жаль, что кентавры ушли от наступающего моря именно сюда.$B$BЖаль для кентавров, разумеется.$B$BОни плюнули нам в лицо, $n. Мы сделали им щедрое предложение, и они поступили неразумно, отвергнув его. Теперь мы... то есть ты – покажешь им, что они были неправы.$B$BОчисти Утес Треснувшего Копыта от кентавров. Да прольется нефть!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25798, 'ruRU', 'На защиту бура', 'Защитите оборудование для добычи нефти.', 'Лично я с пустыми руками отсюда не уйду! Ты со мной?$B$BБьюсь об заклад, тебе не терпится узнать, что вон в том огромном ящике. Что ж, момент истины настал. Доставь одну из наших буровых установок к нефтяным пластам и добудь нам немножко сырца.$B$BКентавры наверняка попытаются на тебя напасть. Так что защищай бур до тех пор, пока тот не выкачает бочку-другую нефти.', 'Оборудование для добычи нефти защищено', '', '', '', '', 'Вернитесь к Краззлу Шустрецу на Утес Треснувшего Копыта в Тысяче Игл.', 25549);
INSERT INTO `quest_template_locale` VALUES (25799, 'ruRU', 'На защиту бура', 'Защитите оборудование для добычи нефти.', 'Лично я с пустыми руками отсюда не уйду! Ты со мной?$B$BБьюсь об заклад, тебе не терпится узнать, что вон в том огромном ящике. Что ж, момент истины настал. Доставь одну из наших буровых установок к нефтяным пластам и добудь нам немножко сырца.$B$BКентавры наверняка попытаются на тебя напасть. Так что защищай бур до тех пор, пока тот не выкачает бочку-другую нефти.', 'Оборудование для добычи нефти защищено', '', '', '', '', 'Вернитесь к Ризнеку на Утес Треснувшего Копыта в Тысяче Игл.', 25549);
INSERT INTO `quest_template_locale` VALUES (25800, 'ruRU', 'Не было бы счастья, да несчастье помогло', 'Добудьте 5 мясистых клешней крабов гавани.', 'Работы у нас тут, конечно, по горло, |3-6($c), но не следует игнорировать подарки судьбы.$B$BКогда случилось наводнение, беснующиеся потоки занесли к нам немало обитателей океана. Теперь Гавань Менетилов кишит крабами – большими, сочными.$B$BЯ всегда говорил: если корабль разбился на крабовой отмели – хоть крабов наешься досыта! Так что принеси-ка ты мне самые крупные, самые мясистые крабьи клешни, какие только сможешь найти, а я заплачу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25801, 'ruRU', 'Угроза из глубин', 'Добудьте голову Жруна и убейте 12 мурлоков любого вида из племени Синежабрых.', 'Мурлоки поднимаются из глубин океана и строят поселения на берегу. Они нападают на наших рыбаков и торговцев, и этому нужно положить конец.$B$BОдин из вожаков, Жрун, повадился со своими родичами из племени Синежабрых устраивать засады на дороге. А после каждого нападения они возвращаются в свои хибары, откуда их уже не достать. Мы хорошо заплатим тому, кто сможет обеспечить безопасность наших торговых путей.$B$BЖрун промышляет в речной бухте к северу отсюда. Найди его, убей гада и всю его свору. И принеси мне его голову.', '', 'Больше он нас не побеспокоит.', 'Жрун', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25802, 'ruRU', 'Украденные товары', 'Обыщите ящики и бочки в прибрежных поселениях мурлоков.', 'Не так давно мурлоки напали на торговое судно \"Слепая принцесса\". Сам корабль и команда не пострадали, но почти весь груз эти твари умудрились утащить за борт. Среди похищенного была статуэтка Теренаса Менетила, очень ценная. Ее нужно вернуть.$B$BОбыщи поселения мурлоков на побережье. Ищи бочки, ящики, сундуки – все, что похоже на краденый груз. Если найдешь статуэтку Менетила, принеси ее мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25803, 'ruRU', 'Поиски продолжаются', 'Найдите статуэтку Менетила.', 'Вы тщательно обыскиваете это поселение мурлоков, но статуэтки Менетила здесь нет.$B$BВозможно, она в одном из поселений на севере или северо-востоке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25804, 'ruRU', 'Поиски в поселениях мурлоков', 'Продолжайте поиски статуэтки Менетила в поселениях мурлоков.', 'В этом поселении ничего нет.$B$B...Но внутреннее чутье вам подсказывает, что в следующий раз обязательно должно повезти.$B$Bстатуэтка Менетила наверняка в одном из поселений к северу отсюда!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25805, 'ruRU', 'Возвращение статуэтки', 'Отнесите статуэтку Менетила Карлу Борану в Гавань Менетилов, что в Болотине.', 'Вытащив бочонок из грязи и вскрыв его, вы обнаруживаете внутри завернутую в мягкую солому серебряную статуэтку. Это фигурка юного длинноволосого паладина с воздетым над головой молотом.$B$BВидимо, это и есть статуэтка Менетила! Теперь нужно вернуться в Гавань Менетилов и передать ее Карлу Борану.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25806, 'ruRU', 'В такой глубокой... а, ничего.', 'Убейте 12 кром\'гарских убийц.', 'Ох, Лига исследователей – сборище абсолютных глупцов. Мало нам призраков тауренов вокруг, так эта Лига исследователей умудрилась еще и открыть тайный ход на первоначальную базу Орды в Когтистых горах, она называется крепость Кром\'гар.$B$BТеперь убийцы из крепости шныряют здесь и по-тихому убивают всех в шахте.$B$BЯ хочу, чтобы ты $gпошел:пошла; туда и все там $gзачистил:зачистила;..$B$BОй, да, чуть не забыл: держи-ка эти очки. Надевай смелей. В них ты будешь отлично видеть любого замаскированного убийцу в шахте.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25807, 'ruRU', 'Возрождение древней богини', 'Примените фимиам вестника на яйце Авианы в святилище Авианы.', 'Уверена, что ты $gвестник:вестница; Авианы, $n! Ведь именно ты впервые $gувидел:увидела; ее и $gспас:спасла; ее сущность из лап дракона.$B$BЯ полагаю, что Авиана скоро вернется в наш мир. И ты $gудостоен:удостоена; чести открыть перед ней врата.$B$BВозьми этот фимиам и воскури его над яйцом Авианы в комнате, что находится выше.$B$BДревняя богиня ждет, $n. Грядет наше спасение!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25808, 'ruRU', 'Эта штука работает?', 'Ликвидируйте главу убийц Кел\'истру.', '<ГНМ-передатчик потрескивает от статических помех, и вы слышите голос лейтенанта Полсона.>$B$BДа что за гномья рухлядь... ЕСТЬ КТО ЖИВОЙ?! $n, ты меня слышишь?$B$BНикак $gпомер:померла; уже?$B$BТак, если ты меня еще слышишь: нам только что донесли про некую главу убийц: она сидит в той же шахте и управляет всеми остальными. Так что найди ее, ликвидируй, а потом доложи мне.$B$BПолсон, отбой.', '', 'Проклятое гномье устройство! ПРИЕМ!', 'Лейтенант Полсон', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25809, 'ruRU', 'Своих не бросать!', 'Спасите 8 испуганных шахтеров.', 'Орда – просто звери!$B$B<Капрал Турс плюет на землю.>$B$BТы глянь вокруг! Всех невинных порешили! Гражданских!$B$BСлушай, $n, ты $gдолжен:должна; нам помочь. Отправляйся в Глубокие плёсы и посмотри, не осталось ли там кого из живых шахтеров. Если кто и выжил, то наверняка, до смерти напуганы! Обыщи все закоулки, в каждой трещине пошарь, даже в тележках! Кто-то ведь непременно сумел выжить и спрятаться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25810, 'ruRU', 'Разорение инкубатора', 'Пройдите через огненные врата в центре Негаснущего пожара и найдите Фардена Когтекрыла.', '$n! Чолуна сказала правду: богиня вернулась! Это какое-то чудо.$B$BНесмотря на то, что ты $gрасправился:расправилась; с драконом Сетрией, нам еще предстоит отыскать все яйца, украденные для нее гарпиями. Мы с Тизали обнаружили их в огромном инкубаторе, расположенном на Огненных Просторах. Это место находится в ином мире, так что Авиана не сможет сопровождать тебя.$B$BВойди в огненные врата в центре долины, что лежит к югу отсюда. Там тебя встретит Фарден Когтекрыл.', '', '', '', '', '', 'Пройдите через огненные врата в центре Негаснущего пожара на Хиджале. Когда будете внутри, поговорите с Фарденом Когтекрылом.', 25549);
INSERT INTO `quest_template_locale` VALUES (25811, 'ruRU', 'Обвал шахты', 'Заложите связку динамита у первой, второй, третьей и четвертой балки.', 'Чтобы обвалить шахту, нужно снести ее опорные балки. Взрывчатки-то я тебе дам, этого добра полно; но чтобы обложить ею каждую балку, тебе придется пробиться через Кром\'гарских убийц.$B$BХотя есть и хорошая весть: мы всегда отмечали все опорные балки большим красным крестом. Так что просто ищи отметки и закладывай взрывчатку около них. Когда все заложишь, возвращайся сюда, и я запущу детонатор.$B$BБдыщщщ!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25812, 'ruRU', 'Спелеологи', 'Поговорите с рядовым Поллардом в Дымчатом гроте.', 'Скорее, $n!$B$BНемедленно плыви к той пещере.$B$BМы тоже туда отправимся и проследим, нет ли за тобой хвоста.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25813, 'ruRU', 'Подуй в рог', 'Покончите с Вырррлом.', 'Тот старый кентавр, Небоступ Врактрис, упоминал некого великого духа ветра, которому поклоняются кентавры. Чтобы вершина окончательно стала нашей, нужно с ним разделаться.$B$BЯ видел, как они дули в огромный рог вон там, на вершине холма, чтобы вызвать элементаля. А он давал им некие распоряжения и исчезал.$B$BПоди и ты вызови его, $n.', '', 'Протруби в рог и убей его!', 'Вырррл', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25814, 'ruRU', 'Подуй в рог', 'Покончите с Вырррлом.', 'Тот старый кентавр, Небоступ Врактрис, упоминал некого великого духа ветра, которому поклоняются кентавры. Чтобы вершина окончательно стала нашей, нужно разделаться с этим божком.$B$BЯ видел, как они дули в огромный рог вон там, на вершине холма, чтобы вызвать элементаля. А он давал им некие распоряжения и исчезал.$B$BПоди и ты вызови его, $n.', '', 'Протруби в рог и убей его!', 'Вырррл', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25815, 'ruRU', 'Третий флот', 'Заберите медовуху Фитсиммонса из подвала таверны в Гавани Менетилов.', 'Когда-то я служил помощником капитана на \"Владычице\", линейном корабле Третьего флота Кул-Тираса. Его называют Обреченным флотом. Обреченным, потому что в своем последнем плавании корабли столкнулись со стаей красных драконов, которыми правили орки!$B$BПротив драконьего огня у нас не было ни единого шанса... Вся флотилия вспыхнула и пошла ко дну здесь, у этого побережья. Я единственный, кому удалось спастись...$B$B...Принеси мне медовухи, |3-6($c). Я храню ее внизу, в подвале таверны. Специально держу подальше от себя, а обойтись без нее все равно не могу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25816, 'ruRU', 'Обреченные на вечные скитания', 'Поговорите с призраком первого помощника Снеллига.', '<Приободрившись, Фитсиммонс продолжает рассказывать...>$B$BЯ единственный уцелевший из всех матросов злополучного Третьего флота Кул-Тираса, что затонул у побережья к северу отсюда. В трюме одного из кораблей тайно перевозилось сокровище, в равной степени великое и ужасное, и его зловещая сила теперь не дает душам моих погибших братьев покинуть гниющие остовы кораблей.$B$BОни день и ночь меня преследуют. Первый помощник Снеллиг взывает ко мне! А он должен быть мертв! Пожалуйста, $n, разыщи его на месте кораблекрушения и просто... скажи ему, чтоб оставил меня в покое!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25817, 'ruRU', 'Проклятая команда', 'Убейте 5 проклятых матросов и 5 проклятых стражей бухты у Погибшего Плота.', 'Матросы Третьего флота прокляты. Обречены вечно бродить по этим берегам, испытывая страшные мучения. Между нами и Фитсиммонсом существует незримая связь: покуда мы страдаем здесь, он тоже не будет знать покоя.$B$BТы $gдолжен:должна; освободить души моих братьев по команде. Изгони их призраков из этого мира, затем возвращайся сюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25818, 'ruRU', 'Очищение', 'Отберите ключ от сейфа на \"Отважном\" у капитана Халиндора.', 'Только свершенная месть поможет снять с нас проклятие. Капитан Халиндор, виновник наших бед, разжег в команде пагубное желание обладать запретным артефактом – Оком Палета. Его дух и поныне сторожит Око, запертое в сейфе на его старом корабле, \"Отважном\".$B$BУничтожь того, кто обрек нас на такие муки, |3-6($c). Одолей капитана, забери у него ключ и унеси Око Палета прочь из этого места.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25819, 'ruRU', 'Око Палета', 'Отнесите проклятое Око Палета Глорину Стальному Лбу в Гавань Менетилов, что в Болотине.', 'Внутри сундука лежит шар из потемневшего стекла, источающий зловещее свечение. Должно быть, это то самое злополучное Око Палета, что наслало проклятие на души моряков.$B$BНеобходимо очистить его от скверны. Быть может, жрец в Гавани Менетилов сумеет помочь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25820, 'ruRU', 'Материнская тревога', 'Убейте 10 режущих плавников гавани.', 'Мой сын Гимлок – свет всей моей жизни. Так отрадно смотреть, как он играет с другими детьми.$B$BНо я все время беспокоюсь за него. В бухте водятся акулы, и плавают они совсем недалеко от берега. Если одна из них сумеет подобраться к детям...$B$BЯ этого не переживу! Пожалуйста, |3-6($r), ты лучше любого из нас $gподготовлен:подготовлена; к таким схваткам. Сможешь убить этих акул ради меня? Если не всех, то хотя бы нескольких?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25821, 'ruRU', 'Особое задание', 'Доложитесь командиру армии Валену в лагере экспедиции Северной стражи, что в Когтистых горах.', 'Ты на славу $gпотрудился:потрудилась; здесь, $n. Командир армии Вален узнал о твоих заслугах и просит тебя явиться к нему, да немедленно. У него есть для тебя особое задание – возможно, ты $gединственный:единственная;, кто сможет остановить вторжение Орды в Когтистые горы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25822, 'ruRU', 'Оружие для войны', 'Добудьте 10 ящиков с оружием Альянса.', 'Придется еще раз подвергнуть тебя опасности, $n. На востоке ты найдешь разработку богатого месторождения минералов, которое недавно разорила Орда. Там повсюду разбросаны наши ящики с оружием. Орда только недавно захватила это место, так что вряд ли они успели найти все.$B$BСтупай туда и раздобудь немного оружия для наших новых друзей из клана Зловещего Тотема!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25823, 'ruRU', 'Безжалостная Орда', 'Убейте 12 врагов из Орды на месте раскопок.', 'Хотя очень важно немедленно добыть ящики с оружием, необходимо очистить от Орды место раскопок на востоке отсюда. Если мы хотим открыть линию снабжения для наших союзников из клана Зловещего Тотема, нам необходим свободный доступ к выработкам.$B$BПеребей всех воинов Орды, какие попадутся тебе на месте раскопок, $n. Во славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25824, 'ruRU', 'Отчет', 'Обратитесь к рядовому Полларду и попросите поведать об испытаниях, которые выпали на его долю.', 'Этот солдат был при смерти, но, боюсь, у нас нет времени ждать, пока он полностью придет в себя. Он располагает информацией, которая позарез нам нужна.$B$BНаберись терпения и выпытай у него все, пока он еще может говорить.$B$BЕсли повезет, удастся выяснить, что нас тут ожидает...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25825, 'ruRU', 'Неси добро', 'Доставьте бочку нефти Пшиксу Медноштифу на гоночную баржу Пшикса и Поззика в Тысяче Игл.', 'Ладно, $n, доставь-ка эту нефть Пшиксу на гоночную баржу и поведай хорошие новости', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25826, 'ruRU', 'Неси добро', 'Доставьте бочку нефти Поззику на гоночную баржу Пшикса и Поззика в Тысяче Игл.', 'Ладно, $n, доставь-ка эту нефть Пшиксу на гоночную баржу и поведай хорошие новости!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25829, 'ruRU', 'Tracking Quest - Goldrinn Hub Complete', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (25830, 'ruRU', 'Последний хранитель знаний', 'Найдите Норду, древо мудрости, в Негаснущем Пожаре на горе Хиджал.', 'Тебе удалось пробудить Древних, $n, но дух Эссины, обитающий в ее роще, по-прежнему безмолвствует. С ее помощью мы могли бы переломить ход сражения и исправить все то, что натворили на этой земле сектанты Сумеречного Молота.$B$BЯ знаю, кто может нам помочь. Старшее из древ – Норду – тысячи лет находится в самом центре того места, которое мы сейчас зовем Негаснущим Пожаром. Он помнит все, что происходило с этим миром с первого дня его появления. Если Норду еще жив, возможно, ему удастся пробудить Эссину. Найди его.', '', '', '', '', '', 'Найдите Норду, древо мудрости, в Негаснущем пожаре на горе Хиджал.', 25549);
INSERT INTO `quest_template_locale` VALUES (25832, 'ruRU', 'Возвращение к Авиане', 'Вернитесь к Авиане в Святилище Авианы на горе Хиджал.', '$n, ты $gсделал:сделала; все, что было в твоих силах. Пещера скоро обрушится!$B$BЯ соберу оставшихся крылатых скакунов и запечатаю за собой огненные врата.$B$BА ты отправляйся вперед и дай знать Авиане, что этого отвратительного инкубатора больше не существует!', '', '', '', '', '', 'Вернитесь к Авиане в Cвятилище Авианы на горе Хиджал.', 25549);
INSERT INTO `quest_template_locale` VALUES (25834, 'ruRU', 'Смерть по доверенности', 'Поговорите с \"Пирожком\" МакСоусом в лагере экспедиции Северной стражи в Когтистых горах.', 'Слышишь шум боя внизу, $n? Сдается, что клан Зловещего Тотема больше не в чести у Орды. Не знаю, что случилось, но это может оказаться нам на пользу.$B$BЯ устрою встречу с послом Зловещего Тотема. Мне нужно, чтобы ты $gдобыл:добыла; все для угощения в честь замирения.$B$B<Командир армии Вален показывает на \"Пирожка\".>$B$BПоговори с \"Пирожком\", $n. Он уже знает, что нам нужно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25835, 'ruRU', 'Волю заставе Вольного Ветра!', 'Поговорите с Квентином на заставе Вольного Ветра в Тысяче Игл.', 'Как ни жаль, пора тебе отправляться дальше. Быстро же иные птенцы вылетают из гнезда... ну или как там.$B$BВ общем, ты нам тут здорово $gпомог:помогла;, $gлюбезный:милая;, но Квентин с ночными эльфами пропадают без тебя под натиском клана Зловещего Тотема на заставе Вольного Ветра, что к северо-западу отсюда. $B$BЯ лично считаю, что дело там – табак, но как знать... может быть, с твоей помощью у них что и выйдет?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25836, 'ruRU', 'Волю заставе Вольного Ветра!', 'Поговорите с Талией Янтарной Шкурой на заставе Вольного Ветра в Тысяче Игл.', 'Что ж, похоже, пути наши расходятся – по крайней мере, на время. К северо-западу отсюда тауренам с заставы Вольного Ветра отчаянно нужна твоя помощь в борьбе с кланом Зловещий Тотем.$B$BСудя по тому, как много ты $gуспел:успела; для нас сделать, там ты тоже сумеешь отличиться в два счета!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25837, 'ruRU', 'Достойное угощение', 'Добудьте 6 яиц калимдорских орлов, 8 бараньих окороков и 10 кусков сыра Камнепадов.', 'Чтобы приготовить достойное угощение, мне понадобится несколько ингредиентов.$B$BЯйца калимдорских орлов нужно достать из их гнезд, поищи в лесах на западе.$B$BБараний окорок! За этим делом наведайся к баранам Когтистых гор.$B$BПоследнее добыть будет потруднее, но омлета с бараниной без баранины не состряпаешь. Ступай на юго-запад к ущелью Камнепадов и отыщи пещеры кобольдов. Перебей их и забери их особенный сыр.$B$BПринеси все это мне, и я создам настоящий кулинарный шедевр!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25838, 'ruRU', 'Помощь из поселка Сталежаров', 'Поговорите с Делбером Кривошипом в поселке Сталежаров.', 'С твоей помощью нам удалось подобраться к Укрытию Мерзлогривов. Скоро запасы троллей из племени Мерзлогривов истощатся, и их поселение можно будет легко атаковать.$b$bВот тут и начинается роль команды Секретной службы Гномрегана. Их техникам удалось найти способ перебросить своих агентов в тыл врага, не открыв Мерзлогривам своего присутствия. Отправляйся в поселок Сталежаров, который расположен к северо-востоку от города, и поговори с Делбером Кривошипом. У него больше информации.', '', '', '', '', '', 'Поговорите с Делбером Кривошипом в поселке Сталежаров.', 25549);
INSERT INTO `quest_template_locale` VALUES (25839, 'ruRU', 'Ультрабезопасный переместитель войск', 'Воспользуйтесь ультрабезопасным переместителем войск, чтобы отправиться в Укрытие Мерзлогривов.', 'Из-за катаклизма враги оказались ближе к дому, поэтому глава секретной операции \"Гномреган\" попросил меня сконструировать устройство, которое бы позволяло быстро и незаметно перебрасывать войска в любой уголок Дун Морога.$b$bИ вот перед тобой ультрабезопасный переместитель войск!$b$bНемного электричества и парашют системы ОПР – для вас, непрофессионалов, перевожу: очень позднее раскрытие – и эта штучка доставит тебя на передовую вовремя. Просто запрыгивай и приготовься к полету! Слемп Шестерзуб будет ждать тебя в зоне приземления.', 'Воспользуйтесь ультрабезопасным переместителем войск, чтобы отправиться в Укрытие Мерзлогривов.', '', '', '', '', 'Вернитесь к Слемпу Шестерзубу в Укрытие Мерзлогривов.', 25549);
INSERT INTO `quest_template_locale` VALUES (25840, 'ruRU', 'Сломить сопротивление', 'Убейте Баттока Берсерка и 5 воинов из племени Мерзлогривов в Укрытии Мерзлогривов.', 'Вождь Мерзлогривов погиб при первой атаке троггов, но после этого их возглавляет один из самых уважаемых воинов. Именно Батток Берсерк основал Укрытие Мерзлогривов, строительство нового поселения и стоял во главе атак на Каранос и горных пехотинцев.$b$bЕсли мы убьем Баттока, без предводителя они станут неорганизованными, и горным пехотинцам будет легче справиться с оставшимися в живых. Баттока можно найти в поселении Мерзлогривов, что к востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25841, 'ruRU', 'Удар сверху', 'Воспользуйтесь сигнальной ракетой, чтобы вызывать воздушные удары по северной и южной сторонам Укрытия Мерзлогривов.', 'Техники Делбера день и ночь не смыкали глаз, помогая нам подготовиться к этому удару. Помимо создания и настройки пусковой установки, его люди подготовили авиационное крыло секретной операции для удара по Укрытию Мерзлогривов. Они будут ждать сигнала для начала атаки.$b$bВозьми эту сигнальную ракету установи ее у группы зданий в северной и южной частях поселения. Ветролеты осуществят быстрые удары по обеим мишеням.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25842, 'ruRU', 'Огнеборство', 'Уничтожьте 5 огненных мучителей, чтобы защитить от них Норду.', 'Мое время на исходе. Лишь толика меня уцелела во всепожирающем пламени. Я видел мириады эпох... но собственная кончина всегда приходит так неожиданно.$B$BНовая жизнь может зародиться на останках прежней. Я должен передать свои знания другим. Умоляю, не дай им забрать меня до тех пор, пока я не закончу начатое.$B$BЗадержи мучителей, |3-6($c), пусть даже на мгновение.$B$BПодари мне краткий миг, а взамен я наделю тебя тысячами жизней.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25843, 'ruRU', 'Месть Тортоллы', 'Поговорите с Тортоллой на Выжженной равнине на горе Хиджал.', 'Гора снова зацвела! Если мы будем действовать быстро, то можем закрепить преимущество.$B$BНаш старый друг Тортолла, древний бог-черепаха, уже в пути. Только вот идет он черепашьим шагом...$B$BОтыщи Тортоллу на тропе, ведущей вниз к Выжженной равнине, что лежит к востоку отсюда. Наши укрепления в тех краях пали в самом начале вторжения; может быть, теперь мы сможем отбить их.', '', '', '', '', '', 'Поговорите с Тортоллой на Выжженной равнине на горе Хиджал.', 25549);
INSERT INTO `quest_template_locale` VALUES (25844, 'ruRU', 'Сколько дикого дверя ни корми', 'Принесите мясное угощение Тону Поклону Ветра на заставу Зловещего Тотема в Когтистых горах.', 'Ты $gслышал:слышала; приказ, $n? Доставь достойное угощение для посла Зловещего Тотема! Он и его свита будут тебя ждать внизу у юго-восточной тропы.$B$BЭто поможет нам завоевать благосклонность их вождя!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25845, 'ruRU', 'Условия службы', 'Передайте условия Зловещего Тотема командиру армии Валену, находящемуся в лагере экспедиции Северной стражи в Когтистых горах.', 'Зловещему Тотему нужно оружие! Орда, вдохновленная своим вождем, с помощью новых гоблинских союзников создала большой запас вооружения. А у нас оружие простое и не сравнится с их огневой мощью. Дайте Зловещему Тотему сильное оружие, и мы вместе сокрушим Орду!$B$BВот наши требования! Дайте Зловещему Тотему оружие – и мы будем сражаться за Альянс!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25846, 'ruRU', 'Грундиг Темное Облако, вождь клана Зловещего Тотема', 'Доставьте ящики с оружием Альянса Грундигу Темному Облаку на заставу Зловещего Тотема в Когтистых горах.', 'Вождь Зловещего Тотема ожидает твоего прибытия, $n. Бери эти ящики с оружием и ступай на заставу Зловещего Тотема, к югу отсюда.$B$BУдачи, $n. Если с тобой что-то случится, я лично оповещу твою ближайшую родню и короля Ринна о том, что ты $gсовершил:совершила; ради Альянса.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25847, 'ruRU', 'Превосходство Зловещего Тотема', 'Используйте оружие из ящика с оружием Альянса, чтобы вооружить 12 воинов клана Зловещего Тотема.', 'По всей долине Высокого леса Орда нападает на Зловещий Тотем. Армии Адского Крика не ведают жалости и убивают всех, кто попадается им на пути.$B$BНо мы положим этому конец! Мы возьмем принесенное тобой оружие, и ты увидишь, как Зловещий Тотем сражается с Ордой. Дай им оружие Альянса – и увидишь, как они уничтожат своих ордынских противников! Ступай, друг, у нас много дел.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25848, 'ruRU', 'Падение', 'Убейте генералов Орды в лагере Апарахе и добудьте знак различия генерала Орды.', 'Когда мы узнали, что Адский Крик прислал другого орка из маг\'харов для надзора за войсками Орды в южной части Когтистых гор, было слишком поздно. Лагерь Апарахе был сожжен дотла, а все принадлежавшие к клану Зловещего Тотема, уничтожены.$B$BТеперь битвой за долину Высокого леса руководят четыре самых страшных военачальника Орды, и среди них тот маг\'хар – генерал Глубгок.$B$BОтправляйся к развалинам лагеря Апарахе к югу отсюда и убей генералов. Мы остановим Орду прямо СЕЙЧАС! Возвращайся ко мне и принеси генеральский знак различия!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25849, 'ruRU', 'Ожившие ископаемые', 'Добудьте 20 окаменелых костей из оживших ископаемых.', 'Послушай, $gдружище:подруга;. Любой нормальный археолог знает, что работа у него рискованная. Как осторожно ни копай, все равно хоть раз да разбудишь древнее зло или будешь проклят злыми духами, такое с каждым случается!$B$BНет, настоящие профессионалы знают, что всякая мелочь вроде оживших костей – не повод прерывать раскопки.$B$BНо сами кости мне нужны, поэтому ты займись-ка этими ископаемыми тварями, что бегают вокруг. Разбери их на составные части и принеси мне. Вознаграждение гарантирую.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25850, 'ruRU', 'Бей прямо по земле!', 'Убейте 7 палеолитических элементалей.', 'Если ты еще не $gзаметил:заметила;, тут, в Болотине, все вверх тормашками. Наводнения, землетрясения... а теперь еще сама почва стала такие чудеса выкидывать, что диву даешься.$B$BВ жизни бы не подумал, что на меня может напасть моя собственная работа, но вот поди ж ты: здоровенные куски земли так и носятся туда-сюда и норовят расплющить все живое.$B$BВид у тебя внушительный, |3-6($r)... Может, спустишься туда и наведешь порядок?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25851, 'ruRU', 'Танцы со Зловещим Тотемом', 'Доложитесь командиру армии Валену в лагере экспедиции Северной стражи, что в Когтистых горах.', 'Возвращайся к своему командиру и расскажи ему о том, что ты $gсделал:сделала; для клана Зловещего Тотема. Скажи ему, что Альянс теперь может спокойно ходить по нашим землям.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25852, 'ruRU', 'Все чисто', 'Доложитесь командиру Томасу Уолполу на тропе Каменного Когтя в Южных степях.', 'Собирай вещи, $n, пора присоединиться к остальным силам Северной стражи в Южных степях. Твое первое задание там будет довольно простым.$B$BДва дня назад мы получили сигнал бедствия от командира Уолпола. Его батальон попал в переделку на тропе Каменного Когтя, около Заставы Чести. Орда там просто кишмя кишит! Отправляйся туда и помоги им, а я передам новости о том, что мы заключили союз с кланом Зловещего Тотема, командованию Северной стражи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25853, 'ruRU', 'Быстро поднятое не считается упавшим', 'Соберите 6 инструментов археолога.', 'Я здесь отвечаю за снабжение. Я, конечно, все понимаю, но удирать оттуда налегке было не лучшей идеей.$B$BВидишь ли, без инструментов археологу особо не работается. Как прикажешь доставать из земли бесценные находки – голыми руками, что ли? Если вернешься на место раскопок, забери инструменты, которые мы там побросали, ладно?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25854, 'ruRU', 'Домашний Кусандр', 'Соберите 6 подпрыгивающих яиц ящеров.', 'Подумать только – оказывается, некоторые ящеры до того умны, что из них может получиться домашний питомец! Серьезно! Я видел, как охотники их приручают.$B$BТут иногда бывает очень одиноко, даже в компании Венны... Питомец – это то, что мне нужно. Крошка-ящерчик – я назову его Кусандром – представляешь, как с ним будет весело!$B$BРаз ты там все равно уничтожаешь взрослых особей, может, принесешь мне несколько яиц? Мне нужны те, из которых детеныши уже готовы вылупиться. Их в два счета отличишь – они аж подпрыгивают.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25855, 'ruRU', 'Плоды инженерной мысли', 'Найдите 7 механизмов Бынструмента.', 'В последнее время мне стало не хватать деталей для инженерных конструкций, а теперь до меня, наконец, дошло: их воруют гноллы из стаи Мохошкуров!$B$BПонятия не имею, для чего детальки могли понадобиться гноллам, но мне они нужней. Их поди уже по всей топи растащили. Если найдешь что-нибудь, верни мне, ладно?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25856, 'ruRU', 'Шкуры кроколисков', 'Добудьте 10 шкур болотного кроколиска.', 'Я уже многие годы добываю в этих краях шкуры кроколисков, |3-6($c). Но кое-что изменилось.$B$BНе хочу докучать тебе слезливой историей, но, в общем, когда случился Катаклизм и Гавань Менетилов затопило, мой дом оказался под водой. Теперь жене и детишкам некуда податься, поэтому мне нужно заработать денег на новое жилище.$B$BУ меня уже руки от усталости отваливаются, но шкур все равно не хватает – нужно еще. Принеси мне несколько, я заплачу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25857, 'ruRU', 'Охота на Челюсти Кошмара', 'Убейте Челюсти Кошмара и заберите его шкуру.', 'Меня давно терзает искушение отправиться на большую охоту... на Челюсти Кошмара – это самый здоровый кроколиск из всех, что я видел. Добыть бы его шкуру – этих денег моей семье с лихвой хватит на то, чтобы выбраться отсюда.$B$BНо я не дурак. Одна ошибка – и я останусь без ноги, а то и вовсе без головы. Кто тогда прокормит мою семью?$B$BДа, гордиться нечем, но я предпочитаю не рисковать понапрасну. Пожалуйста, |3-6($c), помоги... убей Челюсти Кошмара за меня. На севере есть мутный пруд – там ты найдешь этого зверюгу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25858, 'ruRU', 'Просьба госпожи', 'Поговорите с Повелителем глубин Зин\'жатаром, Леди Сира\'кесс и надзирателем Идра\'кессом.$B$BЭто задание из цикла \"Видения воительницы Леди Наз\'жар\". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.', 'Леди Сира\'кесс уже начала готовиться к ритуалу призыва, но у нас украли тигель Наз\'жар. Очевидно, его прихватили с собой квалдиры, когда бежали на мелководье.$B$BПоговори с лидерами каст, собери отряд и веди его на восток, к гряде Бейл\'аран, чтобы вернуть украденный артефакт.$B$BЯ не сомневаюсь в тебе, Воительница, ибо ты ни разу меня не подводила. Сколь сильно меня почитает Королева, столь сильно почитаю тебя я. Даю тебе свое благословение.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25859, 'ruRU', 'Посторонним вход запрещен', 'Убейте 20 квалдиров на выступе Врайкулов.$B$BЭто задание из цикла \"Видения воительницы Леди Наз\'жар\". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.', 'Знаю, что тебя, как и нашу достопочтенную госпожу, порой охватывает жалость и милосердие. Но сегодня я настоятельно советую забыть о доброте: квалдиры – гордый народ, и они обязательно вернутся, чтобы отомстить, если мы их полностью не уничтожим. Так что убей всех, кого встретишь.$B$BУвы, моя задача скучна – следить за тем, чтобы никто из них не вернулся в город. А вот тебе досталось все самое интересное. Я буду болеть за тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25860, 'ruRU', 'Любой ценой', 'Убейте 20 квалдиров в храме Кель\'Дормир.$B$BЭто задание из цикла \"Видения воительницы Леди Наз\'жар\". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.', 'Необходимо немедленно приступить к ритуалу, а твоя задача – обеспечить, чтобы никто его не прервал.$B$BУбей всех квалдиров, которые зайдут в храм. Мои жрицы должны выполнить свою задачу любой ценой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25861, 'ruRU', 'Показательный пример', 'Приведите квалдирского верховного шамана к палачу Вератрессу.$B$BЭто задание из цикла \"Видения воительницы Леди Наз\'жар\". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.', 'В соседних постройках обосновались верховные шаманы. Вовсю распевают свои песни и дерзят, но выйти ко мне не решаются. Эти квалдиры храбры и сильны только во мгле – жалкое недоразумение, населившее подводный мир.$B$BУ меня есть некое послание. И если ваша светлость не слишком занята, прошу вас, приведите ко мне одного из верховных шаманов, чтобы я смог лично донести это послание до него и его народа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25862, 'ruRU', 'Украденное имущество', 'Верните украденный тигель Наз\'жар.$B$BЭто задание из цикла \"Видения воительницы Леди Наз\'жар\". Чтобы вернуться к видению, в нужный момент воспользуйтесь клинком воительницы Леди Наз\'жар.', 'Достопочтенная госпожа отправила меня к тебе на помощь. Она желает, чтобы ты вернула украденный тигель Наз\'жар как можно скорее.$B$BОна должна приступить к ритуалу призыва – и мы начнем готовиться к войне.', '', '', '', '', '', 'Верните тигель Наз\'жар.', 25549);
INSERT INTO `quest_template_locale` VALUES (25863, 'ruRU', 'Избранный груз', 'Вернитесь на запад гряды Бейл\'аран и сообщите новости о тигле Наз\'жар.$B$BЭто задание из цикла \"Видения воительницы Леди Наз\'жар\". Чтобы вернуться к видению, в нужный момент воспользуйтесь клинком воительницы Леди Наз\'жар.', 'Тигель Наз\'жар найден, и теперь осталось лишь доложить Леди Наз\'жар об успехе.', '', '', '', '', '', 'Вернитесь на запад гряды Бейл\'аран и расскажите новости о тигле Наз\'жар.', 25549);
INSERT INTO `quest_template_locale` VALUES (25864, 'ruRU', 'Неприятности с динозаврами', 'Убейте 8 ящеров нагорья любого вида.', 'Ящеры у нас тут совсем расшалились. Моя задача – следить за тем, чтобы это место оставалось безопасным и привлекательным для новых поселенцев, поэтому я назначила за головы тварей награду.$B$BОт многих мы уже избавились, но вот ящеров нагорья, что обитают на севере, становится все больше. Хотя у нас теперь есть кому с ними разобраться, не так ли?$B$BПеребей этих ящеров и возвращайся за наградой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25865, 'ruRU', 'Ограбление по-гнолльски', 'Заберите 8 стальгорнских слитков у гноллов из стаи Мохошкуров.', 'Похоже, тебе можно доверять, $n. Послушай, я прибыла сюда по заданию Стальгорна, чтобы вернуть украденную партию золотых слитков.$B$BЭто слитки из королевской сокровищницы Стальгорна, на каждом стоит королевская печать... Только кретин вздумал бы их красть – ведь отследить каждый очень легко. К несчастью, в этой местности кретинов хоть отбавляй и зовутся они Мохошкурами.$B$BНе знаю, приходилось ли тебе раньше встречаться с гноллами, но эти зверюги коварны, жестоки и очень опасны. Я хочу, чтобы ты их $gубил:убила; и $gвернул:вернула; мне слитки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25866, 'ruRU', 'Звероловы из клана Черного Железа', 'Убейте 10 звероловов из клана Черного Железа.', 'Мне доложили, что к нам в гости нагрянул клан Черного Железа, возможно, ты уже $gвидел:видела; их. У этих дворфов вечно недоброе на уме, а теперь они еще стали зачем-то похищать гноллов из стаи Мохошкуров.$B$BНе понимаю, что они затевают, но этому надо положить конец, пока они еще чего похуже не удумали. Остановить этих дворфов – твоя задача.$B$BА если тебе хочется сделать все по-благородному – попробуй-ка сначала у них вежливо поинтересоваться, что это они замыслили. Увидишь, что получится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25867, 'ruRU', 'Свободу гноллам', 'Заберите ключи зверолова у звероловов из клана Черного Железа, отоприте клетки гноллов и выпустите на волю 6 гноллов.', 'Да мы и сами гноллов не больно-то жалуем, но это не значит, что можно позволять Черному Железу делать из них рабов. Понимаешь, гноллы нас обворовали, мы им за это вломили – все по справедливости; а тут их хотят использовать в каких-то злодейских целях. Этого я сделать не позволю.$B$BКороче говоря, гноллов надо освободить. У звероловов должны быть при себе ключи – забери их и отопри клетки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25868, 'ruRU', 'Йорла Темная Петля', 'Убейте Йорлу Темную Петлю.', 'Я, наконец, выяснила, кто стоит во главе всей этой операции. Приказы дворфам Черного Железа исходят из лагеря на востоке, от Йорлы Темной Петли. Возможно даже, что это именно по ее наущению гноллы и решились украсть золото Стальгорна.$B$BСкажу больше – она известная преступница, и за ее голову назначена награда... Она призывала дворфов восстать против Стальгорна еще в те времена, когда Магни был жив.$B$BТакой шанс нельзя упустить, $n. Иди и прикончи ее!', '', 'Иди и убей ее!', 'Йорла Темная Петля', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25869, 'ruRU', 'Выдворение Зловещего Тотема', 'Убейте 10 захватчиков из клана Зловещего Тотема.', 'Твоим первым заданием будет уничтожение захватчиков из Зловещего Тотема здесь, на заставе Вольного Ветра. Если ты не сумеешь дать им отпор тут, мы не сможем начать наступление на их территории.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25870, 'ruRU', 'Выдворение Зловещего Тотема', 'Убейте 10 захватчиков из клана Зловещего Тотема.', 'Нужно разделаться с захватчиками из Зловещего Тотема тут, на Заставе Вольного Ветра. Эти коварные твари сами напросились!$B$BМы не можем напасть на их земли, когда их войска у нас в тылу. Молю, помоги нам отвоевать наш дом, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25871, 'ruRU', 'Спасение часового', 'Освободите часового Фераласа.', '<Бриенна размахивает запиской, испещренной тауренскими письменами.>$B$BЭти чудовища захватили одну из наших часовых! И угрожают убить ее, если мы не отступим!$B$BНо мы не ведем переговоров с трусливыми врагами! Пожалуйста, вызволи ее, пока еще не слишком поздно, |3-6($c).', '', 'Освободи ее, пока не стало слишком поздно.', 'Пойманный часовой Фераласа', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25872, 'ruRU', 'Без страха и упрека', 'Выручите храбреца заставы Вольного Ветра.', '<Рау размахивает запиской, испещренной тауренскими письменами.>$B$BЭти грязнокровки пленили одного из наших храбрецов! И угрожают убить его, если мы не отступим!$B$BНо мы ни за что не позволим коварному клану Зловещего Тотема остаться на заставе Вольного Ветра! Пожалуйста, выручи храбреца, пока не поздно, |3-6($c).', '', 'Освободите его, пока не поздно.', 'Пойманный храбрец с Заставы Вольного Ветра', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25873, 'ruRU', 'Рог предателя', 'Добудьте рог Долгорога.', 'Вы натыкаетесь на бренное тело Монтарра, сказителя заставы Вольного Ветра. Тело престарелого таурена переломано и лежит в луже его собственной крови.$B$BДорожка из алых капель стелется к дверям таверны...', '', 'Предатель! Лишите его оставшегося рога!', 'Дозорный утесов Долгорог', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25874, 'ruRU', 'Рог предателя', 'Добудьте рог Долгорога.', 'Вы натыкаетесь на бренное тело Монтарра, сказителя заставы Вольного Ветра. Тело престарелого таурена переломано и лежит в луже его собственной крови.$B$BДорожка из алых капель стелется к дверям таверны...', '', 'Предатель! Лишите его оставшегося рога!', 'Дозорный утесов Долгорог', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25875, 'ruRU', 'Гном с той стороны', 'Найдите Минкс, которая маскируется под \"гоблина\" – смотрителя помпы на Илоразработках в Когтистых горах.', 'Туманное озеро кишит тварями Орды. Гоблины устроили там завод и не собираются оттуда уходить, пока не выкачают всю нефть из Когтистых гор.$B$BПо счастью, на той стороне у меня есть один гном, который собирает для нас информацию. Если кто и знает, что происходит с той бомбой, то это мой засланный гном.$B$BОтправляйся к илоразработкам, что к северу отсюда, и найди Минкс. Она будет переодета в гоблина техника помпы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25876, 'ruRU', 'Это там!', 'Украдите Кром\'гарский буровой журнал.', 'Слушай, я отслеживала эту бомбу с тех пор, как ты $gспас:спасла; меня в Ясеневом лесу. Что бы они ни намеревались с ней сделать, это случится скоро.$B$BНа вершине большой буровой вышки находится диспетчерская. В ней ты найдешь Кром\'гарский буровой журнал. В нем ключ к тому, для чего предназначена эта бомба. Ступай туда и добудь журнал! Принеси его сюда, и я его тебе расшифрую.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25877, 'ruRU', 'Не время раскланиваться!', 'Вернитесь к командиру разведчиков Барусу на пост на Мутном озере в Когтистых горах.', 'БЕГИ! Уходи отсюда, $n. Возвращайся к Барусу и расскажи ему о том, что ты $gузнал:узнала;. Он поможет тебе безопасно пересечь долину Боевого Шрама и добраться до дозорного холма Тал\'дары.$B$BМы еще успеем спасти наших юных друидов!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25878, 'ruRU', 'План саботажа', 'Используйте пульты управления гоблинскими помпами, чтобы уничтожить 4 гоблинских нефтяных насоса.', 'Гоблины... Каким был бы этот мир без гоблинов? Я тебе скажу, каким: ЧИСТЫМ!$B$BЭти грязные мелкие грязееды понатыкали нефтяных насосов вокруг озера и высасывают оттуда до капли всю нефть, какая только есть в Когтистых горах. А у каждого насоса они поставили по смотрителю, единственная задача которых – следить за насосами, чтобы ничего не пошло вкривь-вкось.$B$BНо кое-что у них-таки пойдет вкривь-вкось.$B$BПеребей смотрителей гоблинских помп и нарушь им управление насосами. Пусть у них насосы порвет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25879, 'ruRU', 'Проблема болвана неотесанного', 'Перебейте 10 болванчиков.', 'Тебе приходилось видеть хобгоблинов? Это еще одно мерзкое гоблячье создание. Берешь гоблина, делаешь его еще уродливее, толще, больше и тупее – и вот он, хобгоблин. Добавить мерзостности – и вот она, проблема.$B$BЭти дурни неотесанные шатаются по Илоразработкам и у Мутного озера, а гоблины используют их как грубую рабочую силу.$B$BТопай отсюда и истреби их. Раз и навсегда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25880, 'ruRU', 'Предупредить мастера Тал\'дару', 'Отнесите весть мастеру Тал\'даре на дозорный холм Тал\'дары в Когтистых горах.', 'В роще Тал\'дары – десятки учеников. Большинство из них не смогут себя защитить, так что их легко перебить.$B$BОтнеси мастеру Тал\'даре известия о планах Орды. Он скажет, что тебе делать дальше.$B$BФиора Подлунный Полет разрешает тебе взять ее самого быстрого гиппогрифа. Лети скорее на дозорный холм Тал\'дары! Не тяни, $n! Орду надо остановить!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25881, 'ruRU', 'Выжившие стражи', 'Найдите и спасите 8 выживших стражей', 'Мы держались, сколько могли, |3-6($c). В обжигающем огне... изнемогая от жары... Мы потеряли весь город.$B$BКапитан Железный Лес не захотел отступать, когда нас охватило пламя. Наши войска рассеяны. Может, есть выжившие? Мы могли бы предпринять контратаку!$B$BОтправляйся на Выжженную равнину и спаси выживших стражей, которые оказались отрезаны от основного отряда. Затем найди капитана Железного Леса. Он, должно быть, занял укрепленную позицию где-то в гуще битвы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25882, 'ruRU', 'Помощь на ферме', 'Поговорите с сержантом Кремнемолотом на ферме Янтарленов.', 'Капитан Тарран просил меня передать тебе благодарность за помощь и поздравления с успешным завершением миссии. Он со своими людьми заканчивает борьбу с троллями и направляется к раненым.$b$bОн также просил меня обратиться к тебе за помощью по проверке отчетов о набегах троллей на ферму Янтарленов. Когда прибудешь туда, спроси сержанта Кремнемолота.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25883, 'ruRU', 'Найти и обезвредить', 'Уничтожьте 6 комплектов трезубцев наг.', 'Оружие наг...$B$BОсматривая загоны наг, вы видите десятки одинаковых, стратегически расположенных стоек с трезубцами.$B$BУничтожив это оружие, можно сорвать коварные планы врага...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25884, 'ruRU', 'Будь что будет!', 'Убейте 12 наг Зин\'жатара на Жемчужной ферме в лесу Келп’тар.', 'Ох, да чтоб меня...$B$BПонимаю, наш выживший друг нам добра желает, но ты не забывай, что его все же неслабо контузило.$B$BОт этих мерзких тварей может избавить только топор дворфов, по рукоять загнанный в их черепушки.$B$BНавали кучу из их трупов – пускай дважды подумают, стоит ли зариться на твои прелести.$B$BПомяни мое слово, $gпарнишка:милочка;, этим негодяям вид собственной крови доставляет не больше радости, чем мне или тебе.$B$BТеперь иди и задай им!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25885, 'ruRU', 'Ой-ой – что со мной?', 'Соберите 7 побегов вьющихся водорослей у жнецов Мерцающего хребта на Жемчужной ферме.', 'Ох... да что ж такое?!$B$BВнутри все болит... и крутит...$B$BПохоже... эх... Меня отравили!$B$BНас накормили какими-то странными светящимися водорослями, которые выращиваются у крепости.$B$BМне кажется, живот схватит еще сильнее, если не съесть еще маленько...$B$BПрошу тебя, |3-6($r), принеси водорослей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25886, 'ruRU', 'Закрепление успехов', 'Истребите 4 сумеречных полевых командиров.', 'Кажется, последователи культа Сумеречного Молота отступили, чтобы перегруппироваться для нового нападения. Наиболее рьяные адепты остались сзади, чтобы прикрыть тыл. У нас есть возможность ударить по их военачальникам.$B$BОбогни Выжженную равнину и истреби сумеречных полевых командиров.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25887, 'ruRU', 'Волна разрушения', 'С помощью сферы внушения укротите изголодавшихся больших акул, затем натравите их на 12 стражей Зин\'жатара на Жемчужной ферме.', 'Наше время здесь истекает. Надо бы выяснить, зачем наги берут пленных, раз уж мы хотим понять, что они тут затевают.$B$BНо прежде надо разрушить их планы!$B$BСделать это трудно – наг там тьма-тьмущая, но у меня есть идея.$B$BЗа стенами этой пещеры вытесненные нагами голодные акулы рыщут в поисках пропитания.$B$BСлабых рыб легко подчинить. Возьми эту сферу внушения, подчини акул и натрави на наг.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25888, 'ruRU', 'Декомпрессия', 'Воспользуйтесь камнем дыхания Моаны, чтобы выручить 10 пленных солдат на Жемчужной ферме.', 'Мысль о том, что множество солдат, как этот, томится в плену у наг, просто невыносима.$B$BМы должны любой ценой их выручить!$B$BПопробуй вот это, $n. Сделай так, чтобы в камерах было чем дышать.$B$BЕсли удастся поднять бойцов на поверхность, у нас будет шанс их спасти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25889, 'ruRU', 'Спасите детей!', 'С помощью гиппогрифа мастера Тал\'дары спасите 5 молодых беспомощных друидов из рощи Тал\'дары.', 'Мои бедные, беззащитные юные ученики остались в роще Тал\'дары. В долине Боевого Шрама кипит бой, и им никак оттуда не выбраться! Нужно спасти этих детей, пока Орда не сбросила туда свои бомбы!$B$BВозьми моего гиппогрифа, он поможет тебе спасти юных друидов из рощи Тал\'дары. Оставишь их здесь, на городской стоянке гиппогрифов.$B$BСпаси всех, $n! Ведь, кроме тебя, нам не на кого надеяться!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25890, 'ruRU', 'Неспира', 'Войдите в раковину Неспиры через северо-западный вход и найдите способ с ней поговорить.', 'Я прекрасно знаю, что нам надо сейчас делать, $n.$B$BНаги могли добыть эти жемчужины только в одном месте: в Неспире, древнем существе, живущем в раковине неподалеку от этой пещеры. Одно мне совершенно непонятно – как нагам удалось подчинить себе Неспиру?$B$BРядом с выходом из пещеры небольшое отверстие – через него мы сможем попасть в раковину Неспиры. Но сначала мне нужно найти моего хозяина. Встретимся на месте, у северо-западного входа в раковину Неспиры.', 'Найдите способ поговорить с Неспирой', '', '', '', '', 'Поговорите с Целителем Земли Дуарном в Неспире в Вайш\'ире.', 25549);
INSERT INTO `quest_template_locale` VALUES (25891, 'ruRU', 'Последний заход', 'Помогите мастеру Тал\'даре найти уцелевших друидов в роще Тал\'дары.', 'Орда дала сигнал к отступлению. Смотри-ка: они уходят с поля боя, а ведь сколько зла принесли!$B$BМы должны наведаться в рощу Тал\'дары в последний раз. Я никогда не прощу себе, если мы оставим там хотя бы одного выжившего друида.$B$BПомоги мне, $gгерой:героиня;. Я возьму поводья, а ты смотри в оба: нет ли там уцелевших?$B$BОтправимся, как только ты будешь $gготов:готова;.', 'Поиск последних уцелевших бойцов завершен', '', '', '', '', 'Поговорите с мастером Тал\'дарой на его дозорном холме в Когтистых горах.', 25549);
INSERT INTO `quest_template_locale` VALUES (25892, 'ruRU', 'Отступление', 'Воспользуйтесь морским коньком говорящей с волнами Валорен, чтобы вернуться к адмиралу Двореку, находящемуся под южной террасой в Руинах Вайш\'ира.', 'Придется подождать с разговором: сейчас нужно уходить, пока наги не прорвались. Постарайся добраться до форпоста ярусом ниже.$B$BВозьми моего морского конька. Встретимся там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25893, 'ruRU', 'Отчаянный план', 'Встретьтесь с инженером Мегагексом на гряде Бейл\'аран.', 'Джорлан и Мегагекс отправились за помощью. Неподалеку проходят торговые маршруты, и шансы найти подмогу есть, но я бы не стал слишком на это надеяться.$B$BОткровенно говоря, это наша единственная надежда. Долго мы здесь не продержимся: рано или поздно наги найдут нас, и тогда... ну... ты $gсам видел:сама видела;, сколько их там.$B$BОтправляйся на юго-восток к гряде Бейл\'аран и разыщи наших двоих храбрецов. Я постараюсь защитить оставшихся здесь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25894, 'ruRU', 'Опасные воды', 'Уничтожьте 10 слизнешкурых хапуг.', 'С одного из наших кораблей Мегагекс утащил воздушный шар. Он попытался поднять шар на поверхность, но тут откуда ни возьмись появились слизнешкурые хапуги и разодрали шар в клочья.$B$BТеперь Мегагекс хочет запустить второй шар, но история не должна повториться. Уничтожь-ка ты всех этих жаблинов... Или убей столько, чтобы они побоялись снова к нам сунуться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25895, 'ruRU', 'Наготове', 'Достаньте ящик Альянса с предметами первой необходимости.', 'Нужно всегда все иметь наготове. Технику. Планы. Планы на технику!$B$BНа каждом корабле Альянса должен быть ящик с набором для выживания. У меня был воздушный шар из старого ящика, но недавно ему пришел быстрый и печальный конец, поэтому мне нужен еще один ящик.$B$BК юго-востоку отсюда ты найдешь корабль. Будем надеяться, что выжившие матросы совсем потеряли головы во время бегства и не догадались забрать с собой этот замечательный ящик. Их промашка может стать нашим спасением.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25896, 'ruRU', 'Сбор на ритуал', 'Найдите призывателя глубин Азражара на полпути вниз по северной лестнице и 6 жриц прилива Сира\'кесс в верхней части руин, после чего попросите их вернуться в храм.$B$BЭто задание из цикла \"Видения воительницы Леди Наз\'жар\". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.', 'А, это ты, Воительница. Ты несешь с собой слово и волю госпожи. У меня к тебе просьба...$B$BМне нужно, чтобы сюда вернулись призыватель глубин Азражар и жрицы прилива. Их присутствие необходимо для ритуала. Передашь им мою просьбу? Они где-то на террасе храма. Азражара можно найти на лестнице к северу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25897, 'ruRU', 'Веревочный план', 'Добудьте 8 мотков квалдирской веревки.', 'В ящике с предметами первой необходимости нет веревки... Вопиющая халатность!$B$BБьюсь об заклад, у квалдиров должна быть веревка. Они же чуть не живут на лодках, вяжут узлы да одеваются в сети. Иди-ка отбери у них веревку! Без этого наш план яйца выеденного не стоит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25898, 'ruRU', 'Честь и слава', 'Поднимитесь на поверхность, возьмите сигнальное ружье и запустите сигнальную ракету в направлении кораблей Альянса.', 'Готово! Я уверен, все получится. И в этот раз никаких слизнешкуров! Какая удача.$B$BДжорлан уже отправился наверх ловить шар, но честь ведения операции предоставил тебе. Вот такой он добрый.$B$BПоднимись к шару, возьми сигнальное ружье и посмотри, нет ли поблизости кораблей Альянса. Если такой увидишь, стреляй сигнальной ракетой. Собственно, и все.$B$BПлывешь. Поднимаешься на поверхность. Запускаешь ракету. И помощь приходит! Последний пункт мне нравится больше всего.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25899, 'ruRU', 'Прорыв', 'Уничтожьте 10 выжигателей из культа Сумеречного Молота.', 'Огненная армия, принесшая смерть и разрушение на эту гору, отступила к востоку. Тут остались лишь сумеречные выжигатели. Если пробьемся сквозь их строй, то сможем воссоединиться с силами капитана Железного Леса и остановить их продвижение.$B$BЯ больше не в силах вести бой, |3-6($c), но ты, кажется, находишься в лучшей форме. Уничтожь сумеречных выжигателей и пробейся к капитану Железному Лесу!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25900, 'ruRU', 'Контакт', 'Проследите за тем, как Целитель Земли Дуарн попытается заговорить с Неспирой.', 'Не верится, что Неспира сама позволила нагам расположиться в своей раковине. Но я вижу только два возможных объяснения: либо наги убедили ее встать на их сторону, либо довели до такого состояния, что она не смогла сопротивляться. В любом случае дело плохо.$B$BВ этой полости я смогу поговорить с самой Неспирой. Нам нужно выяснить, в чем дело. Когда будешь $gготов:готова;, скажи мне.', 'Поговорите с Целителем Земли Дуарном', '', '', '', '', 'Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.', 25549);
INSERT INTO `quest_template_locale` VALUES (25901, 'ruRU', 'План очищения Хиджала', 'Соберите 15 стрел стража.', 'Подкрепление! Я уж думал, что мы погибнем.$B$BВ живых осталось всего несколько защитников Хиджала, и наши запасы иссякают. На поле боя за стенами этого укрепления должно быть разбросано много стрел, пригодных для битвы.$B$BЗнаю, что данная просьба слишком мелочна для тебя, но не $gмог:могла; бы ты помочь нам их собрать? Это единственный путь пополнить наши запасы!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25904, 'ruRU', 'Молот и Ключ', 'Убейте сумеречного полевого командира и добудьте символ Открытия.', 'Немесис. Он все еще жив.$BСлуги огня продолжают приходить.$BМы должны сами прийти к ним. Прямо в их логово.$B$BОгры знают туда дорогу.$BУбей полевых командиров.$BДобудь символ Открытия.$B$BТы найдешь путь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25905, 'ruRU', 'Бараны в бегах', 'Выведите с холмов Тандрид 6 украденных баранов, используя /свист.', 'Горные пехотинцы Дун Морога всегда выбирали баранов, которых мы растим и объезжаем на ферме Янтарленов. Да, их еще немного осталось, но недостаточно для того, чтобы обеспечить мою семью и сохранить других животных.$b$bНалетчики Мерзлогривов повадились воровать наших баранов под покровом ночи и переправлять их на юг, в холмы Тандрид. Не можешь ли помочь вернуть их? Нужно подобраться к ним достаточно быстро и резко свистнуть, чтобы привлечь их внимание. Дальше они вспомнят, чему их учили.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25906, 'ruRU', 'Третьи огненные врата', 'Пройдите через огненные врата на Огненные Просторы и найдите там Гарунда Горного Пика.', 'Хорошенько запомни этот символ.$BЗапечатлей его в своей памяти.$B$BНарисуй его на земле перед огненными вратами.$BК востоку отсюда.$BСтупи на Огненные Просторы.$B$BЯ не смогу пойти с тобой.$BНо мои дети уже ждут тебя. Внутри.$B$BНайди Гарунда Горного Пика в мире пламени.', '', '', '', '', '', 'Пройдите через огненные врата на Огненные просторы и найдите там Гарунда Горного Пика.', 25549);
INSERT INTO `quest_template_locale` VALUES (25907, 'ruRU', 'Рабский труд', 'Воспользуйтесь веревкой Дуарна, чтобы освободить 8 порабощенных добытчиков жемчуга.', 'Мне понадобится время, чтобы преодолеть этот барьер и поговорить с Неспирой. А ты пока можешь заняться освобождением людей, которых держат в рабстве наги.$B$B<Дуарн достает веревку из своего балахона.>$B$BВозьми, тебе пригодится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25908, 'ruRU', 'Уничтожить врага', 'Убейте по 7 часовых и чародеек Идра\'кесса.', 'Я никак не могу связаться с Неспирой, но все же кое-что ощущаю – например, ей не нравится, что в ней расположились наги.$B$BКогда мы впервые сюда пришли, я видел, что главную полость стерегут десятки часовых и чародеек. Вполне возможно, что, если ты уничтожишь их, Неспире станет легче.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25909, 'ruRU', 'Захват краба', 'Поймайте сетью Дуарна глубинного краба в Неспире.', 'Всем своим существом я ощущаю, что Неспира хочет говорить со мной, но я ее не слышу. Видимо, наги как-то препятствуют этому.$B$B<Дуарн какое-то время молча размышляет.>$B$BПохоже, что-то не дает ей говорить... Необходимо найти то, что послужит ей голосом...$B$BПридумал! Известно, что Идра\'кесс приручают глубинных крабов и выращивают из них помощников в бою. Поймай этой сетью одного краба и принеси мне. Они обитают у внешних границ полости.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25910, 'ruRU', 'Пощады больше не будет', 'Убейте 10 раскаленных мучителей и 4 мастеров пламени Тьмы.', 'Жуткая пещерка, $n, и населяют ее сплошные порождения глубинных кошмаров.$B$BЯ не хочу, чтобы кто-нибудь из них улизнул сквозь портал во внешний мир. Убей всех, кого увидишь!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25911, 'ruRU', 'Добрые вести', 'Вернитесь к капитану Тейлору в Тихий залив.', 'Они, наверное, вышлют лодку. Но на это надо время. Я останусь здесь и вступлю в переговоры.$B$BА ты немедленно возвращайся в пещеру и скажи там, что помощь уже на подходе. Будем надеяться, наги их не обнаружили.$B$BДавай, $n. Плыви. И постарайся обернуться побыстрее.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25912, 'ruRU', 'Что за времена...', 'Найдите записную книжку предка Сарет\'ны.', 'Вокруг нас появляется новый мир, $n. Старые враги пытаются уничтожить нас с одной стороны, а на другой тем временем собираются древние силы.$B$B<Предок Сарет\'на вздыхает.>$B$BЯ помню другие времена, они были куда лучше, и мне их очень не хватает...$B$BНа пике Каменного Когтя остались руины нашей заставы, теперь там одна нечисть. Если тебе вдруг доведется попасть туда, не $gмог:могла; бы ты поискать там мою записную книжку? Там все мои воспоминания... А уж за наградой я не постою.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25913, 'ruRU', 'Даровать им покой', 'Принесите 8 глеф часовых.', 'Когда Орда маршировала по Когтистым горам, я заметил, что некоторые часовые будто бы чем-то заболели. Потом они начали странно вести себя, а когда из-под земли показалось первое щупальце, больные часовые набросились на нас, и вскоре после этого мы потеряли заставу...$B$BОт часовых на том пике теперь остались одни оболочки, этакие вместилища для какого-то кошмарного ужаса. Я хочу, чтобы ты $gдаровал:даровала; им покой и $gзабрал:забрала; их глефы. По каждой глефе можно будет опознать павшую сестру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25914, 'ruRU', 'Назад, в глубины!', 'Убейте предвестника Аф\'ласса и 10 щупалец-захватчиков.', 'Из земли лезут щупальца, и на пике Каменного Когтя царит паника. Мои часовые сражаются с щупальцами, но погоды это практически не делает.$B$BПодозреваю, что под пиком Каменного Когтя обитает некая сила, которая управляет щупальцами. Может, если бы нам удалось уничтожить ее, то и щупальца бы вернулись обратно под землю, откуда они повылезали!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25915, 'ruRU', 'Сила Тортоллы', 'Проводите дитя Тортоллы к кристаллу Немесиса. Если вы потеряете своего спутника, вернитесь к Гарунду Горному Пику.', 'Гнусный захватчик Немесис укрылся здесь, когда нам удалось оттеснить огонь, охвативший Хиджал. У нас пока не хватает сил, чтобы сразиться с Немесисом в открытую, $n, но мы можем обратить против него его же силы.$B$BЯ пошлю с тобой дитя Тортоллы – одного из тех, кого тебе удалось освободить от власти Сумеречного Молота.$B$BОтыщи кристалл Немесиса в глубине пещеры и позволь юной черепахе исследовать его.$B$BНайди меня, если ты потеряешь своего спутника!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25916, 'ruRU', 'Прорыв', 'Проследите за тем, как Целитель Земли Дуарн попытается заговорить с Неспирой.', 'Хорошо известно, что опытный шаман умеет взаимодействовать со всеми четырьмя элементами стихий: землей, огнем, водой и воздухом.$B$BОднако далеко не все знают, что существует и пятый элемент. Он не имеет такого же четкого определения, как остальные... О нем можно сказать только то, что он является связующим звеном между всем живым на планете.$B$BЯ пришел к выводу о том, что краб, как морской обитатель, находится ближе всего к Неспире, поэтому с помощью всех элементов можно убедить его взять на себя роль голоса Неспиры.', 'Поговорите с Целителем Земли Дуарном', '', '', '', '', 'Вернитесь к целителю земли Дуарну в Неспиру в Вайш\'ире.', 25549);
INSERT INTO `quest_template_locale` VALUES (25917, 'ruRU', 'Мы не одиноки', 'Отыщите в Неспире, что в Вайш\'ире, выживших Альянса.', '<Дуарн закрывает глаза, на мгновение застывает, затем кивает.>$B$BНеспира только что сообщила мне, что мы в этой раковине не одни. Небольшая группа из Альянса сражается с нагами на другой стороне раковины, прямо на возвышенности, что над сердцем Неспиры.$B$BСтупай, отыщи их, $n. Возможно, они смогут нам чем-то помочь. А вместе мы, быть может, выведем Неспиру из оцепенения.$B$BЕсли тебе что-нибудь понадобится, я буду здесь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25918, 'ruRU', 'Безоружные', 'Принесите 4 похищенных трезубца с оружейных стоек в Неспире.', 'Честно говоря, я не понимаю, почему мы до сих пор живы. Наги захватили все мое оружие и доспехи. У меня остались только какие-то лохмотья и шахтерская кирка, которая к тому же давным-давно пополам сломалась.$B$BМне нужно хоть какое-то оружие... Да, и моим товарищам тоже, хоть гордость и не позволяет им это признать.$B$BЯ видел стойки с оружием на ближайших складах наг. Мне еще никогда не доводилось сражаться трезубцем, но в любом случае лучше идти в бой с ним, чем с голыми руками.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25919, 'ruRU', 'Удар по телу', 'Ударьте Неспиру в 7 гнойников, расположенных на стенах ее полости.', '<Капитан Тейлор внимательно слушает ваш пересказ разговора Дуарна с Неспирой.>$B$BПонятно. Значит, она хочет, чтобы мы помогли ей проснуться, так?$B$BЕсли учесть, что сотни рабов уже собирают ее жемчужины, то, похоже, ее из пушки не разбудишь. Но, может, у тебя и получится.$B$BЯ вот что предлагаю: хорошенько ее осмотри и попробуй найти слабое место. Быть может, если ударить в чувствительную точку, она придет в себя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25920, 'ruRU', 'Ценные вещи', 'Добудьте у полководцев и пророков Идра\'кесса в Неспире 5 таинственных жемчужин.', 'Я недолго пробыла на жемчужных полях и так и не поняла, какие же цели преследуют наги. Известно, что они хотят использовать Неспиру в качестве орудия войны, но зачем тогда заставляют рабов добывать ее жемчуг?$B$BЕсли нам удастся отсюда выбраться, я бы хотела хорошенько изучить эти жемчужины. Правда, те, что нашли мы, были слишком большими. Нам их не унести. Но я видела в руках у полководцев и пророков жемчуг помельче.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25921, 'ruRU', 'Надзиратель Идра\'кесс', 'Отправляйтесь в верхнюю полость Неспиры и убейте надзирателя Идра\'кесса.', 'Мои воины измождены, $n. Боюсь, мы недолго продержимся против наг. Теперь у нас есть оружие Идра\'кесса и жемчуг Неспиры; пора выбираться отсюда.$b$bДвигайся вдоль стены на юго-восток и ищи подъем в верхнюю полость. Полагаю, их лидер находится где-то там. Возможно, там же скрывается и разгадка к пробуждению Неспиры. Надеюсь, и то, и другое сразу.$b$bЕсли посмеешь отважиться на такое, то ступай в верхнюю полость и попробуй найти ответы на наши вопросы.', '', 'Осквернитель Неспиры', 'Надзиратель Идра\'кесс', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25922, 'ruRU', 'Пробуждение', 'Поговорите с Целителем Земли Дуарном в Неспире, чтобы запустить защитные процессы. Затем покиньте тело Неспиры.', 'Благодаря вашей с капитаном помощи Неспира вышла из оцепенения. Но большинству наг это пока неизвестно. Как только мы уйдем, Неспира запустит в своем теле защитные биологические процессы и уничтожит наг.$B$BПриготовься, а я пока скажу Неспире начать обратный отсчет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25923, 'ruRU', 'Покончить с Немесисом', 'Используйте тотем Тортоллы и победите Немесиса вместе со своим спутником. Если вы потеряете дитя Тортоллы, вернитесь к Гарунду Горному Пику.', 'Черепашка, что сопровождает тебя, может использовать обретенную силу, чтобы на какое-то время сделать вас обоих неуязвимыми. С ее помощью вы сможете пережить самые сильные удары Немесиса. Используйте вот этот тотем.$B$BЭто все, что я могу для тебя сделать. Ты и дитя Тортоллы сокрушите Немесиса раз и навсегда. Покончите с узурпатором!$B$BНайди меня, если ты потеряешь своего спутника.', '', 'Воспользуйтесь тотемом и помощью вашего спутника, черепахи, чтобы выжить во время схватки с противником. С лжебогом нужно покончить!', 'Немесис Узурпатор', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25924, 'ruRU', 'Зов долга', 'Отправляйтесь в бой на корабле наемников.', 'Послушай-ка, |3-6($r)!$B$BВозле побережья Восточных королевств образовался новый остров – и там идет тяжелая битва за эту землю!$B$BВ случае нашей победы Штормград будет совершенно беззащитен!$B$BПришло время нанести удар!$B$BЯвись с докладом в гавань, чтобы отправиться к месту битвы.$B$BВсе военные суда уже в бою, так что поднимешься на борт корабля наемников, который зафрахтовал сам вождь.', 'Отправляйтесь в Вайш\'ир на корабле наемников', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25925, 'ruRU', 'Месть Тал\'дары', 'Убейте 20 солдат Орды и уничтожьте 3 кром\'гарских разрушителя в долине Боевого Шрама.', 'Нужно попытаться восстановить связь с Плато Наблюдателей, это к югу отсюда. Наши дарнасские метатели глеф к твоим услугам, $n. Они помогут тебе пробиться через ордынских захватчиков и проложить путь до плато.$B$BЛишь бы нам не опоздать... Если до Плато Наблюдателей пока не добрались, найди там иерофанта Малика и расскажи ему о том, как у нас идут дела.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25926, 'ruRU', 'Погрязшие в трясине ненависти', 'Убейте 10 тлеющих трясинников.', 'Трясинники, что обитают к западу отсюда, – не братья мне... Они – вопль израненной земли, воплощение мерзостного процесса гниения.$B$BТебе не понять... Кишащие внутри гнилостными спорами, они принимают облик моих сородичей и выдавливают жизнь из болота. Они забирают все, оставляя взамен только разложение. Ничего не осталось, ничего!$B$BПомоги мне обрести покой, |3-6($r). Убей трясинников, очисти землю, и тогда, быть может, душа моя перестанет терзаться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25927, 'ruRU', 'Устрашающее пламя', 'Убейте 8 буйных элементалей огня.', 'Слишком долго пламя угрожало мне... Слишком долго... Но теперь страдают уже не мелкие земные твари, не какие-то жалкие букашки...$B$BГорят поля! Холмы и нагорья кричат, |3-6($r), они кричат от боли. Элементали, вызванные сюда, пожирают все живое вокруг себя.$B$BОт них нет спасения. Останови их, ОСТАНОВИ! Уничтожь тех, кто разжигает пламя...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25928, 'ruRU', 'Триумф Тортоллы', 'Пройдите сквозь огненные врата и вернитесь к Тортолле на Выжженную равнину на Хиджале.', 'Я выведу отсюда детей Тортоллы и запечатаю оскверненный портал.$B$BА ты отправляйся к Тортолле и расскажи ему о нашей победе. Просто пройди через огненные врата. Древний будет доволен!', '', '', '', '', '', 'Пройдите сквозь огненные врата и вернитесь к Тортолле на Выжженную равнину на Хиджале.', 25549);
INSERT INTO `quest_template_locale` VALUES (25929, 'ruRU', 'Морской волк', 'Добудьте с морского дна в Судьбе Легиона 3 солоноводных морских звезды и раковину стромбиды.', 'Приветствую тебя, |3-6($c). Меня зовут Эрунак, мне тоже удалось выжить.$B$BОднако боюсь, неприятности у тебя только начались. В здешних водах рыщут наги, они нападают на все живое.$B$BА ты слишком $gнеприспособлен:неприспособлена; и можешь погибнуть, но я тебе помогу.$B$BРядом с этим кораблем обитает особая разновидность морских звезд. Поймай несколько штук, да раздобудь раковину стромбиды. Я подготовлю заклинание, которое повысит твои шансы на выживание.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25930, 'ruRU', 'Подъем в долину', 'Используйте ракетный агрегат Сэлсбери для подъема на вулкан Обугленной долины.', 'Мне сказали, что до большого смещения пластов Обугленная долина была долиной, отрезанной от моря. А теперь стоит только бросить взгляд на юг, чтобы понять, что Обугленная долина вообще не долина, а центр высокой вулканической активности.$B$BСэлсбери тут сваял устройство, которое позволит нам подняться к жерлу вулкана. Используй его, чтобы забраться на вершину и посмотреть, что там да как.$B$BЯ буду на связи при помощи этого ГНМ-передатчика, который Сэлсбери любезно предоставил в мое распоряжение.', 'Подъем на вулкан Обугленной долины', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25931, 'ruRU', 'Потомство Селдаррии', 'Уничтожьте 5 яиц Селдаррии.', '<ГНМ-передатчик жужжит.>$B$BОсторожно, $n. Не надо тебе будить этого черного дракона.$B$BТеперь осмотрись по сторонам. Если это гнездо, то тут где-то должны быть яйца черного дракона. Поищи их и уничтожь все, какие увидишь.$B$BВозвращайся, как только найдешь и уничтожишь яйца Селдаррии.$B$BДа пребудет с тобой Голдринн!', '', 'Осторожно. Достаточно одной ошибки, и все пропало.', 'Иерофант Малик', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25932, 'ruRU', 'Набеги ночь за ночью', 'Помогите сержанту Кремнемолоту и его горным пехотинцам защитить ферму Янтарленов от налетчиков из клана Мерзлогривов.', 'Донесения, которые я отправляю капитану Таррану, не могут передать всего масштаба проблем, которые мы испытываем от Мерзлогривов. Твое нападение на деревню дало небольшую передышку. Набеги троллей по-прежнему часты, но их ряды поредели.$b$bНо даже несмотря на это, мои люди устали и их боевой дух упал. Не можешь ли ты помочь нам в борьбе против налетчиков Мерзлогривов? Они могут вернуться в любое время.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25933, 'ruRU', 'Помощь карьеру', 'Поговорите со штейгером Камнелобом в карьере Гол\'Болар.', 'Спасибо за все, чем ты $gпомог:помогла; нам здесь, $n.$b$bМой двоюродный брат работает на руднике в карьере Гол\'Болар, но с тех пор, как трогги наводнили рудник и контролируют его, работать там стало невозможно. Карьер и лагерь находятся к юго-востоку от фермы. Не поговоришь ли ты со штейгером, чтобы выяснить, что можно сделать?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25934, 'ruRU', 'Первый в мире гнорген', 'Добудьте 1 пылающее сердце огня.', 'Приветствую, $gгражданин:гражданка; позволь мне представиться. Я Сэлсбери, и скоро я стану первым в мире гноргеном. Малик заверил меня, что как только моя работа здесь будет завершена, он даст мне дар воргенов.$B$BТак, с формальностями покончено, теперь к делу!$B$BВ Обугленной долине, к югу отсюда, бродят недавно созданные огненные элементали. Мне отчаянно нужно редкое пылающее сердце огня с одного из этих духов. Добудь его мне, и я на один шаг стану ближе к моей цели – стать гноргеном!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25935, 'ruRU', 'Голодные щенки', 'Добудьте 6 филе черного дракончика.', 'О, новенькие! Это ты удачно $gзашел, парень:зашла, девушка;! Щенки проголодались, а у нас корма вообще не осталось.$B$BПо счастью, они любят драконье мясо, которого полно в Обугленной долине, к югу отсюда.$B$BБудь $gхорошим мальчиком:хорошей девочкой;, раздобудь мне несколько фунтов филе черного дракончика.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25936, 'ruRU', 'Время вернуть должок', 'Воспользуйтесь зачарованной раковиной для спасения 6 тонущих воинов.', 'Теперь ты можешь свободно перемещаться по этой местности и не бояться потонуть.$B$BТак что приступим к работе.$B$BНачнем с того, что пока мы тут ведем беседы, наши союзники вокруг идут ко дну. Я выручил тебя – а теперь ты помоги им.$B$BЯ наложил чары на раковину, что ты мне $gпринес:принесла;. Воспользуйся ею и выручи наших братьев.$B$BПоторопись!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25937, 'ruRU', 'Бесценные сокровища', 'Достаньте из карьера Гол\'Болар 8 замерзших артефактов.', 'В карьере не только добывали руду. Я возглавлял команду землечерпов Лиги исследователей, которая занималась поиском бесценных древних артефактов.$b$bМне удалось выбраться, но мои коллеги находились гораздо глубже меня и не пережили первой атаки троггов.$b$bОни очень гордились своей работой и рисковали своими жизнями во имя нашей истории. Если ты отправляешься на рудник, возьми с собой эту кирку и постарайся найти что-нибудь на раскопках, начатых землечерпами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25938, 'ruRU', 'Помощь Пустошам', 'Доложитесь офицеру Дженки, которая находится в Тефрис-Аране в Пустошах.', 'Мы получили тревожное сообщение с Высоты Найджела, что в Пустошах. Похоже, сдвиг пластов создал кучу новых проблем, а для их решения у них оборудования не хватает. Больше никакой информации ко мне не поступало.$B$BДоложись офицеру Дженки в Пустошах. Она направит тебя к Высоте Найджела.$B$BУдачи, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25939, 'ruRU', 'Спасение торфяников', 'С помощью благословенной водяной лилии потушите 7 блуждающих огоньков.', 'По Зловещему холму рыскают элементали, и сама земля под ними занимается пламенем. В торфяном болоте, подобном этому, огню всегда найдется, чем подкормиться.$B$BТы $gдолжен:должна; погасить очаги, пока огонь не распространился. Возьми этот цветок... В нем – благословение природы, душа дождя. С его помощью ты сможешь справиться с огнем.$B$BОн пригодится и в борьбе с самими элементалями.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25940, 'ruRU', 'Помощь в Роще Трелей', 'Найдите хранителя Талдроса в Роще Трелей.', 'Благодаря твоим подвигам в Пекле у нас появилась возможность обуздать огонь.$B$BНо природа все еще в опасности: хранитель Талдрос отправился сквозь пламя на север, к Роще Трелей.$B$BПоспеши туда и помоги ему!', '', '', '', '', '', 'Найдите хранителя Талдроса в Роще Трелей.', 25549);
INSERT INTO `quest_template_locale` VALUES (25941, 'ruRU', 'Отдохновение для утомленных', 'Поговорите с легионером Назгримом.', 'Превосходно, |3-6($r), но предстоит еще многое сделать, а силы мои на исходе.$B$BЯ потратил очень много энергии на то, чтобы отправить Служителям Земли сигнал с просьбой о помощи.$B$BЧтобы от меня и дальше был какой-то толк, мне необходим отдых.$B$BПоговори с главным тех, кого ты $gспас:спасла;, и постарайся сделать все от тебя зависящее, чтобы помочь им подготовиться к бою.$B$BНаги прочесывают воды, разыскивая нас. Пройдет немного времени – и они вернутся c подмогой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25942, 'ruRU', 'Выиграть время', 'Убейте 8 налетчиков Зин\'жатара в Судьбе Легиона.', 'Сегодня погибло немало хороших бойцов.$B$BШаман говорит, нельзя терять ни минуты, если мы не хотим пополнить ряды павших.$B$BНаги прочесывают эти воды в поисках уцелевших.$B$BА мы еще не готовы к сражению, |3-6($r). Ты $gдолжен:должна; выиграть нам немного времени на подготовку.$B$BРазыщи наг и попытайся их задержать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25943, 'ruRU', 'Голод не тетка', 'Добудьте 8 кусков сочного мяса крабов c быстролапов с надтреснутой клешней.', 'Чтобы подготовить орков к битве, мне понадобится твоя помощь.$B$BКаждый хороший военачальник знает – воинов надо как следует кормить. На голодный желудок много не навоюешь. Нет еды – нет победы.$B$BМоим солдатам в последнее время пришлось туго. Им нужно пополнить силы. А где взять силу, если есть нечего?!$B$BКстати, я там на дне видел крабов... Ну, в общем, ты понимаешь, что надо делать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25944, 'ruRU', 'Во всеоружии', 'Соберите на морском дне и у жаблинов-расхитителей в Судьбе Легиона 5 оргриммарских топоров, а также 5 кирас и 5 шлемов Оргриммара.', 'Слушай, нам пришлось бросить оружие и почти все доспехи – иначе мы бы утонули.$B$BЭрунак говорит, наги готовят массированную атаку, и у меня нет оснований ему не доверять.$B$BЧтобы выстоять под натиском наг, надо найти брошенное оружие. Без твоей помощи никак.$B$BОружие должно быть на дне, рядом с нашим затонувшим кораблем и к северу от него.$B$BПоторопись, |3-6($r). Враг может подойти в любую минуту.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25945, 'ruRU', 'Мы все делаем одно дело. Или два...', 'Доставьте кром\'гарский фургон к Изгибу Когтистых гор.', 'Теперь ты в армии Адского Крика, $n, а в армии Адского Крика мы радуемся жизни и делаем, что хотим. Прошли те времена, когда наш народ голодал на улицах Оргриммара, а мы подписывали соглашения с эльфами. Сейчас мы просто берем, что нам нужно. Калимдор принадлежит Орде!$B$BАльянс пытается остановить нас. Эти уроды, видите ли, недовольны тем, что им принадлежит большая часть Восточных королевств, им нужно все!$B$BВластитель Кром\'гар созывает войска в Когтистые горы. Присоединяйся к каравану – и вперед!', 'Кром\'гарский фургон доставлен к Изгибу', '', '', '', '', 'Идите к Саурбозу в Изгиб в Когтистые горы, чтобы вступить в армию Кром\'гара.', 25549);
INSERT INTO `quest_template_locale` VALUES (25946, 'ruRU', 'Тайна шлема', 'Отнесите оборудование СМЭШ с корабля Альянса легионеру Назгриму на Серпантин Бессмертного.', 'На этом шлеме и другом оборудовании стоит печать Штормграда. Наверняка они с корабля Альянса, который постигла та же участь, что и ваше судно.$B$BВидно, что эти вещи слишком сложные и прочные; вряд ли их использовали для обычных погружений. Может, Назгрим что про него знает...', '', '', '', '', '', 'Поговорите с легионером Назгримом на Серпантине Бессмертного.', 25549);
INSERT INTO `quest_template_locale` VALUES (25947, 'ruRU', 'Что упало, то пропало', 'Найдите 5 предметов оборудования штормградского СМЭШ.', 'Да, знакомый шлем, |3-6($r). Хорошо, что $gпринес:принесла;.$B$BШлем отряда особого назначения Альянса – подводные боевые действия.$B$BПохоже, кроме стычек с нами у них тут еще какие-то дела.$B$BНа дне, вероятно, находится и другое их снаряжение. Если еще что-нибудь отыщешь, неси – это может изменить ситуацию в пользу Авангарда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25948, 'ruRU', 'Вперед!', 'Поговорите с легионером Назгримом на Серпантине Бессмертного.', 'Время пришло, |3-6($c).$b$bМы готовы как никогда!$b$bЯ поговорю с Авангардом, а потом мы отправимся в море навстречу своей судьбе.', '', '', '', '', '', 'Поговорите с легионером Назгримом на Серпантине Бессмертного.', 25549);
INSERT INTO `quest_template_locale` VALUES (25949, 'ruRU', 'Кровь и гром!', 'Помогите легионеру Назгриму защитить Серпантин Бессмертного.', 'Пора браться за дело, |3-6($r)!$B$BБудем защищать корабль до последнего. Пусть змеюки в следующий раз дважды подумают, прежде чем сюда соваться.$B$BЗа Орду!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25950, 'ruRU', 'Истребление Сира\'кесс', 'Убейте 10 наг Сира\'кесс.', 'Так ты и есть $gэтот:эта; $n, о $gкотором:которой; тут все говорят? Душевно рада знакомству. Как говорится, лучше один раз увидеть...$B$BТак, ладно. Перейдем к делу. Мне нужно, чтобы ты $gотправился:отправилась; на северо-запад к берегу Сира\'кесс и $gпоказал:показала; этим змеюкам, почем фунт лиха.$B$BОни давно нарываются на неприятности, и мы им это устроим. Чтоб впредь неповадно было.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25951, 'ruRU', 'Приговор', 'Удерживайте мост на террасе Кель\'Дормир, пока не прибудут союзники Леди Сира\'кесс.$B$BЭто задание из цикла \"Видения воительницы Леди Наз\'жар\". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.', 'Немедленно отправляйся на восточный мост. Леди Наз\'жар и Повелитель глубин собрали там оставшиеся войска.$B$BСледуй указаниям госпожи и удерживай мост, пока мы не завершим ритуал.$B$BС прибытием наших союзников квалдиры будут обречены на смерть.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25952, 'ruRU', 'Внезапный удар', 'Уничтожьте 10 патрульных Азш\'ира.', 'Наш побег трудно было не заметить, но наги в руинах либо правда не знают об этом, либо не видят в нас никакой угрозы. И этим надо воспользоваться – мы нанесем им удар!$B$BОтправляйся на нижний ярус руин к западу отсюда и уничтожь там как можно больше патрульных. Смотри, чтобы ни один не ушел – враг не должен узнать, что мы поселились в этой пещере.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25953, 'ruRU', 'Быстрый подход', 'Уничтожьте 8 наблюдателей Азш\'ира.', 'Я взял на себя смелость провести предварительную разведку и вот что выяснил: хотя наги не знают точно нашего расположения, они готовы к нападению.$B$BЗа часовыми наг находятся специальные магические устройства, оповещающие о приходе незваных гостей. К счастью, они пожертвовали качеством в угоду количеству: сигнал тревоги начинает передаваться не сразу после обнаружения вторжения. Этого времени как раз хватит, чтобы уничтожить наблюдателей.$B$BДумаю, ты справишься до прибытия других солдат.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25954, 'ruRU', 'Чтобы занять время', 'Осмотрите 4 неразрушенные статуи в садах Вайш\'ира.', 'Тебя ведь $n зовут, да? Мне нужна твоя помощь. Знаю, большинство моих сородичей считает, что сейчас главное – спасение наших жизней, но я не могу не думать о памяти предков.$B$BВо время правления Азшары здесь был один из главных эльфийских городов, в нем полно артефактов величайшего исторического значения. Все, о чем я прошу, – смотри в оба и обращай внимание на все необычные предметы в городе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25955, 'ruRU', 'Новая база', 'Спуститесь на нижний уровень руин и исследуйте северную часть садов Кель\'Дормир, туннель, проходящий под руинами на западе от садов, и постройки в юго-восточном углу руин, под мостами.', 'Эта пещера – наше единственное пристанище. Отступать некуда, и никто не спешит нам на помощь. Что бы ни случилось, нельзя подвергать это место опасности, иначе мы все погибнем.$B$BНеобходим форпост, с которого мы будем проводить атаки.$B$BПосле того как окажешься на нижнем уровне в восточной части руин, осмотри следующие объекты: северную часть садов, проход под главным зданием к западу от садов, а также группу зданий в юго-восточном углу руин, что находится под мостами.$B$BСобери всю доступную информацию об этих местах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25956, 'ruRU', 'На поле брани', 'Принесите обломок на базу Легиона.', 'Повсюду вокруг видны следы битвы. Скелеты наг не вызывают у меня никакого удивления, но вот оружие и останки их противников – довольно неожиданное открытие.$B$BСреди костей выделяется кусок металла, торчащий из черепа. Сложно сказать, частью какого оружия он был, но его можно забрать в виде доказательства.$B$BМеталлический фрагмент может заинтересовать кого-то из обитателей пещеры.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25957, 'ruRU', 'Видения прошлого: вторжение в Вайш\'ир', 'Воспользуйтесь клинком воительницы Леди Наз\'жар на поле битвы возле юго-восточной окраины руин.', 'Тот осколок, который ты $gпринес:принесла;, принадлежал нагам. Я давно ищу подобный предмет, чтобы закончить особое заклинание – оно позволит нам заглянуть в недалекое прошлое.$B$BИтак, заклинание готово, но теперь нужно отнести этот клинок на то место, где бывал его владелец. Отправляйся туда, где его $gнашел:нашла;.$B$BВозможно, теперь мы узнаем о намерениях наг – а может, даже нащупаем их слабые места.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25958, 'ruRU', 'Взгляд в будущее', 'Найдите капитана Злобешипа к северу от садов Кель\'Дормир и поговорите с ним.$B$BВоспользуйтесь морским коньком говорящей с волнами Талры, чтобы быстро добраться до форпоста.', 'После твоего рассказа капитан решил создать форпост под террасой, что к западу отсюда. Теперь он планирует нанести оттуда удар по нагам.$B$BТы $gдолжен:должна; немедленно отправиться к нему и рассказать все, что $gвидел:видела;. Нас слишком мало, и страшно подумать, к чему приведет безрассудная атака.$B$BВозьми моего морского конька. Он знает дорогу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25959, 'ruRU', 'Ясные цели', 'Убейте 10 наг, собирающихся на нижнем уровне под юго-западной террасой.', 'Понятно. Да, это скверные новости, но я не исключал такую возможность. Было бы рискованно действовать, не зная точной численности наг, но именно поэтому мы и создали этот форпост.$B$BСкажу тебе прямо, |3-6($c), – если внезапно не напасть на наг, они сами к нам явятся. А у нас нет ни должных укреплений, ни достаточного количества солдат, так что это не вариант.$B$BНам нужно выиграть время. Можешь избавиться от нескольких наг под дальней южной террасой?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25960, 'ruRU', 'Не так уж безоружны', 'Принесите 8 связок арбалетных болтов дозорным Орды, расставленным на уступах на северном краю Садов Кель\'дормир.', 'Я невольно подслушал твой разговор с капитаном. Знаю – то, что мы делаем, похоже на безумие, но другого выхода нет. От нас зависит жизнь всех обитателей пещеры.$B$BЯ разместил вокруг нескольких часовых, но наг-разведчиков так много, что наши боеприпасы тают на глазах. Если ты пополнишь боезапас, часовые выиграют нам дополнительное время.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25961, 'ruRU', 'Необычное поручение', 'Скопируйте надписи с 4 скрижалей высокорожденных.', 'Хм, ты $gзаметил:заметила;, как неодобрительно капитан посмотрел на меня, и $gрешил:решила; помочь? Я уж и не надеюсь заставить его понять, что среди этих руин можно найти кое-что полезное.$B$BВот ты, как мне кажется, совсем другое дело. Посмотри-ка, подобные скрижали встречаются в окрестных развалинах, и я уже приготовила специальный набор для копирования надписей с этих каменных плит. Возьмешься за работу?', '', '', '', '', '', 'Вернитесь к Элендри Золотое Чело, находящейся к северу от садов Кель\'Дормир.', 19865);
INSERT INTO `quest_template_locale` VALUES (25962, 'ruRU', 'Внезапное озарение', 'Соберите 8 раздувшихся шишек водорослей, висящих под юго-западной террасой.', 'Везде бывал, везде взрывал... Боялся, что этой привычке пришел конец – море, как понимаешь... Но оказалось, нужно лишь немного вдохновения.$B$BЯ нашел кое-что настолько нестабильное, что для бомбы в самый раз подойдет! На юго-западной террасе растут водоросли. В обычных водорослях содержится легкий газ, который позволяет тянуться вверх, а эти водоросли свисают вниз. Причина – тяжелый газ, как раз подходящий для моей бомбы.$B$BПринесешь немножко?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25963, 'ruRU', 'Медлить нельзя', 'Поговорите с Облином Свистозубом, стоящим у здания, чтобы присоединиться к атаке, а затем убейте 100 солдат Азш\'ира, 20 водных визгуний Азш\'ира и 12 археев Азш\'ира с помощью импровизированной взрывчатки.', 'Подготовка завершена, пора в бой.$B$BТы вот что – держись крепче на своем морском коньке, пока мы атакуем. Тот, кто останется один на один в воде с нагами, вряд ли сможет уплыть от них.$B$BУбей как можно больше врагов. Встретимся на верхней террасе, как только у нас закончится взрывчатка. Надеюсь, к тому времени наг останется мало, и мы добьем их сами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25964, 'ruRU', 'Повержены, но не забыты', 'Спасите 6 раненых добровольцев.', 'Какая катастрофа! Многие наши бойцы ранены и не могут добраться до места встречи.$B$BДолго нам эту позицию не удержать. Необходимо спасти как можно больше воинов, пока не явились наги. Отправляйся на юго-запад и сделай все, что в твоих силах.$B$BНаши долго не продержатся. Пожалуйста, поторопись!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25965, 'ruRU', 'Подсчет', 'Проведите разведку по краю круглой террасы на северо-западе и в туннеле под главной лестницей на севере. Оба места расположены на террасе Нар\'шолы на среднем уровне развалин.', 'Злобные твари... а их гарпуны... страшная, скажу тебе, штука.$B$B<Капитан морщится, коснувшись раны в боку.>$B$BНо мы будем держаться. Сколько сможем. Любой ценой. Мне нужен тот, кто пойдет на разведку и подсчитает, сколько их там осталось. Чтобы понять, скольких мы уже перебили.$b$bОдна из самых больших групп находилась за углом в северо-западной части круглой террасы, а еще одна группа располагалась чуть подальше, в маленьком тоннеле на среднем уровне развалин.$b$bПойдешь, |3-6($c)?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25966, 'ruRU', 'Видения прошлого: битва на гряде Бейл\'аран', 'Отправляйтесь на место гибели квалдирского генерала и с помощью сломанного клинка Воительницы призовите видение из прошлого, чтобы узнать продолжение истории о Воительнице.', 'Понимаю, что прошу слишком многого и сейчас совсем не время для такой просьбы – ведь на счету каждый воин. Но мне нужна твоя помощь.$B$BЯ позабочусь о солдатах... а ты отправляйся на запад и разыщи поле боя с квалдирским генералом, о котором ты мне $gговорил:говорила;. Там ты узнаешь больше о деяниях Воительницы. Шестое чувство подсказывает мне, что ключ к победе над нагами скрывается в прошлом, и он как-то связан с Воительницей.$B$BИ, пожалуйста, поторопись: я постараюсь выиграть для тебя время, но силы мои не беспредельны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25967, 'ruRU', 'Отступление', 'Воспользуйтесь морским коньком говорящей с волнами Талры, чтобы вернуться к капитану Злобешипу, находящемуся к северу от Садов Кель\'Дормир.', 'Придется подождать с разговором: сейчас нужно уходить, пока наги не прорвались. Постарайся добраться до форпоста ярусом ниже.$B$BВозьми моего морского конька. Встретимся там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25968, 'ruRU', 'Отчаянный план', 'Найдите Облина Свистозуба на гряде Бейл\'аран.', 'Толдрек с Облином отправились за помощью. Неподалеку проходят торговые маршруты, и шансы найти подмогу есть, но я бы не стал слишком на это надеяться.$B$BЕсли честно, особого выбора нет, и долго мы здесь не продержимся. Рано или поздно наги нас обнаружат и... ты ведь $gсам видел:сама видела;, сколько их там.$B$BОтправляйся на юго-восток к гряде Бейл\'аран и разыщи наших двоих храбрецов. Я постараюсь защитить оставшихся здесь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25969, 'ruRU', 'Опасные воды', 'Уничтожьте 10 слизнешкурых хапуг.', 'С одного из наших кораблей Облин утащил воздушный шар. Он попытался поднять шар на поверхность, но тут откуда ни возьмись появились слизнешкурые хапуги и разодрали шар в клочья.$B$BТеперь Облин хочет запустить второй шар, но история не должна повториться. Уничтожь-ка ты всех этих жаблинов... Или убей столько, чтобы они побоялись снова к нам сунуться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25970, 'ruRU', 'Наготове', 'Разыщите ящик Орды с предметами первой необходимости.', 'До поверхности недалеко, а налегке и плыть проще простого. Но с припасами мы намучаемся – больно они тяжелые.$B$BНа каждом корабле Орды должен быть ящик с набором для выживания. У меня был воздушный шар из старого ящика, но недавно ему пришел быстрый и печальный конец, поэтому мне нужен еще один ящик.$B$BК юго-востоку отсюда ты найдешь корабль. Будем надеяться, что выжившие матросы совсем потеряли головы во время бегства и не догадались забрать с собой этот замечательный ящик. Их промашка может стать нашим спасением.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25971, 'ruRU', 'Веревочный план', 'Добудьте 8 мотков квалдирской веревки.', 'В ящике с предметами первой необходимости нет веревки. Вопиющая халатность! Веревка и бомбы – вот что должно быть в этих наборах. Все остальное только место зря занимает.$B$BХотя шар – не такая уж и бесполезная штука. Сейчас, например, он нам очень даже пригодится.$B$BБьюсь об заклад, у квалдиров должна быть веревка. Они же чуть не живут на лодках, вяжут узлы да одеваются в сети. Иди-ка отбери у них веревку! Без этого наш план яйца выеденного не стоит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25972, 'ruRU', 'Честь и слава', 'Поднимитесь на поверхность, возьмите сигнальное ружье и запустите сигнальную ракету в направлении кораблей Орды.', 'Вот и все. Я уверен, что все получится. И шар на этот раз никто не проткнул – за что спасибо тебе! Как ты $gрасправился:расправилась; с этими слизнешкурыми хапугами – только клочья летели!$B$BТолдрек уже поплыл ловить его, правда, очень тревожился насчет течений, ну и вообще... Сказал, пусть вся слава достанется тебе. Хороший парень... трудно ему, но держится молодцом.$B$BПоднимись к шару, возьми сигнальное ружье и посмотри, нет ли поблизости кораблей Орды. Если увидишь какой-нибудь, стреляй сигнальной ракетой. Собственно, и все.$B$BПлывешь. Поднимаешься на поверхность. Запускаешь ракету. И помощь приходит! Последний пункт мне нравится больше всего.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25973, 'ruRU', 'Добрые вести', 'Возвращайтесь к легионеру Назгриму на базу Легиона.', 'Они, наверное, вышлют лодку. Но на это надо время. Я останусь здесь и вступлю в переговоры.$B$BА ты немедленно возвращайся в пещеру и скажи там, что помощь уже на подходе. Будем надеяться, наги их не обнаружили.$B$BДавай, $n. Плыви. И постарайся обернуться побыстрее.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25974, 'ruRU', 'Истребление Сира\'кесс', 'Убейте 10 наг Сира\'кесс.', 'Так ты и есть $gэтот:эта; $n, о $gкотором:которой; тут все говорят? Ну вот, наконец-то мы с тобой познакомились.$B$BЛадно, давай сразу к делу. Значит, задача такая: отправляйся на северо-запад к берегу Сира\'кесс и перебей змеюк.$B$BОни давно нарываются на неприятности, и мы им это устроим. Ну... вернее, ты устроишь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25975, 'ruRU', 'Экспроприация сокровищ', 'Соберите 6 предметов добычи Глубинных Плавников.', 'Подкрепление прибыло, но нам нужно чем-то платить солдатам. Опытные воины нынче недешевы.$B$BПравда, есть одна идея! Эти мерзавцы-жаблины на Гряде Глубинных Плавников, что на северо-западе отсюда, награбили кучу сокровищ. По-моему, самое время туда наведаться и слегка их \"потрясти\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25976, 'ruRU', 'Экспроприация сокровищ', 'Соберите 6 предметов добычи Глубинных Плавников.', 'Кровь и гром! Подкрепление прибыло, но нам нужно чем-то платить солдатам. А это недешево.$B$BНо у меня есть идея! Мерзавцы-жаблины на Гряде Глубинных Плавников, что на северо-западе отсюда, награбили кучу сокровищ. По-моему, самое время наведаться к ним и слегка \"потрясти\" в пользу Орды.$B$BАдский Крик следит за тобой, $n!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25977, 'ruRU', 'Знаменательный день для Азражара', 'Воткните знамя Альянса в труп призывателя глубин Азражара.', '$n, змеюки снова на нас поперли. Так что давай дуй обратно на северо-запад, к Гряде Глубинных Плавников, и наведи там шороху. Грохни их главного и воткни в его труп наше знамя.$B$BПусть они там от страха обделаются и уберутся куда подальше, поджав хвосты... или щупальца... или что там у них...', '', 'Воткни знамя в его труп!', 'Призыватель глубин Азражар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25978, 'ruRU', 'Погребенные во льду', 'Вскройте 6 ледяных гробниц, чтобы освободить замерзших горных пехотинцев, находящихся в плену озера Хельмово Ложе.', 'Кургорн говорит, что катаклизм нарушил баланс стихий по всему миру. Озеро Хельмово Ложе, которое находится к югу отсюда, всегда было красивым и тихим, но теперь оно захвачено потревоженными водными элементалями. Когда они начали выходить за пределы озера, я отправил туда свои войска, но многие не вернулись, оставшись замороженными в глыбах льда.$b$bЕсли мы сможем освободить их оттуда, у них неплохие шансы выжить. Но у меня не хватает людей для организации второй вылазки к озеру. Не хочешь помочь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25979, 'ruRU', 'Утихомирить волны', 'Убейте 6 озерных волногонов в озере Хельмово Ложе.', 'Стихии в смятении, |3-6($c). Катаклизм потревожил давно дремлющих духов воды озера Хельмово Ложе, что к югу отсюда. Они злы, растеряны и совершенно не желают внимать моим просьбам.$b$bЯ испробовал все, что знал, чтобы успокоить их и убедить перестать набрасываться на горных пехотинцев сержанта.$b$bМне больно говорить это, но другого выхода нет – мы должны убить элементалей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25980, 'ruRU', 'Знаменательный день для Азражара', 'Воткните знамя Орды в труп призывателя глубин Азражара.', '$n, наги снова готовятся к атаке. Возвращайся на северо-запад к Гряде Глубинных Плавников, убей их генерала, призывателя глубин Азражара, и воткни в его труп наше знамя.$B$BЭто устрашит наг, и они уберутся восвояси, поджав хвосты.', '', 'Воткни знамя в его труп!', 'Призыватель глубин Азражар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25981, 'ruRU', 'Это не маски', 'Добудьте 6 голов безжалостных.', '$n, эти кальмарообразные демоны... они присасываются к головам жаблинов и превращают их в послушных рабов!$B$BЯ вот думаю... может быть, сплаваешь на северо-запад к Гряде Глубинных Плавников или на берег Сира\'кесс и принесешь мне штук шесть голов этих противных тварей – безжалостных?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25982, 'ruRU', 'Это не маски', 'Добудьте 6 голов безжалостных.', '$n, эти кальмарообразные демоны... они присасываются к головам жаблинов и превращают их в послушных рабов! Совсем не хочется, чтобы эти твари добрались сюда!$B$BЯ вот думаю... может быть, сплаваешь на северо-запад к Гряде Глубинных Плавников или на берег Сира\'кесс и принесешь мне штук шесть голов этих безжалостных тварей? Желательно – мертвых.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25983, 'ruRU', 'Подводный выступ', 'Поговорите с капитаном Тейлором на Подводном выступе в Вайш\'ире.', 'Необходимо немедленно передать эти сведения капитану Тейлору! Он сейчас на северо-западе, на Подводном выступе, вместе с Эрунаком Говорящим с Камнем и Служителями Земли.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25984, 'ruRU', 'Подводный выступ', 'Поговорите с легионером Назгримом на Подводном выступе в Вайш\'ире.', '$n, нужно немедленно передать эти сведения легионеру Назгриму. Он сейчас на северо-западе, на Подводном выступе, вместе с Эрунаком Говорящим с Камнем и Служителями Земли. Отправляйся немедленно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25985, 'ruRU', 'Крылья над Хиджалом', 'Найдите Чолуну в святилище Авианы на горе Хиджал.', '$n, правда ли, что ты собираешься воззвать к Древним?$B$BК юго-западу отсюда находится святилище Авианы, покровительницы всех пернатых созданий. В святилище обитает моя любимая наставница Чолуна. Никогда не встречала кого-либо, кто так сильно соприкасается с духами, населяющими этот мир. Ты бы $gмог:могла; многому у нее научиться!$B$BНедавние нападения отсекли пути в святилище. Однако туда можно легко попасть по воздуху: поищи второе по высоте дерево на горе Хиджал. Доброго пути!', '', '', '', '', '', 'Разыщите Чолуну в святилище Авианы на горе Хиджал.', 25549);
INSERT INTO `quest_template_locale` VALUES (25986, 'ruRU', 'Проблема на озере', 'Поговорите с сержантом Бахрумом в Лагере Бахрума.', 'Ты $gоказал:оказала; нам большую помощь в обеспечении безопасности рудника и в спасении остававшихся там рабочих. Сенат будет очень рад узнать, что тебе и горным пехотинцам капитана Таррана удалось сделать Дун Морог безопаснее.$b$bНо меня беспокоит отсутствие вестей от сержанта Бахрума и его подразделения. Они отправились на восток, по дороге к озеру Хельмово Ложе, у них был приказ разбить там небольшой лагерь. Не отправишься ли ты туда и не проверишь ли, как дела у сержанта?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25987, 'ruRU', 'Прекрасная маскировка', 'Посмотрите, что будет, если надеть на голову мертвого Безжалостного.', 'Слушай, $n, у меня идея, как замаскироваться! Отлично выйдет. Берешь безжалостную тварь и надеваешь себе на голову.$B$BА что такого? Она же тебя не укусит!$B$BПопробуем?', 'Безжалостный надет', '', '', '', '', 'Поговорите с инженером Мегагексом в Темной пещере в Вайш\'ире.', 25549);
INSERT INTO `quest_template_locale` VALUES (25988, 'ruRU', 'Прекрасная маскировка', 'Посмотрите, что будет, если надеть на голову мертвого Безжалостного.', 'У меня идея, как замаскироваться. Отлично выйдет, $n! Берешь труп безжалостной твари и надеваешь себе на голову.$B$BДа, я все понимаю... но она же дохлая, так что тебе ничего не будет. Ну, разве что пару дней повоняешь тухлятиной, но для пользы же дела!$B$BПопробуем?', 'Безжалостный надет', '', '', '', '', 'Поговорите с Облином Свистозубом в Зловещем гроте, что в Вайш\'ире.', 25549);
INSERT INTO `quest_template_locale` VALUES (25989, 'ruRU', 'Захват краба', 'Поймайте сетью Дуарна глубинного краба в Неспире.', 'Всем своим существом я ощущаю, что Неспира хочет связаться со мной, но я ее не слышу. Видимо, наги как-то препятствуют этому.$B$B<Дуарн какое-то время молча размышляет.>$B$BПохоже, что-то не дает ей говорить... Необходимо найти то, что послужит ей голосом...$B$BПридумал! Известно, что Идра\'кесс приручают глубинных крабов и выращивают из них помощников в бою. Поймай этой сетью одного краба и принеси мне. Они обитают у внешних границ полости.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25990, 'ruRU', 'Прорыв', 'Проследите за тем, как Целитель Земли Дуарн попытается заговорить с Неспирой.', 'Хорошо известно, что опытный шаман умеет взаимодействовать со всеми четырьмя элементами стихий: землей, огнем, водой и воздухом.$B$BОднако далеко не все знают, что существует и пятый элемент. Он не имеет такого же четкого определения, как остальные... О нем можно сказать только то, что он является связующим звеном между всем живым на планете.$B$BЯ пришел к выводу о том, что краб, как морской обитатель, находится ближе всего к Неспире, поэтому с помощью всех элементов можно убедить его взять на себя роль голоса Неспиры.', 'Поговорите с Целителем Земли Дуарном', '', '', '', '', 'Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.', 25549);
INSERT INTO `quest_template_locale` VALUES (25991, 'ruRU', 'Враг близко', 'Отыщите выживших представителей Орды в Неспире, что находится в Вайш\'ире.', '<Дуарн закрывает глаза, делает паузу и затем кивает головой.>$b$bНеспира только что-то сообщила мне, что мы не единственные, кто сражается в раковине. На другой ее стороне от наг отбивается группа беглых рабов Орды; они находятся на уступе, нависающем над сердцем Неспиры.$b$bНайди их, $n, и узнай, какую помощь они в силах нам оказать. Возможно, объединившись с рабами, мы сможем пробудить Неспиру ото сна.$b$bЯ останусь тут на случай, если что-нибудь потребуется.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25992, 'ruRU', 'Безоружные', 'Принесите 4 похищенных трезубца с оружейных стоек в Неспире.', 'Честно говоря, я не понимаю, почему мы до сих пор живы. Наги захватили все мое оружие и доспехи. У меня остались только какие-то лохмотья и шахтерская кирка, которая к тому же давным-давно пополам сломалась.$B$BМне нужно хоть какое-то оружие... Да, и моим товарищам тоже, хоть гордость и не позволяет им это признать.$B$BЯ видел стойки с оружием на ближайших складах наг. Мне еще никогда не доводилось сражаться трезубцем, но в любом случае лучше идти в бой с ним, чем с голыми руками.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25993, 'ruRU', 'Удар по телу', 'Ударьте Неспиру в 7 гнойников, расположенных на стенах ее полости.', '<Легионер Назгрим внимательно слушает ваш пересказ разговора Дуарна с Неспирой.>$B$BПонятно. Значит, она хочет, чтобы мы помогли ей проснуться, так?$B$BЕсли учесть, что сотни рабов уже собирают ее жемчужины, то, похоже, ее из пушки не разбудишь. Но, может, у тебя и получится.$B$BЯ вот что могу предложить: хорошо осмотри ее и попробуй найти слабое место. Быть может, если ударить в чувствительную точку, она придет в себя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25994, 'ruRU', 'Ценные вещи', 'Добудьте у полководцев и пророков Идра\'кесса в Неспире 5 таинственных жемчужин.', 'Я недолго пробыла на жемчужных полях и так и не поняла, какие же цели преследуют наги. Известно, что они хотят использовать Неспиру как оружие в войне, но зачем тогда заставляют рабов добывать ее жемчуг?$B$BЕсли нам удастся отсюда выбраться, я бы хотела хорошенько изучить эти жемчужины. Правда, те, что нашли мы, были слишком большими. Нам их не унести. Но я видела в руках у полководцев и пророков жемчуг помельче.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25995, 'ruRU', 'Надзиратель Идра\'кесс', 'Отправляйтесь в верхнюю полость Неспиры и убейте надзирателя Идра\'кесса.', 'Мои люди измождены, $n. Боюсь, против наг нам долго не продержаться. Теперь у нас есть оружие Идра\'кесс и жемчуг Неспиры; пора выбираться отсюда.$B$BСтупай вдоль стены на северо-восток, там найдешь проход в верхнюю полость. Полагаю, в ней и скрывается их главный – или ключ к пробуждению Неспиры, а может, и то, и другое вместе.$B$BЕсли у тебя хватит сил, поднимись в верхнюю полость и найди ответы на наши вопросы! Адский Крик следит за тобой!', '', 'Осквернитель Неспиры', 'Надзиратель Идра\'кесс', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25996, 'ruRU', 'Пробуждение', 'Поговорите с Целителем Земли Дуарном в Неспире, чтобы запустить защитные процессы. Затем покиньте тело Неспиры.', 'Благодаря вашей с легионером помощи Неспира вышла из оцепенения. Но большинству наг это пока неизвестно. Как только мы уйдем, Неспира запустит в своем теле защитные биологические процессы и уничтожит наг.$B$BПриготовься, а я пока прикажу Неспире начать обратный отсчет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25997, 'ruRU', 'Тайные планы Черного Железа', 'Отправляйтесь в мастерскую Сталекрута, убейте 5 шпионов из клана Черного Железа и отберите план нападения Черного Железа у капитана Бельда.', 'Группа шпионов Черного Железа захватила мастерскую Сталекрута, что к югу отсюда, за озером Хельмово Ложе. Обычно горные пехотинцы не дают им проникнуть в Дун Морог, но сейчас все в смятении.$b$bДворфы Черного Железа будут идиотами, если не воспользуются преимуществами создавшегося хаоса. Нужно узнать, что они замышляют, и остановить их, прежде чем они причинят нам вред.$b$bТы не можешь узнать, что они затевают в мастерской Сталекрута?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (25998, 'ruRU', 'Попасть на аэродром', 'Сядьте на ветролет Мателя в карьере Гол\'Болар.', 'Согласно захваченным тобой документам клан Черного Железа планирует масштабную атаку на аэродром Стальгорна! Совет перебросил большую часть наших войск в Дун Морог, чтобы бороться с нестабильностью, вызванной Катаклизмом, в связи с чем защита аэродрома ослаблена.$b$bНам нужно быстро отправить тебя на аэродром. Иди на запад по дороге, которая ведет к карьеру Гол\'Болар, и найди Мателя Ржавого Ключа. У него должен быть ветролет, которым ты сможешь воспользоваться. Вперед!', '', '', '', '', '', 'Поговорите с командиром форта Камнеломов на аэродроме Стальгорна.', 25549);
INSERT INTO `quest_template_locale` VALUES (25999, 'ruRU', 'Вход перекрыт', 'Поставьте 8 кром\'гарских \"Убийц эльфов\".', 'Грязные никчемные ночные эльфы умудрились обезвредить наше минное поле на Тропе Когтя. Кто-то должен вернуться туда и заново расставить мины! Отличное задание для бесполезного рядового вроде тебя, $n. Надеюсь, у тебя хватит ума не подорваться во время выполнения задания.$B$BНа Тропе Когтя, к северу от нас, ты найдешь разбросанных \"Убийц эльфов\". Бери инструмент и за работу, салага!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26000, 'ruRU', 'Спелеологи', 'Поговорите с Гурроком в Дымчатом гроте.', 'Скорее, $n!$B$BНемедленно плыви к той пещере.$B$BМы тоже туда отправимся и проследим, нет ли за тобой хвоста.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26001, 'ruRU', 'Пропавший взрынженер', 'Найдите взрынженера Улюлюка.', 'Похоже, ты не совсем $gбесполезен:бесполезна;. Думаю, тебе можно поручить кое-что посложнее.$B$BПару дней назад взрынженер Улюлюк отправился в рудник Ветрорезов. Он должен был добраться туда, убедиться, что с бомбой все идет по плану, и вернуться с отчетом. Два дня прошло, а его все нет...$B$BОтправляйся на юг в леса и найди его. Лучше б он помер, иначе ему сильно не поздоровится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26002, 'ruRU', 'План нападения Альянса', 'Отнимите план нападения Альянса у охотницы Давинии.', '<Вы вытягиваете записку из руки Улюлюка.>$B$BОни будут атаковать! Они знают все про бомбу. Они хотят напасть на крепость Кром\'гар! Мне кажется, меня ищут. Отвертеться не получится. Придется дать им бой.$B$BЯ слышу их! Глава отряда – охотница из высших эльфов по имени Давиния. Она говорила о плане нападения. Отомстите за меня, убив ее и захватив этот план! Ее палатка недалеко, к востоку отсюда.$B$BАдский Крик следит за вами...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26003, 'ruRU', 'Урок с Затерянных островов', 'Убейте 12 дарнасских разведчиков.', 'В лесах к югу отсюда полно опасностей. Дарнасские разведчики там прямо кишмя кишат – убийцы, которых Дарнас послал, чтобы разделаться с нами. А может, это мы побьем их, а?$B$BКогда я был на Затерянных островах, один гоблин подарил мне инфракрасные теплодетекторы. Тот, кто их носит, видит тепло, исходящее от живых существ. Возьми детекторы и не снимай их, пока будешь в лесу к югу отсюда. Так ты сможешь засечь разведчиков. Убей как можно больше этих гадов! За Орду!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26004, 'ruRU', 'Крепость Кром\'гар', 'Доставьте план нападения Альянса властителю Кром\'гару в крепость Кром\'гар в Когтистых горах.', 'Наш штаб в Когтистых горах – крепость Кром\'гар. Оттуда властитель Кром\'гар управляет войсками Орды в этих краях. Он рассказывает обо всем, что видит, нашему вождю.$B$BВоенные планы, которые ты $gпринес:принесла;, касаются скорой атаки на крепость Кром\'гар. Тащи планы в крепость, она находится к юго-западу отсюда. Передай документы властителю$B$BДо встречи, $n. Адский Крик следит за тобой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26005, 'ruRU', 'Глоток свежего воздуха', 'Найдите капитана Тейлора на борту \"Крепости Волдрина\" в море над Руинами Вайш\'ира.', 'Капитан Тейлор и многие другие выжившие уже поднялись на поверхность. Наверняка многие из побывавших в глубинах мечтают убраться отсюда подальше и навсегда забыть об этом месте, но нам предстоит еще многое сделать, чтобы не допустить наг в царство воды.$B$BДля начала необходимо расправиться с монстром, потопившим наши корабли по дороге сюда. Я не хочу, чтобы этот кошмар повторился. $B$BЭти сапоги оставил Мегагекс. Они помогут тебе быстрее добраться до места назначения.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26006, 'ruRU', 'Глоток свежего воздуха', 'Разыщите легионера Назгрима на борту \"Стигийской Награды\" в море над Руинами Вайш\'ира.', 'Легионер Назгрим и многие другие выжившие уже поднялись на поверхность. Наверняка многие из побывавших в глубинах мечтают убраться отсюда подальше и навсегда забыть об этом месте, но нам предстоит еще многое сделать, чтобы не допустить наг в царство воды.$B$BДля начала необходимо расправиться с монстром, потопившим наши корабли по дороге сюда. Я не хочу, чтобы этот кошмар повторился. $B$BЭти сапоги оставил Облин. Они помогут тебе быстрее добраться до места назначения.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26007, 'ruRU', 'Отчет', 'Поговорите с Гурроком и узнайте все, что с ним произошло.', 'Этот солдат был при смерти, но, боюсь, у нас нет времени ждать, пока он полностью придет в себя. У него есть информация, которая позарез нам нужна.$B$BНаберись терпения и выпытай у него все, что нам необходимо знать.$B$BЕсли повезет, удастся выяснить, что нас тут ожидает...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26008, 'ruRU', 'Декомпрессия', 'Воспользуйтесь камнем дыхания Моаны, чтобы выручить 10 пленных воинов на Жемчужной ферме.', 'Для меня невыносима мысль о том, что еще множество подобных этому воину находится в плену у наг.$b$bМы должны что-то предпринять, чтобы их спасти!$b$bПопробуй-ка вот что, $n. Сделай так, чтобы тюремные камеры всплыли на поверхность.$b$bЕсли нам удастся переместить их наверх, то возможно, их спасут.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26009, 'ruRU', 'Найти и уничтожить', 'Убейте 20 солдат Альянса в Когтистых горах.', 'Альянс надвигается на наши владения в Когтистых горах. Северная стража прорвала блокаду на юге и занимает долину Ветрорезов к западу от нас. С севера стремительно наступают ночные эльфы. Это надо прекратить!$B$BОтправляйся в Когтистые горы и уничтожь всех солдат Альянса, которые встретятся на твоем пути. Пусть их смерть станет предупреждением для остальных.$B$BКогтистые горы принадлежат Орде!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26010, 'ruRU', 'Прах к праху', 'Используйте кром\'гарский огнемет, чтобы уничтожить 8 палаток Северной стражи.', 'Альянс обнаглел. К западу отсюда в долине Ветрорезов Северная стража разбила лагерь. Они наверняка готовят нападение, о котором ты нам $gговорил:говорила;, $n. Но у них ничего не выйдет!$B$BВозьми огнемет. Точно такими же огнеметами мои поджигатели выжигали врагов из леса. Уничтожь с его помощью палатки. Оставь на своем пути один лишь пепел!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26011, 'ruRU', 'Враг Орды: маршал Полтроу', 'Убейте маршала Полтроу.', 'Мои разведчики узнали, что поражением мы обязаны одному человеку – маршалу Полтроу. Он командует передовым лагерем Северной стражи, который расположен к западу отсюда в долине Ветрорезов. Убери его – и Альянс лишится сильного полевого командира.$B$BПолтроу должен умереть, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26012, 'ruRU', 'Беда в храме Драконьего Покоя', 'Поговорите с Красом в храме Драконьего Покоя, что в Драконьем Погосте.', 'Мой старый друг Крас прислал известие об ужасный событиях в храме Драконьего Покоя, что в Драконьем Погосте. Его сообщение довольно краткое, но из него мне стало понятно, что на Рубиновое святилище, находящееся под храмом, совершено нападение.$B$BК сожалению, неотложные дела не позволяют мне покинуть Даларан и лично разобраться с этим происшествием, но, полагаю, я могу доверить это тебе? Ты так хорошо $Gпроявил:проявила; себя в цитадели Короля-лича... пожалуйста, окажи помощь Красу!', '', '', '', '', '', 'Поговорите с Красом в храме Драконьего Покоя, что в Драконьем Погосте.', 25549);
INSERT INTO `quest_template_locale` VALUES (26013, 'ruRU', 'Нападение на святилище', 'Осмотрите Рубиновое святилище под храмом Драконьего Покоя.', '$R, в Рубиновом святилище под храмом произошло нечто ужасное!$B$BГлавный вход разрушен, стражи мертвы... Мы послали туда разведчиков, но никто не вернулся живым. Боюсь, нам надо готовиться к худшему.$B$BОтправляйся в Рубиновое святилище и выясни, кто осмелился поднять руку на дом моего племени. Как только у нас будет больше информации, мы сможем спланировать дальнейшие действия.', '', '', '', '', '', 'Осмотрите Рубиновое святилище под храмом Драконьего Покоя.', 25549);
INSERT INTO `quest_template_locale` VALUES (26014, 'ruRU', 'Братья Ройпой', 'Поговорите с Хамфри Ройпоем в Затемненной впадине в Вайш\'ире.', 'Рядовой, стой! У нас небольшая проблема!$B$BМы отправили Хамфри и Оскара Ройпоев в Затемненную впадину на северо-запад, а они все никак не вернутся. Должны были разведку провести, но от них ни слуху, ни духу.$B$BТак что слушай приказ, рядовой $n! Отыщи наших товарищей и, если они живы, доставь сюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26015, 'ruRU', 'Охота за фосфориями', 'Добудьте 6 люминесцентных фосфорий из огнепанцирных крабов и блестящих окуней в Затемненной впадине.', 'Последнее, о чем мечтал Оскар перед отправкой в желудок огромного угря, – это принести капитану немного еды. Мы выполним его волю.$B$BБрат разработал гениальный план. Он видел, как мурлоки выманивают рыб специальной светящейся антенной. И сделал себе такую же. Все, что тебе понадобится, – это какой-нибудь светящийся предмет.$B$BУбей несколько крабов и окуней, обитающих на дне впадины. Сами по себе они несъедобны, но в них ценно не мясо, а фосфории.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26016, 'ruRU', 'Распоряжения из главного лагеря', 'Доставьте распоряжения из главного лагеря властителю Кром\'гару в крепость Кром\'гар в Когтистые горы.', 'Полтроу, закрепитесь в долине Ветрорезов. Нам нужно организовать мощную атаку. Когда мы нападем на Кром\'гар, ваши люди должны будут посеять смятение в рядах противника, чтобы гномские ветролеты могли подобраться поближе и разбомбить орочью крепость.$B$BВетролеты взорвут бомбу Кром\'гара прямо там, а вместе с ней – и всю вражескую крепость.$B$BПосле прочтения сжечь.$B$B- Командир армии Вален$B$BЛагерь экспедиции Северной Стражи', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (26017, 'ruRU', 'Приманка', 'Наденьте светошляпу и проплывите через заросли водорослей в Затемненной впадине, чтобы привлечь 30 люминесцентных гирелл.', 'Прикрепи это к голове и плыви через водоросли и кораллы во впадине. Там полно мелких рыбешек, которые сразу клюнут на твою антенну.$B$BРыбы, которую мы принесем в Темную пещеру, хватит на всех!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26018, 'ruRU', 'Смерть Холодному Сиянию', 'Убейте 4 охотников Холодного Сияния и 4 оракулов Холодного Сияния.', 'Ах да! Чуть не забыл! Мне же нужно подготовить отчет.$B$BПохоже, здесь довольно безопасно... Если не считать огромных угрей и нескольких мурлоков. Думаю, капитана гораздо больше заинтересуют мурлоки. $B$BСтупай, напади на парочку – надо узнать, на что они способны в бою. Насколько мне известно, крупные особи охотятся на рыбу среди водорослей, а мелкие прибегают к какой-то магии... Больше я ничего о них не знаю.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26019, 'ruRU', 'Огромная икринка угря', 'Отнесите огромную икринку угря Хамфри Ройпою на дно Затемненной впадины в Вайш\'ире.', '<Видимо, это икринка одного из ужасных огромных угрей, обитающих во впадине. Вы размышляете над тем, не заинтересуется ли ею Хамфри.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26020, 'ruRU', 'В распоряжение Бомбиглотc', 'Поступите в распоряжение взрынженера Бомбиглотc в крепости Кром\'гар в Когтистых горах.', 'Надо подготовиться к нападению. Наши солдаты подготовят бомбу. А тебе нужно отправиться к взрынженеру Бомбиглотc. Она работает над починкой орудий противовоздушной обороны, но пока безуспешно. Иди и убедись, $n, что она работает с должной мотивацией.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26021, 'ruRU', 'Братья Ройпой – 2: фокус с икринкой угря', 'При помощи угретонатора взорвите ужасного огромного угря в Затемненной впадине, а затем добейте раненого угря.', 'Эти угри сожрали моего брата. Брата, слышишь, $n! Пришло время показать им, кто здесь главный.$B$B<Хамфри достает несколько шашек динамита из карманов и вставляет их в икринку.>В одиночку с огромным угрем не справиться, но благодаря этой икринке мы сравняем силы. Оставь ее рядом с одним из угрей и... Ба-бах!$B$BЕсли угорь и не погибнет от взрыва, все равно будет сильно ранен, и ты его легко добьешь.', '', 'Бедный мой брат, бедный Оскар Ройпой! Его поглотил угорь.', 'Оскар Ройпой', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26022, 'ruRU', 'Первая кровь', 'Убейте наемников Синдиката и соберите 10 амулетов из кровавого камня.', 'Будь $gготов:готова;, $n. На этом поле ты прольешь за нас первую кровь.$b$bТе, кто называют себя Синдикатом, на самом деле трусливые людишки, способные предать своих же собственных собратьев. Изоляция делает их легкой добычей.$b$bОтправляйся на север, убей всех наемников Синдиката, какие тебе встретятся, и объяви Северное поместье принадлежащим Отрекшимся. В доказательство своей победы принеси мне амулеты из кровавого камня.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26023, 'ruRU', 'Отрекшийся Троллебой', 'Поговорите с Галеном Троллебоем.', 'Я расскажу тебе одну историю.$b$bЖил-был глупый тролль по имени Зенгу. Ему дали задание разыскать меч Трол\'калар, легендарный клинок, принадлежащий человеческому роду Троллебоев. Ему удалось это сделать и, уверенный, что задание выполнено, он решил покинуть Арати. После этого люди зарезали его, а меч просто-напросто отобрали.$b$bМы же не будем столь глупы. Наши аптекари дали нам идеального проводника для того, чтобы снова заполучить Трол\'калар: принца, который когда-то уже обладал этим мечом.$b$bОн готов проводить тебя, $n. Поговори с ним.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26024, 'ruRU', 'Разыскивается: Марез Клобук', 'Принесите голову Марез капитану Ниалс в Опорный пункт.', 'Назначена награда за голову Марез Клобук, высокопоставленной советницы и деятеля Синдиката. В последний раз ее видели на контролируемой Синдикатом территории Стромгарда.$B$BНаграду можно будет получить у капитана Ниалс.$B$BПредупреждение: Марез – опытная и коварная чернокнижница, замеченная в связях с демонами. При поимке рекомендуется предельная осторожность.', '', 'Принеси мне ее голову!', 'Марез Клобук', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26025, 'ruRU', 'Орк изменник', 'Найдите оскверненную сферу из кровавого камня Марез Клобук.', 'Я не сомневаюсь, что в стенах Стромгарда засел могущественный чернокнижник. Время от времени, используя некую святыню, обладающую магической энергией, этот чернокнижник в больших количествах призывал ужасных демонов. Мы должны отнять у него этот источник энергии.$B$BНайди чернокнижника и убей его. Принеси мне магический объект, который при нем найдешь, что бы это ни было. Я сделаю все, что нужно, чтобы разрушить эту святыню, и прослежу, чтобы ее мощь больше не использовалась для осквернения этой земли.', '', 'Добудьте оскверненную сферу Кровавого камня', 'Марез Клобук', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26026, 'ruRU', 'Мечта о будущем', 'Добудьте машину войны БА-64, механизированный огонь, механизированный лед и механизированный воздух.', 'Господин З.П. болен, $gсударь:сударыня;. Вы ему поможете? Надо всего лишь найти его шляпу и батарейки, и ему сразу полегчает. Я бы и сама их нашла, но я не могу оставить господина З.П. одного!$B$BЕго шляпу украли жадюги из Торговой Компании – вон там, у водяного колеса, а его батарейки спрятаны где-то возле Утеса Ветрорезов. Вы просто поищите их как следует!$B$BПожалуйста, принесите эти штучки господина З.П., чтобы он преподал этим плохим ребятам из Альянса хороший урок?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26027, 'ruRU', 'Призыв к оружию', 'Убейте 7 шаманов из клана Тяжелого Кулака и 3 вождей клана Тяжелого Кулака.', 'Для нашего следующего удара по ограм тебе нужно будет отправиться дальше на восток от Стромгарда. Оставшиеся в живых считают, что эти опустошенные руины стоят того, чтобы за них цепляться. Их сентиментальность отвратительна!$b$bДля нас весь Стромгард – не более чем еще одно смрадное логово огров, которых надо уничтожить. Отправляйся туда, убей их вождей и шаманов и убедись, что никто из оставшихся огров не сможет стать их предводителем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26028, 'ruRU', 'Дикая охота господина З. П.', 'Убейте 20 гномских инженеров и 5 гномских патрульных.', 'Теперь господину З. П. нужен добрый дух, который помог бы ему ориентироваться в пространстве. Вы не поработаете добрым духом, $gсударь:сударыня;? Если вы мне поможете, мы заберемся на эту скалу и перебьем много-много нехороших ребят из Альянса! Что скажете? Пожалуйста, $gсударь:сударыня;! НУ ПОЖАЛУЙСТА!$B$BЕсли мы перебьем много хулиганов из Альянса, господин Кром\'гар купит нам всем мороженое!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26029, 'ruRU', 'Настоящая угроза', 'Убейте Ор\'Калара и заберите его голову.', 'Здешними ограми руководит Ор\'Калар. Годами ему удавалось ускользать от расправы. Само его присутствие – это оскорбление Темной Госпожи. Муг\'тол, предатель Отрекшихся, издалека отдает ему приказы!$b$bНа земле Отрекшихся мы не потерпим ни огров, ни предателей. Принеси мне голову этого огра, а уж я прослежу, чтобы в этот раз ее точно сожгли.', '', 'Ор\'Калар на голову выше любого из своих соплеменников. Это надо исправить.', 'Ор\'Калар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26030, 'ruRU', 'Печать Строма', 'Заберите печать Строма у членов Синдиката в крепости Стромгард.', 'В древние времена лорд Игнеус, прозванный Троллебоем, возглавлял первую человеческую цивилизацию в войне против троллей. Его клинком был Трол\'калар – на их языке это означало \"убийца троллей\".$b$bЯ был одним из последних потомков Троллебоя, поклявшимся сохранить Трол\'калар... и не сдержавшим клятву. Но сейчас мы снова завладеем им, для моего нового хозяина. Меч скреплен тремя печатями. Первая в руках изменников Синдиката, которые прячутся в руинах Стромгарда. Убей их и принеси мне печать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26031, 'ruRU', 'Печать Торадина', 'Соберите 5 фрагментов печати, убив стромгардских защитников в крепости Стромгард.', 'При жизни, чтобы защитить печать Торадина, я разделил ее на пять частей и раздал их моим самым верным соратникам. Это не помогло, но мой преемник сделал то же самое.$b$bЗащитники Стромгарда до сих пор владеют частями печати. Убей их и принеси мне все фрагменты. Я соединю их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26032, 'ruRU', 'Печать Аратора', 'Заберите печать Аратора у лейтенанта Храброгласа.', 'Я доверил печать Аратора лейтенанту Храброгласу, командиру моих кавалеристов. Он едва не расстался с жизнью, защищая ее, но ему удалось тогда сбежать.$b$bВряд ли это получится у него и во второй раз. Храброглас патрулирует дорогу между крепостью Стромгард и Опорным пунктом. Найди его и снова забери у него печать.', '', 'Это был один из лучших, самых верных моих лейтенантов. Ну да ладно!', 'Лейтенант Храброглас', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26033, 'ruRU', 'Трол\'калар', 'Достаньте Трол\'калар из могилы Троллебоя в Стромгарде.', 'Последняя печать моя... и вместе с ней все четыре образуют печать Троллебоя, ключ к могиле. Мы готовы.$b$bТрол\'калар лежит рядом с останками своего владельца, в могиле в катакомбах Стромгарда. Его будут защищать... но тот факт, что я стою перед тобой, говорит о том, что любую защиту можно пробить.$b$bДостань Трол\'калар из могилы и принеси его сюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26034, 'ruRU', 'Сумеречный разрушитель', 'Победите Халиона и отразите нападение на Рубиновое святилище.', 'Нет, это было не случайное нападение, а организованная атака на род красных драконов.$B$BЯ вижу Заритриана, наблюдающего за битвой с вершины холма, но истинный лидер захватчиков – могущественный сумеречный дракон Халион. В первый раз после появления Даргонакса мы столкнулись со взрослым отпрыском Зловестины.$B$BУбей его, $n, изгони захватчиков и сообщи Красу обо всем, что ты здесь $Gвидел:видела;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26035, 'ruRU', 'На вес золота', 'Соберите 10 клыков троллей из племени Сухокожих и 4 лекарские сумки племени Сухокожих.', 'Верховный маг Малин послал меня собрать для него реагенты. Я был в полном замешательстве и не знал, как приступить к делу, но теперь, когда ты здесь, думаю, что моя проблема разрешится.$b$bВот что мне нужно: клыки тролля из племени Сухокожих и лекарские сумки племени Сухокожих.$b$bНе $gмог:могла; бы ты раздобыть все это для меня? Племя Сухокожих обитает к юго-востоку от Арати.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26036, 'ruRU', 'Оружие получше кулаков', 'Найдите заклинательный жезл Трелана и принесите его Скуэрто в Опорный пункт.', 'Эй, $n.$B$BПрости, что был так короток с тобой раньше... Нет, это не каламбур. Я выяснил, где оказалась первая вещь Трелана: Кор\'греш держит ее в Крепости Тяжелого Кулака. И судя по тому, как он кидался в своих глыбами льда, чтобы заставить их держать строй, он, должно быть, уже близко подошел к пониманию того, как использовать мощь жезла на полную катушку.$B$BЧтобы добраться до Крепости Тяжелого Кулака, нужно идти на юг, а затем у моста Тандола повернуть на восток. Найди этого огра и отбери у него жезл.$B$BА за время твоего отсутствия я соображу, что нам делать со Стромгардом.', '', 'Теперь, когда у нас есть жезл, мы можем действовать в соответствии с планом.', 'Кор\'греш Холодная Ярость', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26037, 'ruRU', 'Оборона Трелана', 'Найдите лазурный агат и принесите его ученику Крайтену в крепость Стромгард.', '$gОтдохнул:Отдохнула;?$B$BВот наш следующий шаг: огры так и кишат вокруг башни Аратора в Стромгарде. Необходимо активировать защитные возможности башни, чтобы иметь хоть малейший шанс выстоять против них. Чтобы это сделать, нам понадобится несколько самоцветов, на которые наложил лапы шаман клана Тяжелого Кулака. Он стянул их из башни, но радость его преждевременна – камни недолго будут в его власти.$B$BДостань один из самоцветов и принеси его Крайтену – он знает заклинание, которое нужно наложить на эти камни, чтобы они работали как ключи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26038, 'ruRU', 'Атака на башню', 'Найдите талисман Трелана, сферу Трелана и угольный агат Трелана и принесите их Скуэрто в Опорный пункт.', 'Вот что тебе нужно найти: талисман Трелана, сферу Трелана и угольный агат Трелана.$B$BВсе эти три предмета должны быть в сундуках в башне, и ты преспокойно откроешь эти сундуки. Главное – берегись огров.$B$BОружие лучше держать наготове. Эти огры сообразят, что ты там и пытаешься обокрасть их, и, ясное дело, решат задать тебе взбучку.$B$BБудь $gосторожен:осторожна; – и удачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26039, 'ruRU', 'Плененная принцесса', 'Отберите 12 частиц Мизраэль у кобольдов из племени Сухоусов.', 'Меня зовут Мизраэль. Я принцесса духов земли, и мои пленители – великаны – поймали меня в ловушку глубоко под нагорьем Арати. С миром на поверхности я могу говорить только при помощи этих кристаллов.$B$BПожалуйста, помоги мне. У союзников гигантов – кобольдов из племени Сухоусов – есть такие же кристаллы, они находятся в Теснине Сухоусов, к востоку отсюда. Чтобы объединить силу кристаллов, нужно отобрать у кобольдов частицы Мизраэль.$B$BПрошу тебя, $n, помоги мне!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26040, 'ruRU', 'Ой-ой – что со мной?', 'Соберите 7 побегов вьющихся водорослей у жнецов Мерцающего хребта на Жемчужной ферме.', 'Ох... да что ж такое?!$B$BВнутри все болит... и крутит...$B$BПохоже... эх... Меня отравили!$B$BНас накормили какими-то странными светящимися водорослями, которые выращиваются у крепости.$B$BМне кажется, живот схватит еще сильнее, если не съесть еще маленько...$B$BПрошу тебя, |3-6($r), принеси водорослей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26041, 'ruRU', 'Связывающие камни', 'Соберите огненный ключ, резной ключ и громовой ключ с западного, восточного и внешнего связывающих камней.', 'Четыре связывающих камня разбросаны по Нагорью Арати. Эти камни пригвоздили меня к земле.$b$bРазрушить оковы можно, сняв замок с самого мощного из них – внутреннего связывающего камня. А чтобы сделать это, придется собрать ключи с остальных трех камней.$b$bЭти камни охраняют стражи, но если у тебя хватит ума или удачи, тебе удастся найти возможность справиться с ними.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26042, 'ruRU', 'Разбить краеугольный камень', 'Заберите у Фозрука Жезл Порядка.', 'Открыв камни Обета, ты $gосвободил:освободила; меня от большей части моих оков, но еще кое-что удерживает меня. Это краеугольный камень, который ты видишь среди других камней круга. А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук.$b$bОтбери у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и открой им краеугольный камень.$b$b$n, ты так много $gсделал:сделала;, чтобы мне помочь... Еще немного... и моя благодарность не будет знать границ!', '', 'Заберите Жезл Порядка!', 'Фозрук', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26043, 'ruRU', 'Берегись Рифогрыза!', 'Убейте Рифогрыза и заберите огромный зуб Рифогрыза.', 'По приказу властителя Кром\'гара купание в Скалистом озере ЗАПРЕЩЕНО!$B$BЗлобная тварь, известная как Рифогрыз, превратила озеро в смертельную ловушку. Тот, кто разделается с Рифогрызом, должен забрать его огромный зуб и прийти к главе шпионов Анаре для получения награды.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26044, 'ruRU', 'Ну, и где детали?', 'Поговорите с сержантом Донтрагом в Глубоких плёсах, что в Когтистых горах.', 'Я уже столько времени жду эти детали! Пять дней назад мой лучший взрынженер и две дюжины шахтеров отправились за ними в Глубокие плёсы. Три дня от них не было ни слуху ни духу, мне уже стало не по себе. Властитель отправил двух лучших орков выяснить, что случилось. И те тоже сгинули, никаких вестей от них...$B$BОтправляйся в Глубокие плёсы под этой крепостью и узнай, что случилось. Мне нужны детали!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26045, 'ruRU', 'Где-то тут были запчасти...', 'Соберите 10 запчастей.', 'Никак не могу выбрать из двух зол: подохнуть тут, как все остальные, или умереть в крепости Кром\'гар, когда властитель Кром\'гар узнает, что мы потеряли шахту. Есть и третий вариант – не сделать ни того, ни другого. Посмотрим, что выйдет.$B$BТебе нужны запчасти? Их тут полно, они по всей шахте разбросаны. Надо просто их собрать.$B$BУдачи! Может, если ты соберешь эти запчасти, нам не страшно будет показаться в крепости Кром\'гар.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26046, 'ruRU', 'Между молотом и наковальней', 'Убейте 12 бушующих духов земли.', 'Донтраг объяснит лучше, чем я. Но суть в том, что мы находимся между молотом и наковальней. Тут мы ничего не сможем сделать, потому что нам грозит смерть, а вернуться в лагерь мы не можем, потому что нам грозит смерть, понимаешь?$B$BВот если бы мы объединили усилия, может, что-нибудь из этого и вышло бы. Может, начнешь с истребления элементалей, которые уничтожили все этой шахте, а?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26047, 'ruRU', 'Батраки – они такие...', 'Спасите 10 испуганных батраков.', 'Эти двое БЕС-ПО-ЛЕЗ-НЫ! Когда они только прибыли, я думал, что мы спасены. Как бы не так! Вместо того чтобы нас спасать, Донтраг и Утвоч глянули разок на шахту и придумали какой-то идиотский план, в котором главное – стоять тут... пока не сдохнем, видимо.$B$BНо ты, вроде, поумнее их выглядишь. Может, ты поможешь? У меня тут куча батраков перепугалась до потери пульса и разбежалась по Глубоким плёсам. Найди их и спаси!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26048, 'ruRU', 'Запчасти сюда!', 'Доставьте ящик с запчастями взрынженеру Бомбиглотc в крепость Кром\'гар в Когтистых горах.', 'Уф, ну и работенка! Я и не думал, что мы справимся, $n. А теперь надо отнести эти запчасти взрынженеру Бомбиглотc. Кажется, я слышу жужжание гномских ветролетов. Нельзя терять ни минуты!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26049, 'ruRU', 'Освобожденная принцесса', 'Призовите к кристаллам Мизраэль и победите ее.', 'Мизраэль – вовсе не безобидная плененная принцесса. Она обладает смертоносной силой, и великаны имели все основания, чтобы приковать ее здесь. Боюсь, что тебя надули.$b$bПо словам Геррика, тебе нужно призвать ее к кристаллам Мизраэль, при помощи которых ты в первый раз $gразговаривал:разговаривала; с ней. Победи ее, забери ее мистические оковы и присоедини их к кристаллам. Вот свиток, который тебе пригодится. Береги его, чтобы его достать, я лишился нескольких зубов. Удачи тебе, $n.', '', 'Освободи ее… и уничтожь.', 'Мизраэль', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26050, 'ruRU', 'Хитрые очки', 'Проводите профессора Физзлторпа в пещеру и обратно.', 'Теперь, когда мы настоящие пираты Черноводья, мы должны помочь мистеру О\'Брину разыскать пропавшее эльфийское сокровище.$b$bНайти драгоценные камни в море без посторонней помощи почти невозможно. Доктор сконструировал специальные очки, которые должны помочь. Ему нужно зарядить эти очки энергией, извлеченной из заколдованного камня в пещере, расположенной выше по холму.$b$bНо эта пещера проклята! Когда мы подошли к ней, на нас напали. Защити меня, и тогда я смогу вытянуть энергию из камня и направить ее в очки.', 'Защитите профессора Физзлторпа', '', '', '', '', 'Вернитесь к доктору Драксельмеру в Бухту Фальдира на нагорье Арати.', 25549);
INSERT INTO `quest_template_locale` VALUES (26051, 'ruRU', 'Затонувшее сокровище', 'Доктор Драксельмер в бухте Фальдира просит вас собрать 10 эльфийских самоцветов и после этого вернуть ему очки Ловца сокровищ.', 'Сокровища так долго лежали на дне моря, что покрылись известковым налетом, превратившись в большой камень. Но сила, влитая в эти очки, позволит тебе легко определить их местонахождение.$b$bМаленькая гномская хитрость делает большие дела!$b$bВозьми эти очки Ловца сокровищ, $n, посмотри, может, тебе удастся собрать какие-то из утерянных сокровищ для капитана О\'Брина.$b$bЯ бы и сам поплыл туда, но... гм... ну, у меня есть серьезные научные задачи, требующие срочного решения на надежной, сухой земле... да... вот.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26052, 'ruRU', 'Разговор с Мурашом', 'Отнесите эльфийские самоцветы капитану О\'Брину в бухту Фальдира на нагорье Арати.', 'Не будем заставлять капитана О\'Брина ждать. Он захочет первым увидеть эти драгоценности. В конце концов, для того мы и здесь!$b$bЧерез несколько недель сотрудничества с этими пиратами мы с профессором отлично поняли, что когда мы придерживаем их сокровища, на нашем здоровье это сказывается самым пагубным образом.$b$bВот, $n, отнеси все это О\'Брину.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26053, 'ruRU', 'Очистить нагорье', 'Убейте 8 огров из клана Тяжелого Кулака и 10 головорезов из клана Тяжелого Кулака.', 'Ни одна угроза здесь не останется незамеченной. Если нам нужно защитить земли, где правит Темная Госпожа, значит, мы пройдем их пядь за пядью, пока не уничтожим все живое.$b$bК северо-востоку отсюда, в двух шагах от этого лагеря есть холм, где живут огры из клана Тяжелого Кулака. Нужно истребить их всех до единого, |3-6($c).$b$bОни нам мешают. Будь $gтвердым и безжалостным:твердой и безжалостной;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26054, 'ruRU', 'Что-то они там мутят', 'Убейте Кай\'жу Газ\'риллу и поставьте об этом в известность генерала Маркуса Джонатана в Штормграде.', 'Так тролли из племени Песчаной Бури работают заодно с культом Сумеречного Молота?!$B$BЛадно. Я не позволю этой вонючей ведьме посылать чудовищ в МОЙ город.$B$BСмельчаки, за мной! Мы обагрим песок кровью этих гадов и станем победителями. А когда вернемся, расскажи генералу Маркусу Джонатану обо всем, что здесь произошло. Сам-то я буду занят – кто-то должен присматривать за возвращением горожан, ремонтными работами и прочим.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26055, 'ruRU', 'Затонувшие печали', 'Капитан Стальные Нервы из бухты Фальдира хочет, чтобы вы убили 10 налетчиков и 3 колдуний из клана Пронзающего Гребня.', 'Ох, жизнь – ужасная штука. Я должен бы покоиться на дне моря, а не сидеть здесь у огня, наслаждаясь свежим воздухом.$B$BКоманда не жалела сил, чтобы спасти мою прекрасную \"Девичью Блажь\". Да упокоятся мои ребята в мире, пусть будут благословенны их сердца.$B$BО\'Брину удалось выбраться на берег, а нам не повезло. Море просто опрокинулось на нас, клянусь тебе.$b$bВот мы плывем – и вдруг следующая волна обрушивается на нас. А эти твари! Они убили всех, кто остался в живых. Подлое нагово отродье. Я потерял сознание и пришел в себя уже здесь.$b$bЯ жажду их смерти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26056, 'ruRU', 'Говорящая с волнами', 'Разыщите говорящую с волнами Валорен в Глубинах Кошмаров в Вайш\'ире.', 'Говорящая с волнами Валорен из Служителей Земли уплыла в Глубины Кошмаров, что на северо-востоке, и с тех пор ее больше никто не видел. Боюсь, как бы с ней беды не приключилось...$B$BОтправляйся туда и попробуй ее разыскать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26057, 'ruRU', 'Говорящая с волнами', 'Разыщите говорящую с волнами Валорен в Глубинах Кошмаров в Вайш\'ире.', 'Говорящая с волнами Валорен из Служителей Земли уплыла в Глубины Кошмаров, что на северо-востоке, и с тех пор ее больше никто не видел. Боюсь, как бы с ней беды не приключилось...$B$BОтправляйся туда и попробуй ее разыскать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26058, 'ruRU', 'Защита крепости Кром\'гар', 'Уничтожьте 15 гномских ветролетов или бомбардировщиков и 25 командиров звена гномов.', 'Времени нет! Они идут! Становись к пушке и сбивай гномов с неба! Если на эту бомбу придется много попаданий, она взорвется вместе с нами!$B$BЗащищай базу, $n! На тебя вся надежда!$B$BЕсли мы справимся, отправишься с донесением к властителю Кром\'гару лично.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26059, 'ruRU', 'Глаза и уши: Малака\'джин', 'Отправляйтесь к Знахарю Джин\'Зилу в Малака\'джин, что в Когтистых горах.', 'Застава Чести потеряна. Власть над Степями разлетелась на куски вместе с этой землей. Я получаю сведения о том, что в результате совместной атаки Альянса и Зловещего Тотема мы можем потерять и Малака\'джин. Если Малака\'джин падет, половина Когтистых гор падет с ним!$B$BТы отличный солдат Орды. Станешь моими глазами и ушами в Малака\'джине?$B$BЗнахарь Джин\'Зил ждет тебя.$B$BМалака\'джин находится далеко на юге.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26060, 'ruRU', 'Вуду: сердце скалозавра', 'Добудьте сердце скалозавра.', 'Вуду может помочь нашим войскам отбить атаку Зловещего Тотема. А значит, мне понадобятся кое-какие компоненты, чтобы заняться черной магией$B$BПервый компонент в списке – сердце скалозавра. Этих животных почти истребили, но в здешних краях еще осталось несколько штук. Найди одного из них и принеси мне его сердце, еще теплое!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26061, 'ruRU', 'Вуду: бараний рог', 'Добудьте 6 рогов баранов Когтистых гор.', 'Мне понадобятся некоторые компоненты, чтобы заняться черной магией. Принеси мне рога баранов Когтистых гор, $n! Без них у нас ничего не получится!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26062, 'ruRU', 'Вуду: кристалл резонита', 'Добудьте 8 кристаллов резонита.', 'Последняя составляющая для ритуала вуду – это особый кристалл, который называется резонитом. Его можно найти только в пещерах Камнепадов, что к западу отсюда. Берегись кобольдов! Они будут защищать резонит до последней капли крови!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26063, 'ruRU', 'Королеву играет свита', 'Убейте королеву Силит и любых 10 пауков в Паучьей лощине.', '<Дарн фыркает.>$B$BХмм!$B$BВсе не так, как должно быть. Дарн недоволен. Подругу Дарна убили пауки, в Паучьей лощине. Дарн требует мести!$B$BПоможешь Дарну? Убьешь королеву Силит и ее паучат? Ради Дарна? За подругу Дарна!$B$BПаучья лощина – к северо-западу отсюда вверх по тропе! Иди!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26064, 'ruRU', 'Война с голодом', 'Соберите 8 яиц калимдорских орлов.', 'Войска хотят есть, $n. Поставки продовольствия прекратились, а еды у нас остается все меньше. Если ты достанешь мне продукты, я накормлю солдат до отвала.$B$BИди в лес к западу отсюда и поищи гнезда калимдорских орлов. Забери яйца из гнезд и принеси их мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26065, 'ruRU', 'Освободите Вил\'ле', 'Уничтожьте все щупальца ужаса и освободите Вил\'ле.', 'Поднявшиеся из глубин щупальца ужаса удерживают бедное создание и не дают выбраться. Его надо спасти. Ты сможешь убить этих тварей, $n?$B$BОсвободишь Вил\'ле?$B$BВот, возьми мой тотем и поставь его рядом со щупальцами. От тотема исходит холод, а эти чудовища его не выносят. Они съежатся от холода, и тебе будет легче их уничтожить.', '', 'Освободите Вил\'ле', 'Вил\'ле', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26066, 'ruRU', 'Подкрепление...', 'Используйте хлыст поработителя Дэво, чтобы поработить 6 кобольдов из племени Камнепадов.', 'Кажется, наш запас здоровенных тупых орков, которых можно послать на врага, на исходе. Это плохо. Но есть у меня одна идея...$B$BВозьми этот хлыст и иди на запад, к пещере Камнепадов. В той пещере обосновались грязные кобольды. С помощью этого хлыста ты сможешь подчинить этих тварей, и они будут делать все, что нам надо.$B$BВозвращайся, когда наберешь целый отряд.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26067, 'ruRU', 'Магия Джин\'Зила', 'Используйте вудуистскую палку Джин\'Зила, чтобы наслать на 12 кром\'гарских мародеров магию вуду.', 'Готово! Теперь надо проверить, что у нас получилось.$B$BИди на поле битвы в долину Высокого леса и испробуй мою вудуистскую палку на кром\'гарских мародерах, которые сражаются со Зловещим Тотемом. Магия вуду придаст им сил и поможет перебить врагов!$B$BПоторопись, $n!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26068, 'ruRU', 'Кобольды, вперед!', 'Используйте боевой рог кобольдов рядом со знаменем Орды на Месте раскопок, чтобы послать в бой армию кобольдов!', 'Теперь мы командуем армией кобольдов Когтистых гор! Впечатляюще звучит! Ну, почти...$B$B<Дэво вздыхает.>$B$BЛагерь Альянса к северу отсюда охраняется очень бдительно. В него можно попасть только через место раскопок к северо-востоку отсюда. Возьми боевой рог кобольдов и иди с ним к месту раскопок. Заходи с востока, $n! Когда окажешься там, поверни на запад и иди, пока не достигнешь зоны, которую я обозначил на карте. Протруби в рог, чтобы натравить кобольдов на Альянс!', 'Армия кобольдов начинает атаку!', '', '', '', '', 'Вернитесь к поработителю Дэво в Малака\'джин в Когтистых горах.', 25549);
INSERT INTO `quest_template_locale` VALUES (26069, 'ruRU', 'Нура Землепроходица', 'Поговорите с Нурой Землепроходицей на Верхнем пути в Южных степях.', 'На Южные степи напал Альянс. Таурены попросили помощи, и мы не можем им отказать. Наш долг – сделать все, что в наших силах.$B$BЕсли хочешь помочь, иди по тропе к Верхнему пути, что в деревне. Найди Нуру Землепроходицу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26070, 'ruRU', 'Уничтожение скверны', 'Уничтожьте несколько угрей-сокрушителей, глубоководных прилипал или ловцов провала – в общей сложности 8 тварей.', 'Наши друзья из Служителей Земли обратились к нам за помощью. Похоже, в Жгучем провале завелись какие-то безликие демоны, которые оскверняют живую природу.$B$BЗаймешься оскверненными существами?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26071, 'ruRU', 'Уничтожение скверны', 'Уничтожьте несколько угрей-сокрушителей, глубоководных прилипал или ловцов провала – в общей сложности 8 тварей.', 'Служители Земли, хотят, чтобы мы поубивали за них. В Жгучем провале завелись какие-то безликие демоны, которые оскверняют природу.$B$BОтправляйся туда и займись оскверненными существами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26072, 'ruRU', 'Зарядка тотема', 'Уничтожьте 5 безликих сквернителей в непосредственной близости от улавливающего тотема.', 'Бери мой тотем и отправляйся в Жгучий провал. Там зарядишь его энергией умирающих безликих. Тотем впитает их энергию и не даст вернуться туда, откуда они появились.$B$BКогда тотем полностью зарядится, возвращайся, и мы с его помощью выманим из глубин их предводителя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26073, 'ruRU', 'На южном фронте без перемен', 'Поговорите с властителем Кром\'гаром в крепости Кром\'гар в Когтистых горах.', 'Вернись теперь к властителю Кром\'гару, $n. Расскажи ему, как идут наши дела и что ты $gсделал:сделала; для того, чтобы Малака\'джин не пал.$B$BПрими благодарность от всех нас. Может статься, что когда-нибудь ты будешь править собственными владениями.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26074, 'ruRU', 'Начало конца', 'Доставьте кром\'гарский воздушный шар к илоразработкам в Когтистых горах.', '$GГерой:Героиня;, у нас новая цель. Разведчики из долины Боевого Шрама донесли, что ночные эльфы создали оружие массового уничтожения и прячут его в древнем дереве. Нельзя дать им возможность использовать это оружие против нас.$B$BТебе придется сопровождать бомбу до илоразработок, чтобы ее там заправили, а потом на Плато Скалоступов, с которого мы и сбросим бомбу на врагов.$B$BИди, $n. Обязательно встреться с Джиббли Ракитом на илоразработках.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26075, 'ruRU', 'Грязь по колено', 'Убейте 6 величавых виверн любого вида.', 'У нас тут проблемка...$B$B<Джиббли показывает на большие куски фекалий, лежащие на полу.>$B$BИлоразработки построены рядом с гнездом виверн. С самого начала Илоразработки проектировались так, чтобы не тревожить этих тварей, – они, видишь ли, священные для тауренов и орков. А знаешь, что священно для меня? Чистые ноги, и чтоб их не приходилось отчищать от всякой дряни!$B$BМежду нами, надо бы избавиться от этих зверюг!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26076, 'ruRU', 'Шпионы-паразиты', 'Убейте 8 шпионов Альянса. Для разоблачения шпионов используйте газовую бомбу Джиббли.', 'У нас проблема, $n. Шпионы Альянса повсюду! Ты их не $gвидел:видела;? Это потому что они невидимые! Под прикрытием! Я знаю, что надо делать, но мне нужен помощник вроде тебя, чтобы отправиться туда и осуществить мой план.$B$BИспользуй газовую бомбу, чтобы шпионы проявились. Как только увидишь их, разделайся с ними.$B$BШпиона под прикрытием можно узнать по следу, который он оставляет в воздухе. Смотри внимательней!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26077, 'ruRU', 'Доставка до места назначения', 'Доставьте кром\'гарский воздушный шар на Плато Скалоступов в Когтистых горах.', 'Властитель Кром\'гар прислал приказ. Тебе надо сесть на кром\'гарский воздушный шар и доставить его на Плато Скалоступов. Оттуда надо сбросить груз на силы Альянса в долине Боевого Шрама.$B$BДавай, $n. Не надо заставлять Кром\'гара ждать.$B$BПоговори с генералом Гребо, когда прибудешь на место назначения. Он скажет, что тебе делать дальше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26078, 'ruRU', 'Потушить огонь', 'Воспользуйтесь противопожарным оборудованием, чтобы потушить 6 пожаров на аэродроме Стальгорна.', 'Атака Черного Железа застала нас врасплох. Их диверсантам удалось повредить большинство наших летательных аппаратов, паровых танков и припасов. У нас получилось поднять в воздух только несколько наших бомбардировщиков.$b$bВсе техники, рекруты и стражники, которых я могу выделить, пытаются отремонтировать остальные и сделать так, чтобы они могли взлететь. Пехота пока держится. Возьми это оборудование и помоги потушить горящие бомбардировщики.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26079, 'ruRU', 'Разыскивается: Отто и лорд Соколиный Шлем', 'Принесите головы Отто и Соколиного Шлема капитану Ниалс в Опорный пункт.', 'Ополчение Штормграда объявляет о назначении вознаграждения за головы лорда Соколиного Шлема и его телохранителя Отто. Соколиный Шлем руководит деятельностью Синдиката на нагорье Арати, и его смерть внесла бы большую сумятицу.$B$BЕго телохранитель Отто хотя и не является стратегической целью, представляет собой опасного противника, на счету которого смерть десятков наших воинов.$B$BНаграды за их головы можно получить у капитана Ниалс.', '', 'У него хорошая защита. Будь осторожнее.', 'Лорд Соколиный Шлем', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26080, 'ruRU', 'Последняя услуга', 'Отнесите ройпоевскую рыбу в бумаге капитану Гловаалю в Темную пещеру.', '$n, мне придется попросить тебя отнести это капитану Гловаалю. В таком состоянии я буду неделю добираться до Темной пещеры, а времени у нас совсем нет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26081, 'ruRU', 'Награда Алины', 'Поговорите с темным следопытом Алиной.', 'Здесь заканчивается история Трол\'калара. Он будет орудием, во имя Темной Госпожи несущим смерть всему живому.$b$bТеперь оставь меня, $n. Мое дело – хранить этот клинок. Расскажи Алине о своей победе, уверен, она наградит тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26082, 'ruRU', 'К Боевому Шраму!', 'С помощью кром\'гарского разрушителя убейте 5 дарнасских метателей глеф и 20 любых солдат Альянса в долине Боевого Шрама.', 'Пусть этот старый дурень затевает расследование. Он уверял меня, что непременно докажет, будто у ночных эльфов нет оружия массового поражения.$B$BА пока мы ждем его доказательства, ты поможешь моей армии в долине. Мы там подготовили много осадных танков, и разрушители наши только и ждут сигнала к бою.$B$BСадись в лифт, поезжай вниз, в подвал заставы, и выбери там себе кром\'гарского разрушителя. Ну а потом с его помощью задай жару нашим врагам в долине Боевого Шрама.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26083, 'ruRU', 'Привет, Лоло', 'Найдите дозорного Лоло в бухте Фальдира.', 'Потрохаря прислали следить. Смотреть на разные вещи. Большое приключение!$b$bПотрохарь нашел секретное пиратское судно. Все пираты пугаться, бежать. Но огр Лоло не бежать. Лоло дружить с Потрохарем!$b$bПотрохарь должен идти, но скучать по Лоло. Передай ему привет от Потрохаря.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26084, 'ruRU', 'Павший Молот', 'Отправляйтесь с докладом к Гор\'мулю в Павший Молот, что на нагорье Арати.', 'Ты $gсослужил:сослужила; нам отличную службу, $n. Теперь, когда мы заявили здесь о себе, следующий этап завоевания – дело нескольких месяцев, а вовсе не минут.$b$bНам еще многое нужно сделать, и я избавлю тебя от томительного ожидания, когда здесь появятся наши укрепления. Отправляйся на восток, в Павший Молот. Твоя помощь наверняка пригодится тамошним оркам.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26085, 'ruRU', 'Сплочение защитников', 'Установите 8 знамен Стальгорна над сугробами из рыхлого снега в разных частях аэродрома Стальгорна.', 'Пока наши инженеры работают над тем, чтобы бомбардировщики снова могли подняться в воздух, стражи и горные пехотинцы продолжают бой с захватчиками.$b$bОни ведут бой с самого начала вторжения, без перерывов на еду и сон. Защитники Стальгорна одни из лучших в Азероте, но и их возможности не безграничны. Возьми эти знамена и воткни их в сугробы рыхлого снега. Напомни бойцам, за что они дерутся, помоги поднять их боевой дух.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26086, 'ruRU', 'Орако', 'Поговорите с Орако в Затемненной впадине в Вайш\'ире.', '<Капитан Верн смотрит на часы.>$B$BКуда запропастился этот охотник? Неделю назад отправил Орако на разведку в Затемненную впадину! Я, конечно, не против и вовсе от него избавиться, но мне нужен отчет.$B$BКак тебя зовут? $n? Может, ты его отыщешь? Немного странно отправлять |3-3($c) на поиски охотника, но у меня нет другого выбора.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26087, 'ruRU', '\"Светящийся сок\"', 'Добудьте 6 порций светящегося сока из огнепанцирных крабов и блестящих окуней в Затемненной впадине.', 'Легко подстрелить рыбу в бочке, а вот сделать это в океане непросто.$B$BТебе во впадине попадались мурлоки, |3-6($c)? Вот им ничего не стоит рыбку поймать! У них на головах такие специальные шарики с флуоресцентным соком, поэтому рыба сама к ним плывет. Нам тоже нужно воспользоваться этим способом!$B$BОтправляйся на юг и убей крабов и окуней. В них много светящегося сока, сам видел!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26088, 'ruRU', 'Ловись, рыбка!', 'Наденьте шляпу рыболова и проплывите через заросли водорослей в Затемненной впадине, чтобы привлечь 30 люминесцентных гирелл.', '<Орако наполняет светящимся соком специальный шарик, а затем прикрепляет его к устройству, над созданием которого он, по-видимому, очень долго трудился.>$B$BВот, я тебе сделал такую шапку. На ней специальный огонек, так что рыба приплывет тебе прямо в руки. Как к мурлокам!$B$BМурлоки, как правило, охотятся в зарослях водорослей и кораллов рядом со впадиной. Надень эту шапку и проплыви через водоросли – надеюсь, тебе удастся наловить рыбы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26089, 'ruRU', 'Я убью тебя, рыба', 'Убейте 4 охотников Холодного Сияния и 4 оракулов Холодного Сияния.', 'Рыба проглотила моего волка. Мурлоки похожи на рыбу – вот они и заплатят за его смерть!$B$BВозвращайся во впадину и уничтожь этих тварей! Отомсти за моего волка!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26090, 'ruRU', 'Я принес тебе икринку', 'Отнесите огромную икринку угря Орако в Затемненную впадину в Вайш\'ире.', '<Похоже, это икринка одного из ужасных огромных угрей, обитающих во впадине. Вы размышляете над тем, не заинтересуется ли ею Орако.>', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (26091, 'ruRU', 'Ловись, рыбка – 2: фокус с икринкой угря', 'При помощи угретонатора взорвите ужасного огромного угря в Затемненной впадине, а затем добейте раненого угря.', '<Орако достает из своего мешка взрывную ловушку и вставляет ее в икринку.>$B$BМы превратим эту икринку в бомбу. Оставь ее неподалеку от огромного угря и подожди, пока тот подплывет поближе. После взрыва рыба будет уже при смерти, и ты легко с ней разделаешься.$B$BСпаси моего волка! С этой икринкой у тебя все получится.', '', '', 'Волк', '', '', 'Вернитесь к Орако в Затемненную впадину в Вайш\'ире.', 19865);
INSERT INTO `quest_template_locale` VALUES (26092, 'ruRU', 'Донесение Орако', 'Отнесите донесение Орако капитану \"Жуху\" Верну в Зловещий грот.', '<Вы напоминаете Орако, что он должен отправить капитану Верну отчет.>$B$BТочно, отчет! Да я здесь, кроме рыбы, и не видел ничего. Громадное количество рыбы.$B$B<Орако смотрит на мешок с рыбой, который вы ему принесли.>$B$BОтнеси это капитану. Вместо отчета.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26093, 'ruRU', 'Северное поместье', 'Убейте 10 наемников Стромгарда в Северном поместье.', 'Мы ведем войну за Стромгард и терпим в ней поражение. Мы делим наш некогда великий город с ограми и Синдикатом, одна фракция бьется с другой, и конца этому не видно.$b$bНо наши силы иссякают, в то время, как силы наших врагов – растут.$b$bИ хотя Южнобережье пало, мы не должны допустить, чтобы еще какая-то из наших земель досталась врагу.$B$BОтправляйся на базу Синдиката в Северном поместье и убей их. Мы должны объявить эту территорию своей до того, как до нее доберется Орда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26094, 'ruRU', 'Ответный удар', 'Поднимитесь в воздух на отремонтированном бомбардировщике и при помощи железных штурмовых бомб убейте 30 атакующих Черного Железа. Можно убивать любых дворфов Черного Железа или их союзников на аэродроме Стальгорна.', 'Мой главный инженер говорит, что ему удалось отремонтировать один из бомбардировщиков, и теперь он готов к полету. Возьми эти бомбы и отправляйся к отремонтированному бомбардировщику, он стоит в начале взлетно-посадочной полосы.$b$bКогда поднимешься в воздух, сбрасывай бомбы и постарайся нанести атакующим дворфам из Черного Железа как можно больший урон. Ходили слухи, что они собираются воспользоваться новым видом боевого голема. Смотри в оба, если обнаружишь этих боевых големов, они должны стать для тебя целью номер один.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26095, 'ruRU', 'Знаки Стромгарда', 'Отберите 7 знаков Стромгарда у членов Синдиката в крепости Стромгард.', 'Синдикат в Стромгарде воюет с силами нашего ополчения. Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев.$B$BМы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят!$B$BОтправляйся в район Стромгарда, контролируемый Синдикатом, и отбери у их бойцов наши знаки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26096, 'ruRU', 'Жгучие грибы', 'Соберите 5 жгучих грибов.', 'Кажется, мы нашли применение Безжалостным, которых принес нам твой друг из пещеры. Но к ним еще требуется консервант.$B$BТам внизу, в Жгучем провале, произрастают особые грибы, обладающие необходимыми мне свойствами. Принеси эти грибы, и я посмотрю, что можно сделать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26097, 'ruRU', 'Доказательство лжи', 'Найдите Ортия в роще Тал\'дары в Когтистых горах.', 'В самом сердце долины Боевого Шрама растет старинное древо. Оно выстояло пред силой самого времени, и многие поколения мирно отдыхали или обучались в его сени. Сколько я себя помню, мои собратья вместе с ночными эльфами изучали в роще друидизм. А теперь я должен поверить, что якобы в том дереве скрывают оружие массового поражения?$B$BКром\'гар неправ, и найду этому доказательства!$B$BЯ отправил своего сына, Ортия, в рощу Тал\'дары, чтобы он нашел там. Ступай туда и встреться с ним.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26098, 'ruRU', 'Предательство в чаще', 'Отнесите знак различия кром\'гарского генерала верховному вождю Скалоступу на Плато Скалоступов в Когтистых горах.', 'В этой комнате одни мертвые друиды. Здесь явно что-то не так, потому что следов борьбы нет. К двери ведет кровавый след, будто что-то тащили.$B$BВы разжимаете мертвую руку Ортия и с удивлением обнаруживаете в ней знак различия кром\'гарского генерала.$B$BНужно отнести это верховному вождю Скалоступу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26099, 'ruRU', 'Это ли правосудие?', 'Защитите себя.', 'Он был таким славным парнишкой, $n. Такой молодой, душевный... Он в жизни бы не поднял руку на молодого друида. Они с ним дружили! Нет... Только не Ортий.$B$BЗа это преступление нужно призвать к ответу генерала! Я добьюсь справедливости!', 'Защитите себя.', '', '', '', '', 'Поговорите с Машей Скалоступ на Плато Скалоступов в Когтистых горах.', 25549);
INSERT INTO `quest_template_locale` VALUES (26100, 'ruRU', 'Генерал мертв', 'Поговорите с властителем Кром\'гаром в крепости Кром\'гар в Когтистых горах.', 'Может, ты поговоришь с властителем Кром\'гаром, $n? Может, к твоим словам он прислушается? В конце концов, ты $gодин из героев:одна из героинь; его армии. И ты $gвидел:видела; все своими глазами. Прошу тебя, помоги нам, $n. Нам ничего не надо, только оставили бы нас в покое!$B$BПоговори с властителем Кром\'гаром и попытайся убедить его, что мы сами не хотели, чтобы все так вышло!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26101, 'ruRU', 'Прав сильнейший', 'Встретьтесь с властителем Кром\'гаром на Плато Скалоступов в Когтистых горах.', 'Ты правильно $gпоступил, что доложил:поступила, что доложила; об этом преступлении. Виновники этого гнусного преступления будут наказаны. Прольется кровь.$B$BТеперь, когда Гребо мертв, мне понадобится новый генерал, поэтому его место займешь ты.$B$BЯ буду ждать тебя на Плато Скалоступов, генерал. Давай вместе прекратим весь этот бред.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26102, 'ruRU', 'Кончина Лютореза', 'Убейте генерала Лютореза на аэродроме Стальгорна.', 'Благодаря твоей инициативе мы наконец получили преимущество в битве с кланом Черного Железа. Генерал Люторез, предводитель Черного Железа, находится в центре их расположения на замерзшем озере, что к югу отсюда, и пытается собрать войска.$b$bОн выкрикивает приказы своим бойцам, забравшись на одного из их новых железных големов. Если у него получится собрать их, они по-прежнему будут в состоянии одержать над нами верх. Ты $gдолжен:должна; предотвратить это, $n. Разрушь голема и убей самого генерала Лютореза. Это ключ к нашей победе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26103, 'ruRU', 'Биотопливо', 'С помощью жироотсоса добудьте в Краю Кортуна по 4 банки черепашьего жира, жира прилипалы и жира акулы-молота из тел водорослевых черепах, прилипал-чистильщиков и чешуеспинных акул-молотов.', 'Топливо для подводной лодки стоит очень дорого!$B$BВласть имущие Гномрегана расщедрились и выдали нам несколько бочек, но топливо расходуется гораздо быстрее, чем мы ожидали. Значит, придется импровизировать.$B$BНе секрет, что в организмах морских обитателей много разных химических веществ... В том числе жиров. Возьми это устройство и отправляйся в Край Кортуна. Воткни его в трупы черепах, прилипал и акул-молотов. Если мы не получим топлива, их жир может стать для нас единственным выходом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26105, 'ruRU', 'Защита Края Кортуна', 'Убейте 7 морских волков Адского Крика в Краю Кортуна.', 'Здесь рыщут шпионы Орды? Тут поблизости Темная пещера, а в ней – \"Хват X2\"! Ни в коем случае нельзя подпускать туда Орду!$B$BНужно будет сообщить об этом кое-кому в пещере... Но для начала разделайся с этими наглыми ищейками Орды.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26106, 'ruRU', 'Топливоведение-101', 'Создайте идеальное биотопливо при помощи стола для приготовления топливных образцов в Темной пещере.', 'Что тебе известно о топливе, $n? Создание топлива – очень сложный процесс. Нужно учитывать множество различных показателей: временные параметры переокисления, переменные горючепрочности, критерии силицификации горения... Уж не говоря обо всех остальных факторах.$B$BНадеюсь, если те ингредиенты, которые ты мне $gпринес:принесла;, смешать в правильных пропорциях, мы получим идеальное биотопливо. Попробуй приготовить несколько образцов при помощи вон того стола! Потом принеси мне то, что у тебя получится.', 'Создайте идеальное биотопливо', '', '', '', '', 'Вернитесь к инженеру Мегагексу в Темную пещеру в Вайш\'ире.', 25549);
INSERT INTO `quest_template_locale` VALUES (26107, 'ruRU', 'Вызов духов', 'Соберите 10 глаз ящеров нагорья, убив долгоногов нагорья или твердозубов нагорья.', 'Дар шаманства, присущий нашей расе, вырвал меня из многолетнего летаргического сна. И теперь я совершу для других такое же благодеяние, как то, что позволило мне обрести силы.$b$bЯщеры нагорья хитрые и жестокие твари. Их души могут дать нашим воинам огромную силу. Принеси мне глаза ящеров, чтобы я мог изготовить амулеты, как научил меня Тор\'ган.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26108, 'ruRU', 'Коварство ящера', 'Соберите 12 сердец ящеров, убив плотоглотов нагорья.', 'Плотоглоты нагорья, которые обитают к югу отсюда, еще более свирепы, чем другие ящеры. Они не только сильны, но и очень коварны.$b$bКогда я лежал в летаргическом сне, даже амулеты силы не могли помочь мне. Но Тор\'ган использовал сердца плотоглотов, чтобы вселить в меня силу духа, и это освободило меня.$b$bНаши воины заслуживают того, чтобы обладать коварством ящера. Принеси мне сердца плотоглотов, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26110, 'ruRU', 'Как в старые добрые времена', 'Заберите у курьера-Отрекшегося запечатанную папку.', 'Забавно, конечно. Мы с Кин через многое прошли вместе – и, как и много лет назад, мы опять в Арати.$B$BВ этом самом месте мы – я и она – разрушили планы Отрекшихся и не дали им разработать новую разновидность чумы. Впрочем, непохоже, чтобы Орда усвоила урок – они снова копаются на ферме.$B$BИх курьер снова рыщет повсюду и даже не беспокоится о скрытности. Если ты не прочь помочь нам, найди курьера. Нас интересует то, что у него с собой.', '', 'Он бродит по дороге.', 'Отрекшийся-курьер', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26111, 'ruRU', '...И он придет', 'Раздобудьте мозг Непостижимого.', 'Я заряжаю тебя энергией безликих осквернителей.$B$BПлыви к моему приманивающему тотему в глубоководной впадине на северо-востоке и освободи через него всю энергию. Принеси мне мозг их предводителя.$B$BПризови Их\'тиса Непостижимого... И он придет!', '', 'Вам нужен его мозг!', 'Их\'тис Непостижимый', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26112, 'ruRU', 'Требование ответа', 'Отнесите донесение Камнеломов Мойре Тауриссан к Высокому трону Стальгорна.', 'Так как же так получилось, что воины Черного Железа оказались здесь, у дверей Стальгорна и чуть было не захватили наш город?$b$bРазве не \"императрица\" Мойра, член нашего уважаемого совета Трех Кланов, руководит кланом Черного Железа? Нападение бы не свершилось без ее ведома и позволения. Это же была не какая-то банда дворфов-мятежников, а организованные и хорошо вооруженные силы вторжения.$b$bЯ подготовил донесение о битве на аэродроме. Отнеси его в Стальгорн к Высокому трону и посмотри ей в лицо!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26113, 'ruRU', 'Кви и Кинелори', 'Найдите Кви на холме напротив фермы Го\'Шека.', 'В течение долгого времени Орда удерживала ферму Го\'Шека, что к востоку отсюда. По сравнению с остальными здешними проблемами это не было большим поводом для беспокойства. Но из этого района стали поступать сообщения об активности нежити.$b$bЭто меня беспокоит гораздо больше, чем несчастные крестьяне. Нежить возле фермы уже не в первый раз что-то затевает, поэтому я отправила туда моих лучших разведчиц. Найди Кви и Кинелори, они все тебе расскажут.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26114, 'ruRU', 'Кви верит тебе', 'Поговорите с Кинелори у фермы Го\'Шека на нагорье Арати.', '<Кви начинает просматривать папку.>$b$bЗахват... контролирование территории... ничего нового эта нежить не придумала, но планы у них на все Нагорье Арати. Мы должны помешать.$b$bЯ буду наблюдать отсюда. А ты отправляйся с Кин и достань эти планы захвата. Пусть у этих ходячих трупов не будет никакой информации.$b$bИ береги Кин, слышишь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26115, 'ruRU', 'Что значит быть Ордой...', 'Узнайте, что значит быть Ордой.', 'Встань рядом, $n, и смотри, как наше мощное оружие крушит наших врагов!$B$BУзнай, что это значит – быть Ордой!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26116, 'ruRU', 'Удар Кинелори', 'Защитите Кинелори во время ее возвращения к Кви.', 'Хорошо, $n. Если ты $gготов:готова;, то и я тоже. Идем?', 'Защитите Кинелори', '', '', '', '', 'Вернитесь к Кви на нагорье Арати.', 25549);
INSERT INTO `quest_template_locale` VALUES (26117, 'ruRU', 'За Южнобережье', 'Вернитесь к командиру Амарену в Опорный пункт.', 'После ночи, проведенной в таверне, Кинелори обычно выглядит заметно хуже, чем сейчас. Ты определенно хорошо о ней $gзаботился:заботилась;.$b$bНадо сообщить в Опорный пункт о нашей удаче. Я останусь здесь с Кин, пока она не переведет дух. А ты отправляйся вперед без нас.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26118, 'ruRU', 'Арестовать посла', 'Отправляйтесь в посольство Черного Железа и воспользуйтесь прочными наручниками, чтобы арестовать посла Шлакомолота.', 'Мысль о предательстве посла еще долго будет преследовать меня. Ты $gдолжен:должна; арестовать его прежде, чем он снова причинит нам вред, или, что еще хуже, сбежит и начнет планировать следующую атаку. Пока посол Шлакомолот в городе и на свободе, Стальгорн не может быть в безопасности.$b$bВозьми эти наручники и отправляйся в посольство Черного Железа. Оно находится севернее Высокого трона, у границы Великой Кузни. Арестуй посла Шлакомолота и возвращайся вместе с ним.', 'Арестуйте посла Шлакомолота и приведите его к Высокому Трону', '', '', '', '', 'Вернитесь к Мойре Бронзобород к Высокому трону в Стальгорне.', 25549);
INSERT INTO `quest_template_locale` VALUES (26119, 'ruRU', 'FLAG - Claim Our Stake Launched', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (26120, 'ruRU', 'Драконья Пасть и драконы', 'Убейте 12 похитителей детенешей из клана Драконьей Пасти.', 'Эти орки из клана Драконьей Пасти начинают серьезно мне надоедать. Их самоубийственные вылазки – скорее, повод для раздражения, чем серьезная угроза роще. Единственная польза от них – есть где поднабраться опыта моим часовым.$B$BОднако разведчики докладывают, что орки стали ловить в свои сети черных дракончиков. Вот уж чего этой многострадальной земле не хватает, так это \"приручения\" драконов. Отправляйся на восток, |3-6($c), и перехвати похитителей драконьих детенышей, чтобы нам не пришлось потом расплачиваться за совершенную этими глупцами непростительную ошибку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26122, 'ruRU', 'Защита окружающей среды', 'Используйте жироотсос, чтобы добыть в Донных зарослях по 4 банки черепашьего жира, жира прилипалы и жира акулы-молота из тел водорослевых черепах, прилипал-чистильщиков и чешуеспинных акул-молотов.', 'Ты знаешь, как воняет топливо для подводной лодки, $n? Жуть! А мы его жжем – не жалеем, чтоб только \"Верн\" раскочегарить. Да ладно запах, но оно же убивает все живое вокруг. Нет, вот все-таки надо бережнее относиться к окружающей среде, да.$B$BВ здешних морских животных очень много жира. Возьми это устройство, отправляйся в Донные заросли прямо над этой пещерой и воткни его там в трупы водорослевых черепах, прилипал и акул-молотов – пусть их жир после смерти хозяев спасет жизни другим морским обитателям.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26124, 'ruRU', 'Защита Донных зарослей', 'Убейте 7 морских разведчиков Альянса в Донных зарослях.', 'Здесь рыщут шпионы Альянса? Поблизости Зловещий грот, а в нем – \"Верн\", новая подводная лодка Орды! Ни в коем случае нельзя подпускать Альянс к этому месту!$B$BНужно сообщить об этом кое-кому в гроте... Но для начала разделайся с хитрыми шпионами Альянса.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26125, 'ruRU', 'Защита Донных зарослей', 'Убейте 7 морских разведчиков Альянса в Донных зарослях.', 'Ты $gвидел:видела; наверху шпионов? Это плохо... Такого допускать нельзя!$B$BВозвращайся в Донные заросли и уничтожь их, прежде чем они проникнут в наше убежище.', '', '', '', '', '', 'Расскажите обо всем кровостражу Толдреку в Зловещем гроте в Вайш\'ире.', 19865);
INSERT INTO `quest_template_locale` VALUES (26126, 'ruRU', 'Идеальное топливо', 'Создайте идеальное биотопливо при помощи стола для приготовления топливных образцов в Зловещем гроте.', 'Что тебе известно о топливе, $n? Создание топлива – очень сложный процесс. Нужно учитывать множество различных показателей: временные параметры переокисления, переменные горючепрочности, критерии силицификации горения... Уж не говоря обо всех остальных факторах.$B$BНадеюсь, если те ингредиенты, которые ты мне $gпринес:принесла;, смешать в правильных пропорциях, мы получим идеальное биотопливо. Попробуй приготовить несколько образцов при помощи вон того стола! Потом принеси мне то, что у тебя получится.', 'Создайте идеальное биотопливо', '', '', '', '', 'Вернитесь к Облину Свистозубу в Зловещем гроте, что находится в Вайш\'ире.', 25549);
INSERT INTO `quest_template_locale` VALUES (26127, 'ruRU', 'Явление Сумеречного Молота', 'Убейте 12 сектантов из культа Сумеречного Молота.', 'Я-то, как и все остальные, думал, что это просто ополоумевшие дворфы из клана Черного Железа, а оказалось – это вконец спятившие сектанты!$B$BФанатики из культа Сумеречного Молота хотят – ни много ни мало – уничтожить весь мир. За ними – Смертокрыл и Рагнарос, да и с кланом Черного Железа у них давняя дружба.$B$BНо неважно, кто они, важно другое. Они заняли Дун Модр! Нужно их выбить отсюда. Бери оружие и отправляйся крушить черепа, а я останусь здесь и прослежу, чтобы никто из них не улизнул!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26128, 'ruRU', 'Битва за мост Тандола', 'Одолейте Каламота Пепельную Бороду на Мосту Тандола.', 'Мне уже доводилось защищать Мост Тандола от врагов. Тогда это был сам клан Черного Железа. И мой отец в свое время дрался с ними здесь, и его отец тоже...$B$BЕдинственный вражина, что сумел проскочить мимо меня, рванул прямиком к мосту. Что-то здесь не так, и я нутром чую, что нас там ждет засада.$B$BМне нужна твоя помощь, $n. Ради Стальгорна. Подсобишь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26129, 'ruRU', 'Братья по оружию', 'Поговорите с королем Генном Седогривом в Военном квартале Гилнеаса.', 'Послушай, $n – я впервые с начала гражданской войны согласен с Седогривом. Пора забыть о наших разногласиях и начать все сначала.$B$BЭтим зверям все равно, мятежник ты или нет. $B$BПередай Седогриву, что мои люди встанут на его сторону.$B$BНеподалеку отсюда, в подвале Джосайи есть склад, где мои люди хранят кое-какое тяжелое вооружение.$B$BСкажи нашему королю, что мой арсенал – в его распоряжении.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26130, 'ruRU', 'Отсоединение Л\'горека', 'Убейте Ур\'Гоза, Ску\'Бу и Неф\'Лахима.', 'Л\'горек – древнее существо, возлежащее на скалистом уступе прямо напротив нас. Его держат под строгим наблюдением и выкачивают из него жизненную энергию, которую поглощает некая ненасытная сущность, расположенная где-то под нами.$B$BПод уступом, где лежит Л\'горек, есть пещера, именуемая Донный грот. В этой пещере три сильных мага-огра денно и нощно проводят особые ритуалы, связующие древнего Л\'горека с тварью внизу. Тебе нужно убить эту троицу, чтобы отсоединить Л\'горека.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26131, 'ruRU', 'Подкрепление для Лок Модана', 'Отправляйтесь в Великую Кузню и поговорите с Гритом Турденом о полете в Лок Модан. Когда прибудете, поговорите с пилотом Большеногом.', 'Я несколько часов ожидал, когда совет выслушает мою жалобу, в этом нет ничего хорошего. Кажется, больше всего Мойре хочется парализовать деятельность совета.$b$bА в это время Лок Модан страдает. Наши силы невелики, враги превышают нас численностью. Пожалуйста, $n, может быть хоть ты выслушаешь меня, если совет не захотел? Поговори с Гритом Турденом, укротителем грифонов Стальгорна. Его можно найти в восточной части Великой Кузни. Он поможет тебе перелететь к Южным вратам. Когда прибудешь туда, поговори с пилотом Большеногом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26132, 'ruRU', 'Чудовища Пустоты', 'Уничтожьте 8 исчадий Пустоты.', 'Маги-огры из Донного грота вызвали себе защитников – кровожадных чудовищ Пустоты.$B$BА ведь их потом могут натравить на наших солдат... Этого нельзя допустить! Когда будешь там, постарайся уничтожить чудовищ. Чем больше, тем лучше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26133, 'ruRU', 'Чудовища Пустоты', 'Уничтожьте 8 исчадий Пустоты.', 'Маги-огры из Донного грота вызвали себе защитников – кровожадных исчадий Пустоты.$B$BНе хочется, чтобы потом их напустили на наших солдат. Когда будешь там, постарайся уничтожить всех чудовищ. Всех до единого!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26134, 'ruRU', 'Ничего тут для тебя нет', 'Поговорите с Фуриеном в Тефрис-Аране в Пустошах.', 'Для тебя тут больше ничего не осталось, $n. А мне еще нужно похоронить тело Маши. Потом я вернусь на место бомбежки и начну ритуал восстановления. Возможно, когда-нибудь там расцветет новая роща, где будут обитать духи юных ночных эльфов и с ними мое дитя.$B$BЕсли вдруг ты $gнаправлялся:направлялась; в Пустоши, то мне говорили, будто бы некий эльф крови по имени Фуриен ищет себе смекалистых помощников. Может, вам с ним стоит переговорить.$B$BПрощай же... Я всегда буду помнить тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26135, 'ruRU', 'Видения прошлого: подъем из глубин', 'Воспользуйтесь сломанным клинком Воительницы в храме Кель\'Дормир и посмотрите заключительную часть истории.', 'Я все думаю о том, что ты $gрассказал:рассказала; о нагах. Кто их союзники? Неужели они верят, что смогут победить Хозяина Приливов?$B$BСкоро мы выберемся из этой пещеры, но сначала мы должны достигнуть поставленной цели. Надеюсь, ты согласишься в последний раз узнать что-нибудь у Воительницы.$B$BОсталось только одно место, где мог побывать этот артефакт, – храм над руинами. Но его наверняка хорошо охраняют. Будь $gосторожен:осторожна;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26136, 'ruRU', 'FLAG - Rigor Mortis Removed', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (26137, 'ruRU', 'Проведать парней', 'Отправляйтесь в Болотину и поговорите с горным пехотинцем Рареном возле Дун Альгаза.', 'Уверен, ты $gвидел:видела;, в каком ужасном состоянии озеро Лок сейчас. И, боюсь, этим проблемы не исчерпываются. Вся исчезнувшая вода должна была куда-то деться, и она делась – в Болотину.$b$bТам сейчас много дворфов, которые пытаются помочь, и, конечно, им всем нужны продукты. Поэтому я отправил в Болотину двух моих горных пехотинцев с бочонком эля.$b$bУ меня нет от них никаких известий с тех пор, как они отправились по дороге в Дун Альгаз. Не поищешь их?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26139, 'ruRU', 'В Арати', 'Отправляйтесь на нагорье Арати и поговорите с капитаном Ниалс в Опорном пункте.', 'Тебе надо отправляться вперед и предупредить об этом другую сторону, $n.$b$bЗа мостом на севере находится Опорный пункт, крепость Альянса в Арати. Скажи капитану Ниалс, чтобы он приглядывал за этими псами из Сумеречного Молота.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26140, 'ruRU', 'Беседа с Древним', 'Принесите мозг Непостижимого Л\'гореку в Церебриллий в Вайш\'ире.', 'Наденьте на голову мертвого Безжалостного, чтобы замаскироваться под одного из рабов.$B$BВойдите в Л\'горека. Поговорите с Древним.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26141, 'ruRU', 'Рунные камни обуздания', 'Соберите 7 рунных камней обуздания.', 'ТАМ... НА ТОЙ СТОРОНЕ... ЗАЛА... ТЫ НАЙДЕШЬ... ОЖИДАЮЩИХ ПЕРЕРОЖДЕНИЯ.$B$BНАМ ПОНАДОБЯТСЯ... ИХ РУННЫЕ КАМНИ ОБУЗДАНИЯ... ЧТОБЫ... МЫ МОГЛИ... КОНТРОЛИРОВАТЬ... СКОВАННЫХ ЭЛЕМЕНТАЛЕЙ.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26142, 'ruRU', 'Теперь они не переродятся!', 'Уничтожьте 5 древних каналов.', 'ЧТОБЫ... ИХ ОСТАНОВИТЬ... НАДО УНИЧТОЖИТЬ... ДРЕВНИЕ КАНАЛЫ.$B$BПО НИМ ОНИ ВЫКАЧИВАЮТ... ИЗ МЕНЯ... ЭНЕРГИЮ... И СОЗДАЮТ... ПЕРЕРОЖДЕННЫХ.$B$BСРАЖЕНИЕ С... НЕПТУЛОНОМ... НЕОТВРАТИМО. СУМЕРЕЧНЫЙ МОЛОТ... НЕ ДОЛЖЕН ПОЛУЧИТЬ... ЭТИХ ТВАРЕЙ.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26143, 'ruRU', 'Халлазил Перерожденный', 'Уничтожьте Халлазила Перерожденного.', '<Голос Древнего врезается вам в сознание.>$B$BТЕПЕРЬ... КОГДА ТЫ $gЗАБРАЛ:ЗАБРАЛА;... ЭНЕРГИЮ... ЭТИХ ФАНАТИКОВ, ВОЙДИ... В ХРАМ... И УНИЧТОЖЬ... ХАЛЛАЗИЛА ПЕРЕРОЖДЕННОГО!', '', 'Воспользуйтесь потоком, чтобы уничтожить Халлазила Перерожденного.', 'Халлазил Перерожденный', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26144, 'ruRU', 'Пленники', 'Освободите 5 пленных бойцов Альянса.', 'Этот ключ был у одного из сектантов Сумеречного Молота. Возьми ключ и освободи пленных бойцов Альянса. Их держат в клетках в Л\'гореке.$B$BПоторопись, пока узников не принесли в жертву тому, кто таится в глубине!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26145, 'ruRU', 'Угроза со стороны троггов', 'Соберите 8 каменных зубов троггов.', '$C, не уверен, что ты знаешь об исходящей от троггов опасности, нависшей над дворфийскими землями. Внутренние войска Стальгорна отправлены на фронт Альянса, мы располагаем лишь небольшими оборонительными силами. Мой полк охраняет город, и мы не можем покинуть пост из-за опасности нападения.$b$bНо мы должны усилить натиск на троггов, расселившихся на холмах. Если эта задача тебе по плечу, проведи вылазку в их стан. В доказательство принеси 8 каменных зубов троггов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26146, 'ruRU', 'Защита королевских земель', 'Убейте 12 троггов из племени Камнедробов.', 'Нам нужно защитить озеро Лок, $n! Множество королевских солдат проливает кровь в далеких землях, а наш родной край в опасности. Трогги полезли изо всех щелей! Нашествие троггов грозит безопасности Стальгорна.$b$bНам нужна твоя помощь, $gотважный искатель приключений:отважная искательница приключений;. Ступай и устрани нависшую над нами угрозу. Убей 12 троггов из племени Камнедробов и возвращайся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26147, 'ruRU', 'Больше и страшнее', 'Убейте 8 шаманов из племени Камнедробов и 8 костегрызов из племени Камнедробов.', 'Горные пехотинцы говорят, что ты довольно $gсилен и отважен:сильна и отважна;, $n. Нам здесь пригодится |3-6($r) вроде тебя. Мы никак не можем справиться с троггами. Все бойцы на фронте, и мы остались тут без всякой помощи. Но раз теперь с нами $gбывалый:бывалая:c; |3-6($c), посмотрим, что мы сможем сделать.$b$bИди и убей 8 шаманов из племени Камнедробов и 8 костегрызов из племени Камнедробов. Их можно найти около и внутри пещер в южных горах.$b$bПосмотрим, не преувеличены ли слухи о твоей отваге, гроза троггов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26148, 'ruRU', 'Решающий удар', 'Убейте Громага.', 'Похоже, этими тварями в Лок Модане руководит вождь по имени Громаг. Это огромный трогг, он прячется в глубине пещер к северу отсюда.$b$bЕсли ты чувствуешь, что справишься с этим, я бы хотел, чтобы ты $gвозглавил:возглавила; нападение на Громага.', '', 'Убей его!', 'Громаг', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26149, 'ruRU', 'Пленники', 'Спасите 5 узников из Орды.', 'Этот ключ был у одного из сектантов Сумеречного Молота. Возьми ключ и освободи узников из Орды. Их держат в клетках в Л\'гореке.$B$BПоторопись, пока узников не принесли в жертву тому, кто таится в глубине!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26150, 'ruRU', 'Навестить Мейбелл', 'Поговорите с Мейбелл Маклур на виноградниках Маклур в Элвиннском лесу.', 'Похоже, от тебя будет прок, $n. Как насчет услуги старику?$b$bКогда я последний раз был на виноградниках Маклура, я слышал, как Мейбелл плачет в своем доме. Не будешь ли ты так $gдобр:добра;, чтобы навестить ее? Я немного беспокоюсь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26151, 'ruRU', 'Зловещее письмо', 'Прочитайте зловещее письмо и поговорите с Друзиллой ла Салле на кладбище в долине Североземья.', 'Мне было приказано передать это тебе, как только ты вернешься из лагерей кобольдов, $n. Письмо запечатано эмблемой Бездны – вне всяких сомнений, это послание от местного наставника чернокнижников. Другие дела в аббатстве могут подождать – узнай-ка лучше сначала, о чем говорится в этом письме.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (26152, 'ruRU', 'Разыскивается: Джеймс Кларк', 'Убейте Джеймса Кларка и заберите его голову.', 'Указом армии Штормграда за голову Джеймса Кларка объявлено щедрое вознаграждение.$b$bКларк обвиняется в грабежах, кражах со взломом, поджогах и убийствах. Кроме этого он подозревается в похищении людей и в краже Принцессы, призовой свиньи Бреквеллов.$b$bВ последний раз Джеймса Кларка видели направляющимся в сторону лесопилки Восточной долины.$b$bПредайте Джеймса Кларка правосудию и сообщите об этом маршалу Маккри. Его можно найти на лесопилке Восточной долины.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26153, 'ruRU', 'Тыквенные оладьи Пэнни', 'Раздобудьте 6 штормградских тыкв. Принесите их Робби Флею в Штормграде.', 'Моя дочь Пэнни обожает тыквенные оладьи, однако тыква у нас тут в Элвиннском лесу в этом году не уродилась – заморозки... Зато я слыхал о тыквенной грядке к северу от Штормграда, где тыква, должно быть, как раз поспела. Пойди и раздобудь несколько спелых тыкв, а там поглядим, что у нас получится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26154, 'ruRU', 'Искоренение Сумеречного Молота', 'Подчините себе скованный поток и уничтожьте 50 сумеречных энтузиастов и 10 безликих надзирателей.', 'ТЕПЕРЬ ВОЗЬМИ... ЗАГОВОРЕННЫЙ РУНИЧЕСКИЙ КАМЕНЬ... И С ЕГО ПОМОЩЬЮ... ПОДЧИНИ... ОДИН ИЗ... СКОВАННЫХ ПОТОКОВ... В ЦЕНТРАЛЬНОМ ХРАМЕ. ОНИ ТЕБЯ... НЕ ЗАМЕТЯТ. ТЫ БУДЕШЬ ДЛЯ НИХ... НЕВИДИМКОЙ.$B$BИСПОЛЬЗУЙ... СИЛУ ЭЛЕМЕНТАЛЯ... ЧТОБЫ УНИЧТОЖИТЬ... ПРИВЕРЖЕНЦЕВ... КУЛЬТА СУМЕРЕЧНОГО МОЛОТА... И... ИХ БЕЗЛИКИХ НАДЗИРАТЕЛЕЙ.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26157, 'ruRU', 'Касым Шарим', 'Разыщите Касыма Шарима в пещерах Змеиные Кольца в Выжженных землях.', 'Мне нужно кое-кому кое-что передать. Возьмешься доставить мое сообщение?$B$BКасым Шарим – старый волшебник крови. Он знает о демонах в Выжженных землях больше, чем кто бы то ни было. Хотя по нему и не скажешь... Он очень старый и очень сильный... правда, чуть-чуть странноватый, так что не пугайся. Ты найдешь его в Змеиных Кольцах, в пещерах неподалеку от того места, где ты $gрасправился:расправилась; с теми cектантами.$B$BПожалуйста, передай ему эту записку. Он поймет, что к чему.', '', 'Волшебник крови и эксцентричный отшельник', 'Касым Шарим', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26158, 'ruRU', 'Настроиться на кровавый камень', 'Научитесь использовать телепортирующие кровавые камни в Змеиных Кольцах.', 'Я так понимаю, в пещеру ты $gпробивался:пробивалась; с боем. Надеюсь, тебе было весело. Да, надо признаться, я выбрал не самое... э... подходящее место для своих изысканий. И особенно неподходящее – для любопытных искателей приключений, которые предпочли бы заходить сюда, как к себе домой.$B$BПожалуй, я позволю тебе настроиться на свои телепортирующие кровавые камни. Тут все очень просто. Положи руки на камень в том дальнем углу – и сразу телепортируешься из пещеры. А чтобы телепортироваться обратно, используй камень, который снаружи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26159, 'ruRU', 'Первый шаг', 'Раздобудьте 9 флаконов крови хохочущей гиены и 9 флаконов крови краснокаменного василиска.', 'Как и всякому настоящему волшебнику крови, для сотворения магии мне нужна кровь. Кровь крови рознь, но здесь, в Выжженных землях, есть несколько очень даже пригодных... сортов, скажем так. Главное – знать, где искать.$B$BДля наших целей? Кровь василиска и кровь гиены, в равных пропорциях. Но ее нужно много. Иди на запад, в самый центр Выжженных земель. И не забудь... теперь тебе можно пользоваться телепортом!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26160, 'ruRU', 'Ритуал крови', 'Поговорите с Касымом Шаримом, чтобы начать ритуал крови.', 'Тебе, наверное, интересно, что мы сейчас будем делать. Я тебе расскажу... вкратце. А рассказывать вкратце я мастер.$B$BСектанты культа Приверженцев Тени хотят вызвать демона, Разелиха, и вернуть его в Выжженные земли. Этого нельзя допустить! Поэтому мы вызовем демона сами. Вызовем и убьем. Но ты не думай, что это легко. На словах-то все просто, а вот на деле...$B$BДай мне знать, когда будешь $gготов:готова;, и я начну ритуал.', 'Поговорите с Касымом Шаримом, чтобы начать ритуал.', '', '', '', '', 'Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (26161, 'ruRU', 'По кусочкам', 'Разыщите голову, туловище и ноги Лорама.', 'Нам нужен Лорам Многоног, охотник на демонов. Он знает истинное имя Разелиха, а тебе, я думаю, известно: тот, кто знает настоящее имя демона, получает над ним безграничную власть. Проблема в том, что Лорам убит, а его тело разорвано на куски.$B$BНо если ты соберешь все куски и принесешь их сюда, мы сможем узнать то, что нам нужно. Они все на западе, все три куска... огры Молота Ужаса прячут их у себя в пещерах. Иди прямо сейчас. Кстати, как и за Гримео, за Лорамом остался должок...', '', 'Охотник на демонов собственной персоной.', 'Лорам Многоног', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26162, 'ruRU', 'Алтарь Бурь', 'Отнесите тело Лорама к Алтарю Бурь и охраняйте его, пока идет ритуал воскрешения.', 'Высоко в скалах на западе расположен могущественный алтарь. Могущественный ДЕМОНИЧЕСКИЙ алтарь, который охраняют сектанты. Если сможешь добраться до алтаря, ты сумеешь вернуть нам Лорама.$B$BСкорее всего, алтарь станет сопротивляться. Так что тебе надо будет охранять тело Лорама, пока идет ритуал воскрешения. Когда все закончится, приведи охотника на демонов ко мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26163, 'ruRU', 'Времени нет', 'Отнесите диссонирующую руну дозорному Гримео у Темного портала в Выжженных землях.', 'Разелих собирается вернуться в Выжженные земли и захватить Азерот со своей армией демонов. Прямо сейчас, в эту минуту, он готовится призвать свои легионы, чтобы всех нас истребить. Эти три амулета помогут нам вызвать Разелиха... но никак не помогут его уничтожить.$B$B<Гном рисует в воздухе руну, материализует ее и отдает вам.>$B$BВот. Отнеси ее Гримео, его можно найти у Темного портала, на юго-востоке отсюда. Он тебе скажет, что делать дальше. И поторопись! У нас мало времени!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26164, 'ruRU', 'Обугленный гранит у Темного портала', 'Соберите 24 обугленных гранитных осколка.', 'Касым хочет, чтобы ты $gнабрал:набрала; гранитных осколков вокруг Темного портала. Уж не знаю, зачем ему эти осколки, но мне что-то подсказывает, что это отнюдь не безобидные камушки.$B$BВот тебе кирка. Иди к порталу и набери мелких осколков по радиусу взрыва.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26165, 'ruRU', 'Поганая кровь демонов', 'Соберите 7 бутылок жуткой крови демонов.', 'Шариму нужна кровь демонов. Сказать по правде, она и на кровь-то совсем не похожа – жидкий гной, не иначе! Хотя в данном случае это не важно... хочешь – не хочешь, а придется ее собирать.$B$BТебе повезло: здесь, вокруг Темного портала, этих демонов – хоть пруд пруди. Инферналы, гончие Скверны, стражи Скверны... так что ты быстренько соберешь все, что тебе нужно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26166, 'ruRU', 'Дальнейшая подготовка', 'Отнесите посылку Гримео Касыму Шариму в пещеры Змеиные Кольца в Выжженных землях.', '<Гримео заканчивает упаковывать материалы в аккуратный сверток.>$B$BЗдесь все, о чем просил гном. Непременно передай ему, что это последнее поручение, которое я для него выполняю. Да, я был у него в долгу, но теперь расплатился сполна, и больше я с ним никаких дел иметь не хочу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26167, 'ruRU', 'Амулет Аллистария', 'Раздобудьте амулет Аллистария в пещерах Змеиные Кольца в Выжженных землях.', 'Для того чтобы вызвать нашего демона, нам нужны три амулета. Первый – это амулет Аллистария.$B$BСамого Аллистария уже нет в живых, но его амулет хранится в сокровищнице в этой самой пещере. Вместе с двумя остальными, этот амулет поможет нам вызвать Разелиха Осквернителя.$B$B<Касым на мгновение задумывается.>$B$BАмулет где-то близко ко входу. Я настоятельно рекомендую воспользоваться телепортом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26168, 'ruRU', 'Амулет Севины', 'Раздобудьте амулет Севины у Солюна близ Берега Обломков в Выжженных землях.', 'Второй амулет – амулет Севины – сейчас в руках у мурлока, что живет далеко на юге, на скале над Берегом Обломков. Не знаю, как он попал к этому мурлоку, но я точно уверен, что именно там ты его и найдешь.$B$BНайдешь, заберешь и принесешь сюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26169, 'ruRU', 'Амулет Грола', 'Раздобудьте амулет Грола на Берегу Обломков в Выжженных землях.', 'Грол... огр.$B$B<Касым смеется.>$B$BТело Грола, как я понимаю, не покоится среди других огров. Его тело – а с ним и его амулет силы – находится на погибшем корабле, выброшенном на Берег Обломков, к востоку отсюда. Его амулет будет последним... а все три вместе откроют нам доступ к Разелиху. И у нас будет шанс его остановить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26170, 'ruRU', 'Завершающий ритуал', 'Примите участие в ритуале Касыма Шарима.', 'Нож готов. Лорам с нами. Он знает, что ему делать. Сейчас я воспользуюсь магией трех амулетов, чтобы открыть вам обоим доступ к их создателю, Разелиху.$B$BСкажи мне, когда вы с Лорамом будете готовы, и я начну ритуал.', 'Примите участие в ритуале Касыма Шарима', '', '', '', '', 'Вернитесь к Лораму Многоногу в Змеиные Кольца, что в Выжженных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (26171, 'ruRU', 'Демон, имя тебе Рах\'лих', 'Поговорите с привратником смерти у северного подножия утеса Осквернителя. Поднявшись на вершину утеса, уничтожьте тело Разелиха и воспользуйтесь каменным ножом опечатывания, чтобы пленить душу демона.', 'А теперь слушай внимательно.$B$BСейчас мы отправимся к северному подножию утеса Осквернителя, что на северо-западе. Там нас ждет привратник смерти. Он доставит нас на вершину. Там, наверху, ты мне поможешь прикончить Разелиха, потому что мне одному с ним не справиться.$B$BНо самое главное: ты будешь держать каменный нож и используешь его только по моей команде. Нож запечатает душу Разелиха Осквернителя в его новом вечном узилище.$B$BЕсли у нас все получится, тебе надо будет вернуться к дренею Гримео.', '', 'Тот, кто знает его настоящее имя, владеет его судьбой.', 'Рах\'лих', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26172, 'ruRU', 'Волшебнику крови тоже хочется кушать', 'Отправляйтесь в Выжженные земли и раздобудьте 5 кусков мяса пеплогривых кабанов.', 'Вопреки распространенному мнению, древние и могущественные волшебники крови не пьют кровь. Мы едим обычную еду, как и все остальные, но ее, кстати сказать, сложно добыть во вражеской крепости сектантов.$B$BА вот в центральной долине Выжженных земель водятся пеплогривые кабаны... очень даже пригодные в пищу, поскольку их мясо не нужно готовить – его можно есть прямо сырым. Не хочешь ли ты поохотиться на кабанов и помочь мне пополнить запасы провизии?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26173, 'ruRU', 'Защита тылов', 'Убейте Джаррока Рваное Крыло, Шахандану и Гумгаза.', 'Я сотрудничаю с воинами Орды исключительно потому, что у нас чувство долга превыше вражды... хоть и ненамного. Нам поручено охранять Темный портал, чтобы исключить всякие несанкционированные перемещения. В связи с недавним катаклизмом, сейчас мы особенно уязвимы. Уже есть сообщения о черных драконах, появившихся в этих краях...$B$BМои бойцы исполняют свой долг, но у них тут другие задачи, и нам нужен кто-то, кто помог бы нам с демонами. Рядом с порталом ты найдешь троих демонов-лейтенантов. Их надо прикончить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26174, 'ruRU', 'Осторожность не помешает', 'Изучите планы Орды у Темного портала и постарайтесь, чтобы вас не поймали за этим занятием.', '<Командир стражи Релторн Пустомар говорит полушепотом.>$B$BУ меня есть приказ... сверху... как раз для тебя. Я не раз замечал, как солдаты Орды периодически сверяются с какими-то документами... на той бочке, вон там. Было бы очень неплохо узнать, что там, в этих бумагах, и что замышляет Орда. Мое положение и должность не позволяют мне лично заняться этим сомнительным делом, а ты здесь $gновенький:новенькая;, у тебя, может быть, и получится подойти незаметно...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26175, 'ruRU', 'Сурвич', 'Отправляйтесь к мэру Чарлтону Конниспорту в Сурвич, что в Выжженных землях.', 'За исключением того, что ты $gвидел:видела;, у портала сейчас наблюдается удивительное затишье. Так что, боюсь, у меня больше нет для тебя работы.$B$BНо если тебе очень хочется приключений, можешь сходить в рыбацкий поселок Гилнеаса на юго-западе. Сурвич, если я правильно помню.$B$BНу да, считается, что мы с Гилнеасом дружим, но если по правде... Дружба с воргенами?! Как-нибудь без меня... Я и дренеев-то с трудом перевариваю...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26176, 'ruRU', 'Вперед на Телсамар', 'Доставьте отчет капитана Ругельфасса горному пехотинцу Кэдреллу в Телсамар.', 'Ты $gоказал:оказала; нам здесь немало помощи. Если ты уже покидаешь нас, я бы хотел попросить тебя доставить в Телсамар наш отчет о состоянии дел.$b$bИди по дороге на север и ты не заблудишься. Горный пехотинец Кэдрелл будет рад получить этот отчет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26177, 'ruRU', 'Крабный день', 'Поймайте 6 сточных крабов. Отнесите их Робби Флею в Штормград.', 'Свежие крабьи клешни всегда были одним из любимых блюд короля. В последнее время в городских каналах отлично ловятся крабы. Сделай одолжение, налови немножко. Только смотри, бери живых: мертвые мне ни к чему, король требует только самый свежий улов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26178, 'ruRU', 'Планы на будущее', 'Соберите 12 щенков Поляны Снегопада. Принесите их зверолову Мау\'и в гавани Моа\'ки.', 'Если мы хотим выжить, нам следует бороться с волчерами. Я только боюсь, как бы мы в своем рвении не истребили слишком многих.$b$bВолчеры Поляны Снегопада имеют такое же право на жизнь, как и мы сами. И мы с тобой позаботимся о том, чтобы они получили свой шанс.$b$bЕсли старейшина Ко\'нани не просил тебя с ними разобраться, значит, еще попросит. Когда будешь на севере, на их поляне, собери, пожалуйста, щенков и принеси их мне.', '', '', '', '', '', 'Вернитесь к зверолову Мау\'и в гавань Моа\'ки, что в Драконьем Погосте.', 19865);
INSERT INTO `quest_template_locale` VALUES (26179, 'ruRU', 'Торговая Компания', 'Убейте 7 рабочих Торговой Компании по поручению Морина Ловца Облаков из деревни Кровавого Копыта.', 'Теперь понятно, почему в Мулгоре появилось много сотрудников и оборудования Торговой Компании. Эти гоблины... Компания слишком быстро растет, не жди добра. Как говорят, гоблинам палец в рот не клади.$B$BМаленькие жадины. К несчастью для их деловых операций, таурены не согласны терпеть их присутствие в своих землях. Ступай в их рудник на северо-востоке от разграбленного каравана и преподай им урок.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26180, 'ruRU', 'Бригадир Шумовик', 'Убейте бригадира Шумовика и принесите его планшет Морину Ловцу Облаков в деревню Кровавого Копыта.', 'Согласно документам, которые ты $gотыскал:отыскала; в караване, Торговая Компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить.$B$BМне тошно слышать, на какую низость они готовы пойти ради достижения цели. Я хочу уничтожить того, кто разработал эти планы. Его зовут бригадир Шумовик, он сейчас в руднике Торговой Компании на востоке от разграбленного каравана. Принеси мне его планшет, посмотрим, нет ли там чего полезного.', '', 'Достань его планшет.', 'Бригадир Шумовик', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26181, 'ruRU', 'Возвращение в Темную пещеру', 'Поговорите с Эрунаком Говорящим с Камнем в Темной пещере, что в Вайш\'ире.', 'ВОЗВРАЩАЙСЯ... В... ТЕМНУЮ ПЕЩЕРУ. ЭРУНАК ГОВОРЯЩИЙ С КАМНЕМ ЖДЕТ... ТЕБЯ ТАМ.$B$BМНЕ ПРИШЕЛ КОНЕЦ...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26182, 'ruRU', 'Возвращение в Зловещий грот', 'Поговорите с Эрунаком Говорящим с Камнем в Зловещем гроте, что в Вайш\'ире.', 'ВОЗВРАЩАЙСЯ... В... ЗЛОВЕЩИЙ ГРОТ. ЭРУНАК ГОВОРЯЩИЙ С КАМНЕМ ЖДЕТ... ТЕБЯ ТАМ.$B$BМНЕ ПРИШЕЛ КОНЕЦ...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26183, 'ruRU', 'Королевский сидр', 'Соберите 12 сочных яблок. Отнесите их Робби Флею в Штормграде.', 'Я в вечном долгу перед нашим королем за все, что он для нас сделал. И самое малое, чем могу отплатить ему, – это приготовить его любимый напиток! На наше счастье, ингредиенты для этого лакомства можно достать прямо в Штормграде. Яблони растут во всех районах города. Деревья высоковаты, чтобы рвать с них яблоки, но на земле под ними полно упавших.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26184, 'ruRU', 'Мечта Червоточного', 'Убейте 5 стражей ужаса-разрушителей, 5 повелителей ужаса-осквернителей, 5 оскверненных темностволых древней и 3 скверноспорых болотников в Проклятом лесу.', 'Большинство жителей Сурвича пришли в Выжженные земли отнюдь не в поисках легкой жизни. Они явились сюда воплотить мечту Марла Червоточного – идеалиста-друида, который верил, что исцелить Гниющий Шрам очень даже возможно, и пытался возродить его к жизни.$B$BНо похоже, Марл ошибался. Да, он вырастил свой лес, но демоны по-прежнему бесчинствуют в этих землях, а его великое дерево – все какое-то скрюченное и кривое.$B$BИ все-таки я не теряю надежды. Может быть, если мы пойдем в Проклятый лес и очистим его от демонов... ну, хотя бы от нескольких...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26185, 'ruRU', 'Спросить совета у Круга Кенария', 'Поговорите с кенарийской наблюдательницей Шайаной в Сурвиче в Выжженных землях.', 'Боюсь, что порча, поразившая Выжженные земли, в конце концов добралась и до моего друга Марла. Его эксперимент потерпел неудачу, а его великое древо сплотило вокруг себя демонов.$B$BДерево следует уничтожить, а вместе с ним и самого Марла. Поговори с кенарийской наблюдательницей на другом конце города. Я думаю, она подскажет, что делать дальше.$B$BНадеюсь, ты понимаешь, $n, жителям Сурвича вовсе не обязательно знать о том, что мы собираемся сделать. Моральный дух горожан и так подорван, так что незачем усугублять.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26186, 'ruRU', 'Демонический резервуар', 'Убейте нечистых черных медведей, нечистых ночных ловцов и нечистых крикунов в Проклятом лесу, а потом составьте из их органов демонический резервуар.', 'Нужно привлечь внимание Червоточного, как-то вывести его из этого транса, но только чтобы наверняка.$B$BТа немногая живность, которая сумела обосноваться в Проклятом лесу, наверняка подвержена влиянию местной скрытой энергии. Тебе нужно будет собрать части их тел и соединить их в некую емкость. В каком бы трансе ни пребывал Червоточный – в друидском или демоническом – большой резервуар, полный зараженной животной плоти, сможет его нарушить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26187, 'ruRU', 'Падение Марла Червоточного', 'Убейте Марла Червоточного у дерева Малдраз в Выжженных землях. Для того чтобы вывести Марла из транса, используйте демонический резервуар.', 'Когда жители Сурвича узнают о том, что мы сделали... я даже не знаю, что будет. Они так отчаянно держатся за мечту Червоточного... $B$B...и все-таки, мы должны это сделать. У нас нет выбора. Возьми демонический резервуар и с его помощью выведи Марла из транса. Убей его и возвращайся ко мне.', '', 'Когда его разумом завладели демоны, последняя надежда была утеряна.', 'Марл Червоточный', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26188, 'ruRU', 'Маззранач', 'Принесите бедренную кость пумы плоскогорья Мауру Заклинателю Дождя в деревню Кровавого Копыта.', 'Дед рассказывал мне истории о своих встречах с долгоногом Маззраначем. О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах.$b$bИ вот ирония судьбы – мы столкнулись с ним, когда я странствовал по равнинам, и он здорово укусил меня за плечо. Мой дед ничуть не преувеличивал, описывая это жуткое создание. Я собрал почти все части тел разных животных, необходимые, чтобы вылечить воспаленную рану... кроме бедренной кости пумы плоскогорья.$B$BС каждой минутой я становлюсь все слабее... пожалуйста, помоги мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26189, 'ruRU', 'Угроза Злого Клыка', 'Убейте Горфакса Злого Клыка и 16 орков из клана Драконьей Пасти в Лагере Злого Клыка.', 'Когда мы остановились здесь, чтобы укрыться от ящеров, то обнаружили, что рядом целая толпа орков из клана Драконьей Пасти!$b$bВ Менетиле я слышал, что орки из клана Драконьей Пасти еще большие варвары, чем все остальные орки. Они голыми руками душат драконов... Не знаю, что из этих баек правда, а что нет, но я точно знаю, что нельзя позволять им оставаться в этих холмах.$b$bТы сможешь с этим справиться, $n Отправляйся на восток, в Лагерь Злого Клыка, разберись с этими орками и не забудь про их предводителя!', '', 'Горфакс Злой Клык, предводитель орков из клана Драконьей Пасти', 'Горфакс Злой Клык', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26190, 'ruRU', 'Рыбацкая услада', 'Раздобудьте 5 гигантских зубаток. Принесите рыбу Робби Флею в Штормграде.', 'Если меня спросят, что любит король, я, не задумываясь, отвечу: свежую зубатку. Зубатку легко готовить, но сложно ловить. Тут-то ты мне и $gнужен:нужна;! В водоемах Штормграда полно гигантских зубаток, но охотников до них, мягко говоря, достаточно. Хочу, чтобы ты $gпридумал:придумала;, как \"раздобыть\" несколько таких зубаточек для нашего короля. На маленьких пристанях в городских каналах ты найдешь рыболовов. Как действовать дальше, $gсам:сама; придумаешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26191, 'ruRU', 'Плод стараний', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26192, 'ruRU', 'Сиротки тоже любят печенье!', 'Раздобудьте 4 мешка сахарной пудры и отнесите Робби Флею в Штормград.', 'О сиротах Штормграда редко кто вспоминает, но сегодня не такой день, друг мой! Король заказал особую партию печенья специально для сиротского приюта. А я, представь себе, почти допек последнюю порцию и вдруг обнаружил, что у меня закончилась сахарная пудра. Может быть, сходишь и принесешь? Она есть в любой продуктовой лавке и в городских тавернах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26193, 'ruRU', 'Оборона Провала', 'Убейте 15 любых наг в Обрыве над бездной.', 'Шепот стихий не дает мне собраться с мыслями, $n...$b$bТрон Приливов осажден!$b$bЯ не могу сидеть сложа руки, когда наги угрожают владениям Нептулона. Мы должны найти возможность объединить наши силы.$b$bКапитан Тейлор будет сопровождать меня в глубины, откуда я смогу установить прямую связь с Нептулоном.$b$bОт тебя же потребуется более активное вмешательство. Отвлеки на себя силы врага до моего прибытия к входу в Трон Приливов.$b$bДа помогут нам духи в этот нелегкий час, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26194, 'ruRU', 'Оборона Провала', 'Убейте 15 любых наг в Обрыве над бездной.', 'Шепот стихий не дает мне собраться с мыслями, $n...$b$bТрон Приливов осажден!$b$bЯ не могу сидеть сложа руки, когда наги угрожают владениям Нептулона. Мы должны найти возможность объединить наши силы.$b$bНазгрим будет сопровождать меня в глубины, откуда я смогу установить прямую связь с Нептулоном.$b$bОт тебя же потребуется более активное вмешательство. Отвлеки на себя силы врага до моего прибытия к входу в Трон Приливов.$b$bДа помогут нам духи в этот нелегкий час, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26195, 'ruRU', 'Кто сторожит Стража Природы', 'Поговорите с Ферилоном Дитя Листвы в Роще Стража Природы, что в Болотине.', 'Страж Природы – местная легенда. Получеловек-полурастение, защитник Болотины. Многие раньше думали, что его на самом деле не существует... А потом сюда прибыли ночные эльфы, чтобы его найти, – и нашли в итоге. А после этого они основали поселение к востоку отсюда.$B$BУ них там теперь целая роща вокруг этого Стража. По слухам, он в последнее время разбушевался – сказались наводнение и разруха.$B$BЭльфы – народ хороший. Им бы твоя помощь не помешала. Когда будет возможность, навести верховного друида, расскажи ему о своих подвигах здесь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26196, 'ruRU', 'Длиннокос Мрачный', 'Отнести полевой набор Ферилона Длиннокосу Мрачному в Дун Модре.', 'Дворфы Дун Модра денно и нощно сражаются с кланом Черного Железа, заполонившим их древний дом. Пока мы еще не можем послать туда наших часовых – слишком опасно, – но мы поддержим бойцов, отправив туда необходимые припасы.$B$BЕсли согласишься, отнеси этот сверток Длиннокосу Мрачному – найти его можно к северу отсюда. Его бойцам наверняка пригодится содержимое этого свертка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26197, 'ruRU', 'Будущее Гномрегана', 'Встретьтесь с Бипси Хладолей в Новом Городе Механиков.', 'Мы считаем победой каждый раз, когда нам удается помочь очередному выжившему выбраться из зараженных залов Гномрегана. Такие |3-7($c), как ты, играют важную роль в будущем Гномрегана. В связи с этим главный механик Меггакрут собрал команду наставников, чтобы ты $gмог:могла; обучаться своему искусству.$b$bБипси Хладолей поможет тебе с тренировками и с подготовкой к жизни на поверхности. Она ждет тебя на первом этаже здания, что находится к востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26198, 'ruRU', 'Искусство мага', 'Достигните 3-го уровня, чтобы изучить заклинание \"Кольцо льда\". Выучив заклинание, дважды успешно примените его на тренировочном манекене в Новом Городе Механиков.', 'По мере того, как ты будешь находить новые приключения, а сила твоя будет расти, ты начнешь развивать новые связи с тайной магией и изучать новые заклинания.\n\nСкоро все узнаешь. Ну-ка! Покажи мне все, что умеешь! Я буду здесь.', '', '', '', '', '', 'Вернитесь к Бипси Хладолей в Новый Город Механиков.', 19865);
INSERT INTO `quest_template_locale` VALUES (26199, 'ruRU', 'Будущее Гномрегана', 'Поговорите с \"Доком\" Вертушкой в Новом Городе Механиков.', 'Мы считаем победой каждый раз, когда нам удается помочь очередному выжившему выбраться из зараженных залов Гномрегана. Такие |3-7($c), как ты, играют важную роль в будущем Гномрегана. В связи с этим главный механик Меггакрут собрал команду наставников, чтобы ты $gмог:могла; обучаться своему искусству.$b$b\"Док\" Вертушка поможет тебе с тренировками и с подготовкой к жизни на поверхности. Она ждет тебя у группы зданий к востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26200, 'ruRU', 'Искусство жреца', 'Достигните 3-го уровня, чтобы изучить заклинание \"Слово Тьмы: Боль\". Пять раз примените его на тренировочных манекенах в Новом Городе Механиков.', 'Когда ты окажешься в безумном мире за пределами этих мест и наберешься сил, то начнешь открывать новые, ранее неизвестные тебе способности.$B$BМожет, пойдешь, наберешься опыта и затем вернешься и покажешь мне все, чему научишься?', '', '', '', '', '', 'Вернитесь к \"Доку\" Вертушке в Новый Город Механиков.', 19865);
INSERT INTO `quest_template_locale` VALUES (26201, 'ruRU', 'Власть чернокнижника', 'Достигните 3-го уровня, чтобы выучить заклинание \"Порча\", затем пять раз примените его на тренировочном манекене в Новом Городе Механиков.', 'Меня ничуть не удивляет, что $gчернокнижник:чернокнижница; вроде тебя $gсмог:смогла; выбраться из Гномрегана. Мало кто, даже среди гномов, осознает истинную природу той силы, которой мы владеем.\n\nСтановясь сильнее, ты начнешь слышать голоса тьмы, которые раскроют тебе секреты и обучат новым заклинаниям.\n\nИди, набирайся опыта, и когда выучишь что-то новое, возвращайся и продемонстрируй все мне.', '', '', '', '', '', 'Вернитесь к Аламару Мрачнну в Новый Город Механиков.', 19865);
INSERT INTO `quest_template_locale` VALUES (26202, 'ruRU', 'Будущее Гномрегана', 'Встретьтесь с Аламаром Мрачнном в Новом Городе Механиков.', 'Мы считаем победой каждый раз, когда нам удается помочь очередному выжившему выбраться из зараженных залов Гномрегана. Чтобы вернуть свой дом и избавиться от троггов и облученных гномов, нам пригодится любая помощь. В связи с этим главный механик Меггакрут собрал команду наставников, чтобы помочь тебе обучаться своим, гм, \"искусствам\".$b$bАламара Мрачнна можно найти в здании, которое располагается к западу от нашего. Он владеет теми же силами, что и ты, и поможет тебе восстановиться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26203, 'ruRU', 'Будущее Гномрегана', 'Поговорите с сержантом-инструктором Парогоном в Новом Городе Механиков.', 'Мы считаем победой каждый раз, когда нам удается помочь очередному выжившему выбраться из зараженных залов Гномрегана. Такие |3-7($c), как ты, играют важную роль в будущем Гномрегана. В связи с этим главный механик Меггакрут собрал команду наставников, чтобы ты $gмог:могла; обучаться своему искусству.$b$bСержант-инструктор Парогон поможет тебе с тренировками и с подготовкой к жизни на поверхности. Он ждет тебя на небольшом поле для тренировок к юго-востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26204, 'ruRU', 'Искусство воина', 'Достигните 3-го уровня, чтобы обучиться приему \"Рывок\". Найдите тренировочный манекен в Новом Городе Механиков и используйте этот прием на нем.', 'Самый лучший способ развития – обучение. Узнавая больше, ты начнешь понимать, что можешь делать вещи, о которых раньше и не $gзадумывался:задумывалась;!$B$BИди, набирайся опыта и изучай новые техники боя. Затем вернись и продемонстрируй их на тренировочном манекене.', '', '', '', '', '', 'Вернитесь к сержанту-инструктору Парогону в Новый Город Механиков.', 19865);
INSERT INTO `quest_template_locale` VALUES (26205, 'ruRU', 'Работа для робота', 'Воспользуйтесь многофункциональным роботом GS-9x, чтобы очистить 5 ядовитых гейзеров на зараженном аэродроме. Когда подберетесь достаточно близко к ядовитой луже, робот автоматически начнет очищение.', 'Если этот многофункциональный робот мог бы помочь нам со всеми видами работ, которые для нас, гномов, неприятны или опасны!$b$bПосле того как Термоштепсель подорвал свой облучатель в конце операции \"Гномреган\", на аэродроме к югу от города пузырится слизь и клубятся ядовитые облака.$b$bЕсли мы не примем меры, заражение распространится на остаток наших земель. Возьми с собой многофункционального робота и поднеси его к фонтанам, бьющим из зеленых луж на аэродроме. Робот запрограммирован так, что очистка начнется автоматически!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26206, 'ruRU', 'Будущее Гномрегана', 'Поговорите с Келси Стализвон в Новом Городе Механиков.', 'Мы считаем победой каждый раз, когда нам удается помочь очередному выжившему выбраться из зараженных залов Гномрегана. Такие |3-7($c), как ты, играют важную роль в будущем Гномрегана. В связи с этим главный механик Меггакрут собрал команду наставников, чтобы ты $gмог:могла; обучаться своему искусству.$b$bКелси Стализвон, из Секретной службы Гномрегана, поможет тебе с тренировками и с подготовкой к жизни на поверхности. Ее можно найти в шатре совета к северо-западу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26207, 'ruRU', 'Искусство разбойника', 'Достигните 3-го уровня, чтобы изучить прием \"Потрошение\", затем найдите тренировочный манекен в Новом Городе Механиков и примените на нем \"Потрошение\" 3 раза.', 'Узнавая все больше и становясь более $gопытным разбойником:опытной разбойницей;, ты начнешь изучать новые умения .$b$bОдной из самых сильных сторон разбойника является способность объединять приемы в комбинацию, которая позволяет воспользоваться слабостью врага и дает возможность для совершения более серьезных маневров.\n\nИди, набирайся опыта и узнай, как это делать. Когда научишься, возвращайся и испробуй эту способность здесь.', '', '', '', '', '', 'Вернитесь к Келси Стализвон в Новый Город Механиков.', 19865);
INSERT INTO `quest_template_locale` VALUES (26208, 'ruRU', 'Битва продолжается', 'Посмотрите на голографическую панель перед главным механиком Меггакрутом, чтобы узнать об операции \"Гномреган\".', 'Дворфы Стальгорна были весьма добры и приютили нас, когда нападение троггов и радиация заставили нас покинуть Гномреган в первый раз. Но даже доброта друзей не может избавить нас от тоски по дому.$b$bЯ попросил храбрых гномов и других членов Альянса помочь нам вернуть контроль над Гномреганом и победить узурпатора Термоштепселя раз и навсегда.$b$bВсе, что планировалось в операции \"Гномреган\", нам выполнить не удалось, но Термоштепсель обращен в бегство, и сейчас мы как никогда близки к дому.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26209, 'ruRU', 'На меня повесили убийство', 'Поговорите с несколькими бездомными людьми, населяющими владение Янсена, чтобы найти какие-нибудь указания на то, кто убил Хмуробровов.', 'Вот что, деточка, у нас тут висяк. Двойное человекоубийство... И одно коне... убийство.$B$BЧто хуже всего, мы в Западном крае. Я могу наугад прихлопнуть с десяток бродяг, у которых были основания прикончить этих стариков и несчастную Савраску.$B$BИ вот, я не знаю точно, кто это сделал, и уж конечно, мне совсем неохота тащиться в эту дыру и расследовать смерть парочки поселенцев, но ведь так хочется найти преступника и установить истину! Хочешь помочь? Ступай, поговори с этими лоботрясами. Они уже... в курсе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26210, 'ruRU', 'Гаммерита!', 'Убейте Гаммериту и верните Катуму Удильщику из деревни Сломанного Клыка его лучшую блесну.$B$BКатум сказал, что Гаммерита ползает по берегу среди остальных черепах.', 'Йоу! Тут живет всем черепахам черепаха – звать Гаммерита – предводительница морских хрустогрызов и просто наглая прожорливая рептилия, чтоб ей.$B$BОна слопала мою лучшую блесну! Взяла и откусила прямо с удочки! С тех пор рыба совсем клевать перестала.$B$BНайди Гаммериту и вытащи у нее из брюха мою блесну!', '', 'Береговое чудище в панцире.', 'Гаммерита', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26211, 'ruRU', 'Хрустогрызы, чувак!', 'Убейте 10 морских хрустогрызов по поручению Катума Удильщика из деревни Сломанного Клыка во Внутренних землях.', 'Ты не смотри, что у них такие большие красивые глазки! Страшней морского хрустогрыза зверя нет! Только я удочку закину, как приплывают эти черепахи-переростки, жрут мне всю наживку и удилище пополам ломают!$B$BСделай мне и всей нашей деревне одолжение – поубивай их всех.$B$BВ смысле, хрустогрызов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26212, 'ruRU', 'Лярд потерял свой обед', 'Найдите обед Лярда из деревни Сломанного Клыка во Внутренних землях.$B$BЛярд сказал, что потерял свой обед на острове к северу, где могут встретиться тролли из племени Порочной Ветви.', 'Лярд хотел устроить пикник в секретном месте, а потом пришли злые тролли племени Порочной Ветви и побили Лярда большими палками. Лярд убежал в деревню, но потерял свой обед. Лярд голодный... Может, сходишь в секретное место и найдешь там мой обед? Лярд боится. Это на севере! Остров на севере, там секретное место!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26213, 'ruRU', 'По горячему следу: клан Речной лапы', 'Найдите улику против гноллов из стаи Речной Лапы.', 'Поскольку других улик у нас нет, придется воспользоваться твоей информацией.$B$BТут в окрестностях есть пара лагерей гноллов Речной лапы. Найди их и поищи улики. Принеси все, что сумеешь найти. Тебя интересуют только гноллы и разведчики из клана Речной лапы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26214, 'ruRU', 'По горячему следу: мурлоки', 'Добудьте улику против мурлоков.', 'Хотя все это, по-моему, без толку, придется проверять каждую ниточку.$B$BМне нужно, чтобы ты $gотправился:отправилась; в Бескрайний берег, на запад отсюда, на побережье, и $gвытряс:вытрясла; кой-чего из мурлоков. Попытайся найти улику или какую-нибудь информацию, которая помогла бы нам пролить свет на эти убийства.$B$BЕсли повезет – до встречи, новобранец!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26215, 'ruRU', 'Встреча с Переобутым Лу', 'Поговорите с Переобутым Лу на тыквенной ферме Хмуроброва в Западном крае.', 'Похоже, мы вляпались в настоящую \"детективную историю\", новобранец. Увы, местные не желают говорить, а улики, которые тебе удалось найти у гноллов и мурлоков, гроша ломаного не стоят. Придется пустить в ход план... придется найти Переобутого Лу.$B$BПереобутый Лу – мой старый и верный информатор, который по иронии судьбы прижился на тыквенной ферме Хмуробровов. Сходи на ферму и узнай, что известно Лу.$B$BЕсли он начнет тебе лапшу на уши вешать, скажи, что тебя прислал Горацио.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26219, 'ruRU', 'Замыкая круг', 'C \"Крепости Волдрина\" поднимитесь на борт \"Хвата Х2\" и окажите помощь в операции в Темной пещере.', 'Нам удалось обнаружить чудище, уничтожившее корабли. Его логово расположено в Темной пещере, огромном подводном гроте на краю Обрыва над бездной.$b$bНа этот раз мы подготовились к встрече с ним. Штормградские гномы построили для нас чудо-корабль, огненная мощь которого заставит содрогнуться даже такого монстра. Когда \"Хват Х2\" причалит, поднимайся на него и помоги, чем сможешь. Мы тебя догоним.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26220, 'ruRU', 'С беконом все потянет', 'Заруби взрослых кабанов к югу от Оргриммара и принеси мне 6 туш. Я буду ждать тебя тут, в Волоке.', 'Накормить армию голодных орков – задачка не из простых. Хорошо еще, что у нас много свинины на свинофермах и в окрестностях Оргриммара. Сделай милость, заруби несколько кабанов и принеси мне туши. Я их нашинкую и сделаю отменный бекон солдатам на завтрак.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26221, 'ruRU', 'Замыкая круг', 'Со \"Стигийской Награды\" поднимитесь на борт \"Верна\" и окажите помощь в операции в Зловещем гроте.', 'Нам удалось обнаружить чудище, уничтожившее корабли. Его логово расположено в Зловещем гроте, огромной подводной пещере на краю Обрыва над бездной.$B$BНа этот раз мы подготовились к встрече с ним. Гоблины-умельцы построили для нас чудо-корабль, огневая мощь которого заставит содрогнуться даже такого монстра.$B$BКогда \"Верн\" причалит, поднимайся на него и помоги, чем сможешь. Мы тебя догоним.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26222, 'ruRU', 'Добыча запчастей', 'Принесите 7 запчастей инженеру Искролязгу в Новый Город Механиков.', 'Здесь так много работы и так мало гномов, которые в состоянии помочь! Главный механик попросил меня начать переделку некоторых из наших старых роботов и деталей, оставшихся от операции \"Гномреган\". Я надеюсь, скоро у меня будет новая серия многофункциональных роботов, готовых для полевых испытаний!$b$bУ тебя ведь есть время помочь? Тут в округе валяется много разных деталей. Собирай все, что найдешь, и приноси мне. Никогда заранее не угадаешь, что потом может пригодиться!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26223, 'ruRU', 'Охота на бродяг', 'Убейте 8 среброгривых бродяг.', 'В диких лесах Внутренних земель погибло много храбрых троллей, |3-6($r). Одни из самых опасных животных там – среброгривые волки. Они прячутся в высокой траве и всегда нападают неожиданно.$B$BНельзя закрывать глаза на такую опасность!$B$BУменьши поголовье среброгривых!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26224, 'ruRU', 'Охота на дикарей', 'Убейте 10 диких совух.', 'Одни из самых мерзких существ во Внутренних землях – дикие совухи. Сколько храбрых воинов Сломанного Клыка они уже разорвали своими когтями и клювами...$B$BУбейте всех диких совухов, которых встретите, |3-6($r). Ваша помощь будет взвешена, измерена и по достоинству оценена.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26225, 'ruRU', 'Портвейн \"Пупелливербос\"', 'Соберите 12 бутылок портвейна \"Пупелливербос\".', 'Эй, ты! А ты знаешь, что по северному пляжу разбросаны десятки, если не сотни бутылок вина?$B$BНу вот, теперь знаешь!$B$BЯ бы пошел туда сам, и стал бы грести их лопатой, если бы ни эти проклятущие турели. Клянусь, они хотят моей крови!$B$BЗначит, придется заплатить тебе. Принеси мне 12 бутылок портвейна \"Пупелливербос\", а я \"куплю\" их у тебя, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26226, 'ruRU', 'Раки под креольским соусом', 'Поймайте 10 ильных раков в Оргриммаре. Принесите добычу Мароггу.', 'Вокруг Оргриммара видимо-невидимо маленьких озер. В них круглый год кишмя кишат раки. Тут-то ты и пригодишься, $n. Налови-ка мне этих раков. Если вернешься с хорошим уловом, наши вояки сегодня знатно попируют.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26227, 'ruRU', 'Осторожно: злые фрукты!', 'Сорвите 8 колючих груш. Доставьте их Мароггу в Оргриммар.', 'Солдаты порой хотят десерта. Я их редко балую, но в этот раз, пожалуй, сделаю исключение. Думаю, тебе в Оргриммаре попадался кактус, на котором растет местное лакомство – колючая груша. Беда в том, что фрукт... ну весь в колючках! В общем, береги руки, но плодов мне этих принеси.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26228, 'ruRU', 'Живи и радуйся', 'Используйте старый дом Переобутого Лу у заднего входа в рудник Янго в Западном крае.', 'Слушай, я бы те ни слова не сказал, но у меня должок перед Горацио. Если честно, я ничего не знаю насчет Хмуробровов, но могу тебе указать верное направление.$B$B<Лу передает вам большой ящик.>$B$BПрежде я жил в этом ящике, пока мне не подфартило. Теперь у меня такая житуха, о которой любой бродяга мечтает!$B$BЗначит, берешь этот жилой ящик и топаешь к руднику Янго, к юго-западу отсюда. Как доберешься до конца шахты, спрячься там в ящике.', 'Живи и радуйся!', '', '', '', '', 'Вернитесь к Переобутому Лу на тыквенную ферму Хмуроброва в Западном крае.', 25549);
INSERT INTO `quest_template_locale` VALUES (26229, 'ruRU', '\"Свечка МОЯ!\"', 'Убейте 12 кобольдов-землекопов.', 'Прежде чем я охромел из-за этих треклятых кобольдов, я был первым поставщиком свечей для Вильяма Песта. Эх, я даже придумал себе девиз \"СВЕЧКА-МОЯ!\" Да, таков я был. Кобольды такие говорят: \"Не твоя свечка!\" а я им гордо отвечаю: \"СВЕЧКА – МОЯ!\"- и вышибаю им все мозги!$B$B<Джимб на секунду погружается в размышления.>$B$BХорошие были времена... Лучшие.$B$BА теперь? Я даже до сортира без чьей-то помощи не доползу. Хочешь мне помочь? Перебей побольше кобольдов. Ты целую кучу их найдешь у ближайшей шахты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26230, 'ruRU', 'Пир во время чумы', 'Добудьте 6 хвостов койотов и 5 горстей свежей грязи.', 'Жизнь здесь в Западном краю тяжела, $gсынок:красотка;! Каждый день – борьба. Иногда неделями нормальной еды не видим. Вот почему так важно друг другу помогать. Может, поможешь, а? Я пеку песочные куличики, и мне нужны кое-какие ингредиенты.$B$BДобудь мне свежей грязи с тыквенной делянки перед домом и связку хвостов койота. Койотов ты найдешь на пустошах Западного края.$B$BСтупай! Нам надо много ртов накормить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26232, 'ruRU', 'Прощальные мысли Лу', 'Подслушайте лиходеев, спрятавшись за домом на тыквенной ферме Хмуроброва в Западном крае.', 'На ферму недавно заходили пара громил и устроили тут шухер. Я не знаю, откуда они и на кого работают, но они тут точно НЕСПРОСТА. Кажется, я слышал, как они говорили о том, что может тебя заинтересовать.$B$BЕсли интересно, то они на заднем дворе. Но ежели тебя сцапают или прихлопнут – я тебя в первый раз вижу. Сроду не встречал!$B$BУдачи, детка!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26233, 'ruRU', 'Укради у своих', 'Раздобудьте 6 бочек риса Черного Копья. Принесите их Мароггу в Оргриммар.', 'Как ты знаешь, $n, Гаррош выслал оргриммарских троллей на западную окраину города. К счастью для нас, это значит, что мы легко сможем добраться до их припасов. Я тут готовлю баланду на целую роту солдат, и мне нужна прорва риса. А тролли как раз хранят его в бочках возле своих домов. Добудь мне несколько бочек риса Черного Копья – думаю, мне хватит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26234, 'ruRU', 'Укради у своих', 'Достаньте 6 бочек кезанского риса и принесите их Мароггу в Оргриммар.', 'Как тебе известно, $n, Гаррош выслал оргриммарских гоблинов на западную окраину города. К счастью для нас, это означает, что мы легко можем добраться до их припасов. Я тут готовлю баланду на целую роту солдат, и мне нужна прорва риса. А гоблины как раз хранят его в бочках возле своих домов. Добудь мне несколько бочек кезанского риса – думаю, мне хватит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26235, 'ruRU', 'Вор тоже хочет кушать', 'Раздобудьте 3 пайка ордынских пехотинцев. Отнесите их Мароггу в Оргриммар.', 'Уже несколько недель какие-то ворюги таскают пайки у Оргриммарского гарнизона. Недавно мне доложили, где чаще всего происходят кражи. Как увидишь гору ящиков и провизию, знай – воры наверняка неподалеку. Хочу, чтобы ты $gпоймал:поймала; этих воришек и $gвернул:вернула; украденные пайки. Как закончишь, дуй ко мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26236, 'ruRU', 'Обыск у Сальденов', 'Поговорите с фермером Сальденом на ферме Сальдена в Западном крае.', 'Итак, что нам известно? Нам нужно принять во внимание улики.$B$BВо владении Янсена ты $gнашел:нашла; мокрое письмо и обрывки красной ткани. На ферме Хмуроброва ты $gподслушал:подслушала; разговоры между какой-то темной личностью и магом-огром. Также ты $gполучил:получила; признание в убийстве от банды головорезов – которых потом и $gприкончил:прикончила;.$B$BЧто-то тут не сходится.$B$BК юго-востоку отсюда на ферме Сальдена живет пожилая чета. Ступай туда и поговори с фермером Сальденом. Выясни, что он знает.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26237, 'ruRU', 'Тяжелые времена', 'Убейте 10 дозорных полей.', 'Времена сейчас тяжелые, $gбрат:сестра;. Масса народу из разоренного Штормграда переселяется в Западный край, ресурсов катастрофически не хватает. Люди в смятении, им нужна помощь.$B$BНаша ферма много лет служит странноприимным домом. Сальма делает все, чтобы наши гости выжили, но иногда их похищают дозорные. Дозорные – такие мерзкие твари, что бродят по моим полям. Это такой подарочек на память от Братства Справедливости, которое отсюда вышвырнули. Помоги нам!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26238, 'ruRU', 'Дикие дворфы', 'Убейте 10 воинов или шаманов клана Громового Молота.', 'Орда сильно помогла нам, а мы не нахлебники. Другие племена лесных троллей отброшены, и мы сможем завоевать новые земли во имя Орды.$B$BНо нам мешают дворфы Громового Молота. Они хотят войны – они ее получат, но я не хочу проигрывать войну существам ростом с полменя.$B$BИди и поубивай этих дворфов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26240, 'ruRU', 'Бей в барабаны', 'Испробуйте действие боевых барабанов на 6 воинах племени Сломанного Клыка.', 'Наши воины храбро сражаются с погаными дворфами клана Громового Молота, поэтому тут безопасно. Но нам надо делать все, что в наших силах, чтобы поддержать своих.$B$BДля боя троллям нужны хорошие барабаны. Их ритм призывает на помощь духов, помогающих бить врага сильнее. Возьми мои барабаны с собой на поле битвы. Бей в них, чтобы поддержать наших воинов. Тогда они покажут дворфам, чьи в лесу шишки!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26241, 'ruRU', 'Похлебка Западного края', 'Добудьте 6 плодов окры, 6 боков кровоклыка и 6 кусков жилистого мяса шкуродера.', 'Привет, дорогой друг. Добро пожаловать в наш дом. Хмм, ты не $gпохож:похожа; на бродягу. Ты хочешь нам помочь? Если так, то ты как раз вовремя! Я готовлю ужин для маленьких, и мне нужны кое-какие простые ингредиенты.$B$BЕсли ты сможешь добыть мне окру, несколько боков кровоклыка и пару кусков жилистого мяса шкуродера, я смогу сделать свою знаменитую похлебку Западного края! Все это можно добыть возле нашей фермы. Только опасайся дозорных полей. Они безжалостные убийцы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26244, 'ruRU', 'Земля забирает все', 'Убейте 5 глубинных элементалей.', 'Мы все принадлежим миру земли, $n. В конечном итоге все поглощает земля.$b$bСкоро \"Неистовство Бури\" обратится в пыль, и мы ничего не сможем узнать по его останкам.$b$bИди и убей элементалей, которые разрушают корабль. Это будет лишь отсрочка неизбежного, но нам нужно выиграть время, если мы хотим отыскать части столпа мира.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26245, 'ruRU', 'Крушение воздушного судна', 'Обыщите место крушения \"Неистовства Бури\" в Подземье.', 'Камень перевозили на летающем боевом корабле Орды под названием \"Неистовство Бури\".$b$bВоздушное судно разбилось к югу отсюда, и при помощи гадания мы установили, что камня среди обломков нет.$b$bОбыщи корабли и найди какие-нибудь улики, которые могут подсказать, где находится камень.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26246, 'ruRU', 'Судовой журнал капитана', 'Отнесите судовой журнал капитана Марууту Камневязу в Храм Земли, что в Подземье.', '<Вы перелистываете страницы до последней, прерванной записи.>$b$b...приближаемся к Храму Земли и начинаем посадочные маневры в соответствии с новым маршрутом. На севере мы обнаружили низкое давление в системе и вытащили наш...$b$BКРОВЬ И ГРОМ! МЕРЗАВЦЫ ИЗ АЛЬЯНСА ПРИБЛИЖАЮТСЯ!!!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26247, 'ruRU', 'Дипломатия прежде всего', 'Поговорите с буревестницей Милрой на боевом корабле Альянса.', 'Служители Земли – это нейтральная организация, $n. Мы не можем принимать чью бы то ни было сторону в войне между Ордой и Альянсом.$b$bПосмотри вокруг – мы все разные. Наша миссия провалится, если расовые предрассудки будут стоять выше наших целей. Но пока у нас не появится больше информации, давай держать это в тайне.$b$bНе стоит делать поспешных выводов. Я отправлю тебя и одного из наших новых служителей на боевой корабль Альянса.$b$bРазузнай все, что сможешь, не втягивая нас в конфликт.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26248, 'ruRU', 'Все наши друзья мертвы', 'Воспользуйтесь тотемом духов у 6 тел убитых членов команды.', 'Что-то здесь не так, $n.$b$bКоманда корабля была убита. Но при этом следов кровопролития и разрушений нет.$b$bЭто не дело рук Орды.$b$bМы найдем ответы на интересующие нас вопросы, если поговорим с духами погибших. Они еще не покинули этот мир.$b$bВозьми этот тотем и размести его рядом с телами павших. У тебя будет всего несколько секунд, чтобы узнать их последние мысли.$b$bИ все же, будь $gосторожен:осторожна;! Неизвестно, как отреагируют духи на наше вмешательство.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26249, 'ruRU', 'Каюта адмирала', 'Поищите улики в кабине адмирала на боевом корабле Альянса.', 'Возможно, в каюте адмирала найдутся другие улики. Каюта прямо под нами.$b$bПосмотри, есть ли там выжившие или какая-то информация, которая поможет нам продвинуться в поисках фрагмента столпа мира. Будь $gосторожен:осторожна;, $n. Кто бы ни убил всю команду, он может быть все еще там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26250, 'ruRU', 'А впрочем... взять одного пленного', 'Победите Мор\'норока Ненавистного на боевом корабле Альянса в Подземье.', 'Еще не поздно, $n. Возможно, сектанты все еще там.$b$bСпустись вниз, выясни, кто у них главный, и победи его.$b$bТак или иначе, мы получим ответы на свои вопросы.', '', 'Постарайся не убивать его. Он нужен нам живым.', 'Мор\'норокк Ненавистный', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26251, 'ruRU', 'Пленных не брать', 'Убейте 6 сумеречных саботажников.', 'Похоже, что адепты Сумеречного Молота все еще на корабле. Спустись вниз и разберись с ними.$b$bБудь $gосторожен:осторожна;, $n. У меня есть ощущение, что они тут не с целью провести выездной духовный семинар, если ты понимаешь, о чем я.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26252, 'ruRU', 'Сердце дозорного', 'Принесите сердце дозорного полей фермеру Сальдену на ферму Сальдена.', 'Вы нашли то, что кажется сердцем дозорного полей.$B$BПо звуку, издаваемому устройством, вы можете сказать, что оно полностью функционально. Возможно, вам надо принести его фермеру Сальдену.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26254, 'ruRU', 'Растянуть связки', 'Садитесь на Клюва Бури и проследите за допросом Мор\'норокка.', 'Запрыгивай, $n. Посмотрим, есть ли что сказать господину огролицему.$b$bДа не бойся, Клюв Бури ронял пассажиров всего пару раз.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26255, 'ruRU', 'Вернуться в Храм Земли', 'Поговорите с Маруутом Камневязом в Храме Земли в Подземье.', 'Тебе нужно вернуться с известием в храм. Есть шансы, что фрагмент уже на пути в более безопасное место.$b$bРасскажи Марууту о том, что знаешь. А я тем временем постараюсь разузнать об этом Сумеречном Совете.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26256, 'ruRU', 'Пустить кровь кроводелам', 'Заберите приказы Сумеречного Молота у одного из Сумеречных кроводелов в Кратере Смертокрыла.', 'Здесь клан Сумеречного Молота практикует зловещую магию, $n. Они оживляют и заряжают энергией остатки крови Смертокрыла, так что вместо того, чтобы высохнуть и исчезнуть, она становится чересчур живой.$b$bУничтожь одного из кроводелов и проверь, нет ли при них каких-то документов, которые бы помогли найти этого \"начальника кузни\".', '', 'Один из них должен привести нас к начальнику кузни.', 'Сумеречный кроводел', 'Они держат рабов здесь?', 'Маруут Камневяз', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26257, 'ruRU', 'Он живой!', 'Примените сердце дозорного полей к перегруженному уборочному голему и затем используйте перегруженный уборочный голем для уничтожения 25 заряженных уборочных големов.', 'Если брать во внимание то, что я слышал, тебе нужно всего лишь найти подходящего уборочного голема и поместить в него сердце. Как только ты это сделаешь, то сможешь контролировать это устройство.$B$BЯ думаю, к западу отсюда, возле фермы Мольсен, целое поле этих перегруженных уборочных големов. Только глянь на дуговые разряды.$B$BЕсли тебе удастся заставить эту штуку работать, используй голема, чтобы уничтожить заряженных уборочных големов на старой ферме Мольсена. Эти чудовища куда страшнее чем те, что на нашей ферме.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26258, 'ruRU', 'Кратер Смертокрыла', 'Отправляйтесь в Кратер Смертокрыла в Подземье.', 'В участии Сумеречного Молота в исчезновении столпа мира есть глубокий смысл. Давай надеяться, что мы сможем действовать достаточно быстро, чтобы вернуть столп.$b$b<Маруут кладет руку на ваше плечо.>$b$bЯ установил с тобой духовную связь. Когда ты будешь в Подземье, мы сможем общаться.$b$bОтправляйся в Кратер Смертокрыла, что к юго-востоку отсюда, и узнай, чем там занимается Сумеречный Молот.', 'Вы добрались до Кратера Смертокрыла', 'Теперь наши души связаны, так что мы сможем общаться, когда ты будешь далеко.', 'Маруут Камневяз', 'Они должны были принести фрагмент сюда!', 'Маруут Камневяз', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26259, 'ruRU', 'Кровь Хранителя Земли', 'Добудьте 5 образцов крови Нелтариона из живой крови в Кратере Смертокрыла.', 'Когда Смертокрыл скрылся в Подземье, он был очень серьезно ранен, но все-таки жив.$b$bПролитая им кровь осталась в Кратере Смертокрыла. Сектанты собирают ее и превращают в живых существ, чтобы вытягивать из них силу.$b$bА что если в этой крови остались следы сущности Хранителя Земли? В конце концов, до того, как Нелтарион стал Аспектом смерти, он был Аспектом земли.$b$bСобери образцы живой крови, которую создали сектанты, и мы проверим, есть ли в ней следы сущности Хранителя Земли.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26260, 'ruRU', 'Записи начальника кузни', 'Найдите записи начальника кузни в Кратере Смертокрыла в Подземье.', 'Отправляйся в башню, о которой говорил раб. Ты найдешь ее на северо-восточном конце лагеря.$b$bЕсли мы сможем действовать достаточно быстро, у нас должно получиться подслушать, что будет говориться на встрече у начальника кузни.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26261, 'ruRU', 'Допрос рабов', 'Найдите ключ поработителя из Сумеречного Молота и освободите 6 порабощенных шахтеров.', 'Судя по найденным тобой приказам, в шатре на юго-восточном краю Кратера Смертокрыла лежит ключ.$b$bНайди его и освободи рабов с каменоломни, что к югу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26263, 'ruRU', 'Торнар Громовой Рокот', 'Убейте Торнара Громового Рокота.', 'Мы пытались убрать командира клана Громового Молота, который напал на наши земли, но у нас ничего не вышло.$B$BТорнар Громовой Рокот сидит себе в целости и невредимости в командном пункте, а его голос разносится над полем битвы, посылая дворфов в атаку. Мы так думаем, пришло время ему замолчать.$B$BУбей Торнара, и мы сможем легко разделаться с этими недомерками.', '', 'Наши шансы будут гораздо выше, если этот болван умрет.', 'Торнар Громовой Рокот', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26264, 'ruRU', 'Что остается потом', 'Разыщите на зараженном аэродроме токсических слякочей и соберите 6 единиц спасенного имущества.', 'Многие из нас видели больных и психически неуравновешенных гномов, страдающих от воздействия ядов и радиации Гномрегана. Это состояние будет прогрессировать, в конце концов они станут совсем безумными, но по большей части безопасными, и превратятся в лужицы токсической слизи.$b$bОсновываясь на своих исследованиях, я считаю, что мы, возможно, даже сможем вернуть их из этого состояния. Отправляйся на зараженный аэродром к югу отсюда, разыщи токсических слякочей, о которых я тебе говорил, и принеси имущество гномов, которое у них найдешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26265, 'ruRU', 'Уборка грязи', 'Уничтожьте 6 оживших загрязнений на зараженном аэродроме.', 'У Тока Шустреца какая-то безумная теория насчет этих токсических слякочей, в которых превратились гномы, поэтому у моих людей есть приказ пока их не трогать.$b$bНо зараженный аэродром к югу от нас просто кишит ожившими загрязнениями. Это элементали, состоящие из загрязненной воды и других токсичных материалов. Если не обращать на них внимания, они захватят весь город. Ты поможешь нам избавиться от них?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26266, 'ruRU', 'Надежда народа', 'Отнесите похлебку Западного края Надежде Сальден на Сторожевой холм.', 'Около четырех лет назад в глухую ночь в наш дом вошла маленькая девочка и упала прямо на пороге. Никто не знал, кто она. Бедняжка не помнила, кто она и откуда, – воистину, заблудшая душа.$B$BВскоре мы ее удочерили и назвали Надеждой, потому, что она для нас ей и стала.$B$BТеперь это молодая девушка, которая опекает бедных и бездомных Западного края. Отнеси мою похлебку Западного края на Сторожевой холм, к югу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26267, 'ruRU', 'Большая уборка на Осклизлой скале', 'Убейте 10 нефритовых слизнюков.', 'Много лет назад глубоко в недрах Осклизлой скалы была ордынская база. Ее, похоже, давно забросили, но все равно это важная территория, ее стоит отбить.$B$BПроблема в том, что там теперь полно слизнюков, а они мерзкие до жути... Мозгов у них нет, едкие они как незнамо что и жрут все, что видят.$B$BМне нужен кто-то смелый, кто отправился бы на Осклизлую скалу и поубивал там всех слизнюков. Ты как, $gсмелый:смелая;, $n?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26268, 'ruRU', 'Припасы с Осклизлой скалы', 'Соберите 5 покрытых слизью ящиков с припасами.', 'Я был на Осклизлой скале во время Второй войны. Тогда я был еще совсем молод, до встречи с моей спутницей еще оставались многие годы, и я до сих пор помню, какая поднялась паника, когда на нас напал Альянс. Мы помчались прочь вместе с орками, даже вещи собрать не успели.$B$BБросили все, что у нас было, так что на Осклизлой скале до сих пор полно наших припасов, а ведь они бы нам тут, в деревне, пригодились. А главное – это чтобы наши припасы не загреб себе клан Громового Молота.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26269, 'ruRU', 'Зеленые холмы Тернистой долины', 'Найдите страницу 14 \"Зеленых холмов Тернистой долины\".', 'Одна страница! Не хватает только одной страницы!$B$BС книгой господина Эрнестуэя кое-что... произошло. <Барнил сердито зыркает на Спэнкса>...и несколько страниц пропало.$B$BЯ всех просил поискать, и меня очень выручили, но одна страница так и не нашлась.$B$BУ тебя, конечно, полно дел, но раз уж ты все равно собираешься бродить по джунглям, может, заодно и страничку поищешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26270, 'ruRU', 'Прими нашу благодарность', 'Поговорите с Сальмой Сальден на ферме Сальдена в Западном крае.', 'Много лет нам никто не предлагал помощи, $n. Если бы не ты, нам не пережить бы наступающей зимы. Ты $gпоказал:показала; свою самоотверженность, а таким мы доверяем. Жаль, что у меня нет ничего ценного, чтобы предложить тебе.$B$BИ хотя я не знаю ничего такого, чтобы помочь тебе наказать убийц Хмуроброва, может, тебе поможет моя супруга. Поговори с Сальмой, и она расскажет тебе все, что стоит узнать прежде, чем ты уйдешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26271, 'ruRU', 'Накормить голодных и отчаявшихся', 'Накормите похлебкой Западного края 20 бездомных в Сторожевом холме.', 'Да, я слышала об убийстве Хмуробровов. Это очень трагично, но такие трагедии в Западном крае уже стали привычными. Здесь много людей, которые не хотят и не могут искать себе пропитание. Они отчаялись. Знаешь, каково это – настолько отчаяться, что уже не заботиться о жизни? Мы должны трудиться все вместе, чтобы показать им: надежда есть! Настанет новый день, настанет новая жизнь!$B$BВозьми похлебку Западного края, приготовленную моей матушкой, и помоги накормить голодных возле Сторожевого холма.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26272, 'ruRU', 'Возрождение Черного Копья', 'Найдите Волдреку на тренировочной площадке Черного Копья.', 'Племя Черного Копья стало жертвой обстоятельств. Мы попали в изгнание. Раз за разом мы были вынуждены покидать свои дома... Однако на сей раз мы не сбежим как трусы.$B$BВол\'джин всегда мудро правил племенем и долгое время оберегал нас от невзгод. Сейчас же его мудрость подсказывает ему, что под началом Гарроша Адского Крика Орду ждет непонятное будущее.$B$BВ этот раз мы не сбежим. Мы будем сражаться за свой дом до конца.$B$BПора начать твое обучение, $n. Отправляйся на восток и поговори с Волдрекой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26273, 'ruRU', 'Азы мастерства: поражение цели', 'Уничтожьте 6 манекенов-тики.', 'Ну ладно, $gдружище:подруга;. Начнем с самого простого. Хочу убедиться, что ты владеешь азами тайных искусств.$B$BДавай-ка попробуем поразить эти манекены-тики. Не торопись. Делай, как получится. А я посмотрю, насколько ты умеешь творить заклинания.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26274, 'ruRU', 'Искусство чернокнижника', 'Достигните 3-го уровня, чтобы выучить заклинание \"Порча\". Потренируйтесь в использовании заклинания, пять раз применив его на манекене-тики.', 'Хочу рассказать тебе кой-чего.$B$BКак наберешься сил, начнешь слышать голоса – они тебя будут учить новым штукам и заклинаниям.$B$BИди, набирайся опыта, а потом вернись и покажи, чему $gнаучился:научилась;.', '', '', '', '', '', 'Вернитесь к Волдреке на тренировочную площадку Черного Копья на островах Эха.', 19865);
INSERT INTO `quest_template_locale` VALUES (26275, 'ruRU', 'Практическое занятие', 'Добудьте 6 шкур буйногривой рыси.', 'Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26276, 'ruRU', 'Яма испытаний', 'Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.', 'Ты отлично $gсправился:справилась;, |3-6($c). Может, я и мог бы тебя еще чему-то научить, но глупо тратить время на тренировки.$B$BТебя ждет последний экзамен. Отправляйся в яму испытаний, что в центре этой области, и сразись с настоящим противником – таким, который жаждет тебя растерзать. Когда будешь $gготов:готова;, дай смотрителю знак.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26277, 'ruRU', 'Превосходя ожидания', 'Поговорите с Вол\'джином в крепости Черного Копья.', 'Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26278, 'ruRU', 'Защита Гром\'гола: угроза ящеров', 'Уничтожьте 12 яиц кнутохвоста.', 'Тром\'ка, |3-6($c)!$B$BТы очень вовремя $gприбыл:прибыла; в Гром\'гол. Мы должны наладить здесь поставку припасов в Каменор, но некоторые местные жители нам очень мешают.$B$BНазначаю тебя $gответственным:ответственной; за истребление ящеров в северных окрестностях Гром\'гола. Самих ящеров можно не бояться – ненормальные охотники Эрнестуэя о них позаботятся. А вот твоя задача перебить яйца ящеров.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26279, 'ruRU', 'Защита Гром\'гола: нападение на огров', 'Уничтожьте 4 громил и 4 знахарей из клана Мош\'огг.', 'Когда мы прибыли в эти джунгли, у нас не было ни малейшего намерения воевать с местными племенами. Нам всего лишь надо было наладить поставку припасов в Каменор, причем как можно скорее. Но у нас возникли затруднения: в руинах Мизжа к юго-востоку от Гром\'гола появилась банда огров. Несмотря на все предупреждения, они постоянно нападают на наши обозы.$B$BНазначаю тебя $gответственным:ответственной; за уничтожение этих назойливых огров.$B$BОтправляйся в руины и попытайся выдворить их оттуда. По меньшей мере, это покажет им, что мы настроены серьезно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26280, 'ruRU', 'Защита Гром\'гола: угроза мурлоков', 'Убейте 15 черножабрых мурлоков.', 'Черножабрых мурлоков выжили из океана мурлоки племени Соленая Чешуя, и те укрылись в развалинах Кал\'ай на северо-востоке от нас. Мы долго терпели это соседство, но теперь довольно.$B$BЧерножабрые мурлоки, отрезанные от моря, становятся все злее и посылают своих налетчиков на мои караваны с провиантом. Вдолби им в голову – Орда Адского Крика такого НЕ ПОТЕРПИТ!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26281, 'ruRU', 'Защита Гром\'гола: троллье воровство', 'Добудьте ящики с пайками Гром\'гола на руинах Бал\'лал.', 'Тролли довольно много оставили здесь, в Гром\'голе. И большинство из них понимает, что Орда легко их раздавит, если разгневается, и здешние тролли тоже не исключение.$B$BОднако Кровавые Скальпы в последнее время что-то уж больно активизировались. На прошлой неделе они отправили партию в Гром\'гол и украли несколько ящиков с провиантом.$B$BВоровство еды дело простительное, но только не когда я тут командую. Отправляйся на север к руинам Бал\'лал и верни наше имущество.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26283, 'ruRU', 'Жуть-муть', 'Возьмите образец Вязкой Мути.', 'Меня в последнее время очень заинтересовали слизни, обитающие на Осклизлой скале. Сколько бы раз мы их ни истребляли, через какое-то время их там опять полно, при этом не похоже, чтобы они могли воспроизводиться от какого-то одного уцелевшего слизня.$B$BМне кажется, что там что-то растет. Там должен быть какой-то источник слизи, откуда они все и берутся, и я хочу изучить этот источник. Пожалуйста, найди его, и принеси мне оттуда образец.', '', 'Не подходи слишком близко… неизвестно, чего можно ждать от этой штуки.', 'Вязкая Муть', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26284, 'ruRU', 'Пропавшие без вести', 'Освободите 6 захваченных подрывников из клеток вокруг форта Мерзлогривов.', 'Для подобной работы мне обычно требуется вся моя команда подрывников. Чем больше людей занимается закладкой пороха, зарядов и остального снаряжения, тем быстрее идет дело.$b$bЭти проклятые трогги держат в форте Мерзлогривов много моих подрывников, а работу заканчивать надо.$b$bНо ты производишь впечатление $gспособного:способной:c; |3-1($c). Не найдешь ли захваченных троггами подрывников и не освободишь ли их?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26285, 'ruRU', 'Верните мне мой порох!', 'Отправляйтесь в форт Мерзлогривов и отберите 7 украденных бочонков с порохом у костегрызов или мародеров из племени Каменной Челюсти.', 'Мне нужно много пороха, чтобы разрушить эти пещеры. Не знаю, думали ли об этом мерзкие трогги, когда воровали мои припасы и захватывали моих подрывников! На результат это не влияет.$b$bНо пока я не получу порох обратно, ничего взорвать не получится.$b$bОтправляйся на юг в форт Мерзлогривов и убивай всех троггов, каких найдешь. У любого из них могут быть мои бочонки с порохом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26286, 'ruRU', 'На защите Западного края', 'Добудьте гнолльские приказы атаковать.', 'После того как мой долг в Седых холмах был исполнен, я вернулся в Западный край и увидел, что мои родные места в еще большей разрухе, чем прежде.$B$BЦена нашей войны – тысячи бездомных горожан. Теперь они переселяются сюда и занимают брошенные фермы и города в этих краях.$B$BА что еще хуже, на нас теперь нападают гноллы. Дружина Народного ополчения нуждается в твоей помощи, $n. Перебей гноллов и добудь их приказы. Кто-то дергает их за ниточки, и нам надо выяснить, кто это!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26287, 'ruRU', 'Дружина Западного края', 'Убейте 12 любых гноллов из стаи Речной лапы, напавших на Сторожевой холм.', 'Нас когда-то называли народным ополчением. Однако теперь мы сражаемся под знаменем Штормграда, нас поддерживает король Андуин Ринн. У нас много дел в Западном Крае: разобраться с хаосом, который оставило после себя Братство Справедливости, упрочить власть Альянса и установить порядок. Пока нас бьют по всем фронтам.$B$BСейчас тяжелее, чем когда Братство ничто не сдерживало. Теперь, когда здешние гноллы взялись за оружие, мы просто загнаны в угол. Помоги нам, $n!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26288, 'ruRU', 'Джанго Крапчатый', 'Убейте 5 мистиков и 5 надсмотрщиков из стаи Речной Лапы и Джанго Крапчатого.', 'К югу отсюда находится область Западного края, известная как Пыльные равнины. Насколько мы знаем, здешние гноллы сделали эту область своей неофициальной столицей. И, как в каждой столице, в сердце ее сидит предводитель. Если мы хотим покончить с нападениями, мы должны выследить главного гнолла и прикончить его.$B$BОтправляйся на Пыльные равнины, найди предводителя гнолов, Джанго Крапчатого, и прикончи его. И перебей всех гноллов, что попадутся тебе на пути.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26289, 'ruRU', 'Найти агента Кеарнен', 'Найдите агента Кеарнен.', 'ШРУ следило за Хеликсом Отломчиксом с тех пор, как тот вступил на территорию Альянса две недели назад. В письме, полученном мною от Матиаса Шоу, говорится, что он послал агента по имени Кеарнен в Западный край выследить Хеликса. Найди посланницу Кеарнен – и ты найдешь Хеликса Отломчикса.$B$BКеарнен приходила в город за провизией два дня назад. Она упомянула, что будет возле башни Мортвейка, к юго-востоку отсюда, на Пыльных равнинах.$B$BИди, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26290, 'ruRU', 'Тайны башни', 'Войдите в башню Мортвейка и найдите Хеликса Отломчикса.', 'Хеликс засел в старой башне Клейвена Мортвейка. Не стану врать, $n, она хорошо охраняется. Я насчитала шесть вооруженных наемников только снаружи. В одиночку в башню ты не войдешь. На твое счастье, тут есть мы с Клер.$B$B<Кеарнен поглаживает свою снайперскую винтовку.>$B$BЯ прикрою тебя.$B$BБери это зелье покровов, оно тебе понадобится внутри. Выпей его, как только окажешься в башне, и беги вверх по лестнице. Выясни, что Хеликс там прячет!', 'Тайна Хеликса раскрыта', '', '', '', '', 'Вернитесь к посланнице Кеарнен на Пыльные равнины в Западном крае.', 25549);
INSERT INTO `quest_template_locale` VALUES (26291, 'ruRU', 'Большой переполох в Луноречье.', 'Доложите о том, что вам удалось обнаружить, маршалу Гриану Камнегриву на Сторожевом холме в Западном крае.', 'Я вскоре составлю отчет и вернусь в Штормград. В ШРУ должны узнать о событиях в Западном крае. Рекомендую тебе сделать то же самое и доложить обо всем Гриану.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26292, 'ruRU', 'В Луноречье!', 'Доложитесь капитану Алперту в Луноречье в Западном крае.', 'Некоторое время назад мы разбили лагерь у Луноречья, $n. Один из моих лучших солдат работает в этой округе вместе с отрядом бойцов со Сторожевого холма. Доложись капитану Алперту и узнай, нет ли у него новостей о событиях в Луноречье.$B$BТам находится еще один мой союзник по имени Торелий. Я встретился с ним в Нордсколе, пока был в Валгарде. Он умный и могучий шаман. Возможно, он поможет нам раскрыть эту тайну.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26293, 'ruRU', 'Боевые машины', 'Поговорите со штейгером Глиббсом у задних врат Оргриммара в Оргриммаре.', 'Приспешники \"Разрушителя миров\" скрываются далеко на востоке, на Сумеречном нагорье. Мы сокрушим их, и это сделает самая мощная армия в истории!\n\nНаши новые союзники, гоблины, уже получили приказ строить для нас новые боевые машины – но, судя по сообщениям с мест, их квалификация... оставляет желать лучшего. Мы не можем идти в бой с дефектными машинами. Поговори со штейгером Глиббсом и позаботься о том, чтобы наша техника была готова к бою.', '', '', '', '', '', 'Поговорите со штейгером Глиббсом у задних врат Оргриммара в Оргриммаре.', 25549);
INSERT INTO `quest_template_locale` VALUES (26294, 'ruRU', 'Оружие массовой дисфункции', 'Осматривайте \"Разрушители Адского Крика\", пока не найдете машину с дефектом, а затем проучите главного инженера.', '<Глиббс вытирает пот со лба засаленным платком.>$B$BСаурфанг недоволен качеством работы? Плохо дело. Похоже, моим ребятам придется поднапрячься.$B$BМожет, ты покажешь им пример? Очередная партия разрушителей Адского Крика только что сошла с блоков и готова к осмотру. Осмотри все машины как следует и, если найдешь какие-то недостатки, дай главному инженеру хорошего пинка. И напомни им, что успех Орды во многом зависит от них!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26295, 'ruRU', 'Пропаганда', 'Добудьте информационный буклет, тайный дневник, выпуск луноречского вестника и таинственное воззвание.', 'Мы заметили рост правонарушений среди бездомных в округе. Что-то – или кто-то – взбудоражило их. Что бы за этим ни стояло, все это стало более организованным. Совсем недавно группа бандитов явилась сюда со своими прокламациями.$B$BОтправляйся в Луноречье и поищи улики. Пропагандистские плакаты, листовки, все что угодно... Что найдешь, принеси мне. Может, по этим писулькам мы узнаем, кто за этим стоит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26296, 'ruRU', 'Сбор доказательств', 'Добудьте 6 красных бандан.', 'Материал этих повязок такой же, как и те обрывки ткани, что были найдены на месте убийств Хмуробровов. Принесите еще несколько красных повязок в качестве доказательства и вернитесь к капитану Алперту.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26297, 'ruRU', 'Заря нового дня', 'Отправляйтесь на условленое место в Луноречье и добудьте необходимую информацию.', 'Сдается, встреча, о которой говорила та темная личность, скоро начнется. Бездомные мобилизуются. Я хочу, чтобы ты $gпобывал:побывала; на встрече и $gдобыл:добыла; информацию, $n.$B$BОтправляйся в центр Луноречья и узнай, что там будет говориться. Обо всем, что узнаешь, доложи мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26298, 'ruRU', 'Поиски Йеннику', 'Добудьте 6 клыков троллей из племени Кровавого Скальпа в руинах Бал\'лал.', 'Это рок. Рок преследует младшего сына моего вождя Йеннику. Как у нас заведено, его отдали троллям племени Гурубаши в Зул\'Гуруб, но когда мое племя – племя Черного Копья – ушло вместе с орком Траллом, бедный Йеннику потерялся. Меня послали из далекого Оргриммара обратно в Тернистую долину на поиски сына вождя.$B$BЯ думаю, он у племени Кровавых Скальпов.$B$BЕсли хочешь мне помочь, выследи Кровавых Скальпов – они обитают на севере. Принеси мне их клыки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26299, 'ruRU', 'Охота за головами', 'Раздобудьте 25 сушеных голов, которые носят при себе тролли из племени Кровавого Скальпа, живущие в руинах Зуулдая.', 'Нужно узнать, мертв ли Йеннику.$B$BУбей троллей из племени Кровавого Скальпа в Зуулдая и забери у них сушеные головы. Собрать нужно много, очень много, а я потом их все осмотрю и удостоверюсь, что Йеннику среди них нет.$B$BА если тролли все же убили Йеннику, то пусть на душу их предводителя Ган\'зулаха падет шестисотлетнее проклятие!$B$BСтупай, $n. Головы нужно искать в руинах Зуулдая, это на побережье к северу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26300, 'ruRU', 'Знания Неззилока', 'Отрубите голову Неззилоку Зловещему в Зул\'Кунде.', 'Я не обнаружил Йеннику среди голов, хвала Великому Змею! Но мы не сильно продвинулись в наших поисках.$B$BНеобходимо выяснить истину, но боюсь, она известна лишь знахарю племени Кровавого Скальпа. Он враг племени Черного Копья и просто так говорить не будет – поэтому надо вырвать правду из его мертвых губ!$B$BПринеси мне голову Неззилока Зловещего и положи в этот котел.$B$BЭтот тролль живет в глубине Зул\'Кунды. Только доставь голову... а уж говорить мы ее заставим.', '', 'Главный знахарь племени Кровавого Скальпа находится в глубине руин Зул\'Кунды.', 'Неззилок Зловещий', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26301, 'ruRU', 'Разговор с Неззилоком', 'Добудьте трофей из Балиа\'ма и Зиата\'джай в руинах Дробителей Черепов в Северной Тернистой долине.', '<Голова Неззилока начинает говорить.>$B$BЭто верно. Мне известно, куда забрали дитя Черного Копья. Да, ты $gпобедил:победила; и $gпленил:пленила; мою душу, но я ничего не скажу, если ты не умиротворишь меня!$B$BКровавые Скальпы воюют с Дробителями Черепов. Хочешь заслужить мою благосклонность – укради у Дробителей Черепов, живущих за рекой на востоке, два самых ценных трофейных черепа. Положи их здесь, чтобы у моей души в Пустоте были рабы. Один череп должен быть из груды трофеев в Балиа\'ма, второй – из Зиата\'джай.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26302, 'ruRU', 'Судьба Йеннику', 'Поговорите с Кин\'вилаем в Бамбале.', '<Неззилок говорит.>$B$BТы $gсослужил:сослужила; мне хорошую службу, и я скажу тебе все, что ты хочешь знать... $B$BЮный Йеннику потерян для своего племени.$B$BЕго забрал к себе знахарь Занзил Отверженный. Теперь Йеннику – полностью в его власти... и душой, и телом... и его может освободить только очень сильная магия.$B$BТы такой магией не владеешь, |3-6($c).$B$BНадежды практически нет. Хотя, может быть, твои союзники из Черного Копья в Бамбале на востоке все-таки сумеют спасти Йеннику. Но я сомневаюсь...', '', '', '', '', '', 'Поговорите с Кин\'вилаем в Бамбале в Северной Тернистой долине.', 25549);
INSERT INTO `quest_template_locale` VALUES (26303, 'ruRU', 'Глаз разума', 'Отнимите Глаз разума у Май\'Зота.', 'Глаз разума находится у одного огра-мага, в кургане Мош\'Огга к югу отсюда. Зовут его Май\'Зот. Я знаю его еще с тех пор, как племя Черного Копья жило в Тернистой долине. Он коварен и обладает сильной магией.$B$BЕсли Глаз разума у него, его магия станет еще мощнее.$B$BТебе надо сразиться с Май\'Зотом и отнять у него Глаз разума. Это опасное задание, но только так мы можем спасти Йеннику.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26304, 'ruRU', 'Ночь в джунглях', 'Потушите 8 жаровен в Зул\'Мамве, что в Северной Тернистой долине.', 'Год назад мою мать – вернее, тролльскую женщину, которая обо мне заботилась, – похитили Дробители Черепов из Зул\'Мамве. В отчаянии я побежал за ней. Но тут целая дюжина воинов потащила ее к горящей жаровне. Я спрятался за деревом и видел, как они схватили ее и... и...$B$B<Кил\'карил отводит взгляд.>$B$BПо ночам свет этих жаровен отражается от вершин деревьев и не дает мне уснуть... Прошу тебя, $n... сходи на юг в Зул\'Мамве и погаси их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26305, 'ruRU', 'Спасение Йеннику', 'Отнесите Нимбойе наполненный самоцвет души.', 'Я превратил Око разума в самоцвет души. Он послужит двоякой цели: сначала оглуши им Йеннику, а затем помести самоцвет ему на голову и поймай душу.$B$BМои подозрения подтвердились: Йеннику живет не у Занзила Отверженного, а в Руинах Зул\'Мамве, расположенных к юго-западу отсюда. Как только освободишь душу Йеннику, возвращайся в Гром\'гол к Нимбойе.', '', 'Ему столько пришлось пережить... Пора освободить его душу.', 'Йеннику', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26306, 'ruRU', 'Начало расправы', 'Убейте 5 знахарей и 5 охотников за головами из племени Порочной Ветви в Джинта\'Алоре.', 'Сегодня мы нанесем первый удар в самое сердце гнусного племени Порочной Ветви. Не щади никого, $n, это уже не просто размолвка между троллями. Каждая победа Сломанного Клыка – это победа Орды!$B$BОхотники за головами и знахари племени Порочной Ветви станут нашими первыми жертвами. Займись нижними ярусами и не возвращайся, пока не искупаешь свое оружие во вражеской крови.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26307, 'ruRU', 'Смерть Порочной Ветви!', 'Убейте 5 берсерков и 5 темных чародеев из племени Порочной Ветви в Джинта\'Алоре.', 'Не дадим им возможности ответить. Тебе надо пойти в Джинта\'Алор и прорваться на верхние ярусы.$B$BБерсерки и темные чародеи из племени Порочной Ветви – очень опасные враги, $n. Когда остальные увидят, как мы перекидываем их трупы через стены, они поймут, что мы не шутки шутить сюда пришли.$B$BНе оставляй никого в живых!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26308, 'ruRU', 'Победа наша!', 'Убейте 5 кровопийц и 5 пожирателей душ из племени Порочной Ветви в Джинта\'Алоре.', 'Остались только самые стойкие и злобные из племени Порочной Ветви – кровопийцы и пожиратели душ, поклоняющиеся Хаккару.$B$BОни все ИДИОТЫ! Держатся за старые дурацкие верования. Я не собираюсь больше терпеть их преступления против племени Сломанного Клыка.$B$BНанесем им последний удар. Завоюем Джинта\'Алор для Сломанного Клыка и для Орды!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26309, 'ruRU', 'Темные сосуды', 'Соберите 5 Сосудов с порченой кровью в Джинта\'Алоре.', 'Тролли племени Порочной Ветви пили порченую кровь бога Хаккара, чтобы набраться сил. Они кипятили ее в котлах, и теперь эти сосуды полны нечистой силы.$B$BХаккар давно убит, но вот что странно... я все еще замечаю тут кипящие котлы. Принеси мне несколько, и мы посмотрим, что это такое они тут варят.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26310, 'ruRU', 'Быстролапые паучата', 'Соберите 8 быстролапых паучков в Джинта\'Алоре.', 'Иди сюда, |3-6($c)...$B$BЕсть у меня пара знакомых торговцев, очень заинтересованных в сильных ядах. Так вот, заметила я паучат, которые тут бегают. Нет, я не про больших, а про маленьких, которые размером примерно с твою руку.$B$BОни такого необычного для наших краев цвета... Поймай несколько и принеси их мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26311, 'ruRU', 'Неизведанные воды', 'Найдите Эрезегора Огнеклыка в таверне \"Хвост виверны\", которая расположена на Аллее Чести в Оргриммаре. Возьмите у него карту побережья Сумеречного нагорья.', 'Вождь планирует полномасштабное наступление на Сумеречное нагорье. Там мы надеемся заключить союз с орками из клана Драконьей Пасти.$B$BПо данным из моих источников, один орк этого клана живет здесь, в Оргриммаре. Его зовут Эрезегор Огнеклык, и когда-то он командовал армиями.$B$BЗнания, которыми он обладает, просто бесценны. Найди Огнеклыка и убеди его дать тебе карту побережья – нам нужно знать, как безопасно подвести корабли к нагорью.$B$BПо слухам, Огнеклыка можно встретить в одном из питейных заведений на Аллее Чести...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26312, 'ruRU', 'Неравный бой', 'Помогите Тону Зимнему Утесу, буревестнице Милре и Харготу Бледному Пламени победить их противников, чтобы они смогли перевести дух.', 'Когда началась атака, мы сразу же дали отпор врагу, чтобы занять поле. Но вражеские войска были огромны... мы недооценили их силы. И теперь лучшие наши шаманы остались там, без нашей защиты, почти без сил, в весьма затруднительном положении.$b$bОтправляйся туда и выручи наших братьев. Даже короткая передышка в бою поможет им.$b$bТоропись, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26313, 'ruRU', 'Суть наших проблем', 'Соберите 6 сердец яростных грохотунов.', 'Элементали хаотичны по своей природе, но такая направленная агрессия им не свойственна. Особенно здесь, где они постоянно погибают. Подозреваю, что это дело рук Матери-Скалы Теразан, но мне нужно быть абсолютно уверенной.$b$bУбей яростных грохотунов и принеси мне их сердца. И мы решим, действительно ли ненависть Матери-Скалы всему причиной.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26314, 'ruRU', 'На ровной земле', 'Воспользуйтесь элементиевыми \"кошками\", чтобы сбить с ног 3 слуг Теразан.', 'Нам повезло, эти великаны – отличные мишени. Надо воспользоваться удачей.$b$bНам нужно убрать их с поля боя, но не думаю, что атаковать их в лоб, будет очень умно.$b$bВозьми вот эти \"кошки\", хорошенько закрепи их на лодыжках великанов и тяни как следует. Когда они окажутся на земле, прикончить их будет уже очень легко.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26315, 'ruRU', 'Впечатляющая встреча', 'Прочитайте воззвание Служителей Земли Бодену Впечатляющему.', 'Ты $gвидел:видела; великана, который маячит там вдалеке на северо-востоке? Это Боден Впечатляющий, один из каменных лордов Матери-Скалы.$b$bМы не так уж много знаем о каменных лордах, но Бодена, определенно, уравновешенным не назовешь. К сожалению, похоже, что он руководит этим нападением, так что он один из тех, с кем нам придется встретиться лицом к лицу.$b$bОтнеси ему это воззвание и прочитай его вслух от лица Служителей Земли. Знаю, думать, что словами можно уладить такое дело, – это просто тянуть время, но мы должны по крайней мере попытаться. Будь $gосторожен:осторожна;.', '', 'Не всегда легко избежать взглядов свысока.', 'Боден Впечатляющий', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26316, 'ruRU', 'Как дела у Джессупа?', 'Найдите Джессупа Маккри в его лагере возле форта Мерзлогривов.', 'Из-за катаклизма разверзлись пещеры под фортом Мерзлогривов, и трогги хлынули из своих логовищ. Они вынудили мигрировать троллей, которые всегда жили в этих местах, и они выживут отсюда и нас, если мы будем бездействовать.$b$bГлавный механик Меггакрут нанял прославленного подрывника Джессупа Маккри, чтобы он взорвал пещеры и перекрыл троггам доступ на поверхность. Но мы не получили от него никаких известий и не знаем, удалось ли ему остановить троггов. Не разыщешь ли ты его в его лагере, разбитом возле форта Мерзлогривов, что к югу от зараженного аэродрома?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26317, 'ruRU', 'Детеныш кнутохвоста', 'Принесите детеныша кнутохвоста провозвестнику Мок\'тардину в лагерь Гром\'гол.', 'Вы уже приготовились нанести последний удар по кладке яиц кнутохвоста, как вдруг глянули вниз и увидели, что на вас смотрит едва вылупившийся детеныш. Он словно изучал вас, запоминал черты вашего лица и повторял все ваши движения.$B$BМежду вами и детенышем кнутохвоста установилась некая связь.$B$BВам было приказано уменьшить поголовье ящеров, но задание вы уже и так выполнили, а этот детеныш еще ни в чем не провинился. Может, кто-нибудь в лагере Гром\'гол подскажет вам, что с ним делать.', '', '', '', '', '', 'Поговорите с провозвестником Мок\'тардином в лагере Гром\'гол, что в Северной Тернистой долине.', 25549);
INSERT INTO `quest_template_locale` VALUES (26318, 'ruRU', 'Окончание работы', 'Проберитесь в нижнюю часть пещеры, расположенной в форте Мерзлогривов, убейте босса Бруггора и активируйте детонатор, чтобы взорвать туннели троггов.', 'Моя команда закончила размещать бочонки с порохом и детонатор внизу пещеры, которая находится в западной части форта Мерзлогривов. Все, что от тебя требуется, это пробраться туда и активировать детонатор, чтобы произошедший взрыв завалил туннели.$b$bЭто лишит троггов возможности выбираться на поверхность из глубоких частей пещеры. А если ты победишь предводителя троггов, который называет себя боссом Бруггором, Меггакруту будет легче разобраться с оставшимися.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26319, 'ruRU', 'Тайна раскрыта', 'Поговорите с Торелием Мудрым в Луноречье в Западном крае.', 'Здесь есть шаман, Торелий, который сможет помочь нам. Он друг Гриана, который недавно прибыл в Западный край, чтобы изучить стихийные бедствия, обрушившиеся на нас в последнее время.$B$BПоговори с Торелийом и посмотри, не сможет ли он пролить свет на эту таинственную темную личность.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26320, 'ruRU', 'Видения прошлого', 'Войдите в убежище Братства Справедливости идите по следу бездомных до Мертвых копей. Войдите в Мертвые копи и используйте курильницу, чтобы заглянуть в прошлое.', 'Эти благовония погрузят твое тело и разум в состояние глубокой медитации. Как только начнется транс, тебя увлечет в мир духов. Не сопротивляйся трансу, когда он начнет овладевать тобой, $n. Дай духам показать тебе то, что они знают.$B$BТеперь уходи. Иди к Мертвым копям, к месту, которое, как мне говорили, имеет большое значение в истории Западного края. Как окажешься там, используй благовоние.$B$BТы можешь войти в Мертвые копи через старый фермерский дом к югу отсюда. Следуй за бездомными.$B$BС тем, что обнаружишь, возвращайся к Гриану.', 'Видение прошлого открылось', '', '', '', '', 'Вернитесь к маршалу Гриану Камнегриву на Сторожевой холм в Западном крае.', 25549);
INSERT INTO `quest_template_locale` VALUES (26321, 'ruRU', 'Не покормишь – не вырастишь', 'Добывайте мурлоков из племени Черножабрых в Северной Тернистой долине и кормите своего ящера-кнутохвоста их мясом, пока он не съест 40 кусочков.', 'Похоже, твой детеныш ящера голоден. Если хочешь позаботиться о зверушке, почему б тебе не принести ей какой-нибудь еды? Кнутохвосты частенько нападают на поселение мурлоков из племени Черножабрых, которые обитают неподалеку, к северу отсюда.$B$BУ этого крошки-ящера силенок пока маловато, чтобы самому охотиться, но ему наверняка придется по вкусу свежее мясо мурлока.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26322, 'ruRU', 'Восстание Братства', 'Станьте свидетелем восстания Братства.', 'Я не знал, что у Ван Клифа была дочь, $n. Если этот человек и обладал каким-то особым умением, так это умением хранить тайны.$B$BКакая трагедия. Бедняжка пережила ужасное. Если бы я только знал.$B$BЧто это? Слышишь? Кажется гноллы возвращаются... где стража?$B$BК ОРУЖИЮ, $n!', 'Восстание Братства засвидетельствовано', '', '', '', '', 'Вернитесь с докладом к королю Андуину Ринну в крепость Штормграда.', 25549);
INSERT INTO `quest_template_locale` VALUES (26323, 'ruRU', 'Особенный череп', 'Вернитесь к Нимбойе в лагерь Гром\'гол и покажите ему свежий череп детеныша кнутохвоста.', 'Ваш ручной ящер нашел себе новую игрушку – череп из лежащей неподалеку горы черепов троллей.$B$BВы не можете понять, чем этот череп отличается от остальных, но животное не хочет его отдавать.$B$BНимбойя из лагеря Гром\'гол должен неплохо разбираться в черепах, судя по хранящейся у него коллекции. Может быть, он знает, что особенного в этом черепе.', '', '', '', '', '', 'Вернитесь к Нимбойе в лагерь Гром\'гол, что в Северной Тернистой долине.', 25549);
INSERT INTO `quest_template_locale` VALUES (26324, 'ruRU', 'Где мой боевой флот?', 'Поговорите с полководцем Кроггом в порту Трюмных Вод в Азшаре.', 'Нагорья – земли орков клана Драконьей пасти. Когда они увидят на своем берегу мощь наших объединенных войск, им ничего не останется, кроме как стать нашими союзниками в битве с культом Сумеречного Молота. Даже не сомневаюсь!\n\nФлот уже собирается в порту Трюмных Вод в Азшаре, только вот у них то понос, то золотуха.\nУ тебя получилось заставить этих лодырей-гоблинов работать как следует – подсоби, что ли, и мне.\nОтыщи полководца Крогга в Азшаре и узнай, чего они там тянут резину.', '', '', '', '', '', 'Поговорите с полководцем Кроггом в порту Трюмных Вод в Азшаре.', 25549);
INSERT INTO `quest_template_locale` VALUES (26325, 'ruRU', 'Хороший нюх', 'C помощью детеныша кнутохвоста найдите 8 зуулдайских фетишей.', '<Череп заговаривает с вами.>$B$BЯ жив? Да нет... но могу ожить.$B$BТвой ящер умный, нашел среди многих именно мой череп. В жизни я был сильным, могущественным владыкой у троллей. И с твоей помощью снова стану главным.$B$BКровавые Скальпы из Зуулдая хранят магические штуки, которые помогут мне вернуться. Они прячут их в песках. Возьми своего ящеренка, найди эти фетиши, $n... И кинь их в котел.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26326, 'ruRU', 'Сама земля под нашими ногами', 'Найдите заклинателя земли Торунскара северо-западнее храма Земли, в Бугристых пустошах.', 'Остается лишь одна часть столпа мира и она в руках самой Матери-Скалы. И, что еще хуже, храм осаждают элементали и великаны. Не требуется большого ума, чтобы догадаться, что действуют они по ее повелению.$b$bОтправляйся на северо-запад и встреться с элементалями в бою. Торунскар и Норсала помогут тебе найти возможность поговорить с их вождями и отыскать столп мира. Мы бы предпочли, чтобы это произошло мирным путем, но мы пойдем на все, чтобы закрыть разлом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26327, 'ruRU', 'Герой Старая Наковальня', 'Поговорите с Таргасом Старой Наковальней.', 'Не трать времени на разговоры со мной, $gпаренек:девушка;. На том конце каравана ты найдешь самого Таргаса Старую Наковальню.$B$BТы ведь наверняка $gслышал:слышала; о нем? Он защищал мост Тандола от гномов Черного Железа вместе с королем Штормграда! Он один из самых славных героев Стальгорна.$B$BНо сейчас он среди целой толпы героев! Иди туда и скажи, что ты поможешь ему. Только держись поодаль, у него замах хороший.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26328, 'ruRU', 'Крепкие отношения', 'Найдите Диаманта Терпеливого на северо-восточном краю Бугристых пустошей.', '<Норсала наклоняется к земле, пытаясь узнать, где находится Диамант, но, едва прикоснувшись, отскакивает.>$b$bНичего себе! Это неожиданно. Диамант совсем недалеко. Когда я обратилась к нему, он заговорил со мной и рассказал, где мы можем его найти. Отправляйся на северо-восточный край Бугристых пустошей – Диамант будет ждать тебя там.$b$b$n, будь $gосторожен:осторожна;. Не в их духе устраивать засады, но и осады Храма от них тоже никто не ждал.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26329, 'ruRU', 'Еще одно дело', 'Отнесите донесение Джессупа главному механику Меггакруту в Новый Город Механиков.', 'Ну что ж, пора собирать вещички и приниматься за новую работу. Здесь всегда найдется, что взорвать. Где-то нужно гору передвинуть, где-то овраг пообтесать, и я всегда готов этим заняться.$b$bНе окажешь мне еще одну услугу? Нужно отнести этот отчет главному механику Меггакруту в Новый Город Механиков. Он должен знать, что трогги больше не будут беспокоить его людей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26330, 'ruRU', 'Кто тут большой тролль?', 'Добудьте тело Ган\'зулаха из Зул\'Кунды.', '<Череп снова начинает говорить.>$B$BМоя душа готова, но тело – нет. Кровавые Скальпы давно-давно осквернили мое прежнее тело. Какие ужасные вещи они с ним проделывали... мой дух взирал на то, как раздирали мою плоть и... я не в силах продолжать.$B$BИх вождь Ган\'зулах первым участвовал в этих мерзостях. Если мне не изменяет память, это был сильный, могучий тролль... почти как я. Какое интересное совпадение.$B$BТы понимаешь, как нужно поступить, |3-6($r). Так сделай это побыстрее.', '', 'Он воистину большой тролль.', 'Ган\'зулах', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26331, 'ruRU', 'Приспешники Шестерямстера', 'Убейте 8 приспешников Шестерямстера в арсенале Шестерямстера. Вы можете убивать облученных техников или боевых роботов Шестерямстера.', 'Наш давний враг, Термоштепсель, старается изо всех сил, чтобы помешать нам закончить восстановление Гномрегана. Он выставил против нас одного из самых верных своих приспешников, Разло Шестерямстера, вместе с отрядом облученных гномов.$b$bОни захватили старый арсенал, который находится по дороге на север, и там приспешники Шестерямстера ремонтируют технику. Мы должны остановить их прежде, чем у них получится завести эти механотанки. Отправляйся в арсенал Шестерямстера и убей так много его техников, как только сможешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26332, 'ruRU', 'Зелье Дробителей Черепов', 'Добудьте 6 зелий Дробителей Черепов у троллей Дробителей Черепов в руинах Зиата\'джай и в руинах Балиа\'ма.', '<Череп заговаривает снова.>$B$BТеперь у меня есть тело благодаря тебе, твоему ящеру и Ган\'зулаху. И если мне не изменяет память, вам с приятелем-знахарем понадобится особый настой, чтобы завершить этот ритуал.$B$BКровавые Скальпы хранят свои зелья в Зул\'Кунде, но они довольно слабые. Твое зелье Черного Копья тоже не поможет. Нет... возьми его у троллей Дробителей Черепов, за рекой на востоке.$B$BВозвращайся скорее, |3-6($r). Я буду ждать...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26333, 'ruRU', 'Нет танкам!', 'Воспользуйтесь техно-гранатой, чтобы разрушить 5 отремонтированных механотанков в арсенале Шестерямстера.', 'Мы потеряли немало разведчиков, пытаясь выяснить, что именно Разло Шестерямстер собирается делать со всеми этими механотанками, которые ремонтируют его облученные техники.$b$bДольше медлить нельзя. Мы должны начать действовать прежде, чем Шестерямстер сможет использовать силы своих последователей и свое оружие против нас.$b$bУ этой техно-гранаты достаточно взрывной силы, чтобы разрушить механотанки и не дать Шестерямстеру возможности использовать их. Возьми ее с собой, отправляйся на север, по дороге, ведущей к арсеналу Шестерямстера, и уничтожь эти танки!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26334, 'ruRU', 'Мандокир Повелитель Крови', 'Принесите Осколок яйца ящера-кнутохвоста Мандокиру Повелителю Крови в Лагерь Повстанцев.', '$R. $R, |3-6($r), |3-6($r)... ты же не $gдумал:думала;, что я тебе друг, а, |3-6($r)? Ха-ха-ха!$B$BТы свое дело $gсделал:сделала;. Благодаря тебе я вернулся в царство живых. Поэтому я тебя не убью, а предложу сделку.$B$BОтдай мне ящера.$B$BТы, наверное, уже знаешь, что она не обычный ящер, а мне нужна замена для Оган. Делай, как я говорю. Иначе вы оба – и ты, и знахарь – испытаете на себе силу моего гнева.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26335, 'ruRU', 'Готовность военно-морских сил', 'Исследуйте остов \"Крушителя Врагов\".', 'Адский Крик ждет, когда будет готова армада для вторжения, но в доках на несколько недель отстают от плана. Затраты огромны, а качество работ очень низкое. Проблема в коррупции, $n! И я хочу, чтобы ты ее $gискоренил:искоренила;.$b$b\"Крушитель Врагов\", военный корабль, стоящий на якоре у северо-западного причала, должен был быть оснащен еще несколько дней назад. Это плохо пахнет. Отправляйся туда и $gсам:сама; проследи за оснасткой.$b$bУзнай, кто задерживает работу, и разберись с ним!', '', '', '', '', '', 'Исследуйте остов \"Крушителя Врагов\".', 25549);
INSERT INTO `quest_template_locale` VALUES (26336, 'ruRU', 'Мураш О\'Брин', 'Найдите Мураша О\'Брина в бухте Фальдира на нагорье Арати.', 'Ты совершенно $gправ:права;, $n. Не каждый день встречаешь так называемого героя, который разбирается в том, что происходит, оказавшись так далеко от дома, так что я доверю тебе еще кое-какое дело.$b$bУ меня есть друг по имени Мураш О\'Брин. Он предводитель команды Пиратов Черноводья. Они славные ребята, настоящие пираты. Их судно стоит в бухте Фальдира, в укрытии у южного берега.$b$bУверен, у О\'Брина найдется для тебя прибыльная работенка, если ты в этом $gзаинтересован:заинтересована;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26337, 'ruRU', 'Снижение издержек', 'Найдите где-то в Гавани Трюмных Вод штейгера картеля Трюмных Вод и припугните его.', '<Понять, почему задерживается оснастка \"Крушителя Врагов\", несложно. Изо дня в день штейгер вносит изменения в чертежи.>$b$b<Особенно пугающими выглядят недавние правки. Рабочим приказали снять заклепки, чтобы снизить издержки!>$b$b<Стоит разыскать одного из мастеров \"Крушителя Врагов\" и разобраться с ним, пока никто из Орды не пострадал.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26338, 'ruRU', '\"Кон-тролль\" популяции', 'Убейте 7 мистиков, 7 охотников, 7 разведчиков и 1 повелителя зверей из племени Кровавого Скальпа.', 'Насколько понимаю, ты скоро отправляешься в Зул\'Кунду. Но пока ты здесь, у меня для тебя небольшое задание.$B$BВ Тернистой долине развелось слишком много троллей. Западные земли заняло племя Кровавого Скальпа, восточные – Дробители Черепов. Они перебираются из своих руин в джунгли и нарушают равновесие здешней природы. Пора нам его восстановить.$B$BЗул\'Кунда – столица Кровавого Скальпа. Там живут все высокопоставленные члены племени. Убей нескольких, а потом возвращайся ко мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26339, 'ruRU', 'Сбор в Поселке Пивоваров', 'Поговорите с Ярви Шагом Сквозь Тень в Поселке Пивоваров.', 'Пока мы вместе с главным механиком Меггакрутом и его военными советниками заканчиваем планирование нападения на Разло Шестерямстера, я отправила своего помощника в Поселок Пивоваров, чтобы начать приготовления.$b$bЧтобы добраться до Поселка Пивоваров, иди по дороге, выходящей из города на юго-восток. Когда прибудешь, найди Ярви Шаг Сквозь Тень и узнай, не нужна ли ему помощь. Наши братья-дворфы выделили группу горных пехотинцев Стальгорна, которые присоединятся к нам для битвы с Шестерямстером.', '', '', '', '', '', 'Поговорите с Ярви Шагом Сквозь Тень в Поселке Пивоваров.', 25549);
INSERT INTO `quest_template_locale` VALUES (26340, 'ruRU', 'Охота', 'Поговорите с Барнилом Каменным Горшком в лагере экспедиции Эрнестуэя, что в Северной Тернистой долине.', 'Из всех мест Азерота я застрял именно в Гром\'голе. Здесь полно диких зверей, грабителей караванов, всегда могут напасть тролли – удивляюсь, как я вообще еще жив!$B$BХотя могло быть и хуже. По крайней мере, в Гром\'голе есть стены и стражники. А вот несколько охотников разбили лагерь к северу отсюда – прямо посреди джунглей!$B$BТуда все время кто-то ходит. Так что если ты ищешь себе приключений, туда тоже наведайся. А я, пожалуй, останусь в Гром\'голе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26341, 'ruRU', 'Осколки камня', 'Исследуйте кристаллы Мизраэль.', 'Я обыскал все это нагорье, $n, и обнаружил кое-что, чему я не могу найти объяснения.$b$bК северо-востоку отсюда есть круг из камней, такой же, как и в других местах Арати, но он больше и внушительнее всех остальных и весь встроен в склон горы.$b$bТолько между нами: когда я был там, я слышал голоса. Шепот земли. Если тебе интересно, ты $gсам:сама; можешь сходить посмотреть...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26342, 'ruRU', 'Закрасить черным', 'Воспользуйтесь краскометом, чтобы ослепить 5 караульных роботов Шестерямстера.', 'У нас есть проверенная информация о том, что этот Разло Шестерямстер занял оборонительную позицию на острове посреди Заледеневшего озера. Хуже того, он окружил себя сетью из караульных роботов, которые засекут любого атакующего.$b$bЕсли мы хотим победить Шестерямстера, нужно вывести из строя этих караульных роботов. Это устройство стреляет черной липкой краской, которая залепит оптические сенсоры караульных роботов Шестерямстера. Воспользуйся им, чтобы уничтожить его систему заблаговременных оповещений.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26343, 'ruRU', 'Спрос и предложение', 'Принесите 2 больших шкуры речного кроколиска Дриззлику в лагерь экспедиции Эрнестуэя.', '\"Лучший мастер-кожевник Южных морей, а также Старого и Нового света.\" Вот как меня называют. Меня! Дриззлика! Лучший мастер-коже... Гм... Ну, в общем, понятно.$B$BМои изделия повсеместно славятся как самые лучшие – для тех, кто знает толк в хороших вещах!$B$BЯ только что получил заказ от директора Ридлвокса из Союза ремонтников на дюжину пар его любимых сапог. \"Эксельзиор\"! Наша самая ходовая модель.$B$BВ связи с этим мне нужны шкуры кроколисков. Кроколиски водятся у реки в Северной Тернистой долине.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26344, 'ruRU', 'Немного разнообразия не помешает', 'Принесите 5 шкур кроколисков-хрустогрызов Дриззлику в лагерь экспедиции Эрнестуэя.', 'Ну ладно, в целом, сапоги почти готовы, и пока все идет хорошо. Но вот незадача: ты $gпринес:принесла; мало шкур – их на подкладку не хватит.$B$B\"И что же нам делать, Дриззлик?\" Наверняка этот вопрос уже вертится у тебя на языке. Но тебе повезло. Потому что ты говоришь с Дриззликом, и он знает, что делать!$B$BПодкладка, она не видна снаружи, и на нее можно взять кожу потолще и подешевле. Например, шкуры кроколисков с озера Назферити вполне подойдут. И разницы никто не заметит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26345, 'ruRU', 'Эксельзиор', 'Принесите Дриззлику шкуру старого кроколиска в лагерь экспедиции Эрнестуэя.', 'Внутренняя отделка готова, теперь осталось заняться внешней. На это я пускаю только самые лучшие шкуры старых кроколисков. Они прочнее и текстура у них удобнее для нашивки украшений и разных деталей, благодаря которым прославились фирменные изделия Дриззлика.$B$BПравда, такой материал довольно трудно найти. Для моей работы подходят только шкуры старых кроколисков-хрустогрызов. Они водятся на юге, неподалеку от мыса.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26346, 'ruRU', 'История Мизраэль', 'Вернитесь к Скуэрто в Опорный пункт на нагорье Арати.', 'Когда камень затихает, вы уходите со смутным ощущением тревоги. Что-то не так.$b$bВозможно, о том, что вы уже сделали, следует рассказать Скуэрто.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26347, 'ruRU', 'Хранитель огня', 'Принесите 5 образцов слизи из Бушующей пропасти капитану Грейсону на маяк Западного края.', 'Ночь, когда погибла семья смотрителя маяка, была ужасной. Я беспомощно наблюдал за происходившим, поскольку сам Старый Мрачноглаз вел нападавших. Но что случилось, то случилось, и теперь жизнь моряков, плавающих по Великому морю и близко подходящих к опасным прибрежным рифам, – моя забота. Поддерживать огонь маяка оказалось некому, и эта обязанность легла на мои плечи.$B$BПомоги мне поддерживать огонь – принеси мне слизи из Бушующей пропасти на северо-востоке отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26348, 'ruRU', 'Борьба за чистоту берегов', 'Убейте 7 мурлоков-волноловов и 7 мурлоков-оракулов.', 'Вероятно, ты $gвидел:видела; эти обломки кораблей на берегу. Великое море коварно. Берег Западного края необходимо расчистить, чтобы моряки находили путь к нашим берегам безопасно. Но мурлоки не дают нам покоя.$B$BПеребей мурлоков-волноловов и оракулов, и я позабочусь о твоей награде.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26349, 'ruRU', 'Опасность на побережье', 'Принесите чешуйку Старого Мрачноглаза капитану Грейсону на маяк Западного края.', 'Когда моя жизнь закончилась на этих скалах, я понятия не имел, что мне сулит посмертие. В ту ночь маяк не горел, потому, что Старый Мрачноглаз запугал до смерти семью смотрителя. Они вернулись и зажгли пламя, но Старый Мрачноглаз заставил более слабовольных мурлоков напасть на маяк вместе с ним еще раз. Во второй раз семье не так повезло, и они погибли у меня на глазах.$B$BУбей Старого Мрачноглаза, если найдешь его на берегу, принеси мне одну из его чешуек, и я награжу тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26350, 'ruRU', 'Жрица Ху\'рала', 'Найдите жрицу Ху\'ралу в Бамбале в Северной Тернистой долине и поговорите с ней.', 'Спасибо, $n. Знаю, ты не $gобязан был:обязана была; меня спасать и... В общем, большое спасибо.$B$BВозвращение Мандокира Повелителя Крови – очень дурная новость. Несколько лет назад его убили в Зул\'Гурубе, и мы тогда решили, что больше не увидим ни его, ни ему подобных. Но тролли в Зул\'Гурубе не оставляли попыток провести свой чудовищный ритуал. И если они все же смогли вернуть Мандокира к жизни, то, скорее всего, они воскресили и других.$B$BТролли в Бамбале, что к востоку отсюда, могут знать больше. Поговори с их жрицей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26351, 'ruRU', 'Внутреннее зрение', 'Раздобудьте 5 перьев хищника джунглей в Северной Тернистой долине.', 'Чтобы узнать Мандокира, нужно увидеть Мандокира.$B$BЧтобы увидеть Мандокира, нужны глаза ящера.$B$BМежду тобой и ящером Оган\'ака, дочерью Оган, установилась связь.$B$BЧтобы укрепить ее, нужны перья.$B$BИди на запад, найдешь перья там, да.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26352, 'ruRU', 'План Коззла', 'Возьмите ключ штейгера Коззла, а затем заберите чертежи топливного регулятора.', 'Хоть я родом и из племени Черного Копья, но детство провел здесь, в Тернистой долине. Чего тут только не повидал, но самое ужасное – что Торговая Компания сделала с руслом местной реки.$B$BА в довершение ко всему здесь стал орудовать штейгер Коззл со своими людьми. Мне кажется, у них какой-то новый план. Сделай то, что не удалось мне, $n, – убей Коззла, возьми у него ключ и забери чертежи из его дома.', '', 'Штейгер Коззл прячется на вершине своей буровой вышки. У него есть ключ, что вам нужен.', 'Штейгер Коззл', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26353, 'ruRU', 'Спрятанное сокровище капитана Сандерса', 'Найдите сундучок капитана Сандерса и исследуйте его в поисках следующей подсказки.', 'Если ты читаешь это – стало быть, старина капитан Сандерс уже покоится на дне. Так что мое сокровище теперь может стать твоим, главное – следуй подсказкам.$B$BСначала найди мой сундучок. Его, должно быть, уже наполовину песком занесло, а находится он на западном побережье Западного Края, рядом с обломками корабля. Обломков-то там много, но ржавый якорь на берегу – только один. Найди этот якорь, и ты найдешь мой сундучок. Загляни внутрь за следующей подсказкой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26354, 'ruRU', 'Спрятанное сокровище капитана Сандерса', 'Найдите старый бочонок рядом с разрушенной трубой и исследуйте его в поисках следующей подсказки.', 'Записка гласит: \"Очень хорошо, дружище! А теперь иди строго на восток. Обойди с востока утесы. Поищи разрушенную старую трубу на обочине. Там будет старый бочонок со следующей подсказкой\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26355, 'ruRU', 'Спрятанное сокровище капитана Сандерса', 'Обыщите пустой кувшин рядом с мельницей в поисках следующей подсказки.', 'В бочонке вы находите клочок пергамента. На нем написано: \"А отсюда иди на север. Иди прямо и прямо, никуда не сворачивай, пока не увидишь пустой кувшин рядом с одинокой мельницей на прибрежных скалах. Пошаришь там – может, и найдешь то, что ищешь\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26356, 'ruRU', 'Спрятанное сокровище капитана Сандерса', 'Найдите сундук капитана Сандерса и откройте его, чтобы получить свою награду.', 'Конечно же, глубоко внутри старого кувшина лежит еще одна подсказка к поиску сокровища Сандерса. Чернила кое-где расплылись, а бумага отдает виски, но кое-что вам удалось разобрать: \"Раз уж ты нашел мой старый кувшин из-под виски, значит, ты близко подобрался к сокровищу! Иди от бутылки на запад и спустись к берегу. Доберешься до воды – не останавливайся! Плыви, пока не найдешь остров, где и находится мой сундук с сокровищем!\"', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26357, 'ruRU', 'Лики зла', 'Используйте факел тики, чтобы поджечь 8 ритуальных масок тики в Джинта\'Алоре.', 'Клан Порочной Ветви развесил маски тики по стенам крепости Джинта\'Алор. Но эти рожи недолго будут приглядывать за ними!$B$BВозьми факел, |3-6($c). Подожги маски, а я полюбуюсь, как сгорают их стражи и заклятья, а вместе с дымом растворяется черная магия вуду.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26358, 'ruRU', 'Готовность воздушных сил', 'Найдите Флип на ее свалке в Гавани Трюмных Вод в Азшаре.', 'Я лично гарантировал Адскому Крику, что на этой неделе его воздушный флот будет готов. Но на флагмане, \"Копье Дуротара\", до сих пор не установлены основные двигатели.$b$bФлип обещала новенькие блестящие двигатели еще на прошлой неделе. Отправляйся на ее свалку механизмов за банком и узнай, в чем причина задержки.$b$bВоздушный флот не ждет, $n!', '', '', '', '', '', 'Найдите Флип на ее свалке в Гавани Трюмных Вод в Азшаре.', 25549);
INSERT INTO `quest_template_locale` VALUES (26359, 'ruRU', 'Увидеть ящера', 'Поговорите со жрицей Ху\'ралой в Бамбале, что в Северной Тернистой долине, чтобы поучаствовать в ритуале внутреннего зрения.', 'У тебя есть перья, да.$B$BУ нас есть |3-6($c), да.$B$BПоговори со жрицей, когда будешь $gготов:готова;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26360, 'ruRU', 'Контроль над разумом', 'Добудьте большой мозг Брэддока, убив последнего в Зул\'Мамве.', 'Внутреннего зрения мало, да.$B$BКонтроль над разумом – эта магия мощнее, да.$B$BА для сильной магии нужны сильные реагенты. Например, мозг тролля – очень сильный реагент.$B$BБрэддок в Зул\'Мамве, он очень умный, да.$B$BИди на юг, найди Брэддока и вышиби из него большой мозг.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26361, 'ruRU', 'Самофланж Смута', 'Найдите где-то в Гавани Трюмных Вод Смута. Поймайте его и заберите индукционный самофланж.', 'Это капитан потребовал, чтобы в новых двигателях использовались индукционные самофланжи.$b$bА они тогда еще даже не были изобретены!$b$bЯ дала Смуту задание собрать один на основе украденных у Торговой Компании чертежей, и у него получилось создать работающую модель.$b$bЭто вскружило ему голову. Теперь он носится по всему городу с самофланжем наперевес, прямо рехнулся.$b$bПоймай Смута и отбери у него мой самофланж, $n.', '', 'Отыщите Смута где-то в Гавани Трюмных Вод.', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26362, 'ruRU', 'Стать ящером', 'Поговорите со жрицей Ху\'ралой, а потом помогите пойманному детенышу кнутохвоста сбежать из Зул\'Гуруба.', 'Контроль над разумом. Очень мощный, да.$B$BЕсли повезет, с твоей помощью Оган\'ака сбежит из Зул\'Гуруба.$B$BА потом Оган\'ака опять станет $n\'ака!$B$BПоговори со жрицей, да. И помоги $n\'ака сбежать.', '', 'В ловушке в Зул\'Гурубе', 'Оган\'ака', 'Вернулся из мертвых?', 'Мастер проклятий Джин\'до', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26363, 'ruRU', 'Судьбоносная вершина', 'Соберите 8 идолов-пауков, убивая троллей племени Порочной Ветви на вершине Джинта\'Алора.', 'Ты хорошо $gпостарался:постаралась;, сражаясь с их воинами, $n. Теперь я хочу, чтобы ты $gобследовал:обследовала; вершину Джинта\'Алора.$B$BМы подготовились к самой страшной битве, собирались снести их темный алтарь, но что-то там подозрительно тихо, ни звука не слыхать. Они могли устроить нам ловушку, поэтому вместо того, чтобы лезть туда всем сразу, я предпочту отправить кого-то одного, достаточно сильного.$B$BА если ловушки там нет... Что ж, тогда мне очень любопытно было бы узнать, что там у них стряслось. Принеси мне все улики, которые сможешь там найти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26364, 'ruRU', 'Долой Шестерямстера!', 'Победите Разло Шестерямстера. Когда будете готовы начать битву, поговорите с главным механиком Меггакрутом на Заледеневшем озере.', 'Наши друзья, дворфы Стальгорна, согласились помочь нам в битве против Разло Шестерямстера. Горный пехотинец Камнемол – это опытный боец, который хорошо знает Дун Морог. Он и главный механик Меггакрут находятся в полной готовности на небольшом покрытом снегом островке Заледеневшего озера, что к северу отсюда. Встреться там с ними и дай знать главному механику, когда будешь $gготов:готова; выступить против предателя Шестерямстера.$b$bВозьми это орбитальное прицельное устройство и используй его во время боя. Это поможет главному механику применить его спецоружие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26365, 'ruRU', 'Воззвание к героям: Красногорье!', 'Найдите капитана стражи Паркера в Часовой башне в Красногорье.', 'Здесь, конечно, дела идут ужасно, но в других частях этих земель начались сильные землетрясения из-за смещения земных пластов.$B$BМне тут пришел отчет от капитана стражи Паркера из Красногорья – это одна из наших территорий к востоку от Элвиннского леса. Он просит, чтобы мы прислали ему какого-нибудь героя на помощь.$B$BНо военных у нас так мало, что я даже не знаю, кого мы можем отправить туда. Может, ты сходишь к Паркеру и узнаешь, чего он хочет? Капитана стражи можно найти на вершине башни в Трех Углах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26366, 'ruRU', 'Все дело в голове', 'Убейте Умбоду \"Три Башки\" и заберите его голову.', 'Умбода из племени Порочной Ветви – один из самых сильных воинов и маньяк-убийца.$B$BОн забирает головы тех, кого убивает, и использует потом как побрякушки, трофеи... даже как оружие! Теперь пришло его время ответить за все!$B$BНайди Умбоду \"Три Башки\", убей его и принеси мне ЕГО голову! Посмотрим, как будет сражаться племя Порочной Ветви, когда мы кинем в них его башкой!', '', 'Принеси его голову. Среднюю.', 'Умбода \"Три башки\"', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26367, 'ruRU', 'Месть Онго\'лонго', 'Деритесь с Онго\'лонго, пока он не освободится.', 'Онго\'лонго был одним из нас. Его звали Свирепым троллем, но он был из племени Сломанного Клыка, он был смелым воином, как все мы!$B$BОн попал в плен к племени Порочной Ветви. Они заковали его в цепи в яме на вершине Джинта\'Алора и заставили его плясать для развлечения, извращенцы!$B$BЦепи не могут удержать Онго\'лонго. Надо только разозлить его как следует, $n. Дерись с ним, пока он не вспомнит, что он истинный воин, и не разорвет цепи... И тогда не вставай у него на пути!', '', 'Разозли его, а потом отойди!', 'Онго\'лонго', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26368, 'ruRU', 'Ядовитые секреты', 'Соберите 6 образцов яда Шадры с паучат Шадры в Джинта\'Алоре.', 'Если мы собрались вызывать Шадру, то надо будет собрать побольше этого любопытного яда.$B$BИ нечего на меня так смотреть... Отрекшимся уже доводилось изучать эти земли, и с ядовитой королевой мы встречались по меньшей мере разочек. Ее токсины весьма пригодились нам в прошлом...$B$BПригодятся они Орде и теперь. Так что сделай милость: собери, сколько сумеешь, яда с паучат Шадры – они живут в пещере на вершине... Думаю, ты по-любому перемажешься в нем с головы до ног.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26369, 'ruRU', 'Охота на хранительницу', 'Убейте Морта\'гью Хранительницу и заберите у нее табличку Шадры.', 'Котонга рассказал мне про Шадру. Это ядовитая королева, повелительница пауков, почитатели которой затаились во тьме. Если даже тролли из племени Порочной Ветви уже начали свои ритуалы, то закончить я им не дам.$B$BОбследуй пещеру на вершине Джинта\'Алора, сразу за алтарем. Я думаю, что там скрывается одна из хранительниц Шадры, так что убей ее и принеси мне ее вещи – так хоть будем знать, что там у них происходит.', '', 'Без сомнений, она будет прятаться в глубине пещеры.', 'Морта\'гья Хранительница', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26370, 'ruRU', 'Возвращение на Сторожевой холм', 'Доложите об увиденном маршалу Гриану Камнегриву в Сторожевой холм в Западном крае.', 'Мы не можем игнорировать Братство Справедливости, $n. То, что тебе удалось увидеть, – это возрождение безжалостной организации преступников, которая не остановится ни перед чем, лишь бы разнести Штормград в прах.$B$BВернись на Сторожевой холм и скажи Гриану, что я послал к нему войска. Надеюсь, еще не поздно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26371, 'ruRU', 'Легенда о капитане Грейсоне', 'Найдите капитана Грейсона на маяке Западного края.', 'Тебе приходилось слышать о капитане Грейсоне? Некоторые говорят, что это пьяный бред матроса, но любой в Западном крае скажет тебе, что Грейсон существует на самом деле! Он призрак, который блуждает по маяку Западного края далеко на западе, на Бескрайнем берегу.$B$BСлабо проверить?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26372, 'ruRU', 'Предполетная подготовка', 'Поговорите с капитаном Психхо в Гавани Трюмных Вод в Азшаре.', 'Новый двигатель очень быстрый. И опасный. Я бы сказала \"капризный\".$b$bЭто-то капитану и нравится.$b$bВозвращайся обратно на холм и передай ему, что я сейчас установлю эту штучку, и он должен встретиться со мной на верфи.', '', '', '', '', '', 'Поговорите с капитаном Психхо в Гавани Трюмных Вод в Азшаре.', 25549);
INSERT INTO `quest_template_locale` VALUES (26373, 'ruRU', 'На Каранос', 'Поговорите с капитаном Тарраном в Караносе.', 'Некоторые горные пехотинцы, находящиеся под командованием Камнемола, рассказывали мне о ситуации в Караносе. Когда трогги захватили форт Мерзлогривов, оставшиеся в живых тролли были вынуждены бежать в западном направлении, забираясь в самое сердце дворфийских земель.$b$bТеперь они создают угрозу для дворфийского города Караноса. Поэтому жителям Караноса пригодится любая помощь. Отправляйся в Каранос и найди капитана Таррана. Иди по дороге, ведущей на восток от Поселка Пивоваров, до тех пор, пока не увидишь город.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26374, 'ruRU', 'Готовность наземных сил', 'Обыщите Гавань Трюмных Вод и убедите 12 пехотинцев-дезертиров вернуться на службу.', 'Собирать войска в этом полном злачных мест гоблинском городе было плохой идеей. За деньги здесь можно предаться всем возможным порокам. Наши бывалые солдаты ведут себя безрассудно и просаживают в этом городе все заработанное в Нордсколе за годы.$b$bМожешь пробежаться по городу и собрать всех бойцов, которые ушли в самоволку?$b$bНа поле битвы мои закаленные воины не имеют себе равных, но я не хочу, чтобы они позорили честь мундира дезертирством.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26375, 'ruRU', 'Освободить скальчат', 'Воспользуйтесь крошечным сокрушителем цепей, чтобы освободить 6 кварцевых скальчат.', 'Сумеречные сектанты хватают моих скальчат. Мучают их, пытают. Высасывают саму их сущность, которая и отличает малышей от обычных камней.$b$bПожалуйста, |3-6($r), освободи скальчат. У нас с Диамантом не хватит аккуратности, чтобы разбить цепи, которыми их удерживают, не причинив скальчатам вреда. Но у нас есть инструмент, которым ты $gмог:могла; бы воспользоваться.$b$bВозьми это. Разбей цепи и освободи скальчат.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26376, 'ruRU', 'Глубоко проникающая ненависть', 'Убейте Драгула Громадоруба и 12 сектантов Сумеречного Молота у Врат Лортуны.', 'Я бы извинился за Бодена, но камень не пробьешь.$b$bТак быстро его не переубедишь.$b$bКаменные лорды, в том числе и мы с Боденом, занимаются поисками столпа мира.$b$bВот тут-то у нас и возникают разногласия.$b$bЯ испытаю на тебе свое терпение, |3-6($r).$b$bДокажи, что ты не заодно с Сумеречным Молотом или Смертокрылом...$b$bОбрушь на них нашу ненависть.$b$bНанеси им удар там, где этого не можем мы.$b$bТогда я тебя выслушаю.', '', 'Лидер сил у врат Лортуны.', 'Драгул Громадоруб', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26377, 'ruRU', 'Нетвердая земля', 'Соберите 6 друз нефритовых кристаллов, совместите их, а затем разбейте в лагере Врат Лортуны.', 'Сектанты Сумеречного Молота собирают кристаллы нефритов возле своего лагеря.$b$bГлупые...$b$bБезрассудные...$b$bСобирать ископаемые кристаллы. Приносить их в лагерь. Разбивать их о землю.$b$bОни привлекут проходчиков.$b$bОни научатся уважать землю...$b$bЧасть за частью...$b$bКамень за камнем...$b$b...со временем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26378, 'ruRU', 'Воззвание к героям: Западный Край!', 'Поговорите с лейтенантом Горацио Лейном во Владении Янсена в Западном Крае.', 'Для Западного края настали тяжкие времена, друг. Когда угроза от Братства Справедливости исчезла, этот край стал прибежищем для бездомных и отчаявшихся. Уровень преступности в этом краю повысился, поскольку люди начали драться за кров и еду. А теперь еще и убийство!$B$BЕсли тебе хочется помочь людям Альянса, начни с Западного края. Доложись лейтенанту Горацио Лейну во владении Янсена. Мост в Западный край находится на западе Элвинского леса.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26380, 'ruRU', 'На пути в Каранос', 'Отнесите бочонки с элем на пробу хозяину таверны \"Громоварка\" Белму.', 'Мне нужно было отнести эти бочонки с элем в трактир в Караносе. Это новый загадочный эль, который производит недавно открывшаяся и быстро достигшая успеха пивоварня в Поселке Пивоваров. Как только я вышла из города, меня атаковала группа налетчиков из клана Мерзлогривов. Мне теперь долго придется ремонтировать свою телегу!$b$bЯ не очень-то рассчитываю, что ты сделаешь мне одолжение... или сделаешь? Эти большие бочки не сдвинешь, но у меня есть и маленькие бочонки с элем на пробу. Не отнесешь ли ты их в Каранос? Просто иди по дороге на юго-восток.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26381, 'ruRU', 'Глаз Шадры', 'Принесите глаз Шадры из Агол\'ваты.', 'Шадру обязательно надо призвать. Упускать такую возможность было бы глупо. Аптекари могут найти достойное применение яду богини, но в ритуалах они полные профаны.$B$BПо счастью, я знаком с призыванием богов. Принеси мне останки Шадры, а я помогу тебе вызвать ее в наш мир.$B$BПервая часть – это глаз Шадры, его хранят в Агол\'ватe к северу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26382, 'ruRU', 'Без яиц яичницу не сделаешь...', 'Соберите 5 яиц порождения Шадры в Агол\'вате.', 'Марнал уже много дней надоедает мне своим планом про эту Шадру. Я даже почти расстроилась, когда узнала, что он действительно нашел эту табличку, уже надеялась, что он заткнется на эту тему.$B$BНо несмотря на его высокомерные отзывы о ритуальной магии, он все еще нужен мне – как и я ему. Мне надо будет смешать основную среду с аналогичным...$B$B...Знаешь что, не хочу утомлять тебя подробностями. Просто иди в Агол\'вату и принеси мне яйца ядоплюя. Их охраняют тролли племени Порочной Ветви.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26383, 'ruRU', 'Ветра перемен', 'Воспользуйтесь телепортационным деревом в западном Дарнасе, чтобы добраться до деревни Рут\'теран, после чего побеседуйте с Веспристом, который отправит вас в Лор\'данел.', 'Ты! Да, я к тебе обращаюсь! Мне кажется, или ты хочешь нам помочь?$B$BАубердин пал, и хотя большинство жителей покинули его стены еще во время первых проявлений Катаклизма, многие упрямцы все отказывались от эвакуации до последнего. А теперь город захвачен элементалями воды.$B$BМои сестры помогают спасать выживших, и им срочно нужна помощь. Пожалуйста, воспользуйся западным деревом, чтобы добраться до Рут\'Терана, а там поговори с Веспристом, пусть он как можно скорее отправит тебя в Лор\'данел. Не медли ни минуты!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26384, 'ruRU', 'Темный священник Марнал', 'Принесите табличку Шадры темному священнику Марналу.', 'Нельзя просто так выкидывать эту табличку, $n. Ее можно использовать...$B$BВидишь ли, я разбираюсь с паучьим ядом. Он явно магический и связан с паучьим богом, которому поклоняются тролли. А если эта табличка позволяет его призвать...$B$BВот видишь, куда я клоню, да? Орда не может упустить такую возможность. Отнеси эту табличку к Отрекшимся. Иди на запад к исследовательской станции в руинах Хири\'ваты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26385, 'ruRU', 'Ветра перемен', 'Поговорите с Веспристом в деревне Рут\'теран, чтобы обеспечить безопасный проезд в Лор\'данел.', 'А вот и твое первое задание. Ты $gдолжен:должна; вернуться в деревню Рут\'теран, где мы впервые встретились, и поговорить с Веспристом, который может обеспечить тебе безопасный проезд в Лор\'данел.$B$BКак только прибудешь на место, окажи ночным эльфам всю возможную помощь. Могу ли я рассчитывать на то, что ты отнесешься к ним с должным уважением в свете всего того, что они сделали для нас?$B$BМне же придется отправиться в далекий город Штормград, чтобы встретиться с королем Андуином. Надеюсь, мы скоро увидимся, $n. Доброго пути.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26386, 'ruRU', 'Сурхан', 'Поговорите с Сурханом в Бамбале, что в Северной Тернистой долине.', 'Жрица не очень хорошо орочий понимает, да.$B$BМожет, лучше поговорить с Сурханом, он вон в той палатке.$B$BРасскажи ему, что ты $gвидел:видела; в Зул\'Гурубе, да.', '', '', '', '', '', 'Поговорите с Сурханом в Бамбале, что в Северной Тернистой долине.', 25549);
INSERT INTO `quest_template_locale` VALUES (26387, 'ruRU', 'На голодном пайке', 'Уничтожьте 6 оплетенных жертв в Ползучих руинах.', 'Пауки, живущие на востоке Ползучих руин, бесполезны. Мы зовем их ядоплюями, и ясно, что они как-то связаны с паучьм богом, но это не меняет того факта, что от них больше вреда, чем пользы. Будь на то моя воля, я бы избавилась от них раз и навсегда.$B$BКогда пойдешь в Ползучие руины, уничтожай все коконы, которые найдешь. Они ими питаются, поэтому лишить их еды намного эффективнее, чем пытаться перебить по одному.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26388, 'ruRU', 'Сумеречные небеса', 'Сопроводите воздушный флот Орды к Сумеречному нагорью. Воспользуйтесь дирижаблем, улетающим от южной конечной станции ракетной дороги в Азшаре.', 'Отлично, ты $gприбыл:прибыла;. Подожди здесь прибытия дирижабля капитана Психхо, а затем поднимайся на борт и сопровождай воздушный флот. Адмирал Каменный Кулак будет ждать тебя у порта Драконьей Пасти!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26389, 'ruRU', 'Вторжение клана Черной горы', 'Раздобудьте 8 образцов оружия орков Черной горы.', 'Орки начали сжигать лес, $n! Они захватили виноградник на востоке и сейчас планируют нападение на Штормград! Их нужно остановить!$B$BОтправляйся на восток, на ту сторону реки, и расправься с буйствующими там орками Черной горы. В качестве доказательства того, что с ними покончено, принеси мне орочье оружие.$B$BТы наша единственная надежда, $n!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26390, 'ruRU', 'Оккупанты – вон!', 'Убейте Куртока Душегуба.', 'Орду орков возглавляет свирепая тварь по имени Курток Душегуб. Именно Курток стоит за недавним вторжением, и его необходимо уничтожить – только после этого в долине воцарится мир!$B$BОтправляйся назад, на восток, переправься через реку, пройди виноградник и отыщи тропу, ведущую в горы. Где-то там Курток планирует очередное нападение. Убей его и возвращайся.', '', 'Курток скрывается в дыме и пламени на востоке.', 'Курток Душегуб', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26391, 'ruRU', 'Еще есть надежда', 'Воспользуйтесь огнетушителем Милли, чтобы погасить 8 очагов возгорания на винограднике.', 'В такие времена начинаешь поневоле скучать по Братству Справедливости. Катаклизм открыл проход в Пылающие степи, и теперь долину Североземья наводняют орки из клана Черной горы! Они захватили мой виноградник и хотят сжечь его дотла! ДОТЛА!$B$BПожалуйста, $n, помоги. Этот виноградник – все, что у меня осталось. Возьми мой огнетушитель и потуши пожар на винограднике. Быть может, не все еще потеряно для этой земли!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26393, 'ruRU', 'Срочное сообщение', 'Отнесите записку Аргуса укротителю грифонов Бартлетту Храбрецу.', 'Хотя явно Штормград и не оказывает нам большой помощи, в городе у меня есть знакомый, который снабжает нас оружием. Его зовут Озрик Штранг. Он держит магазин под названием \"Ограниченная неуязвимость\" в Старом городе Штормграда.$b$bНаши запасы оружия подходят к концу, и пора снова обратиться к Озрику. Не отнесешь ему это письмо?$b$bДоберешься быстрее всего, если обратишься к Бартлетту Храбрецу, нашему укротителю грифонов. Найдешь его сразу за кузней. Отнеси ему мою записку и отправляйся на грифоне в Штормград.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26394, 'ruRU', 'Полет в Штормград', 'Заплатите за полет укротителю грифонов Бартлетту Храбрецу, затем доставьте записку Аргуса Озрику Штрангу в магазин \"Ограниченная неуязвимость\" в Старом городе Штормграда.', 'За небольшую плату ты можешь нанять грифона и доставить Озрику записку Аргуса. Нет способа добраться туда быстрее.$b$bЕсли это тебе подходит, вернись ко мне, когда будешь $gготов:готова; к полету. Я, конечно, возьму с тебя немного денег, но поверь, оно того стоит!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26395, 'ruRU', 'Дунгар Долгопив', 'Отнесите ящик Озрика укротителю грифонов Дунгару Долгопиву.', '$n, в этом ящике все, что просил Аргус. Доставите это ему?$b$bЕсли вы уже поговорили в Златоземье с Бартлеттом, то можете вернуться к нему на грифоне. В Торговом квартале вы найдете Дунгара Долгопива, это наш укротитель грифонов.$b$bПоговорите с Дунгаром, а затем как можно быстрее доставьте ящик Аргусу. Нельзя оставлять без оружия наших бойцов в Златоземье!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26396, 'ruRU', 'Возвращение к Аргусу', 'Заплатите за полет укротителю грифонов Дунгару Долгопиву, затем доставьте ящик Озрика кузнецу Аргусу в Златоземье.', 'В Златоземье укротитель грифонов – Бартлетт. Если ты с ним уже $gзнаком:знакома;, ты можешь вернуться туда на одном из моих грифонов.$b$bЭто стоит знать: летать в столицу обучают всех грифонов. Но доставить тебя к какому-то из отдаленных укротителей грифонов он может только в том случае, если ты там уже $gбыл:была;.$b$bТы уже $gбыл:была; у Бартлетта, так что просто скажи мне, когда будешь $gготов:готова; отправиться на грифоне в Златоземье. Там ты сможешь доставить кузнецу Аргусу ящик Озрика.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26397, 'ruRU', 'Да хранит тебя Мать-Земля', 'Отнесите знак Кровавого Копыта верховному правителю Саурфангу в крепость Громмаш в Оргриммаре.$B$BЧтобы отправиться туда, вы можете либо поговорить с укротителем ветрокрылов Талом, либо дождаться дирижабля.', 'Многое изменилось за пределами Мулгора, $n. Мир разрывается на части, а наши союзники из Орды выбрали неверную дорогу. Нам придется наставить их на путь истинный. Даже в самый темный час мы будем смелы и горды и будем выражать наше почтение Матери-Земле во всем, что мы делаем.$B$BТы $gдолжен:должна; идти, $n, и подать пример остальным. Отправляйся в Оргриммар. Расскажи Саурфангу об изгнании клана Зловещего Тотема. Пусть он узнает о нашем достоинстве и нашей дисциплине, о нашей смелости и нашей боли.$b$bТал на Небесной Башне подскажет тебе дорогу. Ступай с миром и никогда не забывай о своем народе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26399, 'ruRU', 'Сокровища клана Мош\'Огг', 'Добудьте сокровища клана Мош\'Огг в руинах за холмом Мош\'Огг.', 'А ты $gслыхал:слыхала; про огров? Один парень по имени Мок\'тардин говорил, что $gкакой-то уродец:какая-то лахудра:r; |3-6($r), $gодетый как:одетая как:c; |3-6($c), $gнашел:нашла; руку огра и...$B$B<Скизи оглядывает вас и замолкает.>$B$BО чем это я? Ах да! $GКакой-то ВЕЛИЧАЙШИЙ ГЕРОЙ нашел:какая-то ПРЕКРАСНЕЙШАЯ ГЕРОИНЯ нашла; руку огра, а по мнению Мок\'тардина это значит, что у огров есть особый артефакт. Я видел, что они охраняют какой-то сундук в руинах, в своем жилище. Может, сбегаешь да посмотришь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26400, 'ruRU', 'Универсальный ключ', 'Откройте сокровищае клана Мош\'Огг, сразившись с крошшером Торговой Компании или при помощи лезвия циркулярной пилы на лесопилке Торговой Компании.', 'Даже твои крепенькие ручонки это не откроют, |3-6($r), тут нужно что-то посильнее. И, сдается, нужная вещь есть у недоумков из Торговой Компании, которые ошиваются к северо-западу отсюда.$B$BКогда я был там в последний раз, видел шагающих крошшеров, с приделанными к рукам огромными лезвиями. Только такими мы и сможем открыть эту коробку!$B$BА если не найдешь крошшеров, попробуй открыть коробку гигантской циркулярной пилой с их лесорубки, она около озера.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26401, 'ruRU', 'Вернуться к Вестии', 'Отнесите амулет Мглистой пещеры Вестии Лунное Копье в башню Эстулана.', 'Мягкий свет пьедестала становится ярче, и на нем оказывается простая цепочка. Это и есть то, что было нужно ученице?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26402, 'ruRU', 'Генерал Шандриса Оперенная Луна', 'Поговорите с Шандрисой Оперенной Луной в Крепости Оперенной луны в Фераласе.', 'Мы, друиды, обычно держимся в стороне от Армии Часовых, но на защиту наших земель выступили единым фронтом. После того как ты $gпомог:помогла мне;, я хочу попросить тебя оказать помощь также и им.$B$BШандриса Оперенная Луна, генерал Часовых, командует армией, набранной со всего Калимдора; найти ее можно в недавно отстроенной крепости Оперенной Луны к югу отсюда. Скажи ей, что тебя послал я, и думаю, она найдет тебе дело.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26403, 'ruRU', 'Рудник Торговой Компании', 'Принесите 5 упавших кристаллов Скизи Крюкоуху в Бамбалу, что в Северной Тернистой долине.', 'Ненавижу эту Торговую Компанию! Оплела своими щупальцами всю Тернистую долину и не дает трудолюбивым гоблинам вроде меня честно зарабатывать!$B$BИ что мне делать? Воровать! Геологи Торговой Компании у озера Назферити, что к северо-западу отсюда, очень интересуются странными синими кристаллами, которые попадались им в шахтах. Отбери образцы у геологов, а как ты это сделаешь – мне все равно!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26404, 'ruRU', 'Работенка уровнем повыше', 'Отрапортуйте Хамми Кофельнагель в Укрытии Кофельнагель на мысе Тернистой долины.', 'Слушай, а ты $gбывал:бывала; в Укрытии Кофельнагель? О, да ты просто $gОБЯЗАН:ОБЯЗАНА; там побывать. Там есть все, что нужно гоблину.$B$BСлушай-ка... Ты вроде |3-6($c) что надо. Расха – вон она, в куртке и юбке, – может тебя туда подбросить, если ты еще не знаешь дорогу.$B$BЯ оплачу полет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26405, 'ruRU', 'Пляски Зул\'Мамве', 'Убейте 16 троллей из племени Дробителей Черепов в Зул\'Мамве.', 'Дробители Черепов – сущая напасть для всей империи троллей. Их грызня с Кровавыми Скальпами расколола северную Тернистую долину. Там, где процветают племена Черного Копья и зандалары, Дробители Черепов сражаются за руины.$B$BМне поручено нанять бойцов, способных покарать этих Дробителей Черепов. Я призываю тебя и тех, кого ты знаешь, отправиться на юг в Зул\'Мамве и приструнить воинственное племя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26406, 'ruRU', 'Зуб Шадры', 'Найдите зуб Шадры в Ползучих руинах.', 'Теперь нам потребуется зуб Шадры.$B$BОн находится в Ползучих руинах к востоку отсюда, и охраняют его дети самой Шадры. Это премерзкие пауки размером с дворфа, и вдвое сильнее. А еще они очень ядовиты, $n... так что осторожнее.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26407, 'ruRU', 'Ручная работа Мош\'Огга', 'Принесите искалеченную руку огра клана Мош\'Огг провозвестнику Мок\'тардину в лагерь Гром\'Гол, что в Северной Тернистой долине.', 'У этого огра при себе оказался необычный предмет – оторванная рука другого огра на веревочке, чтобы носить на шее. Сама рука вся была в шрамах, светящихся слабым фиолетовым цветом.$B$BСветящиеся после смерти шрамы встречаются редко, а уж увидеть такой предмет у огра странно вдвойне. Может, в Гром\'голе кто подскажет, что делать с подобной штуковиной.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26408, 'ruRU', 'Пепел и ясень', 'Поговорите с часовым Шейлой в Укрытии Орендила, что в Ясеневом лесу.', 'Темные берега лежат в руинах, но благодаря тебе мы обрели более-менее безопасное укрытие. Правда, нам предстоит еще многое здесь отстроить...$B$BПродолжай в том же духе, друг мой. Гаррош обрушил на нас всю мощь Орды; они перебьют нас и сровняют лес с землей, если мы их не остановим.$B$BЕсли у нас есть хоть малейшая надежда спасти эти деревья от уничтожения, твой долг помочь нам. Следуй по дороге на юг и отыщи часового Шейлу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26409, 'ruRU', 'Где Клондацк?', 'Найдите посвященного Клондацка в Кварцитовой впадине, что в Подземье.', 'Мой посвященный гоблин ушел некоторое время назад. Его зовут Клондацк.$b$bЯ отправила его наблюдать за камнедерами к юго-западу от Кварцитовой впадины. Может быть, ты $gмог:могла; бы разыскать его? А когда сделаешь это, пожалуйста, попроси его вернуться обратно в Храм.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26410, 'ruRU', 'Заживляющее взрывчатое вещество', 'Соберите 5 порций кварцитовой смолы.', 'Этот парень – сын предводителя земельников! Он уже почти было добрался до Храма, когда на него напала стая камнедеров. Их было больше, чем я мог сосчитать!$b$bМы знаем, что центральный фрагмент столпа мира находится у Отца-Скалы. Может быть, если мы вылечим его сына, король отдаст нам фрагмент?$b$bМои снадобья Флинту не помогут. Но если нам удастся достать кварцитовую смолу, думаю, я смогу сделать заживляющее взрывчатое вещество, которое прижжет и исцелит его раны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26411, 'ruRU', 'Приложить и прижечь', 'Воспользуйтесь заживляющим взрывчатым веществом, чтобы вылечить Флинта Железную Мантию.', 'Ну вот, приложи это вещество к его ранам. Если он сможет пережить прижигающий эффект заживляющего взрывчатого вещества, то излечится.$b$bДумаю так.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26413, 'ruRU', 'Отведи его к заклинательнице земли', 'Представьте Флинта Железную Мантию заклинательнице земли Еве в Храме Земли.', 'Он по-прежнему производит на меня впечатление чокнутого. В голове у него до сих пор должно звенеть.$b$bЛучше всего отвести его в Храм, может быть, заклинательница земли сможет что-то сделать для него.$b$bА я останусь здесь еще ненадолго и \"понаблюдаю\" за этими камнедерами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26414, 'ruRU', 'Ловля светлоперого судака', 'Катрин Лиланд в Штормграде просит вас принести ей 8 задеревенелых светлоперых судаков.', 'Иногда я рыбачу просто для удовольствия. Обычно чтобы расслабиться, иногда – чтобы размяться. А для этого лучше всего подходит задеревенелый светлоперый судак. Эту рыбу ловят не для готовки, а чтобы показать свое мастерство. Светлоперый судак водится в Штормградском озере к северу от города. Ну что, попытаешь счастья?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26415, 'ruRU', 'Questflag for Captain\'s Log', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (26416, 'ruRU', 'Вперед, в джунгли!', 'Разыщите Борта в Оргриммаре.', 'Командир отправил меня на поиски рекрутов, которые могли бы помочь в обороне лагеря Гром\'гол в Северной Тернистой долине. Ты знаешь, где это? Далеко-далеко, за Великим морем, на самом востоке Восточных королевств. Ты, кстати, вполне подходишь под описание наемника... Не хочешь ли на время покинуть эти края?$b$bЕсли да, то поговори с моим напарником Бортом в Оргриммаре. Он посадит тебя на дирижабль.$b$bДа, и передай ему пару слов от меня: \"Воззль воззль\". Именно так; он знает, о чем идет речь.', '', '', '', '', '', 'Разыщите Борта в Оргриммаре.', 25549);
INSERT INTO `quest_template_locale` VALUES (26417, 'ruRU', 'Северная Тернистая долина: павшая империя', 'Явитесь с докладом к командиру Аггро\'гошу в лагерь Гром\'гол в Северной Тернистой долине.', 'Командующий Аггро\'гош ищет преданных воинов Орды для выполнения задания в Гром\'голе. Если ты $gготов:готова;, взбирайся на башню дирижаблей и садись в дирижабль до Гром\'гола. Да, все легче легкого!$B$BКроме шуток, в Тернистой долине сейчас есть чем заняться... там много чего творится, а катаклизм не так набедокурил, как, скажем... в Когтистых горах. Жаль, не могу с тобой пойти.', '', '', '', '', '', 'Явитесь с докладом к командиру Аггро\'гошу в лагерь Гром\'гол в Северной Тернистой долине.', 25549);
INSERT INTO `quest_template_locale` VALUES (26418, 'ruRU', 'Панцирь Шадры', 'Убейте Квиагу Хранительницу и заберите панцирь Шадры.', 'Надо добыть еще одну часть, и тогда у нас будет все необходимое.$B$BПанцирь Шадры хранится у последней ее верховной жрицы, Квиаги Хранительницы. Она стоит на вершине алтаря Зула, и ее охраняют ревнители-фанатики.$B$BВсе просто и ясно, да? Поднимись на вершину алтаря и отсеки ей голову. А потом принеси мне панцирь, и мы наконец-то сможем призвать Шадру.', '', 'Квиага – преданная ученица Шадры. Она не расстанется с панцирем без боя.', 'Квиага Хранительница', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26419, 'ruRU', 'Шадра – королева пауков', 'Убейте Шадру – королеву пауков.', '<Земля начинает трястись, а озеро – волноваться, когда идол оказывается на алтаре. Шадра приходит в этот мир!>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26420, 'ruRU', 'Накопаем червей', 'Отыщите земляного червя-переростка возле Пруда Оливии и поймайте на эту наживку хрустального окуня. Хрустальный окунь водится в Пруду Оливии к северу от Штормграда.', 'Рыбакам привет! Мне тут Арнольд сказал, ты ищешь рыбное место, могу присоветовать. К северу от Штормграда есть прекрасное местечко – Пруд Оливии.$B$BВ пруду круглый год видимо-невидимо хрустального окуня, но поймать его не так-то просто. Он клюет только на особую приманку... земляных червей-переростков. Поищи на берегу возле пруда – там вдосталь этой наживки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26421, 'ruRU', 'Встретиться с главным механиком', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 'Не знаю, помнишь ли ты Меггакрута. Невин говорит, что многие выжившие из Гномрегана страдают потерей памяти.$b$bМеггакрут или, более официально, главный механик Меггакрут – предводитель всех гномов. Он взял за правило лично встречаться со всеми, кому удалось остаться в живых. Тебе следует представиться Меггакруту. Его вместе с его военным консулом можно найти в шатре в центре города.', '', '', '', '', '', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 25549);
INSERT INTO `quest_template_locale` VALUES (26422, 'ruRU', 'Встретиться с главным механиком', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 'Не знаю, помнишь ли ты Меггакрута. Невин говорит, что многие выжившие из Гномрегана страдают потерей памяти.$b$bМеггакрут или, более официально, главный механик Меггакрут – предводитель всех гномов. Он взял за правило лично встречаться со всеми, кому удалось остаться в живых. Тебе следует представиться Меггакруту. Его вместе с его военным консулом можно найти в шатре в центре города.', '', '', '', '', '', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 25549);
INSERT INTO `quest_template_locale` VALUES (26423, 'ruRU', 'Встретиться с главным механиком', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 'Не знаю, вспомнишь ли ты Меггакрута. Невин говорит, что многие выжившие из Гномрегана страдают потерей памяти.$b$bМеггакрут или, более официально, главный механик Меггакрут – предводитель всех гномов. Он взял за правило лично встречаться со всеми, кому удалось остаться в живых. Тебе следует представиться Меггакруту. Его вместе с его военным консулом можно найти в шатре в центре города.', '', '', '', '', '', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 25549);
INSERT INTO `quest_template_locale` VALUES (26424, 'ruRU', 'Встретиться с главным механиком', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 'Не знаю, помнишь ли ты Меггакрута. Невин говорит, что многие выжившие Гномрегана страдают потерей памяти.$b$bМеггакрут или, более официально, главный механик Меггакрут – предводитель всех гномов. Он взял за правило лично встречаться со всеми, кому удалось спастись. Тебе следует представиться ему. Он вместе со своим военным советником находится в шатре в центре города.', '', '', '', '', '', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 25549);
INSERT INTO `quest_template_locale` VALUES (26425, 'ruRU', 'Встретиться с главным механиком', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 'Не знаю, вспомнишь ли ты Меггакрута. Невин говорит, что многие выжившие из Гномрегана страдают потерей памяти.$b$bМеггакрут или, более официально, главный механик Меггакрут – предводитель всех гномов. Он взял за правило лично встречаться со всеми, кому удалось остаться в живых. Тебе следует представиться Меггакруту. Его вместе с его военным консулом можно найти в шатре в центре города.', '', '', '', '', '', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 25549);
INSERT INTO `quest_template_locale` VALUES (26426, 'ruRU', 'Жестокий ветер', 'Найдите Фелсена Выносливого и следуйте его указаниям, чтобы добраться до входа в Гремящие глубины.', 'Есть одно дело, которое я могу поручить тебе.$b$bОпасное дело. Но если ты с ним справишься, это поможет произвести впечатление на самых упрямых каменных лордов.$b$bК северо-западу отсюда находится Изъеденный овраг. Свирепые ветра разбивают тамошние скалы, скрывая под ними настоящую угрозу.$b$bНа Размытом берегу водятся червинты. Они пожирают камни и двигаются сквозь них, как сквозь воду. И с нашей каменной кожей они могут поступить так же.$b$bРазыщи Фелсена Выносливого. Пусть он направит тебя в Гремящие глубины. Когда доберешься туда, я поговорю с тобой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26427, 'ruRU', 'Ни команды, ни капитана', 'Принесите первому помощнику Мади бутылку виски и моток веревки.', 'Не знаю, на чьей ты стороне, но ты не выглядишь, как $gодин:одна; из... них.$b$bЯ не очень хорошо понимаю, что произошло. Я проспал ужин, а когда проснулся, на корабле было полно мертвецов и убийц.$b$bНе знаю, собираешься ли ты убить меня, но я не буду создавать тебе проблем.$b$b<Мади показывает на рану в животе. Его внутренности не на месте.>$b$bЯ больше не могу управлять кораблем. От ранения в живот моментально не умирают. Принеси мне веревок и немного рома... нет, виски.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26428, 'ruRU', 'Грабь награбленное', 'Добудьте головы Кенаты Дабири, Фарбела Дабири и Марселя Дабири.', 'Воровка! Свинья! Кената все еще жива, ее семья живет и процветает, а я страдаю. Вот уж действительно Отрекшаяся!$B$BВсю мою семью забрала чума. Все наше имение тоже разорили во время войны. А теперь она и ее мерзкие дети имели наглость похитить у меня последние ценные вещи.$B$BСами вещи мне уже не нужны. Теперь я жажду мести!$B$BУбей этих проходимцев! Ступай в усадьбу Дабири в Арати, это на северо-востоке от Опорного пункта.', '', 'Она заплатит своей головой!', 'Кената Дабири', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26429, 'ruRU', 'Сокрушить Сухокожих', 'Убейте 10 метателей топоров из племени Сухокожих, 10 охотников за головами из племени Сухокожих и 8 знахарей из племени Сухокожих.', 'Тролли из племени Сухокожих и огры из клана Тяжелого Кулака объединились, чтобы изгнать нас из этих земель, но мы не собираемся подчиняться ни им, ни кому-то другому. Мы убьем их и тем самым покажем им, что здесь и наш дом тоже.$b$bТролли от нас бежали. Огры были бы рады сожрать нас и спать на наших шкурах, если бы мы им только позволили, – но этому не бывать.$b$bМы атакуем троллей из племени Сухокожих к югу отсюда. Убей их столько, сколько сможешь, и возвращайся только тогда, когда их поселения будут залиты кровью.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26430, 'ruRU', 'Деревня Сломанного Клыка', 'Отправляйтесь в деревню Сломанного Клыка во Внутренних Землях и поговорите со старейшиной Сломанным Клыком.', 'Не все лесные тролли такие же отвратительные создания, как Сухокожие. К северу отсюда во Внутренних землях находится деревня Сломанного Клыка, там живет единственное племя лесных троллей, сохраняющее союз с Ордой.$b$bНо даже они не избежали жестокости своих собратьев. Племя Порочной Ветви нападает на них и мешает тем самым участвовать в наших битвах с Альянсом.$b$bТы здесь отлично $gзарекомендовал:зарекомендовала; себя. Если хочешь отправиться в деревню Сломанного Клыка, поговори с Урдой. Деревне не помешает твоя сила.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26432, 'ruRU', 'Падение Джинта\'Алора', 'Найдите старейшину племени Сломанного Клыка у Джинта\'Алора во Внутренних землях.', 'Нам не только дворфы мешают, $gбратишка:сестренка;. Я присматриваю за деревней, а моя подруга, старейшина племени Сломанного Клыка, повела наших воинов против племени Порочной Ветви.$B$BОни убили наших братьев, а меня даже в плен забрали! Такое не должно повториться! На этот раз Джинта\'Алор падет под нашим натиском.$B$BИди в Джинта\'Алор и поговори с моей подругой. Она в лагере возле входа в город.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26433, 'ruRU', 'Святая вода ясности', 'Наберите святой воды ясности из родника Нек\'мани на мысе Тернистой долины.', 'Скизи предупредил меня о твоем приходе. Ладно, сейчас посмотрим, что ты тут $gнашел:нашла;.$B$BДля начала мне нужно, чтобы ты $gдобыл:добыла; святую воду ясности. На юго-востоке от нас находится святилище наг, в котором святая вода столь чиста, свежа и сладка на вкус, что когда делаешь хоть глоточек, ум проясняется и становится виден путь.$B$BПравда, здорово?$B$BНабери ее в роднике Нек\'мани у подножия горы в лагере наг. Удачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26434, 'ruRU', 'Изначальные реагенты силы', 'Добудьте 4 мягкие тигриные шкуры и 4 бархатистые шкуры пантеры.', 'Теперь все понятно... чтобы распознать этот таинственный талисман, нужно получить некие редкие и ценные предметы. Эти изначальные реагенты силы, собранные вместе, откроют нам происхождение сокровища.$b$bОтправляйся на север, к западной части арены Гурубаши, и поохоться на кошек, которые рыщут в джунглях. Их пушистые шкурки помогут нам узнать правду!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26435, 'ruRU', 'Лжец и отпетый мошенник', 'Отнесите открытый сундук сокровищ клана Мош\'Огг Гарли Легкой Наезднице в Пиратскую Бухту у мыса Тернистой долины.', 'Понятия не имею, что это такое. Даже больше скажу – не представляю, где это можно узнать!$B$BИ вообще – почему именно ко мне обратились с этим вопросом?$B$BМне хотелось пить, я попросил воды. А потом поинтересовался драгоценностями и мехами для... для своей девушки.$B$BОднако я, по крайней мере, могу указать вам, в каком направлении двигаться. Гарли Легкая Наездница из Пиратской Бухты работает в Реликварии. Может, чем и пособит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26436, 'ruRU', 'Вросший в землю', 'Разыщите Кора Невозмутимого в Дрожащих Вершинах.', 'Похоже, что твои намерения честны.$b$bЯ сообщу остальным каменным лордам о том, что ты заслуживаешь некоторого доверия.$b$bПосле этого они поговорят с тобой.$b$bИ, что важнее, они тебя выслушают.$b$bНа то, чтобы добиться их расположения, может потребоваться время. Но не жалей времени, эта жертва того стоит.$b$bДалеко на северо-западе, в Дрожащих Вершинах ты найдешь Кора Невозмутимого. У него тихий нрав. Ситуация, в которую он попал, заставляет его прибегать к посторонней помощи.$b$bИди к нему.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26437, 'ruRU', 'Кристальная чистота', 'Соберите 8 меловых кристалловидных образований.', 'В Дрожащих Вершинах есть кристаллы. Белые, меловые кристаллы. Мы втираем их в кожу. Для очищения.$b$bЯ больше не могу шагать по горам. Я стал единым целым с землей. В этом много преимуществ, но теперь я больше не могу добывать для себя эти кристаллы.$b$bПринеси их мне, я стану сильнее. Береги кристаллы от камнедеров. И от моих сыновей. Они должны быть только для меня.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26438, 'ruRU', 'Угроза', 'Убейте 12 яшмоголовых камнедеров.', 'Камнедеры беснуются от голода. Раньше они тихо и спокойно рылись в земле. Теперь им не утолить свой голод. Они стали смертельно опасными.$b$bКамнедеры атакуют моих сыновей. Набрасываются на них. Убивают их. Это нужно прекратить.$b$bУбей камнедеров. Земле от них никакой пользы. Никто и не заметит, если они исчезнут. Спаси моих сыновей. Уничтожай всех камнедеров, какие тебе встретятся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26439, 'ruRU', 'Сформировать заново', 'Помогите 6 спящим каменным элементалям заново сформироваться.', '$R. Если ты действуешь по поручению каменных лордов, то найдутся те, кто может помочь тебе.$b$bНайди каменных элементалей. Они спят повсюду в Дрожащих Вершинах. Не должно составить труда сделать так, чтобы они начали бороться с камнедерами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26440, 'ruRU', 'Приставучий', 'Отведите Камешка к большому скоплению кристаллов в Дрожащих Вершинах.', '<Похоже, вы понравились одному крошечному элементалю.>$b$bКарис... карстр... кристалл?<Камешек выжидательно смотрит на вас.>$b$b<Вы действительно видели большие скопления кристаллов в Дрожащих Вершинах. Может быть, надо отвести его туда?>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26441, 'ruRU', 'Такой большой, такой круглый...', 'Поговорите с Кором, чтобы узнать, чем можно накормить Камешка.', '<Чем-то взволнованный, Камешек озирается по сторонам. После нескольких секунд замешательства он останавливает на вас взгляд своих больших сияющих глаз-самоцветов.>$b$bГоло... голодный...$b$b<Он так смотрит, что невозможно оставаться $gравнодушным:равнодушной;. Может быть, Кор знает, что любят есть такие маленькие элементали?>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26442, 'ruRU', 'Скальный омар', 'Соберите 6 скальных омаров из ловушек под пристанью в порту Штормграда. Остерегайтесь акул!', 'Если бы перед смертью я могла заказать какой-нибудь деликатес, я бы непременно выбрала свежие хвосты омара. Прямо не могу устоять перед ними! Мы тут недавно расставили ловушки на омаров в порту Штормграда. Не сходишь проверить?$B$BДа, вот еще что: остерегайся акул. Они там злобные...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26443, 'ruRU', 'Демонические планы', 'Доставьте демонические планы воздаятелю Ведаару на лесозаготовки Песни Войны в Ясеневый лес.', 'Этот пергамент выронил демон, но что странно – он написан на Всеобщем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя Ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.$B$BВ плане подробно описывается подготовка нападения демонов на Лесную Песнь на севере отсюда – место, где основали свое поселение дренеи.$B$BВозможно, это заинтересует воздаятеля Ведаара с лесозаготовок Песни Войны?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26444, 'ruRU', 'Уничтожить Легион!', 'Убейте 15 демонов на холме Демонического Огня, в каньоне Гибели Демона и гряде Гибели Демона.', 'Я не потерплю их присутствия в нашем мире! Пылающий Легион чуть не уничтожил нашу расу, и мы бежали сюда, чтобы построить себе новый дом в новом мире. Теперь они снова пришли. И мы снова отступили, и снова, и снова!$B$BДовольно! $B$BОстатки Легиона затаились к югу от холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона. Это все, что осталось от полчищ, что некогда вторглись в этот мир.$B$BСтупай же и перебей сколько сможешь, пока еще не поздно!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26445, 'ruRU', 'Больше никогда!', 'Добудьте пламенеющее лезвие Горганнона и желчное копье Ищейки.', '$n, на твои плечи ложится обязанность сорвать нападение Пылающего Легиона! Ты $Gдолжен:должна; уничтожить их предводителей. Остальные демоны, по большей части, – безмозглые твари. $B$BГорганнона ты найдешь в Каньоне Гибели демона к югу за Холмом Демонического Огня, близ сломанного, парящего копья Маннорота.$B$BДиатор Ищейка засел где-то в логове в холме над Грядой Гибели Демона. Чтобы найти эту гряду, отыщи уступ, по которому можно подняться из Каньона Гибели демона близ памятника Грому Адскому Крику.$B$BПринеси мне их оружие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26446, 'ruRU', 'Возрождение Холма Демонического Огня', 'Посадите 8 древесных саженцев в кучи плодородной земли.', '$GМалыш:Малышка;, к юго-западу отсюда находится место, что зовется лесами Ночной Песни. С недавнего времени его называют Холмом Демонического Огня. Прискорбно видеть, как по этой земле бродят демоны и разносят везде свою порчу.$B$BНе поможешь ли ты возродить эту землю?$B$BУ меня есть несколько саженцев, которые я приберег на этот случай. Отнеси их на Холм Демонического Огня и посади их в кучи плодородной земли.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26447, 'ruRU', 'Демонические планы', 'Доставьте демонические планы Валуше на Заставу Расщепленного Дерева, что в Ясеневом лесу.', 'Этот пергамент выронил демон, но что странно – он написан на Всеобщем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя Ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.$B$BВ плане подробно описывается подготовка нападения демонов на Лесную Песнь на севере отсюда – место, где основали свое поселение дренеи.$B$BВы уверены, что это очень заинтересует Валушу на Заставе Расщепленного Дерева.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26448, 'ruRU', 'Уничтожить Легион!', 'Убейте 15 любых демонов на холме Демонического Огня, в каньоне Гибели Демона и гряде Гибели Демона.', 'Остатки демонического Пылающего Легиона слишком долго надоедали нам.$B$BХватит!$B$BЭти демоны лезут от Холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона на востоке.$B$BСтупай и уничтожь их сколько сумеешь – и покроешь славой и себя, и Орду!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26449, 'ruRU', 'Больше никогда!', 'Добудьте пламенеющее лезвие Горганнона и желчное копье Ищейки.', '$n, сделай так, чтобы эта атака Пылающего Легиона сорвалась! Иди и убей этих повелителей Ужаса! Остальные демоны, кроме них – по большей части безмозглые твари. $B$BГорганнона ты найдешь в Каньоне Гибели Демона к югу за Холмом Демонического Огня, близ сломанного, парящего копья Маннорота.$B$BДиатор Ищейка засел где-то в логове в холме над Грядой Гибели Демона. Принеси мне их оружие в доказательство твоей победы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26450, 'ruRU', 'Если они собираются просто оставить это на земле...', 'Добудьте 6 нагских идолов с Южного Гибельного Берега на мысе Тернистой долины.', 'Я тут вот о чем подумала, $n. Эти наги... у них ведь не только водорослей полно. Вокруг святилищ, в песке, под деревьями валяется множество статуэток. И они им совсем НЕ НУЖНЫ!$B$BА мне бы пригодились!.. Я бы... скажем, расставила их по лагерю, чтобы стало уютнее. Все лучше, чем вонючие останки динозавров. Можно пустить на сувениры.$B$BМожно их опять тем же нагам продать, в конце концов!$B$BПочему б тебе не пойти и не подобрать пару-другую статуэток, пока я тут придумываю, как ими лучше распорядиться?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26451, 'ruRU', 'Арена Гурубаши: все против всех!', 'Установите на ринге Арены флаг вызова Гурубаши и победите соперника, вышедшего на бой.', 'Эта арена не похожа на другие. Тут не бывает друзей. Союзы создаются и распадаются в мгновение ока. Орда против Альянса, Альянс против Альянса, Орда против Орды... Тут возможно все.$B$BВозьми этот боевой штандарт, |3-6($r), и водрузи его на середине арены, чтобы начать бой. Победи противника и возвращайся ко мне.$B$BДержи ухо востро, |3-6($r). На арене Гурубаши может случиться что угодно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26452, 'ruRU', 'Вызов Гурубаши', 'Установите на ринге Арены флаг вызова Гурубаши и победите соперника, вышедшего на бой.', '$GВернулся:Вернулась;? Значит, тебя снова потянуло на арену. Что ж, отлично.$B$BВозьми этот боевой штандарт и установи на арене. Когда одолеешь вызванного на бой соперника, возвращайся ко мне.$B$BБудь начеку, |3-6($r). На Арене Гурубаши может случиться все что угодно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26453, 'ruRU', 'Рука помощи', 'Отправляйтесь в Лесную Песнь и поговорите с архитектором Немосом.$B$BОбратитесь к воздаятельнице Паланааре, если вам требуется транспорт.', 'Мой народ принялся за важное дело в восточной части Ясеневого леса при поддержке и помощи калдорай.$B$BПод руководством архитектора Немоса и воздаятеля Ведаара они восстанавливают древний форт ночных эльфов. Это непростая задача, $n, ибо кругом много врагов. Я знаю, что архитектор Немос и его сторонники в Лесной Песни будут благодарны любой помощи, и он просил меня присылать к нему всякого, кого это заинтересует.$B$BЕсли хочешь отправиться туда, окликни меня еще раз, и я организую тебе транспорт.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26454, 'ruRU', 'Напрасные усилия', 'Добудьте 5 связок оскверненной древесины Сатирнаара.', 'Добро пожаловать в Лесную Песнь, |3-6($c). Там, где ныне стоят палатки, однажды вырастут дома, но для этого необходимы постоянные поставки строительных материалов. Я не посмею просить никого из наших рабочих рубить древние деревья этой рощи, но наши соседи на западе не столь трепетно относятся к лесу.$B$BМы заберем немного оскверненного дерева из цитадели сатиров на западе. Доставь древесину Кривокрону на Лесозаготовки Песни Войны. Он один из Древних, и может очистить ее от порчи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26455, 'ruRU', 'Потерянная чаша', 'Добудьте чашу Элуны.', 'В области к западу отсюда, что нынче зовется Сатирнаар, некогда было прославленное святилище, которое возвел мой народ. В нем хранилась бесценная реликвия, чаша Элуны, доверенная хранителям святилища жрецами Элуны. Некогда к святилищу стекались паломники, дабы испытать целительную силу чаши, которой она, как говорят, обладала.$B$BМожет, это просто байки, но если в них есть доля правды, то эта святыня может стать ключом к возрождению нашего истерзанного леса. Мне надо точно это выяснить, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26456, 'ruRU', 'Донесение с северного фронта', 'Доставьте донесение часового Мелирии часовому Дальней Песне в рощу Среброкрылых, что в Ясеневом лесу.', 'Борьбу с Ордой ведет не только Башня в Ночных лесах, $n. К юго-востоку, на границе со Степями, в роще Среброкрылых, находятся Часовые Среброкрылых. Часовой Дальняя Песня из этой рощи направляет наши действия против тех, кто готов разорить наши земли.$B$BЯ немного припозднилась с отправлением моего последнего донесения часовому Дальней Песне, но боюсь оставить башню без охраны.$B$BМне крайне необходима твоя помощь в доставке этого отчета!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26457, 'ruRU', 'Пособники разрушения', 'Убейте надзирателя Гортака и 12 других сторонников Орды на лесозаготовках Песни Войны.', 'Лесозаготовки Песни Войны – нарыв на теле нашей истерзанной земли. Каждый раз, как нам удается пресечь их работу, надзиратель Гортак приказывает своим лесорубам удвоить усилия!$B$BТеперь орки валят столько леса, что даже использовать весь не могут, рубят живые стволы, когда у них бревна гниют за ненадобностью! Это плевок нам в душу, $n, и мы покажем им, что не потерпим дальнейшего разорения наших земель!$B$BСтупай и не ведай покоя, пока этот надзиратель Гортак и его пособники не будут мертвы!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26459, 'ruRU', 'Исследование порчи', 'Релвин Тень Звезды в лагере у Непроглядной Пучины хочет, чтобы вы принесли ему 8 оскверненных стволов мозга.', 'Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора?$b$bЯ боюсь, что эльфы крови могут претерпеть такую же трансформацию. Азерот не может позволить себе породить еще одну расу злобных монстров.$B$BЯ хотел бы изучить ствол мозга сатиров и наг, чтобы понять, на что обрекают себя Син\'дорай. И сатиров, и наг можно найти в Непроглядной Пучине, на западе.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (26462, 'ruRU', 'Мерзкий Сломанный Клык', 'Убейте 10 ловчих или мастеров проклятий из племени Сломанного Клыка.', 'Эти тролли Сломанного Клыка думают, что они особенные, потому что служат Орде. Помереть со смеху можно!$B$BПонимаешь, плевать нам на то, служат ли они Орде, или тролльской империи, или вообще Пылающему Легиону. Мы тут уже несколько столетий троллей убивали и убивать будем.$B$BВообще-то я добрая, так что разрешаю тебе, $gприятель:подруга;, помочь. Бери оружие и топай на поле битвы. Поможешь там нашим ребятам!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26463, 'ruRU', 'В поисках Терониса', 'Найдите Терониса у озера Фалатим, что в Ясеневом лесу.', 'Раэна Волкопас, моя подруга из Астранаара, попросила меня послать разведчика на запад к озеру Фалатим. Теронис ушел несколько дней назад, еще до нападения Орды.$B$BОн думает отыскать один предмет, который, по его мнению, ослабит нападения фурболгов на наш народ – это жезл, сделанный ныне покойным злым волшебником. $B$BПрежде чем уйти, он упомянул, что будет искать драгоценный камень для жезла.$B$BК несчастью, теперь мы знаем, что озеро является источником некоей зловещей силы. Прошу тебя, $n, найди моего друга!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26464, 'ruRU', 'Пропавший камень', 'Найдите светящийся самоцвет.', 'Осматривая вещи Терониса, вы находите дневник, который все еще в неплохом состоянии.$B$BБыстро пролистав его до конца, вы находите упоминание о некоем драгоценном камне, который он нашел, а потом потерял в районе озера Фалатим.$B$BОстается только найти камень, который искал Теронис. Возможно, его забрали эти щупальца...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26465, 'ruRU', 'Древние статуэтки', 'Добудьте 10 древних статуэток.', 'Я хотел бы дать тебе поручение, |3-6($c).$B$BЯ на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги. Они выныривали из воды и вцеплялись в меня когтями! Остальное неважно – главное, что мне удалось сбежать.$B$BБеда в том, что я археолог, и прибыл сюда для того, чтобы раздобыть кое-какие артефакты затопленного города.$B$BМожет быть, ты отправишься вместо меня на юго-запад, к Зорамскому взморью, и отыщешь какие-нибудь древности? Они-то и являются причиной моего прибытия сюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26466, 'ruRU', 'Руузель', 'Добудьте кольцо Зорама.', 'Боюсь, тайна этой древней статуэтки так и останется нераскрытой, если не найти ключа к этому древнему замку.$B$BЭтим ключом является кольцо – кольцо Зорама. Оно принадлежало правителям этого города до того, как волны Раскола поглотили его.$B$BДолгие годы кольцо считалось утраченным, пока наги недавно не нашли его.$B$BИх предводительница, Руузель, живет на острове на северной окраине Зорама. Прошу тебя, $n, добудь мне это кольцо!', '', 'У нее кольцо Зорама!', 'Руузель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26467, 'ruRU', 'Сатиры коварны! Дриады в опасности!', 'Найдите в Ксавиане Анилию.', 'Послушай, я не знаю, кто ты, но мне нужна помощь. Мои сестры отправились отнять у одного сатира Ветвь Кенария. Они сказали, что скоро вернутся, но уже целых два дня прошло!$B$B$n, ты $Gдолжен:должна; найти их! Они искали развалины храма ночных эльфов в Ксавиане на северо-западе. Не знаю, что и думать. Найди Анилию, это она повела их на поиски.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26468, 'ruRU', 'Ветвь Кенария', 'Добудьте Ветвь Кенария.', 'Анилия кладет руки вам на плечи и привлекает вас к себе. Задыхаясь, она показывает на находящуюся на севере арку, затем глаза ее закрываются, и из последних сил она шепчет: \"Он забрал ее... Гелтарис...\" И в душе вы понимаете, что Анилия умирает, жаждая, чтобы Ветвь Кенария была возвращена дриадам.', '', 'Добудь ветвь Кенария!', 'Гелтарис', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26469, 'ruRU', 'Убийство сатиров!', 'Добудьте 16 рогов сатиров.', 'Поверить не могу – Анилии нет! Как часто мы вместе резвились в лесах... Я почти ощущаю... печаль.$B$BЯ знаю, от чего мне станет легче на душе. Пожалуйста, убей сатиров, что отняли у меня Анилию! Принеси мне их рога в доказательство своего деяния, и я буду навек тебе благодарна.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26470, 'ruRU', 'Отвоевать озеро', 'Убейте 12 злобных элементалей воды и Приливницу.', 'Мы бы с легкостью могли отстоять приют Серебряного Ветра у Орды, если бы наши противники не подчинили себе наших защитников – элементалей воды озера Мистраль.$B$BОдин из шаманов призвал Приливницу, старого и злобного духа воды, которая исказила сущность наших элементалей и обратила их против нас самих. Теперь у нас не остается другого выхода, кроме как отступить к башне.$B$BПрошу тебя, отправляйся на восток и отвоюй озеро у Орды. Тогда, возможно, у нас появится шанс вернуть приют.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26472, 'ruRU', 'Безумные друиды', 'Убейте обезумевших друидов: Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.', 'Друиды мертвы! Они были убиты своими же предводителями, которые сошли с ума в результате осквернения Сердца леса проклятыми ордынцами! Даже здесь я чувствую тень разложения, и потому не осмеливаюсь идти дальше.$B$BЯ слишком привязан к Ясеневому лесу и Сердцу леса, но ты... ты $Gмог:могла; бы спуститься в Обитель и сделать то, что должно быть сделано. Ты не заблудишься – я оставил для тебя след из хлебных крошек.$B$BЭто разрывает мне сердце, но я вынужден просить тебя убить некогда великих предводителей друидов – Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26473, 'ruRU', 'Батранов волос', 'Соберите 8 стеблей Батранова волоса.', 'Есть одна травка, что росла некогда в древних руинах Убежища Батрана, что вдоль дороги на востоке. Звалась эта травка Батранов волос и славилась тем, что лечила болезни души.$B$BУвы, теперь ее собирают прислужники Орды для своих зловещих целей.$B$BВ Астранааре болеет ребенок, и сдается мне, что это болезнь не телесная. Я обещал своему наставнику найти лекарство, но мне не под силу сражаться с воинами.$B$BНе сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26474, 'ruRU', 'Лекарство Орендила', 'Принесите лекарство Орендила Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.', '$n, это лекарство, благословенное светом Элуны, должно помочь больному ребенку. Отнеси его в Астранаар отцу ребенка, Пельтуру Белой Луне.$B$BЧтобы добраться до Астранаара, ступай по дороге сначала на юг, потом на восток. Но если хочешь добраться туда побыстрее – поговори с часовым Аваной.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26475, 'ruRU', 'Слеза Элуны', 'Найдите Слезу Элуны.', 'Я надеялся, что лекарство Орендила спасет Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери. Мы должны найти более мощное средство! К счастью, Орендил говорил мне, какие еще он попытается применить лекарства, если первое не поможет.$B$BСлеза Элуны – это такой камень, который можно найти только в одном месте – у обмелевшего озера Ирис, уничтоженном при извержении вулкана Громовой Вершины. Оно находится к востоку от Астранаара. Орендил сказал, что этот камень снимает порчу... прошу тебя, $n, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26476, 'ruRU', 'Посылка для дриад', 'Отнесите светящийся самоцвет Шаэлдрин у башни в Ночных лесах, что в Ясеневом лесу.', 'А, вот и ты, $n. Я изучила записи Терониса, и пришла к выводу, что твоим следующим действием будет поиск остальных фрагментов созданного Дартолом жезла.$B$BЯ бы для начала пошла на восток вдоль дороги, ведущей к башне в Ночных лесах.$B$BДриада Шаэл\'дрин будет тебе лучшим проводником. Найди ее.$B$BВозьми с собой этот самоцвет – он может понадобиться Шаэл\'дрин, если она решит помочь тебе восстановить жезл.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26477, 'ruRU', 'Поиски древка', 'Найдите деревянный ключ и с его помощью получите железное древко жезла Дартола.', 'Хотелось бы мне, чтобы у тебя были более хорошие новости.$B$BРаэна права, мне многое известно о творении Дартола и древнях этих краев – или было известно прежде. Теперь все они осквернены, их природа искажена.$B$BЕсли твоя цель – найти еще один фрагмент жезла, то тебе придется найти ключ, чтобы отпереть сундук, в котором он лежит.$B$BДеревянный ключ – на одном из древней к северо-востоку отсюда, близ Оскверненного леса в Воющей долине. Как только добудешь его, ищи небольшую лощинку в долине... Сундук должен быть спрятан где-то там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26478, 'ruRU', 'Притвориться мертвым', 'Найдите последний фрагмент жезла Дартола, Железное навершие.', 'Последний фрагмент жезла был отдан на хранение друидам-медведям. Я обращалась к их предводителю, Осо Ежевичному Оврагу, с просьбой передать его мне, но его стражники чуть меня не убили. Очевидно, их тоже затронула скверна Орды, исказившая сердце леса.$B$BНо у меня есть идея, как можно проникнуть в пещеру Осо и выкрасть навершие.$B$BЕще в детстве мне легко удавалось притворяться мертвой. Особенно здорово этот трюк срабатывал при встрече с медведем. Я могу научить тебя! Ты отправишься в Тенистый закоулок, а если они попробуют тебя схватить, воспользуешься моим секретом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26479, 'ruRU', 'Возвращение к Раэне', 'Вернитесь к Раэне Волкопас в Астранаар, что в Ясеневом лесу, и передайте ей жезл Дартола.', 'Советую тебе найти Раэну и сказать ей, что жезл воссоздан. Я уверена, она знает, куда тебе направиться дальше. $B$BБудь $gосторожен:осторожна;... сила, заключенная в этом жезле, может послужить как добру, так и злу. Надеюсь, вы с Раэной знаете, что делаете.$B$BУдачи, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26480, 'ruRU', 'Жезл Дартола', 'Найдите Кролга в его хижине в Ясеневом лесу и поговорите с ним при помощи жезла Дартола.', 'Увы, я не могу точно знать, что Теронис собирался делать дальше, но если он сказал правду о силе жезла, то ты можешь с его помощью изменить облик, притворившись фурболгом.$B$BПолагаю, он намеревался использовать его мощь, чтобы подобраться поближе к этим мерзостным тварям, но даже не затронутые порчей существа убили бы его, не будь он осторожен. Изменив облик, Дартол намеревался поговорить с фурболгом, которого не коснулась рука скверны.$B$BЯ бы начала с существа по имени Кролг. Ищи его к юго-востоку от озера Мистраль.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26481, 'ruRU', 'Новое украшение', 'Добудьте череп Рэна Кровавого Клыка и жезл Дартола.', 'Я уверен, что этот погибший волшебник, Дартол, намеревался использовать силу жезла для того, чтобы подчинить и уничтожить нас – точно так же, как ночные эльфы и орки. Но теперь у нас появился шанс использовать эту штуку по другому назначению.$B$BРэн Кровавый Клык – король всех фурболгов Ясеневого леса. Его племя обладает огромной силой и обитает в лагере на востоке.$B$BУбей их всех и принеси мне череп вождя. Пусть эта вещь хоть раз послужит благому делу.', '', 'Добудь череп Рэна.', 'Рэн Кровавый Клык', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26482, 'ruRU', 'Истинная сила жезла', 'Используя жезл Дартола, поговорите с Ота Веном и уговорите его поднять восстание против ордынских захватчиков. Затем отнесите жезл Раэне Волкопас.', 'А теперь возьми жезл, воспользуйся его силой и поговори с моим братом, Ота Веном.$B$BОта сейчас находится среди других фурболгов, захваченных орками. Его содержат в огромной клетке на северной стороне приюта Серебряного Ветра. Этот жезл поможет тебе убедить Ота и других фурболгов поднять восстание и выступить против Орды.$B$BЭто моя последняя просьба; выполнив ее, ты можешь идти дальше по дороге жизни. Но куда бы не завела тебя судьба, знай, что в моем лице ты $Gобрел:обрела; верного друга.', 'Восстание поднято.', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26483, 'ruRU', 'Ган\'дранда', 'Убейте Ган\'дранду.', 'Кроме рубки голов этим троллям, у нас еще полон рот хлопот. Хорошо бы закончить хоть эту битву, да?$B$BИх командир Ган\'дранда засел на разрушенной стене к юго-востоку от поля битвы. Наши ребята сейчас сильно заняты, поэтому тебе придется туда проникнуть и изничтожить Ган\'дранду. Когда они увидят, что их величайший герой сражен, многие наверняка просто бросят оружие!', '', 'Наши шансы будут гораздо выше, если этот негодяй умрет.', 'Ган\'дранда', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26484, 'ruRU', 'На помощь Каменному очагу', 'Поговорите с Крегом Крушителем Скал в Каменном очаге в Подземье.', 'Более пятнадцати тысяч лет назад земельники и каменные трогги каким-то образом проникли в Подземье через Ульдум. С тех пор они и воюют.$b$bЕсли мы хотим отыскать центральный фрагмент столпа мира, то нужно спасти Отца-Скалу.$b$bПожалуйста, отправляйся в Каменный очаг и сделай все, что сможешь, чтобы помочь земельникам в их войне против каменных троггов.$b$bНа тебя все наши надежды, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26485, 'ruRU', 'Хрустогрызы, сэр!', 'Соберите 8 кучек потрохов морских хрустогрызов.', 'Хочу сварить что-то особенное для этих надоедливых троллей. Да-да, для них. Они никогда не забудут мое угощение! Они от него землю клыками рыть будут!$B$BНекоторые ингредиенты у меня уже есть, но мне все же понадобится твоя помощь. На востоке, на побережье у Отвесных скал полно хрустогрызов. Для моего восхитительного пойла мне нужны их свежие потроха.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26486, 'ruRU', 'Игра в бутылочку', 'Соберите 12 бутылок портвейна \"Пупелливербос\".', 'Да-да, я помню, что у нас тут бои идут, но там на побережье возле Отвесных скал лежат разбросанные бутылки. Не хочу, чтобы славный напиток попал в грязные лапы Орды!$B$BЕсли не трудно, собери там бутылки и принеси их мне. Я тебе заплачу сполна, как будто это твоего собственного разлива бутылки!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26487, 'ruRU', 'Вязанка акириса', 'Отберите 6 стеблей акириса у наг-исследователей.', 'Не так-то просто одновременно управлять пятизвездочным отелем и заводом по переработке вторсырья! Ну то есть было бы непросто, если бы я не владела навыками личного помощника торгового принца!$B$BГлавный фокус – многозадачность. К примеру, на юге наги-исследователи носят с собой ценные морские водоросли – стебли акириса. Мы можем продавать эти водоросли заморским клиентам, а можем набивать ими тюфяки для наших гостей! Если подумать, партия этих водорослей нам совсем не помешает.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26488, 'ruRU', 'Большой глоток', 'Выловите царского морского ангела изо рва на Аллее Героев в Штормграде. Поймав рыбу, выпотрошите ее и поищите внутри медальон.', 'Мы с Арнольдом, бывало, отдыхали возле рва на Аллее Героев. Однажды я уронила медальон в воду и не сумела его найти. Поговаривают, там живет гигантская рыба – царский морской ангел, которая глотает все подряд! Понимаю, дело это хлопотное, но, может быть, поймаешь пару-тройку морских ангелов и поищешь мой медальон?$B$BЕсли отыщешь – будь добр, дай мне знать. Медальон мне очень дорог.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26490, 'ruRU', 'Жуть-муть', 'Заберите кусочек вязкой мути у Вязкой Мути.', 'Немногие дворфы в курсе, но чтобы мое пойло РЕАЛЬНО вышибало мозги, я добавляю в него чуть-чуть слизнятины. Ага, прям вот от дворфоядных слизнюков, зеленых таких.$B$BА сейчас нам нужен просто СНОГСШИБАТЕЛЬНЫЙ эффект, так что нам нужен большой слизень! На Осклизлой скале как раз есть один, огромный такой... наверное, это их матка. Мы этого слизня зовем Вязкая Муть.$B$BТак что, если не дрейфишь, сходи туда и принеси мне кусочек этой Вязкой Мути.', '', 'Не подходи слишком близко… неизвестно, чего можно ждать от этой штуки.', 'Вязкая Муть', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26491, 'ruRU', 'Большая уборка на Осклизлой скале', 'Убейте 10 нефритовых слизнюков.', 'Много лет назад на Осклизлой скале был лагерь Орды. Он много лет пустовал, но все еще является желанной целью для наших союзников.$B$BДело в том, что там полно дворфоядных слизнюков и прочей ядовитой дряни. Они не так отвратительны, как тролли, но не намного лучше.$B$BНаши ребята заняты сражением со Сломанным Клыком, так что отправиться на Осклизлую скалу и очистить ее придется тебе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26492, 'ruRU', 'Припасы с Осклизлой скалы', 'Соберите 5 покрытых слизью ящиков с припасами.', 'А вот мой двоюродный брат был на Второй войне. Он рассказывал, как они воевали на Осклизлой скале. Напали они тогда на нее и всех троллей оттуда поганой метлой вымели. А потом еще и гнали их до самого Альтерака!$B$BПотом сюда очень быстро наползли слизни, а ведь здесь еще полно припасов Орды. Нельзя позволить троллям забрать их!$B$BПринеси мне несколько ящиков с северо-запада Осклизлой скалы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26493, 'ruRU', 'Есть желающие!', 'Добудьте 7 секретных ингредиентов Хамми у василисков-хвостохлестов и железозубых василисков в Хрустальной шахте.', 'Такой вал заданий, конечно, здорово изматывает, но все-таки я решила поручить тебе еще кое-что. Ты ведь не против?$B$BВ последнем номере \"Науки и взрывов\", полученном из Гавани Трюмных вод, упоминается какой-то новый мегареагент. Цены на него растут не по дням, а по часам, так что надо поторопиться!$B$B<Хамми наклоняется и шепчет вам на ухо.>$B$BВсе понятно? Хорошо. Этих василисков можно найти в пещере к востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26494, 'ruRU', 'Смешиватель Джаспер', 'Отнесите образцы Хамми смешивателю Джасперу в Укрытие Кофельнагель.', 'Ты не передашь это Джасперу? Он там, у богатых квартир. Ему это очень пригодится.$B$BСпасибо, $n!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26495, 'ruRU', 'Шабал', 'Отнесите щедрый дар Хамми Шабалу в Укрытие Кофельнагель.', 'Тролль у ботанического сада (одновременно лаборатории по производству биологического оружия) – Шабал, наш особый гость. Это один из зандаларов, он проделал неблизкий путь, чтобы сюда добраться.$B$B<Хамми кладет несколько принесенных вами вещиц в небольшой мешок и отдает вам.>$B$BВот, отнеси ему. Скажи, что зандаларов всегда рады видеть в Укрытии Кофельнагель! И не забудь упомянуть, что в нашем деле главное – это рекомендации!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26496, 'ruRU', 'Сломай Порочную Ветвь', 'Найдите Дорана Сталекрылого у Джинта\'Алора во Внутренних землях.', 'Племя Сломанного Клыка – не единственные тролли, с которыми надо разделаться! Тролли из племени Порочной Ветви пачкают эту землю уже долгие годы, обосновавшись в своей крепости Джинта\'Алор.$B$BА нам уже надоело сидеть на Заоблачном пике и ножками болтать. Доран Сталекрылый ведет войско на племя Порочной Ветви из лагеря на юге. Поговори с ним и присоединяйся к войску!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26497, 'ruRU', 'Гнилые плоды Порочной Ветви', 'Убейте 5 знахарей и 5 охотников за головами из племени Порочной Ветви в Джинта\'Алоре.', 'Племя Порочной Ветви отличается от племени Сломанного Клыка, но эта разница не имеет значения: мы уже давно поняли, что хороший тролль – это мертвый тролль.$B$BПлемя Порочной Ветви отвратительно само по себе, даже без хомута Орды на шее. Если мы не избавимся от них, они испоганят всю эту землю.$B$BМожешь начать с их знахарей и охотников за головами на нижних ярусах. Как перебьешь троллей побольше – возвращайся ко мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26498, 'ruRU', 'Смерть Порочной Ветви!', 'Убейте 5 берсерков и 5 темных чародеев из племени Порочной Ветви в Джинта\'Алоре.', 'Дела идут отлично. Продолжай в том же духе и не сбрасывай обороты!$B$BБерсерки из племени Порочной Ветви сражаются как дикие звери, благодаря боевой ярости. Их темные чародеи призывают духов из иного мира! Поэтому нам надо избавиться от этих гнусных существ как можно скорее, $n, не забывай это.$B$BИди на средний ярус и убей берсерков и темных чародеев.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26499, 'ruRU', 'Дар Отца-Скалы', 'Передайте слова Отца-Скалы 12 земельникам-защитникам.', 'После того как Отца-Скалу захватили в плен, мои воины деморализованы. Обычно любой из них может одолеть пятерых каменных троггов. Но сейчас...$b$bЯ хочу, чтобы ты $gотправился:отправилась; на поле, окружающее город. Установи возле расположения защитников знамя короля Железной Мантии. Передай им его добрые слова и напомни о том, за что они борются.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26500, 'ruRU', 'Мы окружены', 'Убейте 12 каменных троггов – душителей.', 'Нашей войне лет больше, чем вашему племени. Посмотрим, сможешь ли ты сделать хоть что-нибудь, |3-6($r).$b$bКаменные трогги – это ошибка титанов. В вашем мире они стали жертвами проклятия плоти. Но здесь, в Подземье, ты можешь видеть их истинную сущность.$b$bМы окружены. Ты не $gмог:могла; бы пойти и убить нескольких троггов для нас? Увидишь, из чего они на самом деле сделаны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26501, 'ruRU', 'Закрыть все выходы', 'Помогите земельникам-геомантам прекратить битву и дайте им оползневые реагенты, чтобы они смогли заблокировать выходы из оружейной, таверны, казарм и святилища.', 'Каменные трогги нашли способ вылезать на поверхность из-под наших домов!$b$bЯ приказал нашим геомантам заблокировать выходы из всех зданий, но чтобы завершить свои ритуалы по вызову оползней, им нужны реагенты и возможность не участвовать в битве.$b$bКогда будешь $gготов:готова;, поговори с генералом Гравием Долгопластом. Его можно найти к северу от Разбитой передовой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26502, 'ruRU', 'Громокамни', 'Соберите 12 громокамней.', 'К северу отсюда находится Разбитая передовая. Там идут самые тяжелые бои.$b$bОтправляйся в Каменный очаг и возьми столько громокамней, сколько сможешь. Они нужны нашим инженерам для катапульт.$b$bКогда наберешь достаточно, отнеси их Глину Грязновалу. На то, что он говорит, не обращай внимания. Он стар и сумасброден и должен был вернуться обратно в землю еще тысячи лет назад.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26503, 'ruRU', 'Оценка угрозы', 'Украдите военные планы гноллов, приказы гноллов и стратегическое руководство гноллов.', 'Эти жалкие ничтожные гноллы опять затевают какую-то пакость, я нутром чую! За последние две недели они развели тут прямо-таки небывалую возню! Боюсь, они собираются напасть на Приозерье.$B$BПрошу тебя: сходи в каждый из местных гнолльих лагерей и собери всю информацию, какую только сможешь найти. Лагеря есть к северу, востоку и юго-востоку отсюда. Все, что найдешь, – тащи сюда', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26504, 'ruRU', 'Разыскиваются: гноллы Красногорья', 'Убейте 15 любых гноллов Красногорья на Трех Углах в Красногорье.', 'Именем королевской стражи Штормграда, все гноллы из юго-западного района Красногорья, также известного как Три Угла, подлежат истреблению.$B$BЕсли вы избавите эту местность от гноллов, доложите об этом капитану стражи Паркеру в Часовой башне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26505, 'ruRU', 'Донесение Паркера', 'Отправляйтесь в Красногорье и отдайте донесение Паркера мировому судье Соломону в Приозерье.', '<Капитан стражи Паркер вручает вам донесение.>$B$BВот, $n. Отнеси мое донесение в Приозерье – это к северу от этой башни. Отдай его мировому судье Соломону и скажи ему: для того чтобы разобраться с гноллами, надо что-нибудь попроще. Взрывчатка, например, да побольше.$B$BДа, и на твоем месте я не сходил бы с дороги.$B$BЦелее будешь. А то вдруг ты этого не $gзнал:знала;. Теперь зато знаешь... Ладно, проехали!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26506, 'ruRU', 'Мясное рагу', 'Соберите 4 глаза тарантула, потроха 4 кондоров и 4 почки кровоклыка.', 'Эй, |3-6($r), помоги мне! Стражники проголодались, а еда у нас вся кончилась! Они требуют моего знаменитого мясного рагу, но у меня совершенно нет продуктов. Не поможешь ли мне, а?$B$BМне нужны почки кровоклыка, потроха кондора и глаза тарантула. Вся эта живность водится прямехонько у этой вот башни, только осмотрись!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26507, 'ruRU', 'Окаменевшие лакомства', 'Соберите 12 окаменевших летучих мышей для Камешка.', 'Окаменевшие летучие мыши.$b$bЭлементали такого размера разборчивы в еде. Но что-то лучшее ты вряд ли найдешь.$b$bК востоку отсюда водятся василиски. Подлетающих слишком близко летучих мышей они превращают в камень, а затем перекусывают ими, когда проголодаются. Так что окаменевшие мыши разбросаны там повсюду.$b$bНо я должен предупредить тебя... Если ты будешь уделять этому элементалю слишком много внимания, потом уже вряд ли от него отделаешься. Он очень сильно привяжется к тебе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26508, 'ruRU', 'Ожерелье Ниды', 'Найдите ожерелье Ниды.', 'Моя подруга Нида потеряла ожерелье, и мы никак не можем его отыскать. Мы весь день рыбачили на одном месте и уже обыскали все вокруг. Должно быть, оно упало в озеро, не иначе. Нам не разрешают купаться в озере: мама говорит, что там под водой живет какая-то злая зверюга... Но ты вроде бы не боишься злых зверюг, а?$B$BМожет, ты найдешь ее ожерелье?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26509, 'ruRU', 'Незваный гость', 'Убейте Грубобрюха и вырвите у него клык.', 'Мой сад снова затоптан и разорен. И я знаю, что за скотина это сделала! Это проклятущий кабан, которого маршал Маррис прозвал Грубобрюхом.$B$BЯ теперь до следующего сезона не смогу посадить желтые нарциссы! Все, что нажито непосильным трудом, все погибло! Прикончи его! Прикончи и покажи мне его клык, тогда я с радостью награжу тебя. Говорят, эта свинина часто пасется в поле к юго-западу от Приозерья, но иногда вот, как видишь, забредает и в мой сад.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26510, 'ruRU', 'Нужно готовиться!', 'Отыщите ГНМ-передатчик.', 'У нас каждый день пропадают люди. Мы думаем, что их похищают гноллы, но никто не имеет ни малейшего понятия о том, куда они могут прятать пленников! Если ты хочешь помочь нам победить гноллов и разыскать наших людей, то тебе потребуется хорошая экипировка. Увы, у нас закончились ГНМ-передатчики, а без него мы никак не сможем связаться с тобой, пока ты будешь на задании.$B$BНаш последний рабочий ГНМ-передатчик на прошлой неделе уволокли мурлоки. Придется тебе пойти на озеро Безмолвия, что к востоку отсюда, и отыскать его там!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26511, 'ruRU', 'Зачистка озера Безмолвия', 'Убейте 10 мурлоков на озере Безмолвия.', 'Ты идешь в сторону озера Безмолвия? Тогда тебе, должно быть, любопытно будет узнать, что мы назначили награду за мурлочьи головы. Убей, сколько сможешь, а мы тебе заплатим. Любой мурлок сойдет – ты, главное, знай себе убивай без разбору.$B$BОзеро Безмолвия, кстати, находится прямо к востоку от Приозерья. Озеро. Вода там еще. Понимаешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26512, 'ruRU', 'Настройка ГНМ-передатчика', 'Отправляйтесь на Приозерское кладбище, чтобы начать настройку ГНМ-передатчика.', 'ГНМ-передатчик, похоже, работает. Я его подключил, осталось только настроить на прием.$B$BТы выйди из Приозерья и иди по дороге на кладбище. Когда дойдешь дотуда, я попробую с тобой связаться.', 'Работа ГНМ-передатчика на кладбище Приозерья проверена', '', '', 'Входящий сигнал чистый, слышимость отличная!', 'Мировой судья Соломон', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26513, 'ruRU', 'Как ветром сдуло', 'Верните 8 ящиков с припасами Красногорья.', 'На нас напали прошлой ночью, или позапрошлой... Не могу точно сказать, когда это было, потому что я не смыкаю глаз вот уже три дня и у меня уже ум за разум зашел.$B$BТак вот, значит, на нас напали гноллы и уволокли решительно все припасы! Как ветром сдуло: вроде было что-то, и вот уже ничего не осталось! Солдаты видели, как они побежали к каньонам, на северо-запад отсюда. Верни нам наши припасы, |3-6($c)!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26514, 'ruRU', 'Зачистка каньона', 'Соберите 10 ошейников гноллов Красногорья.', '<ГНМ-передатчик гудит.>$B$BПервым твоим заданием будет пройтись по каньонам Красногорья, это к северу от Приозерья, и навести там хорошего шороху. Убивай каждого гнома, которого встретишь. Ой, я сказал гнома? Гнолла, конечно же. А в доказательство собирай гнолльи ошейники.$B$BНо должен предупредить тебя, $n: там могут быть еще и эттины. Мои разведчики в последнее время не раз встречали в каньонах больших кровожадных эттинов, так что если хочешь остаться $gжив:жива;, не попадайся им на пути.$B$BСоломон, отбой. Я буду на связи.', '', 'Осторожнее с каньонными эттинами!', 'Мировой судья Соломон', 'Эти гноллы, кажется, поумнели!', 'Мировой судья Соломон', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26515, 'ruRU', 'Месть Онго\'лонго', 'Деритесь с Онго\'лонго, пока он не освободится.', 'Я знаю, как стравить троллей друг с другом.$B$BПлемя Порочной Ветви держит в яме свирепого тролля, причем скован он довольно хлипкими на вид цепями. Я видел, на что тролли способны, так что тонкие цепочки его точно не удержат, если он разъярится.$B$BНайди свирепого тролля и подерись с ним, $n. Но не убивай его. Просто попинай его, пока он не разозлится как следует, а потом дай ему вырваться на волю и больше не мешай. Он отметелит племя Порочной Ветви на ура.', '', 'Разозли его, а потом отойди!', 'Онго\'лонго', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26516, 'ruRU', 'Победа наша!', 'Убейте 5 кровопийц и 5 пожирателей душ из племени Порочной Ветви в Джинта\'Алоре.', 'Остались только самые стойкие и злобные из племени Порочной Ветви – кровопийцы и пожиратели душ, поклоняющиеся Хаккару.$B$BНе забывай, ты не просто сражаешься с троллями, $n. Ты выступаешь против темных сил, которые уничтожат эти земли, если мы их не остановим!$B$BНе давай им пощады!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26517, 'ruRU', 'Судьбоносная вершина', 'Соберите 8 идолов-пауков, убивая троллей племени Порочной Ветви на вершине Джинта\'Алора.', 'Тебе придется идти на вершину, $n. Наши воины не пройдут через последние ворота. Они говорят, там как в могиле – ни звука, ни движения, никаких признаков жизни.$B$BОни думают, что это ловушка, но принимая во внимание то, что ты мне $gпринес:принесла;, я опасаюсь, что там скрыто что-то более мерзкое. Иди к алтарю и разузнай, что там творится. И принеси мне ЛЮБОЙ магический артефакт или идола, которого ты там найдешь. Понятно?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26518, 'ruRU', 'Все дело в голове', 'Убейте Умбоду Три Башки и заберите его голову.', 'Умбода Три Башки – это один из самых огромных троллей. Он ужасно жестокий, а еще он коллекционирует головы – что троллей, что дворфов! Пора ему ответить за все.$B$BРазыщи громилу на нижних ярусах и принеси мне его собственную голову!', '', 'Принеси его башку Среднюю.', 'Умбода \"Три башки\"', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26519, 'ruRU', 'Тот, кто командует эттинами', 'Убейте Ардо Грязнолапа.', 'Вы обнаружили некий документ, написанный полуграмотным гноллом:$B$BБРАТЫ ИСУВОЯ, СЛУШОЙТИ ГРИЗНАЛАПА! ГРИЗНАЛАПУ ДАЛИ ОРКИ СФЕРУ! ГРИЗНАЛАП УПРОВЛЯИТ ЭТТИНАМИ! ГРИЗНАЛАП УБЙОТ ЛЮДИШКАВ! ПРИХАДИТИ, ПАЛУЧИТИ ОТ ГРИЗНАЛАПА ФПИЩЕРИ РЕТБАНА. ПИЩЕРА НАЗАПАДИ, СПРЯТАНА ФКАНЙОНИ!$B$B<В качестве подписи стоит отпечаток лапы.>$B$B<Еще у этого свитка, кажется, оторван кусок.>$B$BВозможно, вам стоит этим заняться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26520, 'ruRU', 'Спасение штейгера Ослоу', 'Подчините себе каньонного эттина при помощи сферы контроля эттина, а потом заставьте его убрать огромный булыжник со штейгера Ослоу в Приозерье.', '<Дотронувшись до сферы, вы слышите тихий щелчок.>$B$B<Вы снимаете сферу с пьедестала.>$B$B<Теперь эта сфера у вас в руках, а стало быть, вы можете управлять эттинами. Может, эттин сумеет убрать огромный булыжник, придавивший штейгера Ослоу в Приозерье. Разыщите эттина и подчините его себе при помощи сферы, а потом отправляйтесь в Приозерье.>', '', 'Каньонные эттины злые и ужасные.', 'Каньонный эттин', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26521, 'ruRU', 'Лики зла', 'Используйте факел тики, чтобы поджечь 8 ритуальных масок тики в Джинта\'Алоре.', 'Тролли из клана Порочной Ветви развесили маски тики по стенам Джинта\'Алора. Мы не потерпим их черной магии и злобной ворожбы!$B$BНастало время послать им сообщение и снять защиту одновременно! Возьми факел, |3-6($c). Подожги маски и полюбуйся, как они горят. Когда они увидят поверженных идолов, то сразу поймут, что Громовой Молот не намерен мириться их присутствием!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26522, 'ruRU', 'Лики зла', 'Используйте факел тики, чтобы поджечь 8 ритуальных масок тики в Джинта\'Алоре.', 'Клан Порочной Ветви развесил маски тики по стенам крепости Джинта\'Алор. Но эти рожи недолго будут приглядывать за ними!$B$BВозьми факел, |3-6($c). Подожги маски, а я полюбуюсь, как сгорают их стражи и заклятья, а вместе с дымом растворяется черная магия вуду.', '', '', '', '', '', 'Вернитесь к Котонге в Джинта\'Алор, что во Внутренних землях.', 19865);
INSERT INTO `quest_template_locale` VALUES (26523, 'ruRU', 'Быстролапые паучата', 'Соберите 8 быстролапых паучков в Джинта\'Алоре.', 'Знаешь, что я заметил? Джинта\'Алор просто кишит пауками. Самые маленькие из них – размером с твою руку. Не то чтобы это было необычным для Внутренних земель, но что-то тут не так.$B$BЕсли честно, то я не верю в то, что тролли держат у себя домашних любимцев. Они явно что-то замышляют. Принеси мне этих пауков. Живьем. Посмотрим, что скажут духи...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26524, 'ruRU', 'Темные сосуды', 'Соберите 5 Сосудов с порченой кровью в Джинта\'Алоре.', 'Тролли племени Порочной Ветви поклоняются темному и кровавому богу Хаккару. Он был мерзкой и вредоносной сущностью, которая когда-то давно почти прорвалась в наш мир, но была побеждена.$B$BПлемя Порочной Ветви все еще кипятит свои котлы, которые были наполнены кровью много лет назад. То ли они так поклоняются давно погибшему духу, то ли замыслили какую-то новую подлость.$B$BПринеси мне эти сосуды, $n. Нам надо исследовать их с помощью пауков и узнать, что здесь происходит!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26525, 'ruRU', 'Ядовитые секреты', 'Убейте 8 паучат Шадры.', 'Если жертвы уже принесены, то скоро Шадра начнет перебираться в наш мир. Та пещера, наверное, уже полна ее отродьями.$B$BНе давай им расползтись, $n. Убивай всех мерзких пауков, которых встретишь на пути!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26526, 'ruRU', 'Охота на хранительницу', 'Убейте Морта\'гью Хранительницу и заберите Табличку Шадры.', 'Шадра, королева пауков... Дух тьмы и смерти! Если они принесли жертвы, значит, пытаются призвать ее в наш мир.$B$BЕсли племя Порочной Ветви проводит ритуалы, я не потерплю, чтобы они спокойно их завершили!$B$BПроверь пещеру под алтарем на вершине Джинта\'Алора. Там может прятаться одна из хранительниц Шадры. Убей ее и принеси то, что она охраняет, мне, чтобы мы могли понять, что тут происходит.', '', 'Без сомнений, она будет прятаться в глубине пещеры.', 'Морта\'гья Хранительница', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26528, 'ruRU', 'Глаз Шадры', 'Найдите в Агол\'вате глаз Шадры.', 'Укротитель грифонов Разящий Коготь отправил меня сюда, чтобы разделаться с Шадрой, королевой пауков. Захватить Джинта\'Алор недостаточно... тролли могут перегруппироваться и призвать это существо еще раз, когда мы не будем этого ожидать. Помоги мне: собери артефакты и убей троллей, которые встанут у тебя на пути.$B$BСначала мы соберем артефакты, затем сами призовем Шадру в этот мир, а потом забьем эту тварь нашими молотками.$B$BПервое, что нам понадобится – это глаз Шадры, его держат под охраной в Агол\'вате, это к северу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26529, 'ruRU', 'Зуб Шадры', 'Найдите зуб Шадры в Ползучих руинах.', 'Теперь нам потребуется зуб Шадры.$B$BОн находится в Ползучих руинах к востоку отсюда, и охраняют его дети самой Шадры. Это премерзкие пауки размером с дворфа, и вдвое сильнее. А еще они очень ядовиты, $n... так что осторожнее.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26530, 'ruRU', 'Панцирь Шадры', 'Убейте Квиагу Хранительницу и заберите у нее панцирь Шадры.', 'Чтобы раз и навсегда покончить с Шадрой, нам нужен еще один предмет.$B$BПанцирь Шадры хранится у последней живущей ныне верховной жрицы паучьего бога, зовут ее Квиага Хранительница. Ее можно найти на вершине алтаря Зула, под охраной фанатиков.$B$BТебе нужно будет забраться на самый верх алтаря и убить ее! Потом заберешь у нее панцирь и принесешь мне.', '', 'Квиага – преданная ученица Шадры. Она не расстанется с панцирем без боя.', 'Квиага Хранительница', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26531, 'ruRU', 'Призыв Шадры', 'Используйте идол Шадры в северо-западном, юго-западном и восточном храмах в Шадра\'Алоре.', 'Наши лучшие воины готовы, идол собран... Пора, $n.$B$BВот как мы поступим. Ты $gпервым:первой; отправишься на юго-запад, в Шадра\'Алор, и возьмешь с собой идола. С этим идолом тебе надо будет по очереди пробраться в каждый из трех храмов, перебив всех троллей-стражников.$B$BКогда ты закончишь, Шадра придет в наш мир, и мы будем поджидать ее, с пылающей в наших сердцах яростью. Поговори с моими ребятами на месте, как только закончишь ритуал!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26532, 'ruRU', 'Шадра – королева пауков', 'Убейте Шадру – королеву пауков.', 'Не теряй времени, $n! Сейчас она вылезет из воды!$B$BУкротитель грифонов Разящий Коготь сейчас подойдет вместе со своими ребятами. Покажем этой букашке небо в алмазах!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26533, 'ruRU', 'Тайна Занзила', 'Добудьте 5 сосудов со смесью Занзила.', 'Давным-давно Гурубаши изгнали из Зул\'Гуруба своего соплеменника – тролля по имени Занзил. По какой причине – неизвестно, но могу предположить, что это было связано с его привычкой давать всем подряд свои сильнодействующие лекарства, влияющие на поведение. Вскоре жрецы Гурубаши и их кровожадный бог были свергнуты, а Занзил Отверженный жив до сих пор.$B$BА с ним и его лекарства.$B$BЯ бы хотел их получить. Отправляйся на юго-восток к зомби.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26534, 'ruRU', 'Убойный напиток', 'Угостите \"Джангл-айсом\" Джаспера Гмургла, Оргуса и капитана Бартоломью Мягкоборода.', 'Прибывающие в Укрытие Кофельнагель подписывают документы об отказе от всяческих прав, и поэтому мы на законных основаниях можем производить над ними базовые эксперименты. Чем мы сейчас и займемся.$B$BНа этот раз травить постояльцев не будем. Оно, знаешь ли, и для бизнеса лучше...$B$B<Джаспер наполняет кувшин смесью Занзила и колотым льдом.>$B$BЮго-восточная башня Укрытия временно служит тюрьмой. Мы ее называем \"Кофельнагельской кутузкой\". Угости этим пойлом арестантов, а потом расскажи мне, что с ними сталось.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26535, 'ruRU', 'Рецепт катастрофы', 'Добудьте рецептуру Занзила у одного из прислужников Занзила в руинах Абораза.', 'Рецепт Занзила нужен мне сейчас больше, чем когда-либо. Он должен быть у одного из прислужников Занзила в руинах Абораза. Отправляйся на восток, на другую сторону мыса и достань мне этот рецепт!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26536, 'ruRU', 'Ревущий водопад', 'Поймайте 4 лиловых окуней в Ревущем водопаде к югу от Штормграда. Возвращайтесь с уловом к Катрин Лиланд.', 'Мы с Арнольдом рыбачим в Штормграде и окрестностях уже долгие годы – конечно, у нас есть любимые места. Лично я предпочитаю Ревущий водопад.$B$BЭто в Элвиннском лесу, к югу от Штормграда. Ревущий водопад – лучшее место для ловли лилового окуня. Мне он нигде больше и не встречался, только в этом водопаде. Правда, нам с Арнольдом нынче туда не выбраться. Может, ты сходишь туда и наловишь таких окушков?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26537, 'ruRU', 'Убей их!', 'Убейте 12 любых каменных троггов на Разбитой передовой.', 'Я хочу, чтобы ты $gпошел:пошла; туда и $gприкончил:прикончила; их.$b$bБерсерков, земледробителей, наездников-убийц – неважно! Я хочу, чтобы эти каменные трогги были раздроблены!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26538, 'ruRU', 'Предметы первой помощи', 'Найдите лекаря на побережье в порту Драконьей Пасти.', 'Когда Сумеречные войска атаковали наш воздушный флот, мы потеряли многих воинов. А те, кто выжил, израненные и обожженные, сейчас плывут к тому, что осталось от флота. Им нужна поддержка с берега!$B$BВ порту Драконьей Пасти должен быть какой-нибудь знахарь или шаман, готовый протянуть руку помощи сородичам. Иди на берег и постарайся добыть лекарства!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26539, 'ruRU', 'Затянувшиеся переговоры', 'Поговорите с Орнаком в порту Драконьей Пасти. Хорзог может быстро доставить вас на побережье.', 'Вождь исчез! Но мы продолжим его план. $n, похоже, у тебя получается достигать поставленных целей. Собственно, поэтому, я к тебе и обращаюсь...$B$BНаши переговоры с Драконьей Пастью зашли в тупик. Их вождь... скажем так, оказался сложным орком. Отправляйся к нему и постарайся добиться возобновления переговоров.$B$BСначала иди на берег. Там Орнак, он сообщит тебе все последние новости.$B$BА затем поговори с Хорзогом, он быстро доставит тебя, куда нужно.', '', '', '', '', '', 'Поговорите с Орнаком в порту Драконьей Пасти. Хорзог может быстро доставить вас на побережье.', 25549);
INSERT INTO `quest_template_locale` VALUES (26540, 'ruRU', 'Опасное сострадание', 'Отнесите ящик бинтов Драконьей Пасти полководцу Кроггу, который находится в море рядом с портом Драконьей Пасти.', 'Красные драконы символизируют жизнь, и поэтому их кровь обладает лечебными свойствами.$B$BПовязки, которые находятся в этом ящике, пропитаны кровью красного дракона. Это все, что у меня есть. Пусть они исцелят твоих воинов.$B$BИ чем бы ни закончились переговоры, помни, что в Драконьей Пасти у тебя есть друзья.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26542, 'ruRU', 'Воззвание к героям: Внутренние земли!', 'Отправляйтесь в Заоблачный пик во Внутренних землях и поговорите с укротителем грифонов Разящим Когтем.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к укротителю грифонов Разящему Когтю в питомник на Заоблачном пике.$B$BНаши братья по оружию из Альянса взывают к вам о помощи, чтобы уберечь свою горячо любимую родину от посягательств Орды. Отправляйтесь на север с нагорья Арати и по горному перевалу дворфов проследуйте на дорогу, что ведет на северо-запад к Заоблачному пику.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26543, 'ruRU', 'Шустрые моллюски', 'Добудьте 10 кусков мяса чудовищного моллюска на восточном побережье к югу от Оргриммара. Возвращайтесь к Разгару с добычей.', 'Нет ничего вкуснее, чем мясо чудовищного моллюска, $n. А у меня столько работы в эти дни, что я никак не могу выбраться на их нерестилище. Может быть, сходишь туда и принесешь мне этой вкуснятины?$B$BМоллюски водятся у берега на восточном побережье Дуротара. В самой гавани Оргриммара их должно быть вдосталь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26544, 'ruRU', 'Они поумнели...', 'Разыщите послание орков Черной горы.', '<ГНМ-передатчик потрескивает и щелкает.>$B$BКажется, орки из клана Черной горы наконец-то поумнели. Мне сообщили, что они решили объединиться с гноллами для совместного нападения. Мне нужны детали, $n!$B$BСтупай проверь пещеры Ретбана, это в западной части каньонов Красногорья. Ищи орков с темной кожей, убивай всякого, что тебе встретится, а потом обыщи их тела на предмет информации.$B$BСоломон, отбой.', '', 'Орки Черной горы – это беда.', 'Мировой судья Соломон', 'Соломон, безупречно владею оркским.', 'Мировой судья Соломон', '', 25549);
INSERT INTO `quest_template_locale` VALUES (26545, 'ruRU', 'Изувой должен умереть!', 'Убейте Изувоя и найдите у него планы вторжения орков Черной горы.', '<ГНМ-передатчик гудит.>$B$BТебе надо найти Изувоя, $n. Он должен ошиваться где-то в северной части каньонов Красногорья. Убей это животное и посмотри, нет ли у него при себе планов вторжения орков Черной горы. Если найдешь – неси их мне в Приозерскую ратушу.$B$BСоломон связь закончил.', '', 'Изувой, сын Изувоя', 'Изувой', '', '', '', 25549);
